// Define the structure for LTE PHY layer control messages
typedef struct {
    int ue_id;
    int cell_id;
    float cqis[4]; // Assuming 4 CQIs per message
} LteControlMessage;

// Define the list of LTE control messages with thread safety
typedef struct {
    pthread_mutex_t mutex; // Mutex for thread safety
    LteControlMessage* messages; // Pointer to the array of messages
    int num_messages; // Number of messages in the list
} LteControlMessageList;

// Function to create and populate the list of LTE control messages
LteControlMessageList* lte_control_message_list_create(int max_num_messages) {
    LteControlMessageList* list = (LteControlMessageList*)malloc(sizeof(LteControlMessageList));
    pthread_mutex_init(&list->mutex, NULL);
    list->messages = (LteControlMessage*)calloc(max_num_messages, sizeof(LteControlMessage));
    list->num_messages = 0;
    return list;
}

// Function to add a new LTE control message to the list
int lte_control_message_list_add(LteControlMessageList* list) {
    pthread_mutex_lock(&list->mutex);
    LteControlMessage* message = (LteControlMessage*)malloc(sizeof(LteControlMessage));
    // Fetch UE ID and cell ID from external database
    int ue_id, cell_id;
    // Assume some error handling for fetching data
    if (!fetch_ue_cell_ids(&ue_id, &cell_id)) {
        free(message);
        pthread_mutex_unlock(&list->mutex);
        return -1; // Error adding message
    }
    // Generate random CQIs
    for (int i = 0; i < 4; i++) {
        message->cqis[i] = (float)(rand() % 100) / 100.0f;
    }
    message->ue_id = ue_id;
    message->cell_id = cell_id;

    // Add the new message to the list
    if (list->num_messages >= list->messages) {
        // Realloc and resize the array
        int new_size = list->num_messages + max_num_messages;
        LteControlMessage* new_messages = (LteControlMessage*)realloc(list->messages, sizeof(LteControlMessage) * new_size);
        list->messages = new_messages;
    }
    list->messages[list->num_messages] = *message;
    list->num_messages++;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success adding message
}

// Example usage:
int main() {
    LteControlMessageList* list = lte_control_message_list_create(100); // Create a list with initial capacity of 100 messages
    for (int i = 0; i < 10; i++) {
        if (lte_control_message_list_add(list) == -1) {
            printf("Error adding message\n");
        }
    }
    return 0;
}
