typedef struct {
    int value;
} Record;

Record* initRecords(int numRecords, long offsetValues[], int keys[], int maxLimit) {
    if (numRecords > maxLimit || sizeof(Record*) * numRecords > maxLimit) {
        printf("Error: Memory allocation exceeds the maximum limit.\n");
        return NULL;
    }

    Record* records = (Record*)malloc(sizeof(Record) * numRecords);
    if (!records) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % RAND_MAX;
    }

    return records;
}

void freeMemory(Record* records, int offsetValues[], int keys[]) {
    if (!records) {
        printf("Error: Memory is already freed.\n");
        return;
    }

    free(records);
    records = NULL;

    // Free memory for offset values and keys arrays
    free(offsetValues);
    free(keys);

    printf("Memory successfully freed.\n");
}

int main() {
    int numRecords = 1000;
    long maxOffsetValue = 10;
    int maxKey = 5;
    int maxLimit = 1024 * 1024; // 1MB

    srand(time(NULL));

    Record* records = initRecords(numRecords, (long*)malloc(sizeof(long) * numRecords), (int*)malloc(sizeof(int) * numRecords), maxLimit);
    if (!records) {
        printf("Error: Initialization failed.\n");
        return 1;
    }

    freeMemory(records, NULL, NULL);

    return 0;
}
