    LineCounter* counter = (LineCounter*) malloc(sizeof(LineCounter));
    counter->total_lines = 0;
    return counter;
}

void line_counter_free(LineCounter** counter) {
    free(*counter);
    *counter = NULL;
}

int process_file(LineCounter* counter, char* file_name) {
    FILE* file = fopen(file_name, "r");
    if (file == NULL) {
        printf("Error: Unable to open file %s.\n", file_name);
        return -1;
    }

    char buffer[BUFFER_SIZE];
    int lines = 0;

    while (fgets(buffer, BUFFER_SIZE, file)) {
        lines++;
    }

    fclose(file);

    if (lines > 0) {
        printf("Processed file %s with %d lines.\n", file_name, lines);
        counter->total_lines += lines;
    } else {
        printf("Error: Unable to read file %s.\n", file_name);
        return -1;
    }

    return 0;
}

int process_directory(LineCounter* counter, char* directory) {
    DIR* dir = opendir(directory);
    if (dir == NULL) {
        printf("Error: Unable to open directory %s.\n", directory);
        return -1;
    }

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) {
            continue;
        }

        char file_path[256];
        sprintf(file_path, "%s/%s", directory, ent->d_name);

        if (ent->d_type == DT_DIR) {
