            // handle manpage
        } else if (ent->d_type == DT_REG && strcmp(ent->d_name, "cs") == 0) {
            // handle cs
        } else if (ent->d_type == DT_REG) {
            process_file(counter, file_path);
        }

        free(ent);
    }

    closedir(dir);

    return 0;
}

