int main(int argc, char** argv) {
    if (argc != 6) {
        fprintf(stderr, "Invalid number of arguments. Expecting 5 command-line arguments.\n");
        return -1;
    }

    int fdIn = open(argv[1], O_RDONLY);
    if (fdIn < 0) {
        perror("open input file");
        return -1;
    }

    int fdOut = open(argv[2], O_WRONLY | O_CREAT, 0644);
    if (fdOut < 0) {
        perror("open output file");
        close(fdIn);
        return -1;
    }

    char* rules = argv[3];
    int maxBufferSize = atoi(argv[4]);
    char* configPath = argv[5];

    off_t fileSize = lseek(fdIn, 0, SEEK_END);
    if (fileSize < 0) {
        perror("lseek input file");
        close(fdIn);
        close(fdOut);
        return -1;
    }

    FILE* logFile = fopen("log.txt", "w");
    if (!logFile) {
        perror("open log file");
        close(fdIn);
        close(fdOut);
        return -1;
    }

    // process rules and apply them to the input file
    processRules(rules);

    // read and write files in chunks to avoid memory issues
    char buffer[maxBufferSize];
    size_t bytesRead, writtenBytes;

    while (fileSize > 0) {
        bytesRead = read(fdIn, buffer, maxBufferSize);
        if (bytesRead < 0) {
            perror("read input file");
            break;
        }
        else if (bytesRead == 0) {
            // end of file
            break;
        }

        // apply rules to the buffer contents
        // ...

        writtenBytes = write(fdOut, buffer, bytesRead);
        if (writtenBytes < 0) {
            perror("write output file");
            break;
        }
        else if ((size_t) writtenBytes != bytesRead) {
            // partial write
            perror("partial write");
            break;
        }

        fileSize -= bytesRead;
    }

    fclose(logFile);
    close(fdIn);
    close(fdOut);

    return 0;
}
