#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_LINE_LENGTH 1024
#define MAX_HOSTNAME_LENGTH 256
#define DNS_TIMEOUT 10000

typedef unsigned char u_char;

int get_dns_ip(const char *hostname, u_char **ip_address) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        return -1;
    }

    struct hostent *host_entry = gethostbyname(hostname);
    if (host_entry == NULL) {
        close(sock);
        return -2;
    }

    char *ip_addr = inet_ntoa(*((struct in_addr *)host_entry->h_addr));
    *ip_address = (u_char*)malloc(strlen(ip_addr) + 1);
    strcpy((char*)*ip_address, ip_addr);

    close(sock);
    return 0;
}

int main() {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        return -1;
    }

    // Read data from network stream
    char buffer[MAX_LINE_LENGTH];
    while (read(sock, buffer, MAX_LINE_LENGTH) > 0) {
        char *line = strtok(buffer, "\n");
        if (line == NULL) {
            continue;
        }

        char **fields = malloc(strlen(line) + 1);
        fields[0] = line;

        // Dynamically allocate memory for each field
        char *field = strtok(NULL, ",");
        int count = 1;
        while (field != NULL) {
            fields[count++] = field;
            field = strtok(NULL, ",");
        }

        // Calculate average of last two fields
        double sum = 0;
        for (int i = count - 2; i < count; i++) {
            sum += atof(fields[i]);
        }
        char *avg_str = malloc(32);
        sprintf(avg_str, "%.2f", sum / 2);

        // Print line contents in comma-separated format
        printf("%s,", fields[0]);
        for (int i = 1; i < count - 2; i++) {
            printf("%s,", fields[i]);
        }
        printf("%s\n", avg_str);
        free(avg_str);

        // Free allocated memory for each field
        for (int i = 0; i < count; i++) {
            free(fields[i]);
        }
        free(fields);
    }

    close(sock);
    return 0;
}
