#include <string.h>

int max_integer(int* arr, int n) {
    if (n == 0)
        return -1; // Return -1 to indicate no largest integer in an empty array
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

int read_integers(int** arr, int* size) {
    *size = 0;
    while (*size < 10000 && scanf("%d", &((*arr)[(*size)])) == 1) {
        if ((*arr)[(*size)] > 1000 || (*arr)[(*size)] < -1000) {
            printf("Error: Integer %d out of range.\n", (*arr)[(*size)]);
            continue;
        }
        (*size)++;
    }
    return 0;
}

int main() {
    int* arr = NULL;
    int size = 0;
    if (read_integers(&arr, &size) != 0)
        return -1;

    printf("The largest integer is: %d\n", max_integer(arr, size));

    free(arr);
    return 0;
}
