import os
from typing import Dict, List
from collections import Counter
import requests

def fetch_word_metadata(word: str) -> Dict:
    api_url = "https://api.example.com/word-metadata"
    try:
        response = requests.get(api_url, params={"word": word})
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error fetching metadata for {word}: {e}")
        return {}

def process_file(filename: str) -> Dict:
    chunk_size = 1000
    with open(filename, 'r') as file:
        lines = [line.strip().lower() for line in file.readlines()]
    words = []
    for i in range(0, len(lines), chunk_size):
        chunk = ' '.join(lines[i:i+chunk_size]).split()
        words.extend([word for word in chunk if word.isalpha()])
    return Counter(words)

def main(filename: str) -> Dict:
    file_words = process_file(filename)
    metadata_dict = {}
    for word, count in file_words.most_common(10):
        metadata = fetch_word_metadata(word.get("word", ""))
        metadata_dict[word] = {
            "count": count,
            "part_of_speech": metadata.get("pos", ""),
            "synonym_count": metadata.get("synonyms", 0)
        }
    return metadata_dict

if __name__ == "__main__":
    filename = "large_text_file.txt"
    result = main(filename)
    print(result)
