#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/pbkdf2.h>

EVP_CIPHER_CTX* flexible_encrypt_decrypt(const char* password, int password_length, const char* salt, int salt_length, int iteration_count, int key_length, int mode) {
    // Initialize error flags
    ERR_clear_error();

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    if (ctx == NULL) {
        return NULL;
    }

    if (key_length == 128) {
        if (!EVP_PBE_Cipher_init_ex(ctx, EVP_aes_128_CBC(), mode)) {
            ERR_free_strings();
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else if (key_length == 256) {
        if (!EVP_PBE_Cipher_init_ex(ctx, EVP_aes_256_CBC(), mode)) {
            ERR_free_strings();
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Derive key using PBKDF2
    if (!PBKDF2(password, password_length, salt, salt_length, iteration_count, key_length / 8, ctx)) {
        ERR_free_strings();
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}
