import subprocess
import os
import json
import logging
from typing import Dict, Any

def modify_config(config_file: str, parameters: Dict[str, Any], environment: str) -> None:
    with open(config_file, 'r') as file:
        config = file.read()

    for key, value in parameters.items():
        command = f"sed -i 's|{key}|{value}|g' {config_file}"
        try:
            subprocess.run(command.split(), check=True)
        except subprocess.CalledProcessError as e:
            logging.error(f"Failed to replace placeholder '{key}' with '{value}': {e}")

    environment_settings = f"{environment}_settings.json"
    if os.path.exists(environment_settings):
        with open(environment_settings, 'r') as file:
            env_config = json.load(file)
        for key, value in env_config.items():
            command = f"sed -i 's|{key}|{value}|g' {config_file}"
            try:
                subprocess.run(command.split(), check=True)
            except subprocess.CalledProcessError as e:
                logging.error(f"Failed to replace environment-specific setting '{key}' with '{value}': {e}")
    else:
        logging.warning(f"Environment-specific settings file '{environment_settings}' not found")

    new_config_file = f"{config_file}.modified"
    with open(new_config_file, 'w') as file:
        file.write(config)

    if os.path.exists(new_config_file):
        command = f"mv {new_config_file} {config_file}"
        try:
            subprocess.run(command.split(), check=True)
        except subprocess.CalledProcessError as e:
            logging.error(f"Failed to move modified configuration file: {e}")
    else:
        logging.warning(f"Modified configuration file '{new_config_file}' not found")
