import java.util.*;
import java.io.*;

public class Pokemon {
    public String getName() { return name; }
    public List<String> getTypes() { return types; }

    private String name;
    private List<String> types;

    public Pokemon(String name, List<String> types) {
        this.name = name;
        this.types = types;
    }
}

public class PokemonTypeMapper {
    private Map<String, Map<String, List<String>>> pokemonTypeWeaknessMap;
    private Map<String, String> typeWeaknessMap;
    private LRU_CACHE lruCache;

    public PokemonTypeMapper(int cacheSize) {
        lruCache = new LRU_CACHE(cacheSize);
        loadPokemonTypeWeaknessMap();
    }

    public String getWeakness(Pokemon pokemon) {
        List<String> weaknesses = new ArrayList<>();
        for (String type : pokemon.getTypes()) {
            if (!lruCache.contains(type)) {
                try {
                    typeWeaknessMap = loadTypeWeaknessMap(type);
                } catch (IOException e) {
                    logError("Failed to load type weakness map: " + e.getMessage());
                    continue;
                }
            }
            Map<String, List<String>> pokemonTypeWeaknessMap = lruCache.get(type);
            if (pokemonTypeWeaknessMap == null) {
                logError("Failed to retrieve type weaknesses for: " + type);
                continue;
            }
            for (String weakness : pokemonTypeWeaknessMap.values().stream()
                    .flatMap(Collection::stream).filter(s -> s.startsWith(type))
                    .collect(Collectors.toList())) {
                weaknesses.add(weakness);
            }
        }
        return String.join(", ", weaknesses);
    }

    private void loadPokemonTypeWeaknessMap() {
        try (BufferedReader br = new BufferedReader(new FileReader("pokemon_type_weakness_map.csv"))) {
            Map<String, Map<String, List<String>>> map = new HashMap<>();
            String line;
            while ((line = br.readLine()) != null) {
                String[] columns = line.split(",");
                if (columns.length < 3) continue;
                String pokemonName = columns[0];
                String type = columns[1].trim();
                List<String> weaknesses = Arrays.stream(columns).skip(2)
                        .map(String::trim)
                        .collect(Collectors.toList());
                map.computeIfAbsent(pokemonName, k -> new HashMap<>()).put(type, weaknesses);
            }
            pokemonTypeWeaknessMap = map;
        } catch (IOException e) {
            logError("Failed to load pokemon type weakness map: " + e.getMessage());
        }
    }

    private Map<String, String> loadTypeWeaknessMap(String type) throws IOException {
        try (BufferedReader br = new BufferedReader(new FileReader("type_weakness_map.csv"))) {
            Map<String, String> map = new HashMap<>();
            String line;
            while ((line = br.readLine()) != null) {
                String[] columns = line.split(",");
                if (columns.length < 2) continue;
                String weaknessType = columns[0].trim();
                String weakness = columns[1].trim();
                map.put(weaknessType, weakness);
            }
            return map;
        } catch (IOException e) {
            logError("Failed to load type weaknesses: " + e.getMessage());
            return new HashMap<>();
        }
    }

    private void logError(String message) {
        // implement logging mechanism here
        System.out.println(message);
    }

    public static class LRU_CACHE implements Cache<String, Map<String, List<String>>> {
        private int size;
        private Map<String, Map<String, List<String>>> cache;

        public LRU_CACHE(int size) {
            this.size = size;
            cache = new LinkedHashMap<String, Map<String, List<String>>>(size) {
                protected boolean removeEldestEntry(Map.Entry<String, Map<String, List<String>>> eldest) {
                    return size() > size;
                }
            };
        }

        public void put(String key, Map<String, List<String>> value) {
            cache.put(key, value);
        }

        public Map<String, List<String>> get(String key) {
            return cache.get(key);
        }

        public boolean contains(String key) {
            return cache.containsKey(key);
        }
    }
}
