// Define the structure to hold information about a cryptographic hash function or block cipher
typedef struct {
    char* name;
    void (*function)(void);
    int parameters;
} Algorithm;

// Function to load and parse the configuration file
Algorithm** load_config(const char* filename) {
    // Open the file for reading
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    // Define the array of available algorithms
    Algorithm** algorithms = (Algorithm**)malloc(10 * sizeof(Algorithm*));
    int count = 0;

    // Parse the configuration file and load available algorithms
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (strncmp(line, "#", 1) == 0 || strncmp(line, " ", 1) == 0)
            continue;
        Algorithm* algorithm = (Algorithm*)malloc(sizeof(Algorithm));
        algorithm->name = strtok(line, ",");
        algorithm->function = NULL; // Initialize with NULL
        algorithm->parameters = 0; // Initialize with 0
        algorithms[count++] = algorithm;
    }

    fclose(file);
    return algorithms;
}

// Function to check the availability of a cryptographic algorithm
int is_available(const char* filename) {
    // Check if the file exists and can be read
    struct stat buffer;
    if (stat(filename, &buffer) != 0 || !S_ISREG(buffer.st_mode))
        return 0;

    // Check if the file has executable permissions
    if (!access(filename, X_OK) == -1)
        return 0;

    return 1; // Algorithm is available
}

// Function to get a list of available cryptographic hash functions and block ciphers
Algorithm** get_algorithms(const char* filename, int* count) {
    // Initialize the array of algorithms
    Algorithm** algorithms = (Algorithm**)malloc(10 * sizeof(Algorithm*));
    *count = 0;

    // Load and parse the configuration file
    Algorithm** config = load_config(filename);
    if (!config)
        return NULL;

    // Iterate over the available algorithms in the configuration file
    for (int i = 0; i < 10; i++) {
        Algorithm* algorithm = config[i];
        if (algorithm) {
            // Check if the algorithm is available and supported by this platform
            int available = is_available(algorithm->name);
            if (available) {
                algorithms[(*count)++] = algorithm;
            } else {
                free(algorithm); // Free memory for unavailable algorithms
            }
        }
    }

    free(config);
    return algorithms;
}

// Function to dynamically load additional cryptographic libraries at runtime
void* dlopen(const char* filename, int mode) {
    void* handle = dlopen(filename, mode);
    if (!handle) {
        fprintf(stderr, "Failed to load library '%s'\n", filename);
        exit(1);
    }
    return handle;
}

// Function to get the list of available cryptographic algorithms
Algorithm** get_algorithms_thread_safe(const char* filename, int* count) {
    // Initialize the array of algorithms
    Algorithm** algorithms = (Algorithm**)malloc(10 * sizeof(Algorithm*));
    *count = 0;

    // Load and parse the configuration file
    Algorithm** config = load_config(filename);
    if (!config)
        return NULL;

    // Iterate over the available algorithms in the configuration file
    for (int i = 0; i < 10; i++) {
        Algorithm* algorithm = config[i];
        if (algorithm) {
            // Check if the algorithm is available and supported by this platform
            int available = is_available(algorithm->name);
            if (available) {
                algorithms[(*count)++] = algorithm;
            } else {
                free(algorithm); // Free memory for unavailable algorithms
            }
        }
    }

    // Load additional cryptographic libraries at runtime
    char* library_filenames[] = {"libhash.so", "libcipher.so"};
    for (int i = 0; i < 2; i++) {
        void* handle = dlopen(library_filenames[i], RTLD_LAZY);
        if (!handle) {
            fprintf(stderr, "Failed to load library '%s'\n", library_filenames[i]);
            exit(1);
        }
    }

    free(config);
    return algorithms;
}

int main() {
    int count = 0;
    Algorithm** algorithms = get_algorithms_thread_safe("algorithm_config.txt", &count);

    // Print the list of available cryptographic algorithms
    for (int i = 0; i < count; i++) {
        printf("%s\n", algorithms[i]->name);
    }

    return 0;
}
