#include <openssl/err.h>
#include <openssl/ssl.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef enum {
    ENC,
    DEC
} operation_t;

void* encrypt_decrypt(const char* input, const char* command_line_option) {
    // Initialize OpenSSL error handling
    ERR_load_crypto_strings();

    // Parse the command line option to determine whether to encrypt or decrypt
    operation_t operation = (strcmp(command_line_option, "-e") == 0) ? ENC : DEC;

    // Create a new SSL context for encryption/decryption
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        // Log error and exit with failure code
        LOG_ERROR("Failed to create SSL context");
        return NULL;
    }

    // Perform the desired operation (encrypt or decrypt)
    SSL* ssl = SSL_new(ctx);
    if (operation == ENC) {
        // Encrypt the input string using the OpenSSL API
        unsigned char* output = EVP_EncryptUpdate(ssl, input, strlen(input), NULL, 0);
        // Manage memory deallocation for the output buffer
        free(output);
    } else {
        // Decrypt the input string using the OpenSSL API
        unsigned char* output = EVP_DecryptUpdate(ssl, input, strlen(input), NULL, 0);
        // Manage memory deallocation for the output buffer
        free(output);
    }

    // Clean up SSL context and object
    SSL_free(ssl);
    SSL_CTX_free(ctx);

    return ssl;
}

void LOG_ERROR(const char* message) {
    FILE* log_file = fopen("log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}
