#include <semaphore.h>
#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void* create_semaphore(char* directory, char* semaphore_name, int initial_value, char* log_file) {
    // Assume that the directory path does not include trailing slash
    char full_directory[256];
    strcpy(full_directory, directory);
    strcat(full_directory, "/");

    // Create the directory if it doesn't exist
    if (access(full_directory, F_OK) != 0) {
        mkdir(full_directory, S_IRWXU | S_IRWXG | S_IRWXO);

        if (access(full_directory, F_OK) == -1) {
            // Log error creating directory
            FILE* log_file_ptr = fopen(log_file, "a");
            fprintf(log_file_ptr, "Error creating directory %s: %s\n", full_directory, strerror(errno));
            fclose(log_file_ptr);
        }
    }

    // Create the semaphore
    sem_t* semaphore = sem_open(full_directory, semaphore_name, O_CREAT | O_RDWR, initial_value);

    if (semaphore == SEM_FAILED) {
        // Log error creating semaphore
        FILE* log_file_ptr = fopen(log_file, "a");
        fprintf(log_file_ptr, "Error creating semaphore %s: %s\n", full_directory, strerror(errno));
        fclose(log_file_ptr);
    }

    return (void*)semaphore;
}
