#include <boost/beast/http.hpp>
#include <boost/beast/version.hpp>
#include <boost/asio.hpp>
#include <iostream>
#include <fstream>
#include <thread>

namespace beast = boost::beast;
namespace asio = boost::asio;

class SandeshClient {
public:
    SandeshClient(asio::io_service& io, const std::string& config_file) 
        : io_(io), config_file_(config_file) {
        // Initialize rate limiter with default values
        rate_limiter_.set_rate_limit(5); // Default 5 requests per minute
    }

    void send_get_request(const std::string& url, const std::string& expected_response) {
        beast::ssl_set_openSSL();
        auto req = beast::http::request<beast::http::string_body>("GET", url, 11);

        // Set user agent header
        req.set("User-Agent", "Sandesh-Client/1.0");

        // Send request asynchronously
        std::thread([this, req, expected_response]() {
            beast::ssl_set_openSSL();
            auto ep = asio::ip::tcp::endpoint(asio::ip::tcp::v4(), 80);
            beast::tcp_stream stream(io_);
            beast::error_code ec;

            // Perform timed connect
            boost::asio::deadline_timer timer(io_, asio::chrono::seconds(2));
            timer.wait();

            stream.async_connect(ep, [this, &req, &stream, expected_response](beast::error_code ec) {
                if (!ec)
                    send_request(stream, req, expected_response);
                else
                    std::cerr << "Error connecting: " << ec.message() << std::endl;
            });
        }).detach();
    }

private:
    void send_request(beast::tcp_stream& stream, beast::http::request<beast::http::string_body>& req, const std::string& expected_response) {
        // Send request
        beast::error_code ec;
        beast::ssl_set_openSSL();

        // Read response status
        beast::http::response<beast::http::string_body> res;

        stream.async_send(req, [this, &res](beast::error_code ec) {
            if (!ec)
                async_read(stream, res);
            else
                std::cerr << "Error sending request: " << ec.message() << std::endl;
        });

        // Verify response status matches expected value
        if (res.result().to_string()[0] == '2' && res.body.size() > 0) {
            if (std::string(res.body.begin(), res.body.end()) == expected_response) {
                std::cout << "Request successful: " << req.target() << " - " << res.result().to_string() << std::endl;
            } else {
                std::cerr << "Error: Request failed for " << req.target() << ". Expected response: " << expected_response << ", Got response: " << res.body.size() << std::endl;
            }
        }

        // Adjust rate limiter based on configuration updates
        config_file_.load();
        if (config_file_.get_rate_limit()) {
            rate_limiter_.set_rate_limit(config_file_.get_rate_limit());
        }
    }

    void async_read(beast::tcp_stream& stream, beast::http::response<beast::http::string_body>& res) {
        // Read response body
        std::thread([this, &stream, &res]() {
            beast::error_code ec;
            beast::flat_buffer buffer;

            stream.async_read_some(beast::buffer(buffer.data()), [this, &stream, &res](beast::error_code ec) {
                if (!ec)
                    res.body = std::string(buffer.data(), buffer.size());
                else
                    std::cerr << "Error reading response: " << ec.message() << std::endl;
            });
        }).detach();
    }

private:
    asio::io_service& io_;
    const std::string config_file_;
    rate_limiter rate_limiter_;
};

int main(int argc, char* argv[]) {
    // Create a new IO service and set up the client
    asio::io_service io;
    SandeshClient client(io, "config.json");

    // Send GET requests to the server with expected responses
    client.send_get_request("https://example.com/endpoint1", "Expected response 1");
    client.send_get_request("https://example.com/endpoint2", "Expected response 2");

    return 0;
}
```

