public string GetElementByXPath(string xmlDocument, string xpathExpression)
{
    XPathDocument document = new XPathDocument(xmlDocument);
    XPathNavigator navigator = document.CreateNavigator();
    XPathNodeIterator iterator = navigator.Select(xpathExpression);

    if (!iterator.MoveNext())
        throw new Exception("No elements found with the given name.");

    XPathNavigator element = iterator.Current;
    return element.Value;
}
