fn create_directory_with_env_var(name: &str) -> Result<(), String> {
    let current_path = env::var("MY_DIRECTORY");
    match current_path {
        Ok(path) => {
            if path == name {
                return Ok(());
            }
        }
        Err(_) => {}
    }

    let new_dir = Path::new(name);
