    [ApiController]
    [Route("api/[controller]")]
    public class UpdateController : ControllerBase
    {
        private readonly IUpdateService _updateService;
        private readonly ILogger<UpdateController> _logger;
        private readonly IMemoryCache _cache;
        private readonly RateLimiter _rateLimiter;

        public UpdateController(IUpdateService updateService, 
                                 ILogger<UpdateController> logger,
                                 IMemoryCache cache, 
                                 RateLimiter rateLimiter)
        {
            _updateService = updateService;
            _logger = logger;
            _cache = cache;
            _rateLimiter = rateLimiter;
        }

        [HttpPost]
        public async Task<ActionResult> Update([FromRoute] string pageSectionId,
                                              [FromRoute] string elementId,
                                              [FromBody] string htmlContent)
        {
            if (!await _rateLimiter.AllowRequestAsync(Request))
                return new StatusCodeResult(429);

            var cachedUpdate = _cache.GetOrCreate(pageSectionId, 
                                                      t => UpdateElement(pageSectionId, elementId, htmlContent));
            return new JsonResult(cachedUpdate) { ContentType = "text/plain" };
        }

        private async Task<string> UpdateElement(string pageSectionId, string elementId, string htmlContent)
        {
            try
            {
                await _updateService.UpdateElementAsync(pageSectionId, elementId, htmlContent);
                _logger.LogInformation("Updated element '{elementId}' in page section '{pageSectionId}'.", 
                                         elementId, pageSectionId);
                return "Page should be refreshed.";
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to update element '{elementId}' in page section '{pageSectionId}'.");
                throw;
            }
        }
    }

    public class RateLimiter
    {
        private readonly IRateLimiter _rateLimiter;

        public RateLimiter(IRateLimiter rateLimiter)
        {
            _rateLimiter = rateLimiter;
        }

        public async Task<bool> AllowRequestAsync(HttpRequest request)
        {
            var ipAddress = request.HttpContext.Connection.RemoteIpAddress;
            return await _rateLimiter.AllowRequestAsync(ipAddress, 10, TimeSpan.FromMinutes(1));
        }
    }
}
