        {
            var user = await _userManager.FindByEmailAsync(model.Email);
            if (user != null && user.LockoutEnabled)
            {
                int failedAttempts = GetFailedAttemptsCount(user);
                if (failedAttempts >= 5)
                {
                    await LockoutUser(user, "Too many attempts");
                    return IdentityResult.Failed();
                }
            }

            // Perform password validation and other custom checks
            var isValidPassword = ValidatePassword(model.Password);
            if (!isValidPassword)
            {
                return IdentityResult.Failed();
            }

            return await base.ValidateUserAsync(model);
        }

        private int GetFailedAttemptsCount(User user) => _userManager.GetFailedAttemptsCount(user);

        private async Task LockoutUser(User user, string reason)
        {
            await _userManager.SetLockoutAsync(user, DateTime.UtcNow.AddMinutes(30), reason);
        }

        // Implement MFA for admin users
        public override async Task<IdentityResult> ValidateUserAsync(LoginInputModel model, bool isMfaEnabled = false)
        {
            var user = await _userManager.FindByEmailAsync(model.Email);
            if (user != null && user.LockoutEnabled && isMfaEnabled)
            {
                // Perform MFA validation
                var isValidMfa = ValidateMfa(model.SecondFactor);
                if (!isValidMfa)
