            if (passwords.Contains(model.Password))
            {
                return IdentityResult.Failed("Password reused");
            }

            // Perform other custom updates and checks
            await base.UpdateUserAsync(user, model);

            // Update password history
            await _userManager.SetPasswordHistory(user, model.Password);
        }

        // Implement email verification for new users
        public override async Task<IdentityResult> CreateUserAsync(LoginInputModel model)
        {
            var user = await _userManager.FindByEmailAsync(model.Email);
