async function readFiles(directory) {
  const fs = require('fs');
  const path = require('path');
  const { promisify } = require('util');

  const readFile = promisify(fs.readFile);
  const stat = promisify(fs.stat);

  async function processFile(file) {
    try {
      const fileStat = await stat(path.join(directory, file));
      if (!fileStat.isFile()) throw new Error(`Not a file: ${file}`);
      const fileType = path.extname(file);
      const filterFiles = ['txt', 'json']; // Add or modify this array based on your requirements

      if (filterFiles.includes(fileType)) {
        const fileContent = await readFile(path.join(directory, file));
        return { fileName: file, content: fileContent.toString() };
      }
    } catch (error) {
      console.error(`Error processing file ${file}: ${error}`);
      return null;
    }
  }

  async function readDirectoryFiles(directory, files = []) {
    try {
      const dirStats = await Promise.all(
        await fs.readdirPromises(directory).map((file) => stat(path.join(directory, file)))
      );

      for (const [index, fileStat] of dirStats.entries()) {
        if (!fileStat.isDirectory()) {
          const processedFile = await processFile(files[index]);
          if (processedFile) files.push(processedFile);
        } else {
          const subFiles = await readDirectoryFiles(path.join(directory, file), []);
          files.push(...subFiles);
        }
      }

      return files;
    } catch (error) {
      console.error(`Error reading directory ${directory}: ${error}`);
      return [];
    }
  }

  try {
    return await readDirectoryFiles(directory);
  } catch (error) {
    console.error(`Error processing directory: ${error}`);
    return [];
  }
}

