function runModuleTests(label, f) {
  const tests = Object.keys(f);
  const maxTimeLimit = 150; // in milliseconds
  const logger = require('winston').createLogger({
    transports: [new require('winston').transports.Console()],
  });

  function test(name) {
    return new Promise((resolve, reject) => {
      let startTime;
      try {
        startTime = process.hrtime();
        f[name]().then(() => {
          const endTime = process.hrtime();
          const duration = (endTime[0] - startTime[0]) * 1e3 + (endTime[1] / 1e6);
          if (duration > maxTimeLimit) {
            reject(new Error(`Test ${name} timed out after ${maxTimeLimit}ms`));
          } else {
            resolve();
          }
        }).catch((error) => {
          reject(error);
        });
      } catch (error) {
        reject(error);
      }
    });
  }

  tests.forEach((testName) => {
    test(testName).then(() => {
      logger.info(`Test ${testName} passed`);
    }, (error) => {
      logger.error(`Test ${testName} failed: ${error}`);
    });
  });

  return Promise.all(tests.map(test)).catch((error) => {
    logger.error(`Module tests failed: ${error}`);
  });
}
