function extractProgrammingLanguages(text) {
    const supportedLanguages = require('./languages.json').map(lang => lang.name);
    const regexPatterns = [
        // JavaScript
        /\bjavascript\b/i,
        // Python
        /\bpython\b/i,
        // Java
        /\bjava\b/i,
        // C++
        /\bc\+\+|cpp\b/i,
        // C#
        /\bcs#|csharp\b/i,
        // Ruby
        /\bruby\b/i,
        // PHP
        /\bphp\b/i,
        // Swift
        /\bswift\b/i,
        // Go
        /\bgolang|go\b/i,
    ];

    const languageCounts = {};

    for (const pattern of regexPatterns) {
        let matches;
        while ((matches = text.match(pattern))) {
            for (const match of matches) {
                match = match.toLowerCase();
                if (!languageCounts[match]) {
                    languageCounts[match] = 0;
                }
                languageCounts[match]++;
                text = text.replace(new RegExp(`\\b${match}\\b`, 'g'), '');
            }
        }
    }

    return Object.fromEntries(Object.entries(languageCounts).filter(([lang, count]) => supportedLanguages.includes(lang)));
}
