function generateFooterScripts(scripts, cacheEnabled) {
  const footer = document.createElement('div');
  footer.innerHTML = '<footer>';

  scripts.forEach(script => {
    const scriptTag = document.createElement('script');
    scriptTag.id = `${script.key}-script`;

    try {
      if (script.async) {
        scriptTag.src = script.url;
        scriptTag.onload = () => {
          console.log(`Async script ${script.key} loaded successfully`);
        };
        scriptTag.onerror = error => {
          console.error(`Error loading async script ${script.key}: ${error}`);
        };
      } else {
        scriptTag.textContent = script.code;
      }

      footer.appendChild(scriptTag);
    } catch (error) {
      console.error(`Error rendering script ${script.key}: ${error}`);
    }
  });

  footer.innerHTML += '</footer>';

  if (cacheEnabled) {
    const cacheKey = 'generatedFooterScripts';
    localStorage.setItem(cacheKey, footer.outerHTML);
  }

  return footer;
}
