import java.io.IOException;
import java.util.Arrays;

public class DataCollector {
    private static final int BUFFER_SIZE = 1000;
    private static final int MAX_DELAY = 5000; // milliseconds
    private static final int MIN_DELAY = 1000; // milliseconds
    private static final int MESSAGE_SENDING_INTERVAL = 30000; // milliseconds

    private volatile boolean isServiceRunning = false;
    private volatile boolean isPaused = false;

    private byte[] buffer = new byte[BUFFER_SIZE];
    private int bufferPosition = 0;
    private int totalDataCollected = 0;

    public DataCollector() {
        startService();
    }

    public void startService() {
        if (!isServiceRunning) {
            isServiceRunning = true;
            isPaused = false;
            new Thread(() -> {
                try {
                    while (isServiceRunning) {
                        bufferPosition = 0;
                        collectData();
                        Thread.sleep((int) Math.min(MAX_DELAY, MIN_DELAY + Math.random() * (MAX_DELAY - MIN_DELAY)));
                    }
                } catch (InterruptedException | IOException e) {
                    stopService();
                }
            }).start();
        }
    }

    public void stopService() {
        isServiceRunning = false;
        try {
            Thread.sleep(MESSAGE_SENDING_INTERVAL);
            sendMessages();
        } catch (IOException e) {
            // Handle messaging system issues
        } finally {
            System.out.println("Service stopped.");
        }
    }

    private void collectData() throws IOException {
        if (!isPaused && isServiceRunning) {
            try (java.io.InputStream in = new java.io.DataInputStream(new java.net.URL("stream_url").openStream())) {
                for (int i = 0; i < BUFFER_SIZE && in.available() > 0; i++) {
                    buffer[i] = in.readByte();
                    bufferPosition++;
                }
            } catch (IOException e) {
                stopService();
            }
        }
    }

    private void sendMessages() throws IOException {
        // Send messages to the external messaging system
    }

    public void pauseDataCollection() {
        isPaused = true;
    }

    public void resumeDataCollection() {
        isPaused = false;
    }

    public int getTotalDataCollected() {
        return totalDataCollected;
    }

    public byte[] getBufferData() {
        return Arrays.copyOf(buffer, bufferPosition);
    }
}
