function traverseDOM(rootNode, selector, filterCallback = null) {
  const matches = [];
  (function traverse(node) {
    if (!node || !node.tagName) return;
    let elementMatches = node.querySelectorAll(selector);
    for (let i = 0; i < elementMatches.length; i++) {
      let elementMatch = elementMatches[i];
      if (filterCallback && !filterCallback(elementMatch)) continue;
      matches.push(elementMatch);
    }
    Array.from(node.children).forEach(traverse);
  })(rootNode);
  return matches;
}']

