// C function to modify file extension
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void modifyExtension(const char *filename, int *digits) {
  // Calculate number of digits based on filename length
  const int len = strlen(filename);
  *digits = len % 3;

  // Determine file type based on extension
  char *ext = strrchr(filename, '.');
  if (ext) {
    *strcat(strdup(ext), (char *)malloc(1 + *digits)) = '\0';
    sprintf((char *)malloc(1 + strlen(filename) + *digits), "%s%.%d.js", filename, ext);
  }
}

// Example usage
const char *filename = "example";
int digits;
modifyExtension(filename, &digits);

