import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class ServiceInstance implements Runnable {
    private String instanceId;
    private Random random = new Random();
    private ExecutorService executorService;
    private HealthMonitor healthMonitor;
    private int maxConcurrentServices;
    private int delayMin;
    private int delayMax;

    public ServiceInstance(String instanceId, ExecutorService executorService,
                             HealthMonitor healthMonitor, int maxConcurrentServices,
                             int delayMin, int delayMax) {
        this.instanceId = instanceId;
        this.executorService = executorService;
        this.healthMonitor = healthMonitor;
        this.maxConcurrentServices = maxConcurrentServices;
        this.delayMin = delayMin;
        this.delayMax = delayMax;
    }

    @Override
    public void run() {
        while (true) {
            start();
            stop();
        }
    }

    private void start() {
        try {
            // Simulate service startup and reporting
            Thread.sleep(random.nextInt(delayMax - delayMin + 1) + delayMin);
            healthMonitor.sendStatus(instanceId, "started");
            executorService.submit(this::run);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private void stop() {
        try {
            // Simulate service shutdown and reporting
            healthMonitor.sendStatus(instanceId, "stopped");
            executorService.shutdownNow();
        } catch (Exception e) {
            System.out.println("Error stopping service instance: " + e.getMessage());
        }
    }
}

class HealthMonitor {
    public void sendStatus(String instanceId, String status) {
        // Implement external health monitoring system integration
        System.out.println("Sending status for instance " + instanceId + ": " + status);
    }
}

public class ServiceManager {
    private int numServiceInstances;
    private ExecutorService executorService;
    private HealthMonitor healthMonitor;
    private int maxConcurrentServices;

    public ServiceManager(int numServiceInstances, HealthMonitor healthMonitor,
                           int maxConcurrentServices) {
        this.numServiceInstances = numServiceInstances;
        this.healthMonitor = healthMonitor;
        this.maxConcurrentServices = maxConcurrentServices;
        executorService = Executors.newCachedThreadPool();
    }

    public void run() {
        for (int i = 0; i < numServiceInstances; i++) {
            ServiceInstance serviceInstance =
                    new ServiceInstance("instance-" + i, executorService, healthMonitor,
                            maxConcurrentServices, 100, 500);
            executorService.submit(serviceInstance);
        }
    }

    public static void main(String[] args) {
        HealthMonitor healthMonitor = new HealthMonitor();
        int numServiceInstances = 5;
        int maxConcurrentServices = 3;
        ServiceManager serviceManager = new ServiceManager(numServiceInstances, healthMonitor,
                maxConcurrentServices);
        serviceManager.run();
    }
}
