['```rust
use reqwest::{blocking::RequestBuilder, header};
use log::log_enabled;
use std::collections::HashMap;

pub fn create_http_client(
    url: &str,
    disable_cert_validation: bool,
    custom_headers: Option<HashMap<String, String>>,
    timeout: u64,
    retry_interval: u64,
) -> RequestBuilder {
    let mut client = reqwest::blocking::Client::new();

    if disable_cert_validation {
        client = client.danger_accept_invalid_certs();
    }

    if let Some(headers) = custom_headers {
        for (key, value) in headers {
            client = client.header(header::raw(key.as_str(), value.as_str()));
        }
    }

    let mut request_builder = client.get(url);
    request_builder.timeout(timeout);

    // implement retry mechanism
    loop {
        match request_builder.send() {
            Ok(response) => break response,
            Err(error) => {
                if log_enabled!(log::Level::Info) {
                    log::info!("Request failed: {}", error);
                }
                thread::sleep(std::time::Duration::from_secs(retry_interval));
            }
        }
    }
}
