    // Check connection
    if (!$db) {
        $error['code'] = 500;
        $error['message'] = "Database connection failed";
        return false;
    }

    // Get the current version number of the user's profile
    $query = "SELECT version FROM users WHERE id = '$userId'";
    $result = mysqli_query($db, $query);
    if (!$result) {
        $error['code'] = 500;
        $error['message'] = "Failed to retrieve version";
        return false;
    }
    $row = mysqli_fetch_assoc($result);
    $currentVersion = $row['version'];

    // Update the user's profile
    $query = "UPDATE users SET status = '$status', last_modified_ip = '$newIp', 
              last_modified_date = NOW(), version = version + 1 WHERE id = '$userId' AND version = '$currentVersion'";
