}

function readAsyncFile($basePath, $randomString, $fs) {
    $filePath = $basePath . $randomString;
    $promise = new \React\Promise\Resolved();
    $fs->readFile($filePath)->then(function ($data) use (&$promise) {
        $promise = new \React\Promise\Resolved($data);
    })->otherwise(function ($error) use (&$promise) {
        $promise = new \React\Promise\Rejected($error);
    });
    return $promise->then(function ($data) {
        if (!$data) {
            return 'File not found or cannot be read.';
        }
        return $data;
    }, function ($error) {
        return 'Error reading file: ' . $error;
    });
}

