["```
const fs = require('fs');
const https = require('https');
const crypto = require('crypto');

function collectData() {
  const config = JSON.parse(process.env.CONFIG || '{}');
  const url = config.streamUrl;
  const privateKeyPath = config.privateKeyPath;
  const certificatePath = config.certificatePath;

  let data = [];
  let interrupted = false;

  function fetchConfig() {
    return new Promise((resolve, reject) => {
      https.get(url, (res) => {
        res.pipe(fs.createWriteStream('config.json'))
          .on('close', () => resolve());
      });
    });
  }

  function downloadData(start, end) {
    return new Promise((resolve, reject) => {
      const options = {
        method: 'GET',
        url,
        headers: {
          'Range': `bytes=${start}-${end}`,
        },
      };

      https.get(options.url, options, (res) => {
        let chunk;
        res.on('data', (d) => {
          chunk = Buffer.concat([chunk, d]);
        });
        res.on('end', () => {
          data.push(chunk);
          resolve();
        });
      })
      .on('error', reject)
      .on('pause', () => {
        interrupted = true;
      })
      .on('resume', () => {
        if (interrupted) {
          downloadData(start, end);
          interrupted = false;
        }
      });
    });
  }

  function combinePem() {
    return new Promise((resolve, reject) => {
      const privateKey = fs.readFileSync(privateKeyPath).toString();
      const certificate = fs.readFileSync(certificatePath).toString();

      crypto.createCert({
        key: privateKey,
        cert: certificate,
      })
        .then((cert) => {
          const pem = `-----BEGIN CERTIFICATE-----
${cert.raw}
-----END CERTIFICATE-----`;
          resolve(pem);
        })
        .catch(reject);
    });
  }

  return Promise.all([fetchConfig(), downloadData(0, Infinity)])
    .then(() => combinePem())
    .catch((err) => console.error('Error:', err));
}

collectData();
```"]

