<?php

class PasswordUpdateDAO {
    private $db;
    private $logger;

    public function __construct(PDO $db, Logger $logger) {
        $this->db = $db;
        $this->logger = $logger;
    }

    public function updatePassword(int $userId, string $oldPassword, string $newPassword): bool {
        // Verify user identity with external authentication service
        if (!verifyUserIdentity($userId)) {
            return false; // User not found or authentication failed
        }

        // Check if password has been updated within the last 24 hours
        $lastUpdate = getLastPasswordUpdateTime($userId);
        if (time() - $lastUpdate < 24 * 60 * 60) { // 24 hours in seconds
            return false; // Password update too frequent
        }

        try {
            // Start transaction
            $this->db->beginTransaction();

            // Update password hash and last update time
            $query = "UPDATE users SET password_hash = :new_password, last_password_update_time = :last_update WHERE id = :user_id";
            $stmt = $this->db->prepare($query);
            $stmt->execute([':new_password' => password_hash($newPassword, PASSWORD_DEFAULT), ':last_update' => time(), ':user_id' => $userId]);

            // Commit transaction
            $this->db->commit();

            // Log password update attempt
            $this->logger->info('Password updated successfully for user ' . $userId);

            return true;
        } catch (PDOException $e) {
            // Rollback transaction on error
            $this->db->rollBack();
            $this->logger->error('Error updating password: ' . $e->getMessage());
            return false;
        }
    }

}

