typedef struct {
    int state;
    struct FSA* next;
} State;

struct FSA {
    int start_state;
    int num_states;
    State states[];
};

State* create_state_list(int* states, int num_states, struct FSA* fsa, int last_state) {
    if (num_states > 1000 || !fsa) return NULL; // maximum size limit

    State* new_list = (State*)malloc((last_state + 1) * sizeof(State));
    for (int i = 0; i <= last_state; i++) {
        new_list[i].state = states[i];
        if (i < last_state) {
            new_list[i].next = &new_list[i+1];
        } else {
            new_list[i].next = NULL;
        }
    }

    fsa->states[last_state].next = new_list; // update 'next' pointer of the last state
    return new_list;
}
