#include <time.h>

typedef struct {
    int id;
    uint32_t checksum;
    time_t timestamp;
} Packet;

void filter_packets(Packet* packets, int packet_count, int* metrics) {
    int max_checksum = 0;
    int max_packet_id = -1;
    int packet_age_max = 50; // in milliseconds

    for (int i = 0; i < packet_count; i++) {
        Packet* packet = &packets[i];
        time_t current_timestamp = time(NULL);
        int packet_age = (current_timestamp - packet->timestamp) / 1000;

        if (packet_age > packet_age_max || packet_age <= 0) continue;

        // Check the number of packets in the past 50 milliseconds
        int packets_in_window = metrics[1];
        if (packets_in_window >= 50) continue;

        // Calculate the checksum and update metrics
        uint32_t checksum = packet->checksum;
        metrics[0] += checksum;
        metrics[1]++;

        if (checksum > max_checksum) {
            max_checksum = checksum;
            max_packet_id = packet->id;
        }
    }

    printf("Max checksum: %d, Packet ID: %d\n", max_checksum, max_packet_id);
}

int main() {
    int packet_count = 1000;
    Packet packets[packet_count];
    int metrics[2] = {0, 0};

    // Initialize packets and metrics
    for (int i = 0; i < packet_count; i++) {
        packets[i].id = i;
        packets[i].checksum = (uint32_t)rand();
        packets[i].timestamp = time(NULL);
    }

    filter_packets(packets, packet_count, metrics);

    return 0;
}
