class AttackTracker {
public:
    AttackTracker() : lastAttacks_(std::vector<int>(5, -1)), cooldownTimer_(0), uniqueCooldown_(false) {}

    void trackAttack(int attackType) {
        if (uniqueCooldown_) {
            return;
        }

        lastAttacks_.erase(lastAttacks_.begin());
        lastAttacks_.emplace_back(attackType);
        uniqueCooldown_ = true;

        std::thread t([&] {
            std::this_thread::sleep_for(std::chrono::seconds(9));
            uniqueCooldown_ = false;
        });
    }

private:
    std::vector<int> lastAttacks_;
    int cooldownTimer_;
    bool uniqueCooldown_;
};

AttackTracker attackTracker_;

void selectAndPrintAttack() {
    static const int numAttacks = 2;

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, numAttacks);

    int currentAttackType;
    do {
        currentAttackType = dis(gen);
        attackTracker_.trackAttack(currentAttackType);
    } while (std::count(attackTracker_.lastAttacks_.begin(), attackTracker_.lastAttacks_.end(), currentAttackType) > 4);

    std::cout << "Selected Attack: " << currentAttackType << std::endl;
}

int main() {
    for (;;) {
        selectAndPrintAttack();
        // Simulate game update
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
}
