```csharp
using System;
using System.Random;

public abstract class RandomValueGenerator
{
    protected float MinValue;
    protected float MaxValue;

    public RandomValueGenerator(float min, float max)
    {
        MinValue = min;
        MaxValue = max;
    }

    public float GetRandomFloat(bool inclusive)
    {
        if (inclusive)
            return (float)GetRandomDouble();
        else
            return (MinValue + new Random().NextDouble() * (MaxValue - MinValue));
    }

    public int GetRandomInt(bool inclusive)
    {
        if (inclusive)
            return GetRandomDouble().ToInt32();
        else
            return MinValue + new Random().Next(Int32.MaxValue) % (int)(MaxValue - MinValue);
    }

    public bool ValidateValues(float[] values)
    {
        foreach (float value in values)
        {
            if (value < MinValue || value > MaxValue)
                return false;
        }
        return true;
    }

    protected abstract double GetRandomDouble();
}
