function reduceArray(arr, initial, callback) {
  const results = [];
  let accumulated = initial;

  async.eachLimit(
    arr,
    1000,
    (num, cb) => {
      const fetchPromise = new Promise((resolve, reject) => {
        setTimeout(() => {
          // Simulate external data source call
          const data = { value: num * 2 };
          resolve(data);
        }, Math.random() * 5000 + 100); // Random timeout between 1-5 seconds
      });

      fetchPromise.then((data) => {
        accumulated += data.value;
        results.push(accumulated);
        cb();
      }).catch((err) => {
        callback(new Error('Error in parallel operation: ' + err));
      });
    },
    (err) => {
      if (err) {
        callback(err);
      } else {
        callback(null, results.reduce((acc, val) => acc + val));
      }
    }
  );
}

