function findElements(node, selector, callback) {
    const results = [];
    (function traverse(node) {
        if (!node) return;
        const classes = node.classList.value.split(' ');
        const ids = Array.from(node.getAttributeNames()).filter(attr => attr.startsWith('id')).map(attr => node.getAttribute(attr));
        if (callback(classes, ids)) results.push(node);
        for (const child of node.children) traverse(child);
    })(node);
    return results.filter(elem => elem.matches(selector));
}
