    if (png_fp == NULL) {
        printf("Error opening PNG file\n");
        fclose(fp);
        free(theme_bitmap);
        return 1;
    }

    // Process log file line by line
    char *line = malloc(MAX_LINE_LENGTH);
    while (fgets(line, MAX_LINE_LENGTH, fp) != NULL) {
        // Calculate average of last two numerical values in each line
        float sum = 0.0f;
        int num_values = 0;
        char *token = strtok(line, " ");
        while (token != NULL && num_values < 2) {
            if (strspn(token, ".0123456789-") == strlen(token)) {
                float value = atof(token);
                sum += value;
                num_values++;
            }
            token = strtok(NULL, " ");
        }

        // Print averages in comma-separated format
        printf("%.2f, %.2f\n", sum / num_values, (sum + 1) / num_values);

        free(line);
        line = NULL;
    }

    fclose(fp);
    free(theme_bitmap);
    theme_bitmap = NULL;

    return 0;
}

