using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using ImageMagick;

public struct TIFFInfo
{
    public int BitsPerSample { get; set; }
    public int SamplesPerPixel { get; set; }
    public int ExtraSamples { get; set; }
}

public class TIFFProcessor
{
    private const string SUPPORTED_BITS_PER_SAMPLE = "1, 2, 4, 8, 16";

    public static (string MD5Hash, TIFFInfo) ProcessTIFFFile(string filePath)
    {
        using (FileStream fileStream = File.OpenRead(filePath))
        using (MagickImage image = new MagickImage(fileStream))
        {
            TIFFInfo info = GetTIFFInfo(image);
            string md5Hash = ComputeMD5Hash(filePath);

            return ($"{md5Hash}", info);
        }
    }

    private static TIFFInfo GetTIFFInfo(MagickImage image)
    {
        int bitsPerSample = image.BitsPerSample;
        int samplesPerPixel = image.SamplesPerPixel;

        if (!SUPPORTED_BITS_PER_SAMPLE.Contains(bitsPerSample.ToString()))
        {
            throw new ArgumentException($"Unsupported bits per sample: {bitsPerSample}");
        }

        int extraSamples = 0;
        for (int i = 0; i < image.GetProfiles().Count; i++)
        {
            if (image.GetProfile(i).GetType() != typeof(MagickProfile))
                continue;

            MagickProfile profile = (MagickProfile)image.GetProfile(i);
            foreach (string tag in profile.Tags)
            {
                if (tag.StartsWith("ExtraSamples"))
                {
                    extraSamples = int.Parse(profile.GetValue(tag));
                    break;
                }
            }
        }

        return new TIFFInfo { BitsPerSample = bitsPerSample, SamplesPerPixel = samplesPerPixel, ExtraSamples = extraSamples };
    }

    private static string ComputeMD5Hash(string filePath)
    {
        using (FileStream fileStream = File.OpenRead(filePath))
        using (MD5 md5 = MD5.Create())
        {
            byte[] hashBytes = md5.ComputeHash(fileStream);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }
}
