    if (!new_filename) return NULL;

    int digits = len - 3;
    if (digits <= 0) digits = 1; // Default to at least one digit
    sprintf(new_filename, "%s%d", filename, digits);

    char *file_type = strrchr(filename, '.');
    if (!file_type || strlen(file_type) < 4) {
        file_type = ".txt"; // Default file type
    } else {
        file_type += 1;
        file_type[3] = '\0'; // Null-terminate the file type
