    total_memory += EVP_DIGEST_SIZE(SHA);

    // Add RSA with SHA1
    if (EVP_add_cipher_alias(RSA, "RSA/SHA1") != 1) {
        printf("Failed to add RSA/SHA1 cipher\n");
    }

