EVP_CIPHER_CTX* aes256CbcCipherInit(const char* password) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    const int key_length = 32;
    const int iv_length = 16;
    const int derived_key_length = 256/8;

    unsigned char password_derived_key[derived_key_length];
    SHA256(password, strlen(password), password_derived_key);

    unsigned char key[key_length];
    memcpy(key, password_derived_key, key_length);

    unsigned char iv[iv_length];
    RAND_bytes(iv, iv_length);

    EVP_SealInit(ctx, &key, &iv);
    EVP_CIPHER_CTX_set_padding(ctx, 0);

    int result = EVP_SealUpdate(ctx, NULL, NULL);
    if (result <= 0) {
        ERR_error_string(ERR_get_error(), NULL);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    ctx->block_mask = 0;

    return ctx;
}

void aes256CbcCipherClean(EVP_CIPHER_CTX* ctx) {
    EVP_CIPHER_CTX_free(ctx);
