int deserialize_byte_array(char* byte_array, int array_length) {
    // Initialize the ObjectInputStream
    void* object_stream = NULL;
    int bytes_read = 0;
    int bytes_written = 0;

    while (bytes_read < array_length) {
        char* buffer = (char*)malloc(1024);

        // Read data from byte_array into buffer
        for (int i = 0; i < 1024 && bytes_read + i < array_length; i++) {
            buffer[i] = byte_array[bytes_read + i];
        }

        bytes_read += 1024;
        int bytesReadThisTime = bytes_read - 1024;

        // Initialize ObjectInputStream
        void* object_input_stream = malloc(sizeof(java::ObjectInputStream));
        java::ObjectInputStream* ois = (java::ObjectInputStream*)object_input_stream;

        // Deserialize the object
        try {
            ois->readObject(buffer);
            free(ois);
            free(object_input_stream);
            free(buffer);
            return 0;
        } catch (const char* e) {
            printf("Error: Object deserialization failed: %s\n", e);

            free(ois);
            free(object_input_stream);
            free(buffer);
            return 1;
        }
    }

    // Handle the last chunk
    int bytesReadThisTime = array_length - bytes_read;
    char* buffer = (char*)malloc(bytesReadsThisTime + 1);

    for (int i = 0; i < bytesReadThisTime; i++) {
        buffer[i] = byte_array[bytes_read + i];
    }
    buffer[bytesReadsThisTime] = '\0';

    // Deserialize the object
    try {
        ois->readObject(buffer);
        free(ois);
        free(object_input_stream);
        free(buffer);
        return 0;
    } catch (const char* e) {
        printf("Error: Object deserialization failed: %s\n", e);

        free(ois);
        free(object_input_stream);
        free(buffer);
        return 1;
    }

    // If we reach here, it means the object could not be read

    return -1;
}

int main(int argc, char** argv) {
    if (argc < 3) {
        printf("Usage: %s [input_file] [output_file]\n", argv[0]);
        return 0;
    }

    int conversion_status = convert_jpeg_to_pdf(argv[1], argv[2]);

    if (conversion_status == 0) {
        char* byte_array = malloc(1024 * 1024);

        // Read the output file
        FILE* output_file = fopen(argv[2], "rb");
        fseek(output_file, 0L, SEEK_END);
        int bytes = ftell(output_file);
        rewind(output_file);

        if (fread(byte_array, 1, bytes, output_file) < bytes) {
            printf("Error: Unable to read the file\n");
            return -1;
        }

        fclose(output_file);

        int deserialization_status = deserialize_byte_array(byte_array, bytes);

        free(byte_array);

        if (deserialization_status == 0) {
            printf("Deserialization successful\n");
        } else {
            printf("Error: Deserialization failed\n");
        }
    }

    return 0;
}

