#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <json-c/json.h>

#define MAX_CONCURRENT 10
#define LOG_FILE "command_log.txt"

int run_commands(char *commands, int max_concurrent, char *log_file) {
    FILE *fp = fopen(log_file, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    json_object *config = json_object_from_file("config.json");
    if (!config) {
        perror("Error loading config file");
        fclose(fp);
        return -1;
    }

    int command_count = 0;
    char *token = strtok(commands, ";");
    while (token) {
        command_count++;
        token = strtok(NULL, ";");
    }

    pid_t *child_pids = malloc(command_count * sizeof(pid_t));
    int *child_statuses = malloc(command_count * sizeof(int));

    for (int i = 0; i < command_count; i++) {
        if (waitpid(-1, NULL, WNOHANG) >= MAX_CONCURRENT) {
            // wait for one of the children to finish
            pid_t finished_pid = waitpid(-1, NULL, WNOHANG);
            while (finished_pid != 0) {
                int status;
                waitpid(finished_pid, &status, 0);
                if (WEXITSTATUS(status)) {
                    // command failed, log and return error
                    fprintf(fp, "Command %d failed with exit code %d\n", i + 1, WEXITSTATUS(status));
                    fclose(fp);
                    free(child_pids);
                    free(child_statuses);
                    return 0;
                }
                finished_pid = waitpid(-1, NULL, WNOHANG);
            }
        }

        pid_t child_pid = fork();
        if (child_pid == -1) {
            perror("Error forking");
            fclose(fp);
            free(child_pids);
            free(child_statuses);
            return -1;
        } else if (child_pid == 0) {
            // execute the command
            system(token);

            // log the command execution
            fprintf(fp, "Command %d executed successfully\n", i + 1);

            exit(0);
        }

        child_pids[i] = child_pid;
    }

    for (int i = 0; i < command_count; i++) {
        waitpid(child_pids[i], NULL, 0);
    }

    free(child_pids);
    free(child_statuses);
    fclose(fp);

    return 1;
}
