import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class CommandExecutor {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final List<Callable<String>> callableList = new ArrayList<>();

    public void executeCommand(String command) throws IOException, InterruptedException {
        Callable<String> callable = () -> {
            Process process = Runtime.getRuntime().exec(command.split(" "));
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                StringBuilder output = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append("\n");
                }
                System.out.println(output.toString());
            } catch (IOException e) {
                System.err.println("Error executing command: " + e.getMessage());
            }
            return process.waitFor() + "";
        };
        Future<String> future = executor.submit(callable);
        callableList.add(future);

        try {
            String result = future.get();
            System.out.println("Command executed in " + (System.currentTimeMillis() - Long.parseLong(result)) + " ms");
        } catch (ExecutionException e) {
            System.err.println("Error getting command result: " + e.getMessage());
        }
    }

    public void deleteFile(String filePath) throws IOException {
        if (!filePath.isEmpty()) {
            Runtime.getRuntime().exec("rm " + filePath).waitFor();
        }
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        CommandExecutor executor = new CommandExecutor();

        // Example usage
        executor.executeCommand("ls -l /path/to/directory");
        executor.deleteFile("/path/to/file.txt");

        // Shut down the executor
        executor.executor.shutdown();
    }
}
