public class ServiceManager {

    private static final int MAX_CONCURRENT_SERVICES = 5; // adjust this value as needed

    public void startServices(int numInstances, long delayBetweenStarts) throws InterruptedException {
        ExecutorService executor = Executors.newCachedThreadPool();
        ScheduledExecutorService scheduledExecutor = Executors.newScheduledThreadPool(numInstances);

        for (int i = 0; i < numInstances; i++) {
            executor.submit(() -> {
                // Start a new service instance
                startService(scheduledExecutor);
            });
        }

        try {
            Thread.sleep(delayBetweenStarts);
        } catch (InterruptedException e) {
            throw new InterruptedException("Interrupted while waiting for services to start");
        }
    }

    public void stopServices(int numInstances, long delayBetweenStops) throws InterruptedException {
        ExecutorService executor = Executors.newCachedThreadPool();
        ScheduledExecutorService scheduledExecutor = Executors.newScheduledThreadPool(numInstances);

        for (int i = 0; i < numInstances; i++) {
            executor.submit(() -> {
                // Stop a service instance
                stopService(scheduledExecutor);
            });
        }

        try {
            Thread.sleep(delayBetweenStops);
        } catch (InterruptedException e) {
            throw new InterruptedException("Interrupted while waiting for services to stop");
