using System;
using System.Security.Cryptography;
using System.Text;

public string DecryptMessage(string base64EncodedMessage, string key, string iv, string mode)
{
    if (string.IsNullOrEmpty(base64EncodedMessage))
        throw new ArgumentException("Input message is empty or null", nameof(base64EncodedMessage));

    if (string.IsNullOrEmpty(key))
        throw new ArgumentException("Encryption key is empty or null", nameof(key));

    if (string.IsNullOrEmpty(iv))
        throw new ArgumentException("Initialization vector is empty or null", nameof(iv));

    if (!new[] { "CBC", "ECB" }.Contains(mode, StringComparer.OrdinalIgnoreCase))
        throw new InvalidOperationException($"Unsupported encryption mode '{mode}'");

    try
    {
        byte[] base64DecodedMessage = Convert.FromBase64String(base64EncodedMessage);
        using (var tripleDES = TripleDESCryptoServiceProvider.Create())
        {
            tripleDES.Key = Encoding.ASCII.GetBytes(key);
            tripleDES.IV = Encoding.ASCII.GetBytes(iv);

            if (!tripleDES.CanDecrypt)
                throw new InvalidOperationException("Invalid key or IV");

            byte[] decryptedBytes;
            switch (mode.ToUpper())
            {
                case "CBC":
                    decryptedBytes = Decrypt CBC(base64DecodedMessage, tripleDES);
                    break;
                case "ECB":
                    decryptedBytes = Decrypt ECB(base64DecodedMessage, tripleDES);
                    break;
                default:
                    throw new InvalidOperationException($"Unsupported encryption mode '{mode}'");
            }

            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }
    catch (CryptographicException ex)
    {
        throw new ArgumentException("Invalid key or IV", nameof(key), ex);
    }
}

private byte[] DecryptCBC(byte[] base64DecodedMessage, TripleDESCryptoServiceProvider tripleDES)
{
    using (var memoryStream = new MemoryStream(base64DecodedMessage))
    {
        using (var cryptoStream = new CryptoStream(memoryStream, tripleDES.CreateDecryptor(), CryptoStreamMode.Read))
        {
            return cryptoStream.ToArray();
        }
    }
}

private byte[] DecryptECB(byte[] base64DecodedMessage, TripleDESCryptoServiceProvider tripleDES)
{
    return tripleDES.Decrypt(base64DecodedMessage);
}
