using System.Text;

public static class Sha256HashGenerator
{
    public static byte[] GetSha256Hash(string input, bool useHexadecimalFormat = false, string customSalt = null)
    {
        using (var sha256 = SHA256.Create())
        {
            if (!string.IsNullOrEmpty(customSalt))
            {
                var saltBytes = Encoding.UTF8.GetBytes(customSalt);
                var inputWithSalt = Convert.ToBase64String(sha256.ComputeHash(saltBytes)) + input;
                byte[] hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(inputWithSalt));
                return hashBytes;
            }
            else
            {
                return sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
            }
        }
    }

    public static string GetSha256HexHash(string input, bool useCustomSalt = false, string customSalt = null)
    {
        byte[] hashBytes = GetSha256Hash(input, !useCustomSalt, customSalt);
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
    }
}
