using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public static class AesCbcDecryptor
{
    public static byte[] Decrypt(byte[] ciphertext, byte[] encryptionKey, byte[] iv)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = encryptionKey;
            aes.IV = iv;

            using (var decryptor = aes.CreateDecryptor())
            {
                var buffer = new byte[ciphertext.Length];
                using (var ms = new MemoryStream(ciphertext))
                {
                    using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    {
                        var decryptedBytes = new byte[ciphertext.Length];
                        int bytesRead;
                        while ((bytesRead = cs.Read(decryptedBytes, 0, decryptedBytes.Length)) > 0)
                        {
                            buffer = decryptedBytes.Take(bytesRead).ToArray();
                        }
                    }
                }
                return buffer;
            }
        }
    }

    public static async Task<byte[]> DecryptAsync(byte[] ciphertext, byte[] encryptionKey, byte[] iv)
    {
        var taskArray = new Task<int>[ciphertext.Length / 1024 + 1];
        for (int i = 0; i < taskArray.Length; i++)
        {
            int startIndex = i * 1024;
            int endIndex = Math.Min((i + 1) * 1024, ciphertext.Length);
            taskArray[i] = Task.Run(() =>
            {
                using (var aes = Aes.Create())
                {
                    aes.Key = encryptionKey;
                    aes.IV = iv;

                    using (var decryptor = aes.CreateDecryptor())
                    {
                        var buffer = new byte[endIndex - startIndex];
                        using (var ms = new MemoryStream(ciphertext, startIndex, endIndex - startIndex))
                        {
                            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                            {
                                int bytesRead;
                                while ((bytesRead = cs.Read(buffer, 0, buffer.Length)) > 0)
                                {
                                    return bytesRead;
                                }
                            }
                        }
                    }
                }
            });
        }

        await Task.WhenAll(taskArray);

        var decryptedBytes = new byte[ciphertext.Length];
        for (int i = 0; i < taskArray.Length; i++)
        {
            int startIndex = i * 1024;
            int endIndex = Math.Min((i + 1) * 1024, ciphertext.Length);
            buffer = new byte[endIndex - startIndex];
            bytesRead = await taskArray[i];
            Array.Copy(buffer, decryptedBytes, bytesRead);
        }
        return decryptedBytes;
    }
}
