                throw new ArgumentException("File path is required.");

            using var stream = await GetFileStream(filePath, downloadUrl);
            using var compressedStream = new MemoryStream();

            // Check file integrity
            if (!CheckFileIntegrity(stream))
                return null;

            await stream.CopyTo(compressedStream);

            compressedStream.Position = 0;
            using var compressedFileStream = new FileStream(filePath, FileMode.CreateNew, FileAccess.Write);
            using var decompressor = new Inflater();
            using var buffer = new MemoryStream();

            // Decompress and deserialize
            decompressor.Inflate(buffer, compressedStream);
            buffer.Position = 0;

            CustomDataStructure data;
            try
            {
                var formatter = new BinaryFormatter();
                data = (CustomDataStructure)formatter.Deserialize(buffer);
            }
            catch (SerializationException ex)
            {
                throw new InvalidOperationException("Deserialization failed.", ex);
            }

            return data;
        }

        private async Task<Stream> GetFileStream(string filePath, string downloadUrl)
        {
            if (!string.IsNullOrEmpty(downloadUrl))
            {
                // Download file from external source
                using var webClient = new WebClient();
                await webClient.DownloadFileTaskAsync(downloadUrl, filePath);
            }
            else
            {
                // Load local file
                using var fileStream = File.OpenRead(filePath);
                return fileStream;
            }
