lazy_static! {
    static ref LOGGING_SERVICE: log4rs::Logger = {
        let config = log4rs::config::Config::from_string(
            r#"
                appender.console.type = ConsoleAppender
                appender.console.layout.type = PatternLayout
                appender.console.layout.pattern = "%d{%Y-%m-%dT%H:%M:%S} [%t] %-5p %c{1.} : %m%n%wex
            "#,
        ).unwrap();
        let logger = log4rs::Logger::new("main", config.root().clone());
        logger.set_min_level(log4rs::LevelFilter::Info);

        logger
    };
}

pub fn set_directory(path: &str) {
    let temp_dir_path = format!("{}/{}", fs::temp_dir().display(), path);
    let mut dir_path = temp_dir_path.clone();

    let env_var_name = "DIR_PATH";
    let mut value = dirs::get-dir-path().unwrap_or_default();

    if !Path::new(&value).exists() {
        match fs::create_dir_all(&dir_path) {
            Ok(_) => info!("Directory created: {}", dir_path),
            Err(e) => warn!("Failed to create directory: {} ({})", e, dir_path),
            _ => {}
        }
        value = dir_path.clone();
    }

    if let Some(old_value) = std::env::var_os(env_var_name) {
        value.push(',');
        value.push_str(old_value.as_ref().unwrap());
    }

    match std::env::set_var(env_var_name, value) {
        Ok(_) => info!("Environment variable set: {}", env_var_name),
        Err(e) => warn!("Failed to set environment variable: {} ({})", e, env_var_name),
    }
}

fn clean_up() -> Result<(), Box<dyn std::error::Error>> {
    if let Some(dir_path) = dirs::get_dir-path().as_deref() {
        match fs::remove_dir_all(dir_path) {
            Ok(_) => info!("Temporary directory cleaned up: {}", dir_path),
            Err(e) => warn!("Failed to clean up temporary directory: {} ({})", e, dir_path),
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_set_directory() {
        set_directory("test");
        assert!(std::env::var("DIR_PATH").is_ok());
    }

    #[test]
    fn test_clean_up() {
        let _ = dirs::get_dir-path();
        clean_up().unwrap();
    }
}
