#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
} record;

record* create_records(int count) {
    record* records = (record*)malloc(count * sizeof(record));
    for (int i = 0; i < count; i++) {
        records[i].key = rand() % 100 + 1; // Random value between 1 and 100
    }
    return records;
}

void find_max(int* arr, int size) {
    record max_record;
    max_record.key = *arr;
    for (int i = 0; i < size; i++) {
        if (*(arr + i) > max_record.key) {
            max_record.key = *(arr + i);
        }
    }
    printf("Largest integer: %d\n", max_record.key);
}

int main() {
    int* arr;
    int size;
    srand(time(NULL)); // Initialize random seed

    printf("Enter the number of integers: ");
    scanf("%d", &size);

    if (size > 1000) {
        printf("Error: Maximum allowed size is 1000.\n");
        return -1;
    }

    arr = (int*)malloc(size * sizeof(int));

    for (int i = 0; i < size; i++) {
        scanf("%d", arr + i);
    }

    record* records = create_records(size);

    find_max(arr, size);

    free(arr);
    free(records);

    return 0;
}
