import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;

public class HashingService {
    private final int MAX_CACHE_SIZE = 1000;
    private Map<String, String> cache = new HashMap<>();
    private ExternalHashingServiceClient client;
    private LoggingService loggingService;

    public String getHash(String input) throws Exception {
        if (input == null || input.isEmpty()) {
            return null;
        }

        String md5 = computeMD5(input);
        String sha256 = computeSHA256(input);

        loggingService.logInputAndOutput(input, md5, sha256);

        return new StringBuilder(md5).append(":").append(sha256).toString();
    }

    private String computeMD5(String input) throws Exception {
        if (cache.containsKey(input)) {
            return cache.get(input);
        }

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = input.getBytes();
            byte[] hashBytes = md.digest(bytes);

            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) {
                    sb.append('0');
                }
                sb.append(hex);
            }

            cache.put(input, sb.toString());
            return sb.toString();

        } catch (NoSuchAlgorithmException e) {
            // Handle MD5 algorithm not found
            throw new Exception("MD5 algorithm not supported", e);
        }
    }

    private String computeSHA256(String input) throws Exception {
        if (cache.containsKey(input)) {
            return cache.get(input);
        }

        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] bytes = input.getBytes();
            byte[] hashBytes = md.digest(bytes);

            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) {
                    sb.append('0');
                }
                sb.append(hex);
            }

            cache.put(input, sb.toString());
            return sb.toString();

        } catch (NoSuchAlgorithmException e) {
            // Handle SHA-256 algorithm not found
            throw new Exception("SHA-256 algorithm not supported", e);
        }
    }
}
