    pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);

    // Define array of record structures with dynamic memory allocation
    Record* records = (Record*)malloc(sizeof(Record)*10);
    for(int i=0; i<10; i++) {
        records[i].value = 0;
        records[i].timestamp = time(NULL);
