            pthread_mutex_lock(&mutex);
            for(int i=0; i<10; i++) {
                if(records[i].value != 0) {
                    // Update timestamp for each record
                    records[i].timestamp = time(NULL);
                }
            }
            pthread_mutex_unlock(&mutex);
        }

        usleep(100000); // Simulate delay to allow for updates and thread safety
    }

    free(records);
    close(sock);

    return NULL;
}

