void* init_data(int max_memory, int offset_max, int key_max) {
    pthread_mutex_lock(&mutex);

    offsets = (int*)malloc(max_memory / sizeof(int));
    if (!offsets) {
        fprintf(stderr, "Error: failed to allocate memory for offsets.\n");
        return NULL;
    }

    keys = (int*)malloc(max_memory / sizeof(int));
    if (!keys) {
        free(offsets);
        offsets = NULL;
        fprintf(stderr, "Error: failed to allocate memory for keys.\n");
        return NULL;
    }

    records = (record_t**)malloc(max_memory / sizeof(record_t*));
    if (!records) {
        free(keys);
        keys = NULL;
        free(offsets);
        offsets = NULL;
        fprintf(stderr, "Error: failed to allocate memory for records.\n");
        return NULL;
    }

    // Initialize arrays
    int i;
    for (i = 0; i < max_memory / sizeof(int); i++) {
        offsets[i] = rand() % offset_max;
        keys[i] = rand() % key_max;

        record_t* temp_rec = (record_t*)malloc(sizeof(record_t));
        if (!temp_rec) {
            for (int j = 0; j < i; j++) {
                free((void*)records[j]);
            }
            free(records);
            records = NULL;
            free(keys);
            keys = NULL;
            free(offsets);
            offsets = NULL;
            fprintf(stderr, "Error: failed to allocate memory for record.\n");
            return NULL;
        }

        temp_rec->value = rand() % RAND_MAX;
        records[i] = temp_rec;
    }

    pthread_mutex_unlock(&mutex);

    // Store initialized data to disk
    FILE* file = fopen("data.txt", "w+");
    if (file) {
        for (i = 0; i < max_memory / sizeof(int); i++) {
            fprintf(file, "%d %d %d\n", offsets[i], keys[i], records[i]->value);
        }
        fclose(file);
    } else {
        // Recovery mechanism: restore data from disk
        file = fopen("data.txt", "r");
        if (file) {
            int i;
            char line[256];
            while (fgets(line, sizeof(line), file)) {
                int offset, key, value;
                sscanf(line, "%d %d %d\n", &offset, &key, &value);

                // Allocate memory for new record
                record_t* temp_rec = (record_t*)malloc(sizeof(record_t));
                if (!temp_rec) {
                    fclose(file);
                    file = NULL;
                    fprintf(stderr, "Error: failed to allocate memory for record.\n");
                    return NULL;
                }

                temp_rec->value = value;
                records[offset] = temp_rec;
            }
            fclose(file);
        } else {
            // Log error and exit
            fprintf(stderr, "Error: unable to recover data from disk.\n");
            return NULL;
        }
    }

    return (void*)records;
}

// Thread-safe function to free allocated memory
void* free_data(void* ptr) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < max_memory / sizeof(int); i++) {
        if (records[i]) {
            free((void*)records[i]);
        }
    }

    free(records);
    free(keys);
    free(offsets);

    pthread_mutex_unlock(&mutex);

    return NULL;
}

