#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>

#define MAX_MEMORY 1024*1024*10 // 10MB
#define RANDOM_RANGE 100

typedef struct {
    int key;
} record_t;

record_t *records = NULL;
long *offsets = NULL;
int *keys = NULL;

void free_memory() {
    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);
}

int check_memory_usage(size_t size) {
    static size_t peak_usage = 0;
    static size_t current_usage = 0;

    current_usage += size;
    if (current_usage > peak_usage) peak_usage = current_usage;

    return current_usage <= MAX_MEMORY && peak_usage <= MAX_MEMORY;
}

int main() {
    int max_memory = MAX_MEMORY;
    int i, j;
    record_t *record;
    long *offset;
    int *key;

    // Initialize memory allocation limit
    if (!check_memory_usage(0)) return -1;

    while (1) {
        // Allocate and initialize arrays
        size_t offsets_size = sizeof(long);
        size_t keys_size = sizeof(int);
        if (!check_memory_usage(offsets_size + keys_size)) break;
        offsets = (long*)malloc(offsets_size);
        keys = (int*)malloc(keys_size);

        for (i = 0; i < 100; i++) {
            // Randomly set values
            for (j = 0; j < RANDOM_RANGE; j++) {
                offset = &offsets[i];
                key = &keys[i];
                *offset = i;
                *key = i;

                record = (record_t*)malloc(sizeof(record_t));
                if (!check_memory_usage(sizeof(record_t))) break;
                record->key = rand() % RANDOM_RANGE;
            }
        }

        // Release allocated memory
        for (i = 0; i < 100; i++) {
            free(records + i);
        }
        free(offsets);
        free(keys);

        // Recheck maximum memory usage
        max_memory /= 2;
    }

    return 0;
}
