#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>

// Define the record structure
typedef struct {
    double value;
    char* string;
} Record;

// Function to dynamically generate and initialize data records
void* generateRecords(size_t maxMemoryLimit, int* totalRecords) {
    // Initialize memory pool with specified maximum limit
    void* memoryPool = malloc(maxMemoryLimit);
    if (memoryPool == NULL) {
        return NULL;
    }

    // Initialize record count
    *totalRecords = 0;

    // Create a thread-safe mutex for managing the memory pool
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    while (1) {
        size_t requiredMemory = sizeof(Record);

        // Check if there's enough space in the memory pool
        if (pthread_mutex_lock(&lock)) {
            // Handle errors
            return NULL;
        }

        if (requiredMemory > maxMemoryLimit - sizeof(Record)*(*totalRecords)) {
            pthread_mutex_unlock(&lock);
            break;
        }

        // Allocate a new record and initialize its fields
        Record* record = (Record*)malloc(requiredMemory);
        record->value = rand() / (double)RAND_MAX; // Generate random double value
        char string[32]; // Dynamic allocation for string
        sprintf(string, "Record %d", *totalRecords);
        record->string = strdup(string);

        // Encrypt the record using AES-256-CBC and RSA with SHA1
        unsigned char* encryptedData = NULL;
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_add_cipher(ctx, EVP_aes_256_cbc());
        EVP_add_digest(ctx, EVP_sha1());

        int encryptedDataLength = 0;
        int recordLength = sizeof(Record);
        if (EVP_EncryptInit_ex(ctx, NULL, NULL, &record->value, &record->string)) {
            // Handle errors
            return NULL;
        }
        unsigned char* output = malloc(recordLength + EVP_get_cipher_block_size(EVP_CIPHER_CTX_get_cipher(ctx)));
        if (!EVP_EncryptUpdate(ctx, output, &encryptedDataLength, record, recordLength)) {
            // Handle errors
            return NULL;
        }
        encryptedData = malloc(encryptedDataLength);
        memcpy(encryptedData, output, encryptedDataLength);

        // Decrypt the record using RSA with SHA1 and AES-256-CBC
        EVP_add_digest_alias(ctx, EVP_sha1());

        if (EVP_DecryptInit_ex(ctx, NULL, NULL, &record->value, &record->string)) {
            // Handle errors
            return NULL;
        }
        unsigned char* decryptedData = malloc(recordLength);
        if (!EVP_DecryptUpdate(ctx, decryptedData, &encryptedDataLength, record, recordLength)) {
            // Handle errors
            return NULL;
        }

        // Store the encrypted data in the memory pool and update the record count
        pthread_mutex_unlock(&lock);

        memcpy(memoryPool + sizeof(Record)*(*totalRecords), encryptedData, encryptedDataLength);
        free(record->string);
        free(record);
        *totalRecords += 1;

        // Periodically log resource usage statistics, such as peak memory usage
        if (*totalRecords % 100 == 0) {
            printf("Peak memory usage: %zu bytes\n", maxMemoryLimit);
        }
    }

    return memoryPool;
}

void freeRecords(void* memoryPool, int totalRecords) {
    // Free all allocated memory
    for (int i = 0; i < totalRecords; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        memcpy(record, memoryPool + sizeof(Record)*i, sizeof(Record));
        free(record->string);
        free(record);

        // Periodically log resource usage statistics
        if (i % 100 == 0) {
            printf("Peak memory usage: %zu bytes\n", i * sizeof(Record));
        }
    }

    free(memoryPool);
}
