typedef struct {
    int key;
    float value;
    char* str;
} data_point;

data_point* init_data_structure(int num_points) {
    if (num_points <= 0) return NULL;

    data_point* points = (data_point*)malloc(num_points * sizeof(data_point));
    if (!points) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    int* keys = (int*)malloc(num_points * sizeof(int));
    float* values = (float*)malloc(num_points * sizeof(float));
    char** strs = (char**)malloc(num_points * sizeof(char*));

    for (int i = 0; i < num_points; i++) {
        points[i].key = i;
        points[i].value = (rand() / (RAND_MAX + 1.0f)) * 100;
        char str[101];
        sprintf(str, "Data Point %d", i);
        strs[i] = (char*)malloc(strlen(str) + 1);
        strcpy(strs[i], str);

        keys[i] = i;
        values[i] = points[i].value;
    }

    free(keys);
    free(values);
    return points;
}

void add_data_point(data_point** points, int num_points, int new_key, float new_value) {
    if (!points || num_points <= 0) return;

    data_point* new_point = (data_point*)malloc(sizeof(data_point));
    new_point->key = new_key;
    new_point->value = new_value;
    char str[101];
    sprintf(str, "Data Point %d", new_key);
    new_point->str = (char*)malloc(strlen(str) + 1);
    strcpy(new_point->str, str);

    *points = (data_point*)realloc(*points, ++num_points * sizeof(data_point));
    memcpy(&((*points)[num_points - 2]), new_point, sizeof(data_point));

    free(new_point->str);
}

void remove_data_point(data_point** points, int num_points, int key_to_remove) {
    if (!points || num_points <= 0) return;

    for (int i = 0; i < num_points; i++) {
        if ((*points)[i].key == key_to_remove) {
            free((*points)[i].str);
            memset(&((*points)[i]), 0, sizeof(data_point));
            memmove(&(*points)[i], &(*points)[i + 1], (num_points - i - 1) * sizeof(data_point));

            (*points) = (data_point*)realloc(*points, --num_points * sizeof(data_point));
            return;
        }
    }
}

void free_data_structure(data_point* points, int num_points) {
    for (int i = 0; i < num_points; i++) {
        free(points[i].str);
    }

    free(points);
}
