```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

#define MAX_MEMORY 1024*1024 //1MB
#define RANDOM_VALUE_RANGE 1000

// Structure to represent a DNS record
typedef struct {
    int value;
} record;

// Thread-safe mechanism for managing arrays and records
record** records = NULL;
int num_records = 0;
pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;

void free_records() {
    if (records != NULL) {
        for (int i = 0; i < num_records; i++) {
            free(records[i]);
        }
        free(records);
        records = NULL;
        num_records = 0;
    }
}

// Function to perform DNS resolution and return the IP address
u_char* dns_resolution(char* hostname) {
    // Check if the allocated memory exceeds the limit
    if (num_records >= MAX_MEMORY / sizeof(record*)) {
        ERR_error_string(ERR_get_error(), NULL);
        return (u_char*) "Error: Memory limit exceeded";
    }

    // Initialize arrays and records
    record** new_records = realloc(records, (num_records + 1) * sizeof(record*));
    if (new_records == NULL) {
        ERR_error_string(ERR_get_error(), NULL);
        return (u_char*) "Error: Memory allocation failed";
    }
    records = new_records;

    // Initialize a new record
    record* new_record = malloc(sizeof(record));
    if (new_record == NULL) {
        ERR_error_string(ERR_get_error(), NULL);
        return (u_char*) "Error: Memory allocation failed";
    }
    new_record->value = rand() % RANDOM_VALUE_RANGE;
    records[num_records++] = new_record;

    // Perform DNS resolution using OpenSSL
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        ERR_error_string(ERR_get_error(), NULL);
        return (u_char*) "Error: OpenSSL initialization failed";
    }

    // Resolve the hostname and get the IP address
    X509_NAME* name = X509_NAME_create();
    X509* cert = d2i_X509(name);
    if (!cert) {
        ERR_error_string(ERR_get_error(), NULL);
        return (u_char*) "Error: DNS resolution failed";
    }

    // Handle errors and return the IP address
    u_char* ip_address = (u_char*) inet_ntoa(cert->general_name.gn_value);
    free(cert);
    X509_NAME_free(name);
    SSL_CTX_free(ctx);

    return ip_address;
}

int main() {
    char* hostname = "example.com";
    u_char* ip_address = dns_resolution(hostname);
    printf("%s", ip_address);
    free_records();
    return 0;
}
