#define MAX_MEMORY 1000000 // adjust this value during runtime
#define LOG_INTERVAL 10 // log statistics every 10 records

typedef struct {
    double value;
    char* string;
} Record;

Record** pool = NULL; // dynamically allocated array of Record pointers
int pool_size = 0; // current size of the record pool
int max_records = 0; // maximum number of records allowed

void init_pool(int max_size) {
    if (max_size > MAX_MEMORY / sizeof(Record*)) {
        printf("Warning: Maximum memory limit exceeded. Reducing pool size.\n");
        max_size = MAX_MEMORY / sizeof(Record*);
    }
    pool_size = 0;
    max_records = max_size;
}

void add_record(double value, char* string) {
    if (pool_size >= max_records) {
        printf("Error: Pool full. Cannot add new record.\n");
        return;
    }

    Record* record = malloc(sizeof(Record));
    record->value = value;
    record->string = strdup(string);

    // compress data using zlib
    unsigned char* compressed_data = NULL;
    int compr_len = compress((char*)record, sizeof(Record), &compressed_data);
    if (compr_len < 0) {
        printf("Error: Compression failed.\n");
        free(record->string);
        free(record);
        return;
    }

    // encrypt data using AES
    unsigned char* encrypted_data = NULL;
    int enc_len = AES_encrypt(compressed_data, compr_len, &encrypted_data);
    if (enc_len < 0) {
        printf("Error: Encryption failed.\n");
        free(compressed_data);
        free(record->string);
        free(record);
        return;
    }

    record->string = NULL; // mark string as freed
    free(record);

    pool[pool_size++] = record;

    // log resource usage statistics every 10 records
    if (pool_size % LOG_INTERVAL == 0) {
        printf("Logged: %d records, %d bytes used.\n", pool_size, compr_len + enc_len);
    }
}

void free_pool() {
    for (int i = 0; i < pool_size; i++) {
        Record* record = pool[i];
        if (record->string != NULL) {
            free(record->string);
        }
        free(record);
    }

    free(pool);
}
