    for (int i = key_range_start; i <= key_range_end; i++) {
        keys[i - key_range_start] = rand() % (key_range_end - key_range_start + 1);
    }

    // Allocate memory for record array
    int num_records = max_offset * (key_range_end - key_range_start + 1) / 100;
    record_t* records = init_records(num_records);

    if ((size_t)records > max_memory_usage) {
        free(offsets);
        free(keys);
        return -2;
    }

    // Initialize and fill in record array
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[rand() % (key_range_end - key_range_start + 1)];
        records[i].offset = offsets[rand() % max_offset];
    }

    // Convert JPEG to PDF and save the output
    if (system("convert input.jpg output.pdf") != 0) {
        printf("Failed to convert image: %s\n", file_name);
        return -3;
    }

    // Deserialize byte array and write to a new file
    FILE* file = fopen(output_file_name, "wb");
    fwrite(byte_array, sizeof(unsigned char), strlen((char*)byte_array), file);
    fclose(file);

    return 0;
}

void free_allocated_memory(long* offsets, int* keys, record_t* records) {
    if (offsets) {
        free(offsets);
    }
    if (keys) {
        free(keys);
    }
    if (records) {
        free(records);
    }
}
