int validate_int(int num) {
    if (num < -1000 || num > 1000)
        return 0;
    return 1;
}

int find_largest_int(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void read_and_validate_integers(int** arr, int* size) {
    *size = 0;
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        if (sscanf(buffer, "%d", &(*arr)[(*size)]++) == 1)
            if (!validate_int((*arr)[(*size] - 1]))
                break;
    }
}

void print_largest_integer(int* arr, int size) {
    printf("The largest integer is: %d\n", find_largest_int(arr, size));
    free(arr);
}

int main() {
    int* arr = NULL;
    int size = 0;
    read_and_validate_integers(&arr, &size);
    print_largest_integer(arr, size);
    return 0;
}
