    void* records = NULL;
    size_t total_memory_used = 0;

    for (size_t i = 0; i < count; i++) {
        dataRecord record;

        // Ensure the total memory usage does not exceed the specified maximum limit
        if ((total_memory_used + sizeof(dataRecord)) > max_memory_limit) {
            return NULL; // Return an error or handle it as needed
        }

        // Dynamically generate and initialize a pool of dataRecord structures
        record.value = rand() / (double)RAND_MAX;
        record.string = malloc(strlen("Example string") + 1); // Allocate memory for the string
        strcpy(record.string, "Example string");

        if (!records) {
            records = malloc(sizeof(dataRecord)); // Initialize the first record
        } else {
            dataRecord* prev_record = (dataRecord*)records;

            while (((dataRecord*)records + i)->string != NULL && ((dataRecord*)records + i - 1)->value > record.value) {
                size_t memory_size = ((dataRecord*)records + i - 1)->string ? sizeof(dataRecord) : sizeof(dataRecord) - sizeof(char*) + strlen(((dataRecord*)records + i - 1)->string);

                // Free the previous records to prevent memory fragmentation
                free(((dataRecord*)records + i - 1).string);
                free((char*)records);
                records = malloc(memory_size); // Reallocate the records with updated sizes
                prev_record = (dataRecord*)records;
            }

            ((dataRecord*)records + i) = record; // Update the current record pointer
        }

        total_memory_used += sizeof(dataRecord) + strlen(record.string);
    }

    return records;
}

