#include <stdio.h>
#include <stdlib.h>
#include <thread>
#include <random>

// Define a struct to represent record structures
struct Record {
    int key;
    long offset;
};

// Function to manage memory allocation for arrays and records
void* allocateMemory(size_t size, int maxLimit) {
    // Check if the total allocated memory exceeds the maximum limit
    static size_t totalAllocated = 0;
    totalAllocated += size;
    if (totalAllocated > maxLimit) {
        return NULL; // Return NULL if the total allocated memory exceeds the maximum limit
    }

    // Allocate memory using a thread-safe mechanism (e.g., POSIX threads)
    void* ptr = malloc(size);
    if (!ptr) {
        // Handle allocation failure
        perror("Memory allocation failed");
        return NULL;
    }
    return ptr;
}

// Function to initialize and populate record structures with random values
void initializeRecords(Record** records, size_t numRecords) {
    // Initialize a random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 100);

    for (size_t i = 0; i < numRecords; ++i) {
        Record* record = records[i];
        // Initialize the 'int' field with a random value within the given range
        record->key = dis(gen);
        // Initialize the 'long' offset field with a random value
        record->offset = static_cast<long>(dis(gen));
    }
}

// Function to free allocated memory when done
void freeMemory(void** ptrs, size_t numPtrs) {
    for (size_t i = 0; i < numPtrs; ++i) {
        if (ptrs[i]) {
            free(ptrs[i]);
            ptrs[i] = NULL;
        }
    }
}

// Function to serialize records into a disk file
void serializeRecords(const Record** records, size_t numRecords, const char* filename) {
    // Open the file in binary mode
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    // Write the serialized record data to the file
    fwrite(records, sizeof(Record), numRecords, file);
    fclose(file);
}

// Function to deserialize records from a disk file
void deserializeRecords(Record** records, size_t numRecords, const char* filename) {
    // Open the file in binary mode
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    // Read the serialized record data from the file
    fread(records, sizeof(Record), numRecords, file);
    fclose(file);
}
