    LtePhyMessage* message = (LtePhyMessage*)arg;

    message->ue_id = rand() % 1000 + 1;
    message->cell_id = rand() % 50 + 1;

    message->cqis_count = rand() % 8 + 1; // Generate random number of CQIs
    message->cqis = (int*)malloc(message->cqis_count * sizeof(int));

    for (int i = 0; i < message->cqis_count; i++) {
        message->cqis[i] = rand() % 40 - 5; // Generate random CQI values
    }

    return message;
}

LtePhyMessage** generate_messages(int num_messages) {
    pthread_t threads[1000]; // Initialize array of threads for concurrent processing
    LtePhyMessage** messages = NULL;
    int i, result;

    if (num_messages > 1000)
        num_messages = 1000; // Limit the number of messages

    messages = (LtePhyMessage**)malloc(num_messages * sizeof(LtePhyMessage*));

    for (i = 0; i < num_messages; i++) {
        LtePhyMessage* message = NULL;

        if ((result = pthread_create(&threads[i], NULL, generate_message, &message)) != 0) {
            // Log memory allocation failure
            FILE* log_file = fopen("memory_log.txt", "a");
            fprintf(log_file, "Memory allocation failed at index %d.\n", i);
            fclose(log_file);

            return NULL;
        }

        pthread_join(threads[i], (void**)&message); // Wait for thread to complete

        messages[i] = message;
    }

    return messages;
}
