#include <zlib.h>
#include <openssl/aes.h>

#define MAX_RECORDS 1000
#define MAX_RECORD_SIZE 1024
#define MAX_MEMORY_LIMIT 50000000

typedef struct {
    double value;
    char string[MAX_RECORD_SIZE];
} DataRecord;

DataRecord *data_records = NULL;
int record_count = 0;
size_t total_memory_usage = 0;
int max_memory_limit = MAX_MEMORY_LIMIT;

void free_data_records() {
    for (int i = 0; i < record_count; i++) {
        free(data_records[i].string);
    }
    free(data_records);
}

void log_resource_usage() {
    printf("Peak memory usage: %zu bytes\n", total_memory_usage);
}

void *malloc_thread_safe(size_t size) {
    void *ptr = malloc(size);
    if (ptr != NULL) {
        total_memory_usage += size;
        if (total_memory_usage > max_memory_limit) {
            // Handle out-of-memory situation
        }
    }
    return ptr;
}

int encrypt_data_record(const DataRecord *record, unsigned char **ciphertext) {
    int ciphertext_len = 0;
    AES_KEY aes_key;
    OpenSSL_add_all_algorithms();
    EVP_Encode_CTX *encode_ctx = NULL;
    if (EVP_DecryptInit_ex(&aes_key, "AES-128-CBC", NULL, NULL) != 1) {
        // Handle encryption failure
        return -1;
    }
    ciphertext_len = EVP_EncryptUpdate(encode_ctx, NULL, &ciphertext_len, record->string, strlen(record->string));
    *ciphertext = malloc(ciphertext_len + AES_BLOCK_SIZE);
    EVP_EncryptFinal_ex(&aes_key, (*ciphertext) + ciphertext_len, &ciphertext_len);
    return 0;
}

int compress_data_record(const DataRecord *record, unsigned char **compressed) {
    z_stream stream;
    byte out[MAX_RECORD_SIZE];
    int ret = inflateInit2(&stream, -15);
    if (ret != Z_OK) {
        // Handle compression failure
        return -1;
    }
    stream.next_in = (Bytef *) record->string;
    stream.avail_in = strlen(record->string);
    stream.total_in = strlen(record->string);
    do {
        ret = inflate(&stream, Z_NO_FLUSH);
        if (ret != Z_OK) {
            // Handle compression failure
            return -1;
        }
    } while (stream.avail_out == 0);
    *compressed = malloc(stream.total_out + 1);
    memcpy(*compressed, stream.next_out, stream.total_out);
    (*compressed)[stream.total_out] = '\0';
    inflateEnd(&stream);
    return 0;
}

int main() {
    int i;
    for (i = 0; i < MAX_RECORDS; i++) {
        DataRecord *new_record = malloc_thread_safe(sizeof(DataRecord));
        new_record->value = (double) i;
        sprintf(new_record->string, "Record %d", i);
        if (encrypt_data_record(new_record, NULL) != 0) {
            // Handle encryption failure
            return -1;
        }
        compress_data_record(new_record, NULL);
    }
    log_resource_usage();
    free_data_records();
    return 0;
}
