['```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int intValue;
    char charArray[20];
    long charArrayLength;
} record;

void log_error(const char *message) {
    time_t current_time = time(NULL);
    printf("[ERROR] %ld: %s\n", current_time, message);
}

void *allocate_memory(int num_records, int min_value, int max_value) {
    void *memory_block = NULL;

    // Allocate memory for offset values
    long *offset_values = (long *)malloc(num_records * sizeof(long));
    if (!offset_values) {
        log_error("Failed to allocate memory for offset values");
        return NULL;
    }

    // Initialize offset values with random values within the given range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offset_values[i] = min_value + rand() % ((max_value - min_value) + 1);
    }

    // Allocate memory for keys
    int *keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        log_error("Failed to allocate memory for keys");
        free(offset_values);
        return NULL;
    }

    // Initialize keys with random values within the given range
    for (int i = 0; i < num_records; i++) {
        keys[i] = min_value + rand() % ((max_value - min_value) + 1);
    }

    // Allocate memory for record structures
    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        log_error("Failed to allocate memory for records");
        free(offset_values);
        free(keys);
        return NULL;
    }

    // Initialize records with random values and lengths
    long *char_array_lengths = (long *)malloc(num_records * sizeof(long));
    if (!char_array_lengths) {
        log_error("Failed to allocate memory for character array lengths");
        free(records);
        free(offset_values);
        free(keys);
        return NULL;
    }

    // Initialize record structures and their char array lengths
    for (int i = 0; i < num_records; i++) {
        records[i].intValue = min_value + rand() % ((max_value - min_value) + 1);
        records[i].charArrayLength = rand() % 20;
        memset(records[i].charArray, '\0', sizeof(records[i].charArray));
    }

    // Combine memory blocks and return the combined block
    memory_block = (void *)malloc((num_records * sizeof(long)) +
                                     (num_records * sizeof(int)) +
                                     (num_records * sizeof(record)) +
                                     (num_records * sizeof(long)));
    if (!memory_block) {
        log_error("Failed to allocate memory for the combined block");
        free(char_array_lengths);
        free(records);
        free(offset_values);
        free(keys);
        return NULL;
    }

    // Copy allocated data into the combined memory block
    memcpy(memory_block, offset_values, num_records * sizeof(long));
    memcpy((void *)memory_block + (num_records * sizeof(long)), keys, num_records * sizeof(int));
    memcpy((void *)memory_block + (num_records * sizeof(long) + num_records * sizeof(int)),
           records, num_records * sizeof(record));
    memcpy((void *)memory_block +
               (num_records * sizeof(long) + num_records * sizeof(int) + num_records * sizeof(record)),
           char_array_lengths, num_records * sizeof(long));

    free(offset_values);
    free(keys);
    free(records);
    free(char_array_lengths);

    return memory_block;
}
