    int* keys = (int*)malloc(key_size * sizeof(int));
    for (int i = 0; i < key_size; i++) {
        keys[i] = i;
    }

    // Dynamically allocate memory for record array
    Record** records = (Record**)malloc(record_num * sizeof(Record*));
    for (int i = 0; i < record_num; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->value = rand() % 100;
    }

    // Free dynamically allocated memory
    free(offsets);
    free(keys);

    return records;
}

