['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

struct data {
    int intValue;
    char* string;
    struct node* list;
};

struct node {
    int value;
    struct node* next;
};

void insertNode(struct node** head, int value) {
    if (*head == NULL || (*head)->value > value) {
        struct node* newNode = (struct node*) malloc(sizeof(struct node));
        newNode->value = value;
        newNode->next = *head;
        *head = newNode;
    } else if ((*head)->next != NULL) {
        insertNode(&((*head)->next), value);
    }
}

void* createDataArray(void* arg) {
    int count = *((int*) arg);
    struct data* dataArray = (struct data*) malloc(count * sizeof(struct data));
    if (!dataArray) return NULL;

    pthread_mutex_lock(NULL); // No mutex is needed as we're not accessing shared resources
    for (int i = 0; i < count; i++) {
        dataArray[i].intValue = rand() % 100;
        dataArray[i].string = malloc(50 * sizeof(char));
        if (!dataArray[i].string) {
            free(dataArray);
            return NULL;
        }
        strcpy(dataArray[i].string, "random");
        dataArray[i].list = NULL;
    }
    pthread_mutex_unlock(NULL);

    return (void*) dataArray;
}

int main() {
    int count = 10; // Define the size of the data array
    int* arg = &count;

    pthread_t thread;
    if (pthread_create(&thread, NULL, createDataArray, arg) != 0) {
        printf("Error creating thread.\n");
        return -1;
    }

    void* result;
    if (pthread_join(thread, &result)) {
        printf("Error joining thread.\n");
        return -1;
    }

    struct data* dataArray = (struct data*) result;

    // Free the dynamically allocated memory
    for (int i = 0; i < count; i++) {
        free(dataArray[i].string);
    }
    free(dataArray);

    return 0;
}
