typedef struct {
    int value;
    char* str;
} Record;

Record** create_records(int num_records) {
    Record** records = (Record**)malloc(num_records * sizeof(Record*));
    for (int i = 0; i < num_records; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->value = rand() % 100;
        char buffer[10];
        sprintf(buffer, "record_%d", i);
        records[i]->str = strdup(buffer);
    }
    return records;
}

void resize_records(Record** records, int new_num_records) {
    Record** new_records = (Record**)realloc(records, new_num_records * sizeof(Record*));
    if (!new_records) {
        printf("Memory allocation failed.\n");
        return;
    }
    for (int i = 0; i < new_num_records; i++) {
        if (i >= num_records) {
            new_records[i] = (Record*)malloc(sizeof(Record));
            new_records[i]->value = rand() % 100;
            char buffer[10];
            sprintf(buffer, "record_%d", i);
            new_records[i]->str = strdup(buffer);
        }
    }
    free(records);
    records = new_records;
}

void free_records(Record** records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i]->str);
        free(records[i]);
    }
    free(records);
}

int main() {
    srand(time(NULL));
    Record** records;
    int num_records;

    printf("Enter the number of records: ");
    scanf("%d", &num_records);

    while (1) {
        records = create_records(num_records);

        // handle dynamic changes in the number of records
        printf("Do you want to resize? (y/n): ");
        char response;
        scanf(" %c", &response);
        if (response == 'n') break;

        printf("Enter new number of records: ");
        int new_num_records;
        scanf("%d", &new_num_records);

        resize_records(records, new_num_records);
        num_records = new_num_records;
    }

    free_records(records, num_records);
    return 0;
}
