['Here is the C code for the task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structure for record
typedef struct {
    int value;
    char *str;
} Record;

// Function to dynamically manage memory and initialize arrays and data structures
void* allocateRecords(int n) {
    // Calculate total size required
    size_t total_size = sizeof(Record*) * n + sizeof(char*) * n;

    // Allocate memory for array of pointers
    Record** records = (Record**)malloc(total_size);
    if (!records) return NULL;  // Error checking

    // Initialize each record's int field and string field with a unique index
    for (int i = 0; i < n; i++) {
        Record* r = (Record*)malloc(sizeof(Record));
        r->value = rand() % 100;
        char str[5];
        sprintf(str, "%d", i);
        r->str = strdup(str);
        records[i] = r;
    }
    return records;
}

// Function to dynamically resize array of pointers
void* reallocateRecords(void** old_records, int n) {
    // Calculate total size required
    size_t total_size = sizeof(void*) * (n + 1);

    // Allocate new memory for array of pointers
    void** new_records = (void**)malloc(total_size);
    if (!new_records) return NULL;  // Error checking

    // Copy data from old array to new array
    for (int i = 0; i < n; i++) {
        new_records[i] = old_records[i];
    }

    // Free memory of old array
    free(old_records);

    return new_records;
}

// Function to export records to JSON file
void saveRecords(void** records, int n) {
    FILE* f = fopen("records.json", "w");
    if (!f) return;  // Error checking

    for (int i = 0; i < n; i++) {
        Record* r = *(Record**)records[i];
        fprintf(f, "{\"value\": %d, \"str\": \"%s\"}\n", r->value, r->str);
    }
    fclose(f);
}

// Function to main program
int main() {
    int n;
    printf("Enter the initial number of records: ");
    scanf("%d", &n);

    // Dynamically allocate memory for arrays and data structures
    void** records = allocateRecords(n);

    // Read user input and update record count dynamically
    int choice;
    while (1) {
        printf("1. Add more records, 2. Remove a record, 3. Exit: ");
        scanf("%d", &choice);
        switch (choice) {
            case 1:
                n++;  // Increase the number of records
                records = reallocateRecords(records, n);
                break;
            case 2:
                if (n > 0) {
                    n--;  // Decrease the number of records
                    reallocateRecords(records, n);  // Update existing memory allocations
                }
                break;
            case 3:
                return 0;  // Exit program
        }
    }

    // Export records to JSON file
    saveRecords(records, n);

    // Free allocated memory and close files
    for (int i = 0; i < n; i++) {
        Record* r = *(Record**)records[i];
        free(r->str);
        free(r);
    }
    free(records);

    return 0;
}
