struct record {
    int value;
};

void* alloc_and_init_arrays(size_t max_memory) {
    size_t offset_array_size = (max_memory / sizeof(long)) * 0.8;
    long* offsets = (long*)malloc(offset_array_size * sizeof(long));
    if (!offsets || offset_array_size > max_memory) {
        free(offsets);
        return NULL;
    }

    int key_array_size = (max_memory / sizeof(int)) * 0.6;
    int* keys = (int*)malloc(key_array_size * sizeof(int));
    if (!keys || key_array_size > max_memory) {
        free(keys);
        free(offsets);
        return NULL;
    }

    struct record* records = (struct record*)malloc((max_memory / sizeof(struct record)) * 0.4);
    if (!records || (size_t)(records + 1 - records) > max_memory) {
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    for (int i = 0; i < (offset_array_size / sizeof(long)); i++) {
        offsets[i] = rand() % 1000000;
    }
    for (int i = 0; i < (key_array_size / sizeof(int)); i++) {
        keys[i] = rand() % 10000;
    }
    for (int i = 0; i < ((max_memory / sizeof(struct record)) * 0.4) / sizeof(struct record); i++) {
        records[i].value = rand() % 100000;
    }

    return offsets;
}

void free_allocated_memory(void* ptrs[], size_t count) {
    for (int i = 0; i < count; i++) {
        if (ptrs[i])
            free(ptrs[i]);
    }
}

void check_and_log_resource_usage(void* ptrs[], size_t count) {
    size_t total_memory_used = 0;
    for (int i = 0; i < count; i++) {
        if (ptrs[i]) {
            total_memory_used += sizeof(long) + sizeof(int);
        }
    }
    printf("Peak memory usage: %zu bytes.\n", total_memory_used);
}

void perform_cryptographic_operations(void* ptrs[], size_t count) {
    EVP_add_cipher(AES, "AES-256-CBC");
    EVP_add_cipher(Camellia, "Camellia-256-CBC");
    EVP_add_digest(MD5, "MD5");
    EVP_add_digest(SHA, "SHA-256");
    EVP_add_digest_alias("SHA1", SHA);
}
