int main() {
    srand(time(NULL)); // Initialize random number generator

    long* offset_values = NULL;
    int* key_values = NULL;
    float* value_values = NULL;

    record_t** records = NULL;
    size_t record_count = 0;

    // Allocate and initialize arrays
    if (offset_values = malloc(sizeof(long) * 1000)) {
        if (!check_memory_limit(MEMORY_LIMIT - sizeof(long) * 1000)) {
            return 1; // Out of memory
        }
        for (size_t i = 0; i < 1000; i++) {
            offset_values[i] = i;
        }
    } else {
        printf("Failed to allocate offset values\n");
        return 1;
    }

    if (key_values = malloc(sizeof(int) * 1000)) {
        if (!check_memory_limit(MEMORY_LIMIT - sizeof(int) * 1000)) {
            return 1; // Out of memory
        }
        for (size_t i = 0; i < 1000; i++) {
            key_values[i] = i;
        }
    } else {
        printf("Failed to allocate key values\n");
        return 1;
    }

    if (value_values = malloc(sizeof(float) * 1000)) {
        if (!check_memory_limit(MEMORY_LIMIT - sizeof(float) * 1000)) {
            return 1; // Out of memory
        }
        for (size_t i = 0; i < 1000; i++) {
            value_values[i] = (float)i;
        }
    } else {
        printf("Failed to allocate value values\n");
        return 1;
    }

    // Allocate and initialize records
    if (records = malloc(sizeof(record_t*) * 1000)) {
        for (size_t i = 0; i < 1000; i++) {
            record_t* record = malloc(RECORD_SIZE);
            record->key = i % 10;
            record->value = (float)(i % 10000) / 10000.0f;
            char buffer[20];
            sprintf(buffer, "Record %d", i);
            record->str = malloc(strlen(buffer) + 1);
            strcpy(record->str, buffer);
        }
    } else {
        printf("Failed to allocate records\n");
        return 1;
    }

    // Sort and filter records
    qsort(records, 1000, RECORD_SIZE, compare_records);
    size_t filtered_count = filter_records(records, &record_count);

    // Free memory
    free_memory((void**)&offset_values, 1);
    free_memory((void**)&key_values, 1);
    free_memory((void**)&value_values, 1);
    for (size_t i = 0; i < filtered_count; i++) {
        free(records[i]->str);
        free(records[i]);
    }
    free(records);

    return 0;
}

int compare_records(const void* a, const void* b) {
    record_t* rec1 = *(record_t**)a;
    record_t* rec2 = *(record_t**)b;

    if (rec1->key < rec2->key) {
        return -1;
    } else if (rec1->key > rec2->key) {
        return 1;
    } else {
        return 0;
    }
}

size_t filter_records(record_t** records, size_t* record_count) {
    *record_count = 0;

    for (size_t i = 0; i < 1000; i++) {
        if (records[i]->key >= 5 && records[i]->key <= 8) {
            (*record_count)++;
        }
    }

    return *record_count;
}

bool check_memory_limit(size_t limit) {
