    json_t *root = json_loads(json_string, 0, &json_error);
    if (!root) return 0; // invalid JSON

    if (!json_is_object(root)) return 0; // not an object

    int has_access_token = 0;
    int has_expires_in = 0;
    int has_token_type = 0;
    int has_refresh_token = 0;

    json_t *token_type = json_object_get(root, "token_type");
    if (token_type && json_is_string(token_type) && !strcmp(json_string_value(token_type), "Bearer")) {
        has_token_type = 1;
    } else return 0; // invalid token type

    json_t *expires_in = json_object_get(root, "expires_in");
    if (expires_in && json_is_integer(expires_in)) {
        has_expires_in = 1;
        int expires_in_int = json_integer_value(expires_in);
        if (expires_in_int <= 0) return 0; // invalid expires_in
    } else return 0; // missing or invalid expires_in

    json_t *access_token = json_object_get(root, "access_token");
    if (access_token && json_is_string(access_token)) {
        has_access_token = 1;
    }

    json_t *refresh_token = json_object_get(root, "refresh_token");
    if (refresh_token && json_is_string(refresh_token)) {
        has_refresh_token = 1;
    }

    json_decref(root);
    return (has_access_token && has_expires_in && has_token_type) ? 1 : 0;
}

