typedef struct {
    float data;
    char* string;
} sensor_data_t;

sensor_data_t* generate_sensor_data(int num_records, int max_memory_limit) {
    // Initialize the memory pool
    void* memory_pool = malloc(max_memory_limit);
    if (!memory_pool) {
        return NULL; // Failed to allocate memory pool
    }

    // Initialize a pointer to keep track of the current allocation
    void** current_allocation = &((char*)memory_pool);

    for (int i = 0; i < num_records; i++) {
        // Generate random data and string
        float* data = (float*)malloc(sizeof(float));
        if (!data) {
            return NULL; // Failed to allocate memory for data
        }
        *data = rand() / (RAND_MAX / 1.0f);

        char* string = (char*)malloc(1024); // Assuming max string length is 1023
        if (!string) {
            free(data);
            return NULL; // Failed to allocate memory for string
        }
        sprintf(string, "Record %d: %.2f", i + 1, *data);

        // Allocate a new sensor_data_t record and initialize it
        sensor_data_t* record = (sensor_data_t*)malloc(sizeof(sensor_data_t));
        if (!record) {
            free(data);
            free(string);
            return NULL; // Failed to allocate memory for record
        }
        record->data = *data;
        record->string = string;

        // Update the current allocation pointer
        *current_allocation++ = record;

        // Check if we've exceeded the maximum memory limit
        size_t total_memory_usage = (size_t)(current_allocation - ((char*)memory_pool));
        if (total_memory_usage > max_memory_limit) {
            return NULL; // Exceeded maximum memory limit
        }
    }

    // Return a pointer to the first record
    return *(((sensor_data_t**)memory_pool));
}
