        return NULL; // handle allocation failure
    }
    for (size_t i = 0; i < count; i++) {
        records[i].value = rand() % 100; // initialize with a random value
    }
    return records;
}

int* allocate_int_array(size_t count, int min_value, int max_value) {
    int* arr = (int*)malloc(count * sizeof(int));
    if (!arr) {
        return NULL; // handle allocation failure
    }
    for (size_t i = 0; i < count; i++) {
        arr[i] = rand() % ((max_value - min_value) + 1) + min_value;
    }
    return arr;
}

long* allocate_long_array(size_t count, long min_value, long max_value) {
    long* arr = (long*)malloc(count * sizeof(long));
    if (!arr) {
        return NULL; // handle allocation failure
    }
    for (size_t i = 0; i < count; i++) {
        arr[i] = rand() % ((max_value - min_value) + 1) + min_value;
    }
    return arr;
}

void* allocate_and_init_memory(pthread_mutex_t* mutex, size_t offset_count, size_t key_count, size_t record_count) {
    int* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;

    pthread_mutex_lock(mutex);
    if (!allocate_long_array(offset_count, 0, INT_MAX)) {
        // handle allocation failure
        pthread_mutex_unlock(mutex);
        return NULL;
    }
    if (!allocate_int_array(key_count, 0, INT_MAX)) {
        // handle allocation failure
        free((void*)offsets);
        pthread_mutex_unlock(mutex);
        return NULL;
    }
    if (!allocate_records(record_count)) {
        // handle allocation failure
        free((void*)offsets);
        free((void*)keys);
        pthread_mutex_unlock(mutex);
        return NULL;
    }

    offsets = (int*)malloc(offset_count * sizeof(int));
    keys = (int*)malloc(key_count * sizeof(int));

    if (!offsets || !keys) {
        // handle allocation failure
        free((void*)records);
        free((void*)keys);
        pthread_mutex_unlock(mutex);
        return NULL;
    }

    records = (record*)malloc(record_count * sizeof(record));
    pthread_mutex_unlock(mutex);

    return (void*)records;
