// Function to dynamically allocate and initialize arrays and records
void initArraysAndRecords(int maxMemLimit) {
    // Allocate memory for arrays
    double* doubles = (double*)malloc(maxMemLimit * sizeof(double));
    char** strings = (char**)malloc(maxMemLimit * sizeof(char*));
    long* offsets = (long*)malloc(maxMemLimit * sizeof(long));
    int* keys = (int*)malloc(maxMemLimit * sizeof(int));
    long long* timestamps = (long long*)malloc(maxMemLimit * sizeof(long long));

    // Initialize arrays
    for (int i = 0; i < maxMemLimit; i++) {
        doubles[i] = (double)i;
        strings[i] = (char*)malloc(10 * sizeof(char));
        sprintf(strings[i], "%d", i);
        offsets[i] = (long)i;
        keys[i] = i;
        timestamps[i] = (long long)i;
    }

    // Allocate memory for data records
    DataRecord* records = (DataRecord*)malloc(maxMemLimit * sizeof(DataRecord));

    // Initialize records
    for (int i = 0; i < maxMemLimit; i++) {
        records[i].d = (double)i;
        records[i].s = strings[i];
        records[i].i = keys[i];
        records[i].ll = timestamps[i];
        records[i].f = (float)i / 10.0;

        // Generate random value for double field
        srand(time(NULL));
        int randomValue = rand() % 100;
        if (randomValue > 50) {
            records[i].d += (double)randomValue;
        }
    }

    // Free allocated memory when done
    free(doubles);
    free(strings);
    free(offsets);
    free(keys);
    free(timestamps);
}

int main() {
    int maxMemLimit = 1000; // specify maximum memory limit
    initArraysAndRecords(maxMemLimit);

    return 0;
}
