#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

#define MAX_MEMORY 1024 * 1024 // 1 MB
#define INITIAL_RECORDS 100
#define COMPRESSION_LEVEL 6
#define LOG_INTERVAL 10

typedef struct {
    int value;
    char* str;
} dataRecord;

dataRecord* records = NULL;
int recordCount = 0;
int maxRecords = INITIAL_RECORDS;
z_stream stream;
unsigned char inbuf[16384];
unsigned char outbuf[16384];

void* compress(dataRecord* record) {
    deflateInit2(&stream, COMPRESSION_LEVEL, Z_DEFAULT_COMPRESSION, 15, 8);
    int bytesWritten = compressBound(record->str);
    unsigned char* compressedData = malloc(bytesWritten + 1);
    stream.next_in = (Byte*)record->str;
    stream.avail_in = strlen(record->str) + 1;
    stream.next_out = compressedData;
    stream.avail_out = bytesWritten;
    deflate(&stream, Z_FINISH);
    compressData = realloc(compressedData, bytesWritten);
    return compressData;
}

void initRecords() {
    for (int i = 0; i < maxRecords; i++) {
        dataRecord* record = malloc(sizeof(dataRecord));
        int randomValue = rand() % 100;
        record->value = randomValue;
        char buffer[1024];
        sprintf(buffer, "record_%d", i);
        record->str = strdup(buffer);
    }
}

void manageMemory(int newMaxRecords) {
    if (newMaxRecords < maxRecords) {
        for (int i = 0; i < maxRecords - newMaxRecords; i++) {
            free(&records[i].str);
            free(&records[i]);
        }
    } else if (newMaxRecords > maxRecords) {
        dataRecord* temp = realloc(records, sizeof(dataRecord) * newMaxRecords);
        for (int i = maxRecords; i < newMaxRecords; i++) {
            temp[i].value = rand() % 100;
            char buffer[1024];
            sprintf(buffer, "record_%d", i);
            temp[i].str = strdup(buffer);
        }
    }
    maxRecords = newMaxRecords;
}

void logMemoryUsage() {
    if (recordCount > 0) {
        printf("Peak memory usage: %d MB\n", recordCount * sizeof(dataRecord));
    }
}

int main() {
    int prevMaxRecords = MAX_MEMORY / sizeof(dataRecord);
    while (1) {
        // Periodic checks for maximum memory limit
        if (recordCount >= prevMaxRecords) {
            printf("Memory usage exceeds limit. Reducing capacity.\n");
            manageMemory(prevMaxRecords - 10);
        }
        logMemoryUsage();
        // Simulate compression and logging at regular intervals
        if ((recordCount % LOG_INTERVAL == 0)) {
            for (int i = 0; i < recordCount; i++) {
                void* compressedData = compress(&records[i]);
                printf("Compressed data: %s\n", (char*)compressedData);
            }
        }
    }
}
