#include <stdio.h>
#include <stdlib.h>
#include <time.h>

struct record {
    int key;
    long offset;
};

int find(int* parent, int i) {
    if (parent[i] != i)
        parent[i] = find(parent, parent[i]);
    return parent[i];
}

void unionset(int* parent, int x, int y) {
    x = find(parent, x);
    y = find(parent, y);
    if (x < y)
        parent[y] = x;
    else
        parent[x] = y;
}

int disjoint_pairs(struct record* records, int n) {
    int* parent = (int*)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++)
        parent[i] = i;

    int count = 0;
    clock_t start = clock();
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (find(parent, i) != find(parent, j)) {
                unionset(parent, i, j);
                printf("Disjoint pair found: %d - %d\n", i, j);
                count++;
            }
        }
    }
    clock_t end = clock();
    printf("Time taken: %ld milliseconds\n", (end - start) / 1000);

    free(parent);
    return count;
}

void init_records(struct record* records, int n, int key_range, long offset_range) {
    for (int i = 0; i < n; i++) {
        records[i].key = rand() % key_range;
        while (find_keys(records, i) && records[i].key > 1000)
            records[i].key = rand() % key_range;

        do {
            records[i].offset = (long)rand() % offset_range + 1;
        } while (records[i].offset > 1000);
    }
}

int find_keys(struct record* records, int i) {
    for (int j = 0; j < i; j++) {
        if (records[j].key == records[i].key)
            return 1;
    }
    return 0;
}

int main() {
    srand(time(NULL));

    struct record* records = (struct record*)malloc(sizeof(struct record) * 100);
    int key_range = 100;
    long offset_range = 1000;

    init_records(records, 100, key_range, offset_range);

    printf("Disjoint pairs found: %d\n", disjoint_pairs(records, 100));

    free(records);
    return 0;
}
