// Function to dynamically allocate memory for arrays and shapes
void* alloc_memory(int max_limit) {
    // Check if the allocation limit is exceeded
    if (max_limit < 0 || max_limit > INT_MAX) {
        return NULL;
    }

    int total_size = sizeof(double) * 2 + sizeof(ShapeType);
    int remaining_size = max_limit - total_size;

    // Allocate memory for arrays and shapes
    Shape* shape_arr = (Shape*)malloc(total_size);
    double* array1 = (double*)malloc(sizeof(double) * 2);
    struct Point* array2 = (struct Point*)malloc(sizeof(struct Point));

    // Initialize the arrays and shapes
    for (int i = 0; i < 2; i++) {
        array1[i] = i;
    }
    for (int i = 0; i < 3; i++) {
        array2[i].x = i;
        array2[i].y = i;
    }

    // Check if the allocated memory is within the specified limits
    if (remaining_size < sizeof(ShapeType)) {
        free(shape_arr);
        free(array1);
        free(array2);
        return NULL;
    }

    return shape_arr;
}

// Function to free all allocated memory
void free_memory(void* ptr) {
    free(ptr);
}

