```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure to represent records
typedef struct {
    int offset;
    char key[10];
    double value;
} record_t;

// Define a structure to manage array of records and strings
typedef struct {
    int max_records;
    int current_records;
    record_t **records;
    char **strings;
    int max_strings;
    int current_strings;
    pthread_mutex_t mutex;
} record_array_t;

// Function to create a new record array instance
record_array_t *create_record_array(int max_records, int max_strings) {
    record_array_t *array = (record_array_t *)malloc(sizeof(record_array_t));
    array->max_records = max_records;
    array->current_records = 0;
    array->records = (record_t **)malloc(max_records * sizeof(record_t *));
    array->max_strings = max_strings;
    array->current_strings = 0;
    array->strings = (char **)malloc(max_strings * sizeof(char *));
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

// Function to free a record array instance
void free_record_array(record_array_t *array) {
    for (int i = 0; i < array->current_records; i++) {
        free(array->records[i]->key);
        free(array->records[i]);
    }
    for (int i = 0; i < array->current_strings; i++) {
        free(array->strings[i]);
    }
    pthread_mutex_destroy(&array->mutex);
    free(array->records);
    free(array->strings);
    free(array);
}

// Function to add a new record to an existing array
void add_record(record_array_t *array, int offset, const char *key, double value) {
    pthread_mutex_lock(&array->mutex);

    if (array->current_records >= array->max_records) {
        // Resize the records array if necessary
        array->max_records *= 2;
        array->records = (record_t **)realloc(array->records, array->max_records * sizeof(record_t *));
    }

    record_t *new_record = (record_t *)malloc(sizeof(record_t));
    strcpy(new_record->key, key);
    new_record->offset = offset;
    new_record->value = value;

    array->records[array->current_records] = new_record;
    array->current_records++;

    pthread_mutex_unlock(&array->mutex);
}

// Function to add a new string to an existing array
void add_string(record_array_t *array, const char *string) {
    pthread_mutex_lock(&array->mutex);

    if (array->current_strings >= array->max_strings) {
        // Resize the strings array if necessary
        array->max_strings *= 2;
        array->strings = (char **)realloc(array->strings, array->max_strings * sizeof(char *));
    }

    char *new_string = (char *)malloc(strlen(string) + 1);
    strcpy(new_string, string);

    array->strings[array->current_strings] = new_string;
    array->current_strings++;

    pthread_mutex_unlock(&array->mutex);
}

// Function to print the record array
void print_record_array(record_array_t *array) {
    for (int i = 0; i < array->current_records; i++) {
        printf("Offset: %d, Key: %s, Value: %.2f\n", array->records[i]->offset, array->records[i]->key, array->records[i]->value);
    }
}

int main() {
    record_array_t *array = create_record_array(10, 5);

    add_record(array, 1, "key1", 1.0);
    add_string(array, "string1");
    add_record(array, 2, "key2", 2.0);
    add_string(array, "string2");

    print_record_array(array);

    free_record_array(array);

    return 0;
}
```']

