DistributedSystem* createNodeList(int nodes, int lastNode, int** nodeArray) {
    DistributedSystem* list = (DistributedSystem*)malloc((lastNode + 1) * sizeof(DistributedSystem));
    for (int i = 0; i <= lastNode; i++) {
        list[i].port = 0;
        list[i].protocol = "";
        if (i < nodes) {
            int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
            struct sockaddr_in addr;
            addr.sin_family = AF_INET;
            addr.sin_port = htons(list[i].port);
            inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
            bind(socket_fd, (struct sockaddr*)&addr, sizeof(addr));
            listen(socket_fd, 3);
        }
    }
    *nodeArray = list;
    return list;
}

void addVertices(int num_vertices, DistributedSystem* graph) {
    for (int i = 0; i < num_vertices; i++) {
        graph[i].port = rand() % 10000 + 1;
        char buffer[16];
        sprintf(buffer, "Vertex_%d", i);
        graph[i].protocol = malloc(strlen(buffer) + 1);
        strcpy(graph[i].protocol, buffer);
    }
}

void addEdges(int num_edges, DistributedSystem* graph) {
    for (int i = 0; i < num_edges; i++) {
        int vertex1 = rand() % num_vertices;
        int vertex2 = rand() % num_vertices;
        graph[vertex1].port++;
        graph[vertex2].port++;
    }
}

void freeNodeList(int lastNode, DistributedSystem* list) {
    for (int i = 0; i <= lastNode; i++) {
        if (list[i].protocol != NULL) {
            free(list[i].protocol);
        }
    }
    free(list);
}
