#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_RECORDS 10000
#define MEMORY_LIMIT 1048576 // 1 MB in bytes
#define INT_MIN -1000
#define INT_MAX 1000

typedef struct {
    int key;
    int value;
} record_t;

record_t* records = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* alloc_array(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL || (size > 0 && ptr < size)) {
        free(ptr);
        return NULL;
    }
    return ptr;
}

int init_arrays_and_records(int max_keys, int* keys, long* offsets) {
    pthread_mutex_lock(&mutex);

    records = alloc_array(sizeof(record_t) * MAX_RECORDS);
    if (records == NULL) {
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    keys = (int*)realloc(keys, sizeof(int) * max_keys);
    if (keys == NULL) {
        free(records);
        records = NULL;
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    offsets = (long*)realloc(offsets, sizeof(long) * max_keys);
    if (offsets == NULL) {
        free(keys);
        keys = NULL;
        free(records);
        records = NULL;
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    for (int i = 0; i < max_keys; i++) {
        keys[i] = i;
        offsets[i] = 0;
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        int key = i % max_keys;
        records[i].key = key;
        records[i].value = rand() % (INT_MAX - INT_MIN + 1) + INT_MIN;
    }

    pthread_mutex_unlock(&mutex);
    return 1;
}

void free_all_memory() {
    pthread_mutex_lock(&mutex);

    free(keys);
    keys = NULL;

    free(offsets);
    offsets = NULL;

    free(records);
    records = NULL;

    pthread_mutex_unlock(&mutex);
}
