void* allocateMemory(int numStructures) {
    // Calculate total bytes required for structures and status
    size_t totalBytes = (sizeof(MyStruct) + sizeof(enum Status)) * numStructures;

    // Ensure memory allocation does not exceed specified maximum limit
    if (totalBytes > getMaximumResourceLimit()) {
        return NULL;
    }

    // Allocate memory for array of MyStruct and status
    void* allocatedMemory = malloc(totalBytes);
    if (!allocatedMemory) {
        logAllocationFailure(numStructures, "malloc failed");
        return NULL;
    }

    // Initialize array with SUCCESS status
    enum Status* statusArray = (enum Status*) allocatedMemory + numStructures * sizeof(MyStruct);
    for (int i = 0; i < numStructures; i++) {
        statusArray[i] = SUCCESS;
    }

    return allocatedMemory;
}

// Function to free all allocated memory
void freeMemory(void* allocatedMemory) {
    free(allocatedMemory);
}

// Function to dynamically resize or pad the char buffer if necessary
void resizeBuffer(MyStruct* structure, int newStringLength) {
    // Calculate required bytes for updated buffer size
    size_t requiredBytes = (newStringLength + 1) * sizeof(char);

    // Check if current buffer size is sufficient
    if (requiredBytes > strlen(structure->buffer)) {
        // Resize or pad the buffer as needed
        char* newBuffer = realloc(structure->buffer, requiredBytes);
        if (!newBuffer) {
            logAllocationFailure(1, "realloc failed");
            return;
        }
        structure->buffer = newBuffer;
    }
}

