#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Define the dynamic array of records
typedef struct {
    Record* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

// Function to initialize the dynamic array with a specified initial capacity and maximum limit
DynamicArray* initDynamicArray(size_t initialCapacity, size_t maxLimit) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!arr) return NULL; // Handle allocation failure

    arr->data = (Record*)calloc(initialCapacity, sizeof(Record));
    if (!arr->data) {
        free(arr);
        return NULL;
    }

    arr->capacity = initialCapacity;
    arr->count = 0;

    pthread_mutex_init(&arr->mutex, NULL);

    return arr;
}

// Function to add a new record to the dynamic array
int addRecord(DynamicArray* arr, int value) {
    if (arr->count >= arr->capacity * 2) { // Resize the array when it's half full
        size_t newSize = arr->capacity * 2;
        Record* newData = (Record*)realloc(arr->data, newSize * sizeof(Record));
        if (!newData) return -1; // Handle allocation failure

        arr->data = newData;
        arr->capacity = newSize;
    }

    Record newRecord = {value};
    arr->data[arr->count++] = newRecord;

    if (arr->count > arr->capacity) {
        pthread_mutex_lock(&arr->mutex);
        arr->capacity *= 2; // Double the capacity to prevent frequent resizes
        pthread_mutex_unlock(&arr->mutex);
    }

    return 0;
}

// Function to print the dynamic array's contents
void printArray(DynamicArray* arr) {
    for (size_t i = 0; i < arr->count; i++) {
        printf("%d ", arr->data[i].value);
    }
    printf("\n");
}
