    node->id = id;
    node->name = name;
    node->port = port;

    // Add the new node to the graph
    db->nodes[db->num_nodes] = node;
    db->num_nodes++;
}

// Function to free all allocated memory when done
void destroy_node_list(DistributedDatabase* db) {
    for (int i = 0; i < db->num_nodes; i++) {
        free(db->nodes[i]);
