int findOrCreateStringInPool(char* str, size_t poolSize, int** pool, size_t* usedSpace) {
    int found = -1;
    for (size_t i = 0; i < *usedSpace; i++) {
        if (!strcmp(str, (*pool)[i])) {
            found = i;
            break;
        }
    }

    if (found == -1) {
        if (*usedSpace >= poolSize) {
            return -1; // Pool is full
        }

        (*pool)[*usedSpace] = str;
        (*usedSpace)++;
    }

    return found;
}

void freeResources(long* offsetArr, int* keyArr, double* valueArr, record** records, size_t recordCount, char** stringPool, size_t usedSpace) {
    for (size_t i = 0; i < recordCount; i++) {
        if (records[i]->stringValue != NULL) {
            free(records[i]->stringValue);
        }
    }

    free(offsetArr);
    free(keyArr);
    free(valueArr);

    for (size_t i = 0; i < usedSpace; i++) {
        if (stringPool[i] != NULL) {
            free(stringPool[i]);
        }
    }

    free(records);
    free(stringPool);
}

int main() {
    // Configuration parameters
    const int MAX_STRING_POOL_SIZE = 100;

    srand(time(NULL));

    // Initialize arrays
    long* offsetArr = (long*)allocateMemory(sizeof(long) * 10);
    int* keyArr = (int*)allocateMemory(sizeof(int) * 10);
    double* valueArr = (double*)allocateMemory(sizeof(double) * 10);

    initializeArray(offsetArr, 10);
    for (size_t i = 0; i < 10; i++) {
        keyArr[i] = rand() % 100 + 1;
        valueArr[i] = (double)rand() / RAND_MAX;
    }

    // Initialize records
    record** records = (record**)allocateMemory(sizeof(record*) * 10);
    for (size_t i = 0; i < 10; i++) {
        records[i]->intValue = rand() % 100 + 1;
        int foundIndex = findOrCreateStringInPool("String", MAX_STRING_POOL_SIZE, &stringPool, &usedSpace);
        if (foundIndex == -1) {
            // Handle error
        }
        else {
            records[i]->stringValue = stringPool[foundIndex];
        }
    }

    // Free resources
    freeResources(offsetArr, keyArr, valueArr, records, 10, stringPool, usedSpace);

    return 0;
}
