record* init_array(int num_nodes, int max_key, int max_offset) {
    record* arr = (record*)malloc(num_nodes * sizeof(record));
    for (int i = 0; i < num_nodes; i++) {
        arr[i].key = rand() % (max_key + 1);
        arr[i].offset = rand() % (max_offset + 1);
    }
    return arr;
