void update_network_node(int node_id, int num_nodes, record* nodes) {
    // Implement network protocol operations here
    // For example:
    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    bind(socket_fd, (struct sockaddr*) &nodes[node_id], sizeof(nodes[node_id]));
    listen(socket_fd, 3);

    // Example of updating node with TCP protocol
    if (node_id == 0) {
        for (int i = 1; i < num_nodes; i++) {
            send(socket_fd, &nodes[i], sizeof(nodes[i]), 0);
        }
    } else {
        for (int i = 0; i < node_id; i++) {
            recv(socket_fd, &nodes[i], sizeof(nodes[i]), 0);
        }
    }

    close(socket_fd);
}

