#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct node {
    double val;
    char str[64];
    struct node* next;
} Node;

typedef struct record {
    int value;
    Node* node;
} Record;

Node* create_node(double val, const char* str) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->val = val;
    strcpy(node->str, str);
    node->next = NULL;
    return node;
}

Record* create_record(int value, Node* node) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;
    record->value = value;
    record->node = node;
    return record;
}

void free_all(Node** nodes, Record** records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        Node* current = *nodes++;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
        Record* current_record = *records++;
        while (current_record) {
            Record* next_record = current_record->node ? current_record->node : NULL;
            free(current_record);
            current_record = next_record;
        }
    }
}

void init_arrays(Node** nodes, Record** records, size_t count, int max_value, double max_floating_point) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        Node* node = create_node((double)rand() / RAND_MAX * max_floating_point, "example_string");
        Record* record = create_record(rand() % max_value, node);
        // Set the value of each record's int field to a random value within the given range
        record->value = rand() % max_value;
        // Link the struct nodes accordingly
        if (i > 0) {
            (*nodes)[i-1]->next = node;
        }
        *nodes = node;
        *records = record;
    }
}

int main() {
    size_t count = 10000;
    int max_value = 100;
    double max_floating_point = 10.0;

    Node* nodes = NULL;
    Record* records = NULL;

    init_arrays(&nodes, &records, count, max_value, max_floating_point);

    // Use the arrays and linked list here...

    free_all(&nodes, &records, count);
    return 0;
}
