int manage_memory(size_t limit) {
    size_t total = 0;
    long* offsets = NULL;
    int* keys = NULL;
    Record* records = NULL;
    time_t* timestamps = NULL;

    if ((offsets = (long*)malloc(sizeof(long) * 100)) == NULL ||
        (keys = (int*)malloc(sizeof(int) * 100)) == NULL ||
        (records = (Record*)malloc(sizeof(Record) * 100)) == NULL ||
        (timestamps = (time_t*)malloc(sizeof(time_t) * 100)) == NULL) {
        return -1;
    }

    for (size_t i = 0; i < 100 && total <= limit; i++) {
        records[i].key = rand() % 100;
        records[i].offset = (long)i;
        timestamps[i] = time(NULL);
        total += sizeof(long) + sizeof(int) + sizeof(Record) + sizeof(time_t);
    }

    if (total > limit) {
        free(offsets);
        free(keys);
        free(records);
        free(timestamps);
        return -1;
    }

    // Initialize remaining records to default values
    for (; i < 100; i++) {
        records[i].key = -1;
        records[i].offset = -1;
        timestamps[i] = -1;
    }

    return 0;
}
