        fprintf(stderr, "Error: Maximum sessions exceeded.\n");
        return NULL;
    }

    session_t* sessions = (session_t*)malloc(max_sessions * sizeof(session_t));
    if (!sessions) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    char* usernames[] = {"user1", "user2", ..., "user100"}; // predefined list of 100 common usernames
    srand(time(NULL));

    for (int i = 0; i < max_sessions; i++) {
        session_t* session = &sessions[i];
        session->session_id = rand() % (MAX_SIZE - 1) + 1;
        strcpy(session->username, usernames[rand() % 100]);
        session->duration = rand() % (MAX_SIZE - 1) + 1;

        // sort sessions by duration in ascending order
        qsort(sessions, max_sessions, sizeof(session_t), compare_sessions);
    }

    return sessions;
}

int compare_sessions(const void* a, const void* b) {
    session_t* session_a = (session_t*)a;
    session_t* session_b = (session_t*)b;

    if (session_a->duration < session_b->duration)
        return -1;
    else if (session_a->duration > session_b->duration)
        return 1;
    else
        return 0;
}

