    void* arr[3];

    // Allocate memory for double precision floating-point numbers
    double* doubles = (double*)malloc(size * sizeof(double));
    if (!doubles || sizeof(doubles) > MAX_MEMORY) {
        free(doubles);
        return NULL;
    }
    arr[0] = doubles;

    // Allocate memory for character strings
    char** chars = (char**)malloc(size * sizeof(char*));
    if (!chars || sizeof(chars) > MAX_MEMORY) {
        free(chars);
        return NULL;
    }
    arr[1] = chars;

    // Allocate memory for point structures
    Point* points = (Point*)malloc(size * sizeof(Point));
    if (!points || sizeof(points) > MAX_MEMORY) {
        free(points);
        return NULL;
    }
    arr[2] = points;

    // Log allocation event
    pthread_mutex_lock(&log_mutex);
    log_event("Allocate arrays", "Success");
    pthread_mutex_unlock(&log_mutex);

    return arr;
}

