#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

Record* allocateRecords(int numRecords, int maxLimit) {
    if (numRecords <= 0 || maxLimit <= 0) {
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    void* arena = malloc(maxLimit);
    if (!arena) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    Record* records = (Record*) arena;
    for (int i = 0; i < numRecords; i++) {
        int val = rand() % maxLimit;
        records[i].value = val;

        if ((void*) &records[i] + sizeof(Record) > (void*) arena + maxLimit) {
            free(arena);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
    }

    pthread_mutex_unlock(&lock);

    return records;
}

void deallocateRecords(Record* records, int numRecords) {
    if (!records || numRecords <= 0) {
        return;
    }

    free((void*) records);
}
