#include <stdlib.h>
#include <stdio.h>

#define MAX_ALLOC 1024*1024
#define RECORD_SIZE sizeof(record)

typedef struct record {
    int value;
} record;

record *record_alloc(int size) {
    return (record *)malloc(size * RECORD_SIZE);
}

int record_free(record **records, int size) {
    for(int i = 0; i < size; ++i)
        free(records[i]);
    free(records);
    return 0;
}

long *offset_alloc(int size) {
    return (long *)malloc(size * sizeof(long));
}

void offset_free(long **offsets, int size) {
    for(int i = 0; i < size; ++i)
        free(offsets[i]);
    free(offsets);
}

int key_alloc(int size) {
    return (int *)malloc(size * sizeof(int));
}

void key_free(int **keys, int size) {
    for(int i = 0; i < size; ++i)
        free(keys[i]);
    free(keys);
}

// Function to manage dynamic allocation and initialization of memory
record **manage_records(int count, record ***records, long *offsets, int *keys[], int max_size) {
    // Initialize records
    for (int i = 0; i < count; ++i) {
        if (*records[i] == NULL || *records[i]->size <= 0) {
            // Calculate new size
            int new_size = sizeof(record);
            while ((new_size | i) > max_size)
                new_size <<= 1;
            // Resize and initialize record array
            record **tmp_records = (record **)realloc(*records, (i + 1) * sizeof(record *));
            *tmp_records = record_alloc(new_size);
            *records = tmp_records;

            // Check if the allocated memory is within the specified limits
            printf("Records: %zu bytes\n", *records[i]->size);
        }
    }

    return records;
}

long **manage_offsets(int count, long ***offsets) {
    for (int i = 0; i < count; ++i) {
        if (*offsets[i] == NULL || *offsets[i]->size <= 0) {
            int new_size = sizeof(long);
            while ((new_size | i) > MAX_ALLOC)
                new_size <<= 1;
            long **tmp_offsets = (long **)realloc(*offsets, (i + 1) * sizeof(long *));
            *tmp_offsets = offset_alloc(new_size);
            *offsets = tmp_offsets;
        }
    }

    return offsets;
}

int **manage_keys(int count, int ***keys) {
    for (int i = 0; i < count; ++i) {
        if (*keys[i] == NULL || *keys[i]->size <= 0) {
            int new_size = sizeof(int);
            while ((new_size | i) > MAX_ALLOC)
                new_size <<= 1;
            int **tmp_keys = (int **)realloc(*keys, (i + 1) * sizeof(int *));
            *tmp_keys = key_alloc(new_size);
            *keys = tmp_keys;
        }
    }

    return keys;
}

// Function to free all allocated memory
void free_memory(record ***records, long **offsets, int **keys, int count) {
    record_free(records, count);
    offset_free(offsets, count);
    key_free(keys, count);
}
