    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    table->size = size;
    table->buckets = (node**)calloc(size, sizeof(node*));
    table->count = 0;
    table->threshold = size / 2; // default load factor threshold
    table->error = 0;
    return table;
}

void insert_hash_table(hash_table* table, int key, long offset) {
    int index = key % table->size;
    node* newNode = (node*)malloc(sizeof(node));
    newNode->key = key;
    newNode->offset = offset;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    table->count++;
}

record* init_record(int size) {
    record* records = (record*)calloc(size, sizeof(record));
    return records;
}

void set_random_value(record* records, int size, int min, int max) {
    for (int i = 0; i < size; i++) {
        records[i].key = rand() % (max - min + 1) + min;
    }
}

