#include <stdlib.h>
#include <stdio.h>

#define TABLE_SIZE 256
#define LOAD_FACTOR 0.7
#define BUCKET_SIZE 8

typedef struct DataPoint {
    long offset;
    double key;
} DataPoint;

typedef struct HashNode {
    DataPoint* data;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    HashNode** buckets;
    int size;
    int count;
} HashTable;

// Error handling flags
int error_occurred = 0;

HashTable* create_hash_table(int initial_size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        error_occurred = 1;
        return NULL;
    }
    table->buckets = (HashNode**)calloc(initial_size, sizeof(HashNode*));
    if (!table->buckets) {
        free(table);
        error_occurred = 1;
        return NULL;
    }
    table->size = initial_size;
    table->count = 0;
    return table;
}

void resize_hash_table(HashTable* table) {
    int new_size = table->size * 2;
    HashNode** new_buckets = (HashNode**)realloc(table->buckets, new_size * sizeof(HashNode*));
    if (!new_buckets) {
        error_occurred = 1;
        return;
    }
    for (int i = 0; i < new_size; i++) {
        new_buckets[i] = NULL;
    }
    table->size = new_size;
    free(table->buckets);
    table->buckets = new_buckets;
}

HashNode* create_hash_node(DataPoint* data) {
    HashNode* node = (HashNode*)malloc(sizeof(HashNode));
    if (!node) {
        error_occurred = 1;
        return NULL;
    }
    node->data = data;
    node->next = NULL;
    return node;
}

void insert_hash_table(HashTable* table, DataPoint* data) {
    int index = data->key * BUCKET_SIZE % table->size;
    HashNode* current = table->buckets[index];
    while (current) {
        if (data->key == current->data->key) {
            // Update existing entry
            return;
        }
        current = current->next;
    }
    DataPoint* new_data = (DataPoint*)malloc(sizeof(DataPoint));
    if (!new_data) {
        error_occurred = 1;
        return;
    }
    *new_data = *data;
    HashNode* new_node = create_hash_node(new_data);
    if (!new_node) {
        free(new_data);
        return;
    }
    if (table->buckets[index]) {
        // Insert at end of linked list
        HashNode* prev = table->buckets[index];
        while (prev->next) {
            prev = prev->next;
        }
        prev->next = new_node;
    } else {
        table->buckets[index] = new_node;
    }
    if ((double)table->count / table->size > LOAD_FACTOR) {
        resize_hash_table(table);
    }
    table->count++;
}

DataPoint* find_hash_table(HashTable* table, double key) {
    int index = key * BUCKET_SIZE % table->size;
    HashNode* current = table->buckets[index];
    while (current) {
        if (key == current->data->key) {
            return current->data;
        }
        current = current->next;
    }
    return NULL;
}

void remove_hash_table(HashTable* table, double key) {
    int index = key * BUCKET_SIZE % table->size;
    HashNode* prev = NULL;
    HashNode* current = table->buckets[index];
    while (current) {
        if (key == current->data->key) {
            if (!prev) {
                // Remove from beginning of linked list
                table->buckets[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->data);
            free(current);
            table->count--;
            return;
        }
        prev = current;
        current = current->next;
    }
}

void destroy_hash_table(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        HashNode* current = table->buckets[i];
        while (current) {
            HashNode* next = current->next;
            free(current->data);
            free(current);
            current = next;
        }
    }
    free(table->buckets);
    free(table);
}
