// Define a structure to represent an FSA state
typedef struct {
    int value;
} record_t;

// Define a structure to represent an FSA
typedef struct {
    record_t* records;
    int num_records;
    long* offsets;
    int num_offsets;
    int* keys;
    int num_keys;
} fsa_state_t;

// Function to dynamically allocate and initialize arrays
fsa_state_t* create_fsa(int num_states, int last_state) {
    // Dynamically allocate memory for FSA state list
    fsa_state_t* f = (fsa_state_t*)malloc(sizeof(fsa_state_t));

    if (!f) return NULL;

    // Initialize arrays for 'long' offsets and 'int' keys
    f->num_offsets = num_states;
    f->offsets = (long*)malloc(sizeof(long) * f->num_offsets);

    if (!f->offsets) {
        free(f);
        return NULL;
    }

    for (int i = 0; i < f->num_offsets; i++) {
        f->offsets[i] = i + 1;
    }

    // Initialize array of 'record' structures
    f->num_records = last_state - num_states + 1;
    f->records = (record_t*)malloc(sizeof(record_t) * f->num_records);

    if (!f->records) {
        free(f->offsets);
        free(f);
        return NULL;
    }

    // Initialize records with random values within a given range
    srand(time(NULL));
    for (int i = 0; i < f->num_records; i++) {
        f->records[i].value = rand() % 100 + 1;
    }

    // Dynamically allocate memory for and initialize arrays of 'int' keys
    f->num_keys = num_states;
    f->keys = (int*)malloc(sizeof(int) * f->num_keys);

    if (!f->keys) {
        free(f->offsets);
        free(f->records);
        free(f);
        return NULL;
    }

    for (int i = 0; i < f->num_keys; i++) {
        f->keys[i] = i + 1;
    }

    return f;
}

// Function to handle state list allocation and initialization
void* create_state_list(int num_states, int last_state) {
    // Dynamically allocate memory for FSA state list
    fsa_state_t* states = (fsa_state_t*)malloc(sizeof(fsa_state_t));

    if (!states) return NULL;

    // Initialize arrays for 'long' offsets and 'int' keys
    states->num_offsets = num_states;
    states->offsets = (long*)malloc(sizeof(long) * states->num_offsets);

    if (!states->offsets) {
        free(states);
        return NULL;
    }

    // Initialize array of 'record' structures
    states->num_records = last_state - num_states + 1;
    states->records = (record_t*)malloc(sizeof(record_t) * states->num_records);

    if (!states->records) {
        free(states->offsets);
        free(states);
        return NULL;
    }

    // Initialize records with random values within a given range
    srand(time(NULL));
    for (int i = 0; i < states->num_records; i++) {
        states->records[i].value = rand() % 100 + 1;
    }

    // Dynamically allocate memory for and initialize arrays of 'int' keys
    states->num_keys = num_states;
    states->keys = (int*)malloc(sizeof(int) * states->num_keys);

    if (!states->keys) {
        free(states->offsets);
        free(states->records);
        free(states);
        return NULL;
    }

    for (int i = 0; i < states->num_keys; i++) {
        states->keys[i] = i + 1;
    }

    // Periodic logging of resource usage statistics
    printf("Memory allocation successful: num_states=%d, last_state=%d\n", num_states, last_state);

    return states;
}

// Function to free allocated memory
void free_allocated_memory(fsa_state_t* f) {
    if (f->offsets) free(f->offsets);
    if (f->records) free(f->records);
    if (f->keys) free(f->keys);
