#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>

// Structure to hold a record
typedef struct {
    int key;
    long offset;
} Record;

// Hash table structure for separate chaining with linked lists
typedef struct node {
    Record record;
    struct node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t bucket_count;
    size_t load_factor_threshold;
    pthread_mutex_t mutex;
}HashTable;

void init_hash_table(HashTable* hash_table, size_t bucket_count) {
    hash_table->buckets = (Node**)malloc(bucket_count * sizeof(Node*));
    for(size_t i = 0; i < bucket_count; i++) {
        hash_table->buckets[i] = NULL;
    }
    hash_table->bucket_count = bucket_count;
    hash_table->load_factor_threshold = 0.7f;
}

void add_to_hash_table(HashTable* hash_table, Record record) {
    size_t index = record.key % hash_table->bucket_count;
    Node* node = (Node*)malloc(sizeof(Node));
    node->record = record;
    node->next = hash_table->buckets[index];
    hash_table->buckets[index] = node;

    pthread_mutex_lock(&hash_table->mutex);
    size_t bucket_size = 0;
    for(size_t i = 0; i < hash_table->bucket_count; i++) {
        Node* current = hash_table->buckets[i];
        while(current) {
            bucket_size++;
            current = current->next;
        }
    }

    float load_factor = (float)bucket_size / hash_table->bucket_count;
    if(load_factor > hash_table->load_factor_threshold) {
        // Dynamic resizing
        size_t new_bucket_count = 2 * hash_table->bucket_count;
        Node** new_buckets = (Node**)malloc(new_bucket_count * sizeof(Node*));
        for(size_t i = 0; i < new_bucket_count; i++) {
            new_buckets[i] = NULL;
        }

        for(size_t i = 0; i < hash_table->bucket_count; i++) {
            Node* current = hash_table->buckets[i];
            while(current) {
                size_t index = current->record.key % new_bucket_count;
                if(!new_buckets[index]) {
                    new_buckets[index] = current;
                } else {
                    Node* temp = current;
                    current = current->next;
                    temp->next = new_buckets[index];
                    new_buckets[index] = temp;
                }
            }
        }

        free(hash_table->buckets);
        hash_table->buckets = new_buckets;
        hash_table->bucket_count = new_bucket_count;

    }
    pthread_mutex_unlock(&hash_table->mutex);

}

Record* get_from_hash_table(HashTable* hash_table, int key) {
    size_t index = key % hash_table->bucket_count;
    Node* current = hash_table->buckets[index];
    while(current) {
        if(current->record.key == key) {
            return &current->record;
        }
        current = current->next;
    }
    return NULL;
}

void free_hash_table(HashTable* hash_table) {
    for(size_t i = 0; i < hash_table->bucket_count; i++) {
        Node* current = hash_table->buckets[i];
        while(current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }

    free(hash_table->buckets);

}

