#include <stdlib.h>
#include <time.h>
#include <stdio.h>

typedef struct {
    int value;
} record;

typedef struct {
    long offset;
    int key;
} key_offset;

int initialize_records(key_offset* offsets, int* keys, record*** records, size_t num_records) {
    *records = (record**)malloc(num_records * sizeof(record*));

    if (*records == NULL) {
        return -1; // Out of memory
    }

    for (size_t i = 0; i < num_records; i++) {
        (*records)[i] = (record*)malloc(sizeof(record));

        if ((*records)[i] == NULL) {
            for (size_t j = 0; j < i; j++) {
                free((*records)[j]);
            }

            free(*records);
            return -1; // Out of memory
        }
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_records; i++) {
        (*records)[i]->value = rand() % 100;
    }

    return 0; // Success
}
