        sqlite3_bind_longlong(stmt, 3, *((long*)((*offsets)[i])));

        // Execute the SQL statement
        sqlite3_step(stmt);

        // Close the prepared statement
        sqlite3_finalize(stmt);
    }

    // Commit the transaction on the database
    sqlite3_commit(db);
}

