['```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long offset;
    int key;
} key_offset_pair;

void free_records(key_offset_pair *pairs, record *records) {}

void manage_records(long *offsets, int *keys, record *records, size_t max_memory_limit) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    size_t allocated_size = 0;
    size_t total_size = 0;
    long *allocated_offsets = NULL;
    int *allocated_keys = NULL;
    record **allocated_records = NULL;

    while (total_size < max_memory_limit && records) {
        pthread_mutex_lock(&mutex);

        size_t needed_size = sizeof(long) + sizeof(int);
        if (total_size + needed_size > max_memory_limit) {
            break;
        }

        allocated_offsets = realloc(allocated_offsets, total_size + needed_size);
        allocated_keys = realloc(allocated_keys, total_size + needed_size);
        record **new_records = realloc(allocated_records, total_size / sizeof(record*) + 1);
        new_records[total_size / sizeof(record*)] = records;

        allocated_offsets = (long*)((char*)allocated_offsets + total_size);
        allocated_keys = (int*)((char*)allocated_keys + total_size);

        pthread_mutex_unlock(&mutex);
    }

    // free memory
    while (total_size > 0) {
        pthread_mutex_lock(&mutex);

        size_t needed_size = sizeof(long) + sizeof(int);
        allocated_offsets -= (total_size - 1) / 2;
        allocated_keys = (int*)((char*)allocated_keys - (total_size - 1) / 2);
        total_size -= needed_size;

        pthread_mutex_unlock(&mutex);
    }

    free(allocated_offsets);
    free(allocated_keys);
    free(allocated_records);
}
```']

