        offsets[i] = i * i;
    }

    return records;
}

// Function to dynamically resize the arrays and record structures when their current capacity is exceeded
Record *resizeArrays(Record *records, int capacity) {
    // Calculate new capacity by doubling the current size
    int newCapacity = capacity * 2;

    // Allocate memory for new arrays and records
    Record *newRecords = (Record *)malloc(newCapacity * sizeof(Record));
    if (!newRecords) return NULL;  // Handle memory allocation failure

    long *newOffsets = (long *)malloc(newCapacity * sizeof(long));
    int *newKeys = (int *)malloc(newCapacity * sizeof(int));

    // Copy data from old arrays to new arrays
    for (int i = 0; i < capacity; i++) {
        newRecords[i].value = records[i].value;
        newKeys[i] = keys[i];
        newOffsets[i] = offsets[i];
    }

    // Free memory of old arrays and records
    free(records);
    free(offsets);
    free(keys);

    return newRecords;
}

// Function to verify the correctness of the initialized data
int verifyData(Record *records, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (records[i].value != rand() % 100 || records[i].key != i || records[i].offset != i * i) {
            return -1;
        }
    }
    return 0;
}

int main() {
    // Initialize arrays and record
    int capacity = 1024;  // Initial capacity
    Record *records = initArrays(capacity);

    // Verify the correctness of initialized data
    if (verifyData(records, capacity) != 0) {
        printf("Error: Data verification failed.\n");
        return -1;
    }

    // Dynamically resize arrays and record structures when their current capacity is exceeded
    for (int i = 0; i < capacity; i++) {
        if ((i + 1) * 2 > capacity) {
            records = resizeArrays(records, capacity);
            capacity *= 2;
        }
    }

    // Free all allocated memory when it is no longer needed
    free(records);

    return 0;
}
