typedef struct {
    int value;
    char* str;
} record_t;

record_t** dynamic_array_new(size_t initial_capacity) {
    record_t** array = (record_t**)malloc(initial_capacity * sizeof(record_t*));
    if (!array) {
        return NULL;  // Out of memory
    }
    for (size_t i = 0; i < initial_capacity; ++i) {
        array[i] = (record_t*)malloc(sizeof(record_t));
        if (!array[i]) {
            free(array);
            return NULL;  // Out of memory
        }
    }
    return array;
}

void dynamic_array_free(record_t** array, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        free(array[i]->str);
        free(array[i]);
    }
    free(array);
}

record_t* record_new(int value) {
    record_t* record = (record_t*)malloc(sizeof(record_t));
    if (!record) {
        return NULL;  // Out of memory
    }
    record->value = value;
    char buffer[32];
    sprintf(buffer, "Record %d", value);
    record->str = strdup(buffer);
    if (!record->str) {
        free(record);
        return NULL;  // Out of memory
    }
    return record;
}

void dynamic_array_init(record_t** array, size_t capacity, int min_value, int max_value) {
    srand(time(NULL));  // Initialize random number generator
    for (size_t i = 0; i < capacity; ++i) {
        record_t* record = record_new(rand() % ((max_value - min_value) + 1) + min_value);
        array[i] = record;
    }
}

void dynamic_array_resize(record_t** array, size_t* capacity, size_t new_capacity) {
    if (new_capacity <= *capacity) {
        return;  // No need to resize
    }
    record_t** new_array = dynamic_array_new(new_capacity);
    if (!new_array) {
        return;  // Out of memory
    }
    for (size_t i = 0; i < *capacity; ++i) {
        new_array[i] = array[i];
    }
    for (size_t i = *capacity; i < new_capacity; ++i) {
        record_t* record = record_new(rand() % ((100 - 1) + 1) + 1);
        new_array[i] = record;
    }
    free(array);
    *capacity = new_capacity;
    array = new_array;
}

void dynamic_array_print(record_t** array, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        printf("Record %d: value = %d, str = %s\n", i, array[i]->value, array[i]->str);
    }
}

int main() {
    size_t capacity = 10;
    record_t** array = dynamic_array_new(capacity);
    if (!array) {
        return -1;  // Out of memory
    }
    int min_value = 1;
    int max_value = 100;
    dynamic_array_init(array, capacity, min_value, max_value);
    size_t new_capacity = capacity * 2;
    dynamic_array_resize(&array, &capacity, new_capacity);
    dynamic_array_print(array, capacity);
    dynamic_array_free(array, capacity);
    return 0;
}
