char *getRandomString(char **stringPool) {
    static char buffer[100];
    int numUsed = 0;
    char *result = NULL;

    for (int i = 0; i < 200; i++) {
        if (!stringPool[i]) continue;
        int found = 0;
        for (int j = 0; j < numUsed; j++) {
            if (strcmp(stringPool[j], stringPool[i]) == 0) {
                found = 1;
                break;
            }
        }

        if (!found) {
            strcpy(buffer, stringPool[i]);
            result = buffer;
            numUsed++;
        }
    }

    return result;
}

