#define MAX_CONCURRENCY 10
#define RANDOM_RANGE 100

typedef struct {
    int value;
} record;

record* create_records(int num_records) {
    record* records = (record*)malloc(num_records * sizeof(record));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % RANDOM_RANGE;
    }
    return records;
