void init_data_points(int num_points, long* offset_values, int* keys, double* values, data_point** points) {
    srand(time(NULL));

    *points = (data_point*)malloc(num_points * sizeof(data_point));

    for (int i = 0; i < num_points; i++) {
        (*points)[i].key = rand() % 100;
        if ((*points)[i].key > RAND_MAX / 2) {
            // handle overflow
            printf("Overflow detected. Adjusting value.\n");
            (*points)[i].key -= RAND_MAX / 2;
        }

        (*points)[i].value = (double)rand() / RAND_MAX * 100.0;
        if ((*points)[i].value > RAND_MAX / 2.0) {
            // handle overflow
            printf("Overflow detected. Adjusting value.\n");
            (*points)[i].value -= RAND_MAX / 2.0;
        }

        int desc_len = rand() % 10 + 1;
        char* desc = (char*)malloc(desc_len * sizeof(char));
        for (int j = 0; j < desc_len; j++) {
            desc[j] = 'a' + rand() % 26;
        }
        desc[desc_len - 1] = '\0';
        (*points)[i].description = desc;
    }
}

int main() {
