typedef struct {
    float temperature;
} device;

typedef struct {
    int key;
    double value;
    char* string;
} data_point;

void init_devices(device** devices, int num_devices) {
    for (int i = 0; i < num_devices; i++) {
        device* dev = (device*)malloc(sizeof(device));
        dev->temperature = (float)(rand() / (RAND_MAX / 1.0f)); // random temperature reading
        devices[i] = dev;
    }
}

void init_data_points(data_point** data_points, int num_data_points) {
    for (int i = 0; i < num_data_points; i++) {
        data_point* dp = (data_point*)malloc(sizeof(data_point));
        dp->key = (rand() % 100); // random key
        dp->value = (double)(rand() / (RAND_MAX / 1.0f)); // random value
        char buffer[MAX_STRING_LENGTH];
        int len = (rand() % MAX_STRING_LENGTH) + 1; // random string length
        for (int j = 0; j < len; j++) {
            buffer[j] = (char)(rand() % 26); // generate random ASCII characters
        }
        buffer[len] = '\0';
        dp->string = (char*)malloc(len + 1);
        strcpy(dp->string, buffer);
        data_points[i] = dp;
    }
}

void free_devices(device** devices, int num_devices) {
    for (int i = 0; i < num_devices; i++) {
        device* dev = devices[i];
        free(dev);
    }
    free(devices);
}

void free_data_points(data_point** data_points, int num_data_points) {
    for (int i = 0; i < num_data_points; i++) {
        data_point* dp = data_points[i];
        free(dp->string); // free string memory
        free(dp);
    }
    free(data_points);
}

void manage_memory(device** devices, int num_devices, data_point** data_points, int num_data_points) {
    size_t total_devices_size = sizeof(device) * num_devices;
    size_t total_data_points_size = sizeof(data_point) * num_data_points;

    if (total_devices_size + total_data_points_size > TOTAL_MEMORY_LIMIT) {
        printf("Memory limit exceeded. Freeing memory...\n");
        free_devices(devices, num_devices);
        free_data_points(data_points, num_data_points);
    }
}

int main() {
    srand(time(NULL)); // seed random number generator

    int num_devices = 500;
    device* devices = (device*)malloc(sizeof(device) * num_devices);
    init_devices(devices, num_devices);

    int num_data_points = 2000;
    data_point* data_points = (data_point*)malloc(sizeof(data_point) * num_data_points);
    init_data_points(data_points, num_data_points);

    manage_memory(devices, num_devices, data_points, num_data_points);

    // ... use devices and data_points as needed ...

    free_devices(devices, num_devices);
    free_data_points(data_points, num_data_points);

    return 0;
}
