    static void initialize(std::vector<Node>* nodes, int numNodes) {
        for (int i = 0; i < numNodes; ++i) {
            Node node;
            std::string keyStr = std::to_string(i);
            std::string offsetStr = std::to_string(rand());
            node.sensorData.key = rand();
            node.sensorData.offset = rand();
            if (rand() % 2 == 0) {
                node.isTemperatureSensor = true;
                node.sensorData.data = keyStr + " - Temperature: " + offsetStr;
            } else {
                node.sensorData.data = keyStr + " - Humidity: " + offsetStr;
            }
            nodes->push_back(node);
        }
    }

    static void logSensorData(std::vector<Node>& nodes) {
        for (const auto& node : nodes) {
            if (node.isTemperatureSensor) {
                std::cout << "Temperature Sensor Data: " << node.sensorData.data << std::endl;
            } else {
                std::cout << "Humidity Sensor Data: " << node.sensorData.data << std::endl;
            }
        }
    }

    static void freeMemory(std::vector<Node>& nodes) {
        for (auto& node : nodes) {
            if (node.isTemperatureSensor) {
                // Free dynamically allocated string
                delete[] &node.sensorData.data;
            } else {
                // Free dynamically allocated string
                delete[] &node.sensorData.data;
            }
        }
    }

    static std::vector<Node> createNodeList(int numNodes) {
        if (numNodes <= 0) {
            return {};
        }

        std::vector<Node> nodes;
        initialize(&nodes, numNodes);
        return nodes;
    }

    static void handleConcurrentAccess(std::vector<Node>& nodes) {
        // Handle concurrent access
        for (auto& node : nodes) {
            if (node.isTemperatureSensor) {
                // Process temperature sensor data concurrently
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            } else {
                // Process humidity sensor data concurrently
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        }
    }
};

int main() {
    int numNodes = 5;
    auto nodes = DynamicSmartCityMonitoringSystem::createNodeList(numNodes);

    DynamicSmartCityMonitoringSystem::logSensorData(nodes);
    DynamicSmartCityMonitoringSystem::handleConcurrentAccess(nodes);
    DynamicSmartCityMonitoringSystem::freeMemory(nodes);

    return 0;
}
