    long* offsetValues = (long*)malloc(numOffsets * sizeof(long));
    int* intKeys = (int*)malloc(numOffsets * sizeof(int));
    double* doubleValues = (double*)malloc(numOffsets * sizeof(double));

    // Initialize arrays from file
    FILE* configFile = fopen("config.txt", "r");
    if (!configFile) {
        printf("Error opening config file.\n");
        return;
    }

    for (int i = 0; i < numOffsets; i++) {
        fscanf(configFile, "%ld %d %lf\n", &offsetValues[i], &intKeys[i], &doubleValues[i]);
    }
    fclose(configFile);

    // Allocate memory for records
    dataRecord* recordArray = (dataRecord*)malloc(numOffsets * sizeof(dataRecord));

    // Initialize records with random values and strings
    srand(time(NULL));
    for (int i = 0; i < numOffsets; i++) {
        recordArray[i].key = rand() % 100;
        recordArray[i].value = (double)rand() / RAND_MAX;
        char str[20];
        sprintf(str, "Record_%d", i);
        recordArray[i].str = strdup(str);
    }

    // Free allocated memory
    free(offsetValues);
    free(intKeys);
    free(doubleValues);

    *offsets = numOffsets;
    *keys = intKeys;
    *values = doubleValues;
    *records = recordArray;
}

void deallocArraysAndRecords(dataRecord* records) {
    for (int i = 0; i < *records; i++) {
        free(records[i].str);
    }
    free(records);
}
