```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
#include <openssl/aes.h>
#include <pthread.h>

// Define the structure for sensor data records
typedef struct {
    float value;
    char* str;
} Record;

// Function to dynamically allocate memory for a new record
Record* create_record(float value, const char* str) {
    Record* record = (Record*)malloc(sizeof(Record));
    if(record) {
        record->value = value;
        record->str = strdup(str);
    }
    return record;
}

// Function to compress a record using Zlib
int compress_record(z_stream cstream, Record* record) {
    // Define the compression buffer size
    int buffer_size = 1024;

    // Initialize the compression buffer
    unsigned char* buffer = (unsigned char*)malloc(buffer_size);
    z_stream cinfo = {0};

    // Set up the Zlib compressor
    cstream.zalloc = Z_NULL;
    cstream.zfree = Z_NULL;
    cstream.opaque = Z_NULL;

    // Compress the record and store it in the buffer
    cstream.next_in = (Bytef*)record->str;
    cstream.avail_in = strlen(record->str);
    cstream.total_in = 0;

    int bytes_written = 0;
    do {
        cstream.next_out = buffer;
        cstream.avail_out = buffer_size;
        cstream.total_out = 0;

        // Compress the record
        deflate(&cstream, Z_FINISH);

        bytes_written += cstream.total_out;
    } while (cstream.avail_out == 0);
    return bytes_written;
}

// Function to encrypt a record using AES
int encrypt_record(BIO* bio, Record* record) {
    // Define the encryption key and IV
    const char* key = "your_secret_key";
    const char* iv = "your_secret_iv";

    // Create an EVP context for AES encryption
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    // Encrypt the record and store it in a buffer
    int buffer_size = 1024;
    unsigned char* buffer = (unsigned char*)malloc(buffer_size);
    unsigned char* encrypted_buffer = (unsigned char*)malloc(buffer_size);
    int bytes_written = 0;

    do {
        // Set up the encryption context
        EVP_EncryptInit_ex(ctx, NULL, NULL, record->str, strlen(record->str));

        // Encrypt the record
        int bytes_encrypted = EVP_EncryptUpdate(ctx, buffer, &bytes_written, record->str, strlen(record->str));
        EVP_CIPHER_CTX_free(ctx);

        // Store the encrypted record in the buffer
        memcpy(encrypted_buffer, buffer, bytes_encrypted);
    } while (bytes_written > 0);
    return bytes_written;
}

// Function to handle sensor data records asynchronously using threads
void* handle_records(void* arg) {
    // Define the thread ID and the maximum memory limit
    pthread_t thread_id = pthread_self();
    int max_memory_limit = 1024 * 1024 * 5; // 5MB

    // Create a record pool to store compressed and encrypted records
    Record** record_pool = (Record**)malloc(max_memory_limit);
    for(int i = 0; i < max_memory_limit; i++) {
        record_pool[i] = NULL;
    }

    while(1) {
        // Handle new sensor data records
        for(int i = 0; i < max_memory_limit; i++) {
            if(record_pool[i]) {
                // Compress the record using Zlib and encrypt it using AES
                int bytes_compressed = compress_record(zstream, record_pool[i]);
                int bytes_encrypted = encrypt_record(bio, record_pool[i]);

                // Store the compressed and encrypted record in a buffer
                unsigned char* buffer = (unsigned char*)malloc(bytes_compressed + bytes_encrypted);
                memcpy(buffer, compressed_data, bytes_compressed);
                memcpy(buffer + bytes_compressed, encrypted_data, bytes_encrypted);

                // Log resource usage statistics asynchronously
                pthread_create(&thread_id, NULL, log_resources, NULL);

                // Release the record from the pool and free its memory
                free(record_pool[i]->str);
                free(record_pool[i]);
            }
        }

        // Sleep for a short duration before handling new records
        sleep(1);
    }
}

int main() {
    // Initialize OpenSSL for cryptographic operations
    SSL_library_init();

    // Define the maximum memory limit and the thread ID
    int max_memory_limit = 1024 * 1024 * 5; // 5MB
    pthread_t thread_id = pthread_self();

