    Record** record_pool = (Record**)malloc(max_memory_limit);
    for(int i = 0; i < max_memory_limit; i++) {
        record_pool[i] = NULL;
    }

    // Handle sensor data records asynchronously using threads
    pthread_create(&thread_id, NULL, handle_records, NULL);

    return 0;
}
