#include <zlib.h>

typedef struct {
    double value;
    char *str;
} Record;

void *malloc_secure(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

int record_compare(const void *a, const void *b) {
    Record *ra = (Record *) a;
    Record *rb = (Record *) b;
    return memcmp(&ra->str, &rb->str, strlen(ra->str) + 1);
}

void encrypt_record(Record *record, int key_size) {
    AES_KEY aes_key;
    unsigned char iv[AES_BLOCK_SIZE];
    unsigned char ciphertext[32];

    // Generate IV and set up AES key
    for (int i = 0; i < AES_BLOCK_SIZE; i++) {
        iv[i] = (unsigned char) rand();
    }
    AES_set_encrypt_key((const unsigned char *) "my_secret_key", key_size, &aes_key);
    AES_cfb128_encrypt(&record->value, ciphertext, 32, &aes_key, iv, 0, 1);

    // Free IV
    free(iv);
}

void compress_record(Record *record) {
    int compr_length = compress((void *) &record->str, strlen(record->str), NULL, 0);
    if (compr_length < 0) {
        printf("Compression failed\n");
        exit(1);
    }
    record->str = malloc(compr_length + 1);
    memcpy(record->str, (void *) &record->str, compr_length);
    record->str[compr_length] = '\0';
}

int main() {
    // Initialize Zlib compression
    z_stream strm;
    deflateInit(&strm, 9);

    // Initialize AES encryption
    int key_size = 16; // for example, use AES-128
    srand(time(NULL));

    // Allocate and initialize data records
    Record *records = malloc_secure(sizeof(Record) * 100);
    for (int i = 0; i < 100; i++) {
        record->value = (double) rand() / RAND_MAX;
        record->str = malloc_secure(strlen("Example string ") + 1);
        strcpy(record->str, "Example string ");
        encrypt_record(record, key_size);
        compress_record(record);
    }

    // Periodically log resource usage statistics
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, log_stats, NULL);

    return 0;
}

void *log_stats(void *arg) {
    while (1) {
        // Log resource usage statistics here
        printf("Peak memory usage: %zu MB\n", peak_memory_usage());
        sleep(10);
    }
}
