int find(int* parent, int x) {
    if (parent[x] != x) {
        parent[x] = find(parent, parent[x]);
    }
    return parent[x];
}

void union_sets(int* parent, int x, int y) {
    int root_x = find(parent, x);
    int root_y = find(parent, y);

    if (root_x < root_y) {
        parent[root_y] = root_x;
    } else {
        parent[root_x] = root_y;
    }
}

int count_disjoint_pairs(int** data, int* size, int* parent) {
    int disjoint_pairs = 0;

    for (int i = 0; i < *size; i++) {
        for (int j = i + 1; j < *size; j++) {
            if (find(parent, i) != find(parent, j)) {
                union_sets(parent, i, j);
                disjoint_pairs++;
            }
        }
    }

    printf("Disjoint pairs: %d\n", disjoint_pairs);

    return disjoint_pairs;
}

int main() {
    // Initialize variables
    int num_records = 10000;
    Record* data = (Record*)malloc(num_records * sizeof(Record));

    FILE* file = fopen("data.txt", "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        return -1;
    }

    // Read data from file
    for (int i = 0; i < num_records; i++) {
        fscanf(file, "%d %s\n", &data[i].offset, data[i].key);
    }
    fclose(file);

    int* parent = (int*)malloc(num_records * sizeof(int));
    for (int i = 0; i < num_records; i++) {
        parent[i] = i;
    }

    // Perform Union-Find operations
    count_disjoint_pairs(&data, &num_records, parent);

    free(data);
    free(parent);

    return 0;
}
