// Function to calculate mean
double calculateMean(double *arr, int n) {
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += arr[i];
    }
    return sum / n;
}

// Function to calculate median
double calculateMedian(double *arr, int n) {
    qsort(arr, n, sizeof(double), NULL);
    if (n % 2 == 1)
        return arr[n/2];
    else
        return (arr[(n-1)/2] + arr[n/2]) / 2;
}

// Function to calculate standard deviation
double calculateStandardDeviation(double *arr, int n) {
    double mean = calculateMean(arr, n);
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += pow(arr[i] - mean, 2);
    }
    return sqrt(sum / n);
}

// Function to initialize arrays and records
