    // Initialize offsets array
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = i;
    }

    // Initialize sensor values array
    for (int i = 0; i < numRecords; i++) {
        sensorValues[i] = (double)i;
    }

    // Initialize records array
    for (int i = 0; i < numRecords; i++) {
        (*records)[i]->value = i;
    }
}

