    // Initialize OpenSSL encryption context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_add_cipher(ctx, "AES-256-CBC");

    // Encrypt each data record
    for (int i = 0; i < num_records; i++) {
        char encrypted_record[MAX_MEMORY];
        int len = strlen(records[i]->string);
        unsigned char* buffer = (unsigned char*)malloc(len + 1);
        memcpy(buffer, records[i]->string, len);
        buffer[len] = '\0';

        // Compress the string
        uLong compressed_len;
        unsigned char* compressed = compress((const Bytef*)buffer, len, &compressed_len);
        if (compressed == NULL) {
            free(buffer);
            EVP_CIPHER_CTX_free(ctx);
            return -1;  // Error during compression
        }

        // Encrypt the compressed string
        int ciphertext_len;
        unsigned char* encrypted = AES_encrypt((unsigned char*)buffer, len, ctx, &ciphertext_len);
        if (encrypted == NULL) {
            free(buffer);
            free(compressed);
            EVP_CIPHER_CTX_free(ctx);
            return -1;  // Error during encryption
        }

        // Store the encrypted record
        memcpy(encrypted_record, encrypted, ciphertext_len);
        free(buffer);
        free(compressed);
        free(encrypted);
    }

    // Deallocate OpenSSL context
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

