import json

def replace_placeholders(config_file, placeholders):
    for placeholder, value in placeholders.items():
        command = f"sed -i 's/{placeholder}/{value}/g' {config_file}"
        try:
            subprocess.run(command.split(" "), check=True)
        except subprocess.CalledProcessError as e:
            raise Exception(f"Sed command failed: {e}")

def add_encrypted_password(config_file, encrypted_password):
    command = f"echo '{encrypted_password}' >> {config_file}"
    try:
        subprocess.run(command.split(" "), check=True)
    except subprocess.CalledProcessError as e:
        raise Exception(f"Sed command failed: {e}")

