Record* record_init(size_t max_limit, size_t* total_allocated) {
    Record* records = NULL;
    long* offsets = NULL;
    int* keys = NULL;

    // Initialize memory for offset and key arrays
    if (!(offsets = (long*)malloc(max_limit * sizeof(long)))) {
        return NULL;
    }
    if (!(keys = (int*)malloc(max_limit * sizeof(int)))) {
        free(offsets);
        offsets = NULL;
        return NULL;
    }

    // Initialize record array
    if (!(records = (Record*)malloc(max_limit * sizeof(Record)))) {
        free(offsets);
        free(keys);
        offsets = NULL;
        keys = NULL;
        return NULL;
    }

    size_t total_allocated_size = max_limit * sizeof(long) + max_limit * sizeof(int) + max_limit * sizeof(Record);

    if (*total_allocated < total_allocated_size) {
        *total_allocated += total_allocated_size;
    }

    // Set record values to random
    for (size_t i = 0; i < max_limit; i++) {
        records[i].key = rand() % 100;
    }

    return records;
}

void record_free(Record* records, size_t* total_allocated) {
    free(records);
    *total_allocated -= max_limit * sizeof(Record);
}

