// Initialize an array of config_entries and manage memory dynamically
int initialize_config_parser(int max_entries, int max_key_len) {
    // Calculate total memory needed based on max_entries and max_key_len
    size_t total_memory = sizeof(config_entry) * (max_entries + 1);
    char* memory_pool = (char*)malloc(total_memory);

    if (!memory_pool) {
        printf("Error: Memory allocation failed.\n");
        return -1;
    }

    // Initialize the array of config_entries
    config_entry* entries = (config_entry*)memory_pool;

    for (int i = 0; i < max_entries; i++) {
        // Dynamically allocate memory for each entry's key
        char* key = (char*)malloc((max_key_len + 1) * sizeof(char));
        if (!key) {
            printf("Error: Memory allocation failed.\n");
            return -1;
        }
        entries[i].key = key;

        // Initialize the type and value for each entry
        entries[i].type = i % 3; // Randomly select a type (0=int, 1=bool, 2=str)
        if (entries[i].type == 2) {
            entries[i].value = strdup("random_value");
        } else if (entries[i].type == 1) {
            entries[i].value = (void*)malloc(sizeof(int));
            *(int*)entries[i].value = rand() % 10;
        } else {
            // Initialize int value for type=0
            entries[i].value = (void*)malloc(sizeof(int));
            *(int*)entries[i].value = rand() % 100;
        }
    }

    // Periodically check and log resource usage statistics
    printf("Peak memory usage: %zu bytes.\n", total_memory);

    return 0;
}

// Example of how to use the config_parser function with AES encryption
int main() {
    int max_entries = 10;
    int max_key_len = 16;

    // Initialize the config parser and encrypt each entry's value
    if (initialize_config_parser(max_entries, max_key_len) < 0) {
        return -1;
    }

    // Encrypt the values using AES
    for (int i = 0; i < max_entries; i++) {
        config_entry* entry = &entries[i];
        // Create an AES context and encrypt the value
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        unsigned char* encrypted_value;
        int encrypted_len;

        EVP_EncryptInit_ex(ctx, NULL, NULL, (void*)entry->value, entry->key);
        EVP_EncryptUpdate(ctx, &encrypted_value, &encrypted_len, (void*)entry->value, sizeof(int));

        // Store the encrypted value and free any temporary memory
        entry->value = (void*)malloc(encrypted_len + 1);
        memcpy((void*)entry->value, encrypted_value, encrypted_len);
        free(encrypted_value);

        EVP_CIPHER_CTX_free(ctx);
    }

    return 0;
}
