The JavaScript function for traversing a DOM tree efficiently is as follows:

```javascript
function traverseDOM(root, selector, callback) {
    const cache = {};

    (function recurse(node) {
        if (!node) return;

        if (cache[selector]) {
            Array.prototype.push.apply(cache[selector], node.querySelectorAll(selector));
        } else {
            let matches = node.querySelectorAll(selector);
            if (matches.length > 0) {
                Array.prototype.push.apply(cache[selector], matches);
            }
        }

        recurse(node.firstElementChild);
        recurse(node.lastElementChild);

        Object.keys(node.attributes).forEach((attrName) => {
            const attrValue = node.getAttribute(attrName);
            if (callback && callback(attrName, attrValue)) {
                recurse(node.children[0]);
            }
        });
    })(root);

    return cache;
}
```

This JavaScript function caches the matching elements to optimize performance.']

