double multiply_matrices(double** mat1, double** mat2, int rows1, int cols1, int rows2, int cols2) {
    double prod = 0.0;
    for (int i = 0; i < rows1; i++) {
        for (int j = 0; j < cols2; j++) {
            for (int k = 0; k < cols1; k++) {
                prod += mat1[i][k] * mat2[k][j];
            }
        }
    }
    return prod;
}

void normalize_data(sensor_data* data, int count) {
    double mean = 0.0;
    double stdev = 0.0;
    for (int i = 0; i < count; i++) {
        mean += data[i].data;
    }
    mean /= count;

    for (int i = 0; i < count; i++) {
        stdev += (data[i].data - mean) * (data[i].data - mean);
    }
    stdev /= count;

    for (int i = 0; i < count; i++) {
        data[i].data = (data[i].data - mean) / sqrt(stdev + 1e-9);
    }
}

void parallel_normalize_data(sensor_data* data, int count) {
    pthread_t threads[count];
    pthread_attr_t attr;
    pthread_attr_init(&attr);

    for (int i = 0; i < count; i++) {
        pthread_create(&threads[i], &attr, normalize_thread, (void*)&data[i]);
    }

    for (int i = 0; i < count; i++) {
        pthread_join(threads[i], NULL);
    }
}

void* normalize_thread(void* arg) {
    sensor_data* data = (sensor_data*)arg;
    double mean = 0.0;
    double stdev = 0.0;

    for (int i = 0; i < 10; i++) {
        mean += data[i].data;
    }
    mean /= 10;

    for (int i = 0; i < 10; i++) {
        stdev += (data[i].data - mean) * (data[i].data - mean);
    }
    stdev /= 10;

    for (int i = 0; i < 10; i++) {
        data[i].data = (data[i].data - mean) / sqrt(stdev + 1e-9);
    }

    return NULL;
}

void parallel_add_matrices(double** mat1, double** mat2, int rows, int cols) {
    pthread_t threads[rows];
    pthread_attr_t attr;
    pthread_attr_init(&attr);

    for (int i = 0; i < rows; i++) {
        pthread_create(&threads[i], &attr, add_matrix_thread, (void*)&mat1[i]);
    }

    for (int i = 0; i < rows; i++) {
        pthread_join(threads[i], NULL);
    }
}

void* add_matrix_thread(void* arg) {
    double* mat = (double*)arg;
    double sum = 0.0;

    for (int j = 0; j < cols; j++) {
        sum += *mat + *(mat + j);
    }

    return NULL;
}
