    char message[256];
    int severity;
} log_entry_t;

log_entry_t* log_entries = NULL;
size_t log_entry_count = 0;
size_t log_entry_capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_logging() {
    pthread_mutex_lock(&mutex);
    log_entry_capacity = (sizeof(log_entry_t) * MAX_LOG_ENTRIES) + sizeof(size_t);
    if ((log_entries = malloc(log_entry_capacity)) == NULL || 
        (log_entry_count = 0, log_entry_capacity = 0) ) {
        // handle allocation error
        free(log_entries);
        log_entries = NULL;
    }
    pthread_mutex_unlock(&mutex);
}

void add_log_entry(int timestamp, const char* message, int severity) {
    pthread_mutex_lock(&mutex);
    if (log_entry_count >= log_entry_capacity) {
        size_t new_capacity = log_entry_capacity * 2 + sizeof(size_t);
        void* temp = realloc(log_entries, new_capacity);
        if (temp == NULL) {
            // handle allocation error
            free(log_entries);
            log_entries = NULL;
        } else {
            log_entries = temp;
            log_entry_capacity = new_capacity;
        }
    }

    log_entry_t* entry = &log_entries[log_entry_count++];
    entry->timestamp = timestamp;
    strncpy(entry->message, message, 256);
    entry->severity = severity;

    pthread_mutex_unlock(&mutex);
}

void free_logging() {
    pthread_mutex_lock(&mutex);
    if (log_entries != NULL) {
        free(log_entries);
        log_entries = NULL;
        log_entry_count = 0;
        log_entry_capacity = 0;
    }
    pthread_mutex_unlock(&mutex);
}
