typedef struct Node {
    char* str;
    int num;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t total_memory_used = 0;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL || size > MAX_MEMORY - (total_memory_used + size)) {
        free(ptr);
        ptr = my_malloc(size);
    }
    return ptr;
}

void insertNode(char* str, int num) {
    Node* newNode = (Node*) my_malloc(sizeof(Node));
    newNode->str = strdup(str);
    newNode->num = num;
    newNode->next = head;
    pthread_mutex_lock(&lock);
    if (head != NULL)
        ((Node*) head)->prev = &newNode;
    else
        head = &newNode;
    total_memory_used += sizeof(Node) + strlen(str) + 1;
    pthread_mutex_unlock(&lock);
}

void deleteNode() {
    Node* current = head;
    if (current == NULL)
        return;
    pthread_mutex_lock(&lock);
    head = current->next;
    if (head != NULL)
        head->prev = NULL;
    free(current->str);
    free(current);
    total_memory_used -= sizeof(Node) + strlen(current->str) + 1;
    pthread_mutex_unlock(&lock);
}

void traverseList() {
    Node* current = head;
    while (current != NULL) {
        printf("String: %s, Number: %d\n", current->str, current->num);
        current = current->next;
    }
}

void freeAllMemory() {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
    head = NULL;
    total_memory_used = 0;
}
