    int key;
    char buffer[10];
} record_t;

record_t* record_new(int key, const char* buffer) {
    record_t* rec = (record_t*)malloc(sizeof(record_t));
    if (!rec) {
        return NULL;
    }
    rec->key = key;
    strcpy(rec->buffer, buffer);
    return rec;
}

void record_free(record_t* rec) {
    free(rec);
}

int offset_alloc(int size) {
    int* offsets = (int*)malloc(size * sizeof(int));
    if (!offsets) {
        return -1; // Error allocating memory
    }
    return offsets;
}

void offset_free(int* offsets, int size) {
    free(offsets);
}

int key_alloc(int size) {
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        return -1; // Error allocating memory
    }
    return keys;
}

void key_free(int* keys, int size) {
    free(keys);
}

char** buffer_alloc(int size) {
    char** buffers = (char**)malloc(size * sizeof(char*));
    if (!buffers) {
        return NULL; // Error allocating memory
    }
    for (int i = 0; i < size; i++) {
        buffers[i] = (char*)malloc(10);
        if (!buffers[i]) {
            buffer_free(buffers, i);
            return NULL;
        }
    }
    return buffers;
}

void buffer_free(char** buffers, int size) {
    for (int i = 0; i < size; i++) {
        free(buffers[i]);
    }
    free(buffers);
}

// Function to manage linked list of nodes
record_t* linked_list_alloc(int max_size) {
    record_t* head = NULL;
    record_t** records = buffer_alloc(max_size);
    int offsets[max_size];
    int keys[max_size];

    // Initialize all values in arrays to 0 or empty strings
    for (int i = 0; i < max_size; i++) {
        offsets[i] = 0;
        keys[i] = 0;
        if (records) {
            memset(records[i], '\0', 10);
        }
    }

    // Initialize head of the linked list
    head = record_new(0, "");

    return head;
}

void linked_list_free(record_t* head) {
    while (head) {
        record_t* next = head->next;
        free(head);
        head = next;
    }
}
