        DataRecord record = {keys[i], values[i], buffer};
        dataRecords[i] = &record;
    }

    return dataRecords;
}

// Function to free all allocated memory
void freeMemory(DataRecord** dataRecords, int arraySize) {
    for(int i = 0; i < arraySize; i++) {
