// Define a custom allocator structure
typedef struct {
    void* base;
    size_t capacity;
} CustomAllocator;

// Initialize the custom allocator
CustomAllocator init_allocator(size_t capacity) {
    CustomAllocator alloc = (CustomAllocator)malloc(sizeof(struct));
    alloc.base = malloc(capacity);
    alloc.capacity = capacity;
    return alloc;
}

// Free the custom allocator and its memory block
void free_allocator(CustomAllocator alloc) {
    free(alloc.base);
    free((void*)(&alloc));
}

// Define a record structure with an integer field
typedef struct {
    int value;
} Record;

// Allocate memory for arrays and structures, initialize them with random values
int* allocate_and_init_arrays(size_t max_limit, size_t array_size) {
    // Initialize the custom allocator
    CustomAllocator alloc = init_allocator(max_limit);

    // Allocate memory for two integer arrays and an array of record structures
    int* offset_values = (int*)malloc(array_size * sizeof(int));
    int* keys = (int*)malloc(array_size * sizeof(int));
    Record* records = (Record*)malloc(array_size * sizeof(Record));

    // Initialize the arrays with random values within a specified range
    srand(time(NULL));
    for(size_t i = 0; i < array_size; i++) {
        offset_values[i] = rand() % max_limit;
        keys[i] = rand() % max_limit;
        records[i].value = rand() % max_limit;
    }

    // Free the custom allocator and its memory block
    free_allocator(alloc);

    return (int*)malloc(array_size * sizeof(int));
}

// Function to encrypt record structures using AES in CBC mode with an IV generated from HMAC-SHA256 of a user-provided key
void* encrypt_records(void* records, int record_count, const void* key) {
    // Initialize the custom allocator
    CustomAllocator alloc = init_allocator(record_count * sizeof(Record));

    // Allocate memory for the encrypted records and initialization vector
    void* encrypted_records = (void*)malloc(record_count * sizeof(Record));
    unsigned char iv[16];
    HMAC_CTX ctx;
    HMAC_Init(&ctx, key, 32, EVP_sha256());
    HMAC_Update(&ctx, NULL, 0);
    HMAC_Final(&ctx, iv);

    // Encrypt each record using AES in CBC mode with the generated IV
    for(int i = 0; i < record_count; i++) {
        Record* record = &((Record*)records)[i];
        unsigned char encrypted_record[16];
        AES_KEY aes_key;
        EVP_BytesToKey(&aes_key, EVP_sha256(), NULL, key, 32, (unsigned char*)"AES", 3);
        AES_cbc_encrypt(record, encrypted_record, sizeof(Record), &aes_key, iv, AES_ENCRYPT);
    }

    // Free the custom allocator and its memory block
    free_allocator(alloc);

    return encrypted_records;
}

// Function to decrypt record structures using AES in CBC mode with an IV generated from HMAC-SHA256 of a user-provided key
void* decrypt_records(void* records, int record_count, const void* key) {
    // Initialize the custom allocator
    CustomAllocator alloc = init_allocator(record_count * sizeof(Record));

    // Allocate memory for the decrypted records and initialization vector
    void* decrypted_records = (void*)malloc(record_count * sizeof(Record));
    unsigned char iv[16];
    HMAC_CTX ctx;
    HMAC_Init(&ctx, key, 32, EVP_sha256());
    HMAC_Update(&ctx, NULL, 0);
    HMAC_Final(&ctx, iv);

    // Decrypt each record using AES in CBC mode with the generated IV
    for(int i = 0; i < record_count; i++) {
        Record* record = &((Record*)records)[i];
        unsigned char decrypted_record[16];
        AES_KEY aes_key;
        EVP_BytesToKey(&aes_key, EVP_sha256(), NULL, key, 32, (unsigned char*)"AES", 3);
        AES_cbc_encrypt(record, decrypted_record, sizeof(Record), &aes_key, iv, AES_DECRYPT);
    }

    // Free the custom allocator and its memory block
    free_allocator(alloc);

    return decrypted_records;
}

// Function to log encryption/decryption events with timing information
void log_event(const char* message) {
    time_t now = time(NULL);
    printf("Event: %s, Time: %02d:%02d:%02d\n", message, (int)(now / 3600), (int)((now % 3600) / 60), (int)(now % 60));
}
