#include <openssl/rsa.h>
#include <openssl/sha.h>

typedef struct {
    double dval;
    int ival;
    char* str;
} dataRecord;

dataRecord* initializeData(int numRecords, int maxMemLimit, int minDoubleRange, int maxDoubleRange, int minIntRange, int maxIntRange, int stringLen) {
    if (numRecords > maxMemLimit / sizeof(dataRecord)) {
        printf("Error: Exceeding memory limit.\n");
        return NULL;
    }

    dataRecord* records = (dataRecord*)calloc(numRecords, sizeof(dataRecord));
    double* doubles = (double*)calloc(numRecords, sizeof(double));
    int* ints = (int*)calloc(numRecords, sizeof(int));
    char** strings = (char**)calloc(numRecords, sizeof(char*));

    for (int i = 0; i < numRecords; i++) {
        records[i].dval = (double)(rand() % (maxDoubleRange - minDoubleRange + 1) + minDoubleRange);
        records[i].ival = (int)((rand() % (maxIntRange - minIntRange + 1)) + minIntRange);

        char buffer[stringLen];
        sprintf(buffer, "String_%d", i);
        strings[i] = (char*)strndup(buffer, stringLen);
    }

    if (!records || !doubles || !ints || !strings) {
        printf("Error: Memory allocation failed.\n");
        free(records);
        free(doubles);
        free(ints);
        for (int i = 0; i < numRecords; i++) {
            free(strings[i]);
        }
        free(strings);
        return NULL;
    }

    // Perform cryptographic operations concurrently with data initialization
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_add_cipher(ctx, EVP_aes_128_cbc());
    EVP_add_digest(ctx, EVP_sha256());

    for (int i = 0; i < numRecords; i++) {
        char buffer[stringLen];
        sprintf(buffer, "String_%d", i);
        unsigned char* encryptedBuffer = (unsigned char*)malloc(stringLen + 16);
        int outLen;
        EVP_EncryptInit_ex(ctx, NULL, NULL, strings[i], stringLen);
        EVP_EncryptUpdate(ctx, encryptedBuffer, &outLen, buffer, strlen(buffer));
        EVP_CIPHER_CTX_free(ctx);

        // Check resource usage statistics periodically
        if (i % 100 == 0) {
            printf("Peak memory usage: %ld MB.\n", (long)(getpeakmemoryusage() / (1024 * 1024)));
        }
    }

    free(doubles);
    free(ints);
    for (int i = 0; i < numRecords; i++) {
        free(strings[i]);
    }
    free(strings);

    return records;
}

void freeData(dataRecord* records) {
    if (!records) {
        return;
    }

    for (int i = 0; i < numRecords; i++) {
        free(records[i].str);
    }
    free(records);
}
