#include <time.h>
#include <string.h>

struct task {
    int priority;
    char name[256];
    struct timespec next_execution_time;
};

void* task_array_alloc(size_t size, int max_limit) {
    void* mem = malloc(size);
    if (!mem || pthread_mutex_unlock(&mem_lock)) {
        free(mem);
        return NULL;
    }
    return mem;
}

void task_array_free(void** array, size_t size) {
    for (int i = 0; i < size; ++i) {
        free(array[i]);
    }
    free(array);
}

int task_array_init(task_array_t* array, int max_limit) {
    if (!array || pthread_mutex_lock(&mem_lock)) {
        return -1;
    }
    array->size = 0;
    array->capacity = 10; // Initial capacity
    array->tasks = (task*)task_array_alloc(array->capacity * sizeof(task), max_limit);
    if (!array->tasks) {
        pthread_mutex_unlock(&mem_lock);
        return -1;
    }
    for (int i = 0; i < array->capacity; ++i) {
        strncpy(array->tasks[i].name, "Unnamed Task", 256);
    }
    return 0;
}

void task_array_add(task_array_t* array, struct task new_task) {
    if (!array || pthread_mutex_lock(&mem_lock)) {
        return;
    }
    if (array->size >= array->capacity) {
        // Reallocate memory with increased capacity
        void** temp_tasks = (void**)realloc(array->tasks, (array->capacity * 2 + 1) * sizeof(task));
        if (!temp_tasks) {
            pthread_mutex_unlock(&mem_lock);
            return;
        }
        array->tasks = temp_tasks;
        array->capacity *= 2;
    }
    strncpy(array->tasks[array->size].name, new_task.name, 256);
    array->tasks[array->size] = new_task;
    ++array->size;
    pthread_mutex_unlock(&mem_lock);
}

void task_array_log(task_array_t* array) {
    if (!array) {
        return;
    }
    for (int i = 0; i < array->size; ++i) {
        log_info("Task %d: Priority=%d, Name='%s', Next Execution Time=%ld.%ld\n", i + 1, array->tasks[i].priority,
                 array->tasks[i].name, array->tasks[i].next_execution_time.tv_sec, array->tasks[i].next_execution_time.tv_nsec);
    }
}

void task_array_free_all(task_array_t* array) {
    if (!array || pthread_mutex_lock(&mem_lock)) {
        return;
    }
    for (int i = 0; i < array->size; ++i) {
        free(array->tasks[i].name);
    }
    task_array_free(array->tasks, array->capacity);
    task_array_free(array, array->capacity);
    pthread_mutex_unlock(&mem_lock);
}

task_array_t task_array_init_with_limit(int max_limit) {
    task_array_t array;
    task_array_init(&array, max_limit);
    return array;
}
