        if (records[i].key == key) {
            return &records[i];
        }
    }
    return NULL;
}

void save_records(const char* filename) {
    FILE* file = fopen(filename, "wb");
    fwrite(records, sizeof(record), num_records, file);
    fclose(file);
}

record* load_records(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    size_t size;
    fread(&size, sizeof(size), 1, file);

    record* loaded_records = malloc(size * sizeof(record));

    fread(loaded_records, sizeof(record), size, file);

    fclose(file);

    return loaded_records;
}
