#include <stdio.h>
#include <stdlib.h>

// Define the record structure
typedef struct {
    int key;
    int value;
} record;

// Function to add a new record to the dataset
void add_record(record** records, int* num_records, int key, int value) {
    // Dynamically allocate memory for a new record
    record* new_record = (record*)malloc(sizeof(record));
    new_record->key = key;
    new_record->value = value;

    // Reallocate the array to accommodate the new record
    *num_records += 1;
    (*records) = (record*)realloc(*records, (*num_records) * sizeof(record));

    // Copy data from old records to the new records
    for (int i = *num_records - 2; i >= 0; i--) {
        (*records)[i + 1] = (*records)[i];
    }
    (*records)[0] = *new_record;

    free(new_record);
}

// Function to remove a record from the dataset
void remove_record(record** records, int* num_records, int key) {
    for (int i = 0; i < *num_records; i++) {
        if ((*records)[i].key == key) {
            // Reallocate the array without the removed record
            *num_records -= 1;
            (*records) = (record*)realloc(*records, (*num_records + 1) * sizeof(record));

            // Copy data from old records to the new records
            for (int j = i; j < *num_records; j++) {
                (*records)[j] = (*records)[j + 1];
            }

            return;
        }
    }
}

// Function to find a record in the dataset
record* find_record(record** records, int num_records, int key) {
    for (int i = 0; i < num_records; i++) {
        if ((*records)[i].key == key) {
            return &(*records)[i];
        }
    }
    return NULL;
}

// Function to save the current state of the records to disk
void save_records(const char* filename, record** records, int num_records) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    // Write the number of records to the file
    fwrite(&num_records, sizeof(int), 1, file);

    // Write each record to the file
    for (int i = 0; i < num_records; i++) {
        fwrite(&(*records)[i], sizeof(record), 1, file);
    }

    fclose(file);
}

// Function to load the records from disk and store them in memory
record* load_records(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    // Read the number of records from the file
    int num_records;
    fread(&num_records, sizeof(int), 1, file);

    record* loaded_records = (record*)malloc(num_records * sizeof(record));

    // Load each record from the file
    for (int i = 0; i < num_records; i++) {
        fread(&loaded_records[i], sizeof(record), 1, file);
    }

    fclose(file);

    return loaded_records;
}

// Function to initialize the records and load them from disk if necessary
record** init_records(const char* filename) {
    record** records = NULL;
    int num_records = 0;

    // Load the records from disk
    record* loaded_records = load_records(filename);
    if (loaded_records != NULL) {
        num_records = loaded_records[0].key;
        records = &loaded_records[1];
    }

    return &records;
}

int main() {
    record** records;
    int num_records;

    // Initialize the records and load them from disk
    records = init_records("records.bin");

    // Add, remove, and search for records as needed

    // Save the current state of the records to disk when necessary
    save_records("records.bin", &records, num_records);

    return 0;
}
```']

