```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} record_t;

record_t* initializeArrays(size_t offsetSize, size_t keySize, size_t recordSize, size_t maxMemoryUsage) {
    size_t totalRecords = offsetSize * keySize;

    if (totalRecords > maxMemoryUsage) {
        return NULL; // Error: Too many records to fit in memory
    }

    record_t* records = (record_t*)malloc(recordSize * totalRecords);
    long* offsets = (long*)malloc(sizeof(long) * offsetSize);
    int* keys = (int*)malloc(sizeof(int) * keySize);

    if (!records || !offsets || !keys) {
        free(records);
        free(offsets);
        free(keys); // Error: Memory allocation failed
        return NULL;
    }

    for (size_t i = 0; i < offsetSize; i++) {
        offsets[i] = (long)i * 2; // Initialize random offset values
    }

    for (size_t i = 0; i < keySize; i++) {
        keys[i] = (int)(i % 100); // Initialize random key values
    }

    for (size_t i = 0; i < totalRecords; i++) {
        records[i].value = rand() % 100; // Set record values to random integers within the given range
    }

    return records;
}

void freeArrays(record_t* records, long* offsets, int* keys) {
    if (!records || !offsets || !keys) {
        return; // Error: Nothing to free
    }

    free(records);
    free(offsets);
    free(keys);
}

int main() {
    size_t offsetSize = 1000;
    size_t keySize = 500;
    size_t recordSize = sizeof(record_t);
    size_t maxMemoryUsage = 10 * 1024 * 1024; // 10MB

    srand(time(NULL)); // Initialize random number generator

    record_t* records = initializeArrays(offsetSize, keySize, recordSize, maxMemoryUsage);

    if (!records) {
        printf("Error: Memory allocation failed\n");
        return -1;
    }

    freeArrays(records, NULL, NULL); // Free allocated memory when done

    return 0;
}
