#define MAX_MESSAGES 1000
#define LOG_LEVEL_ERROR 1
#define LOG_LEVEL_WARN 2

typedef struct {
    int ue_id;
    int cell_id;
    float cqis[4];
} lte_phy_control_message;

typedef struct {
    lte_phy_control_message* messages;
    int num_messages;
    pthread_mutex_t mutex;
    FILE* log_file;
} lte_phy_control_list;

void init_lte_phy_control_list(lte_phy_control_list* list);
void add_lte_phy_control_message(lte_phy_control_list* list, lte_phy_control_message* message);
int is_list_full(lte_phy_control_list* list);
void serialize_list_to_file(const char* filename, lte_phy_control_list* list);
void deserialize_list_from_file(const char* filename, lte_phy_control_list* list);

lte_phy_control_list* create_lte_phy_control_list() {
    lte_phy_control_list* list = (lte_phy_control_list*)malloc(sizeof(lte_phy_control_list));
    if (!list) {
        return NULL;
    }
    init_lte_phy_control_list(list);
    return list;
}

void init_lte_phy_control_list(lte_phy_control_list* list) {
    list->messages = (lte_phy_control_message*)calloc(MAX_MESSAGES, sizeof(lte_phy_control_message));
    if (!list->messages) {
        fprintf(stderr, "Error: Unable to allocate memory for messages.\n");
        exit(EXIT_FAILURE);
    }
    list->num_messages = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void add_lte_phy_control_message(lte_phy_control_list* list, lte_phy_control_message* message) {
    pthread_mutex_lock(&list->mutex);
    if (is_list_full(list)) {
        // Replace oldest message with new one
        int old_idx = 0;
        for (int i = 1; i < MAX_MESSAGES; i++) {
            if (!list->messages[i].ue_id) break;
            old_idx = i;
        }
        memmove(&list->messages[old_idx], &message, sizeof(lte_phy_control_message));
    } else {
        memcpy(list->messages + list->num_messages++, message, sizeof(lte_phy_control_message));
    }
    pthread_mutex_unlock(&list->mutex);
}

int is_list_full(lte_phy_control_list* list) {
    return list->num_messages >= MAX_MESSAGES;
}

void serialize_list_to_file(const char* filename, lte_phy_control_list* list) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file '%s' for writing.\n", filename);
        return;
    }
    fwrite(&list->num_messages, sizeof(int), 1, file);
    for (int i = 0; i < list->num_messages; i++) {
        fwrite(list->messages + i, sizeof(lte_phy_control_message), 1, file);
    }
    fclose(file);
}

void deserialize_list_from_file(const char* filename, lte_phy_control_list* list) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file '%s' for reading.\n", filename);
        return;
    }
    fread(&list->num_messages, sizeof(int), 1, file);
    list->messages = (lte_phy_control_message*)realloc(list->messages, list->num_messages * sizeof(lte_phy_control_message));
    for (int i = 0; i < list->num_messages; i++) {
        fread(list->messages + i, sizeof(lte_phy_control_message), 1, file);
    }
    fclose(file);
}
