#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>

#define MAX_DOUBLE 10000.0
#define MAX_CHAR 256
#define TOTAL_SIZE 2000000 // 2MB in bytes
#define MAX_DATA 50000
#define MAX_DOUBLE_IN_DATA 25000
#define MAX_CHAR_IN_DATA 10000

typedef struct {
    double d;
    char c;
    char *s;
} data_t;

data_t **data_array = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_data(int num_elements) {
    int size = sizeof(data_t *) + sizeof(data_t) * num_elements;
    if(size > TOTAL_SIZE) return NULL; // Check for memory limit
    data_t *data = (data_t *)malloc(size);

    if (!data) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex); // Lock the mutex

    data_array = (data_t **)realloc(data_array, sizeof(data_t *) * (num_elements + 1));
    if (!data_array) {
        free(data);
        pthread_mutex_unlock(&mutex);
        printf("Memory allocation failed.\n");
        return NULL;
    }

    data_array[num_elements] = data;
    pthread_mutex_unlock(&mutex); // Unlock the mutex

    for(int i = 0; i < num_elements; i++) {
        data[i].d = (double)(rand() / (RAND_MAX / MAX_DOUBLE));
        data[i].c = (char)rand() % MAX_CHAR;
        data[i].s = malloc(strlen("Hello") + 1);
        strcpy(data[i].s, "Hello");
    }

    return (void *)data_array;
}

void free_data(int num_elements) {
    pthread_mutex_lock(&mutex); // Lock the mutex

    for(int i = 0; i < num_elements; i++) {
        free(data_array[i]->s);
    }

    data_t *free_data = realloc(NULL, sizeof(data_t *) * (num_elements + 1));
    for(int i = 0; i <= num_elements; i++) {
        free_data[i] = data_array[i];
    }

    free(data_array);
    pthread_mutex_unlock(&mutex); // Unlock the mutex
}

void check_allocation() {
    if (!data_array) {
        printf("No memory allocated.\n");
    } else {
        int total_size = 0;
        for(int i = 0; i < MAX_DATA; i++) {
            total_size += sizeof(data_t);
        }

        if(total_size > TOTAL_SIZE) {
            printf("Memory exceeds the limit.\n");
        } else {
            printf("Memory usage is within the specified limits.\n");
        }
    }
}

int main() {
    int num_elements = 10;
    data_array = allocate_data(num_elements);

    check_allocation();

    free_data(num_elements);

    return 0;
}
```']

