    long* offset_values = NULL;
    int* keys = NULL;
    record_t** records = NULL;

    pthread_mutex_lock(mutex);

    while (true) {
        offset_values = realloc(offset_values, sizeof(long) * (MAX_OFFSET_VALUES + 1));
        if (!offset_values) {
            free(keys);
            free(records);
            pthread_mutex_unlock(mutex);
            return NULL;
