#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <zlib.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define RECORD_COUNT 1000
#define INT_MAX 2147483647

typedef struct {
    int value;
    char* str;
    struct node* next;
} record;

record* allocateRecords(int count) {
    if (count <= 0 || count > RECORD_COUNT)
        return NULL;

    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        record* rec = &records[i];
        rec->value = rand() % INT_MAX;
        rec->str = NULL;
        rec->next = NULL;
    }
    return records;
}

void freeRecords(record* records) {
    if (!records)
        return;

    for (int i = 0; i < RECORD_COUNT; i++) {
        record* rec = &records[i];
        if (rec->str)
            free(rec->str);
    }
    free(records);
}

record* compressRecords(record* records, int count) {
    z_stream strm;
    unsigned char out[1024];

    // Initialize compression stream
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    record* compressed_records = (record*)malloc(count * sizeof(record));
    if (!compressed_records) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Compress records
    for (int i = 0; i < count; i++) {
        record* rec = &records[i];
        int str_len = sprintf(out, "%d", rec->value);
        out[str_len] = '\0';
        char* compressed_str = malloc(str_len + 1);
        memcpy(compressed_str, out, str_len + 1);

        // Initialize compression stream
        strm.next_in = (Byte*)compressed_str;
        strm.avail_in = str_len;
        strm.total_in = str_len;

        int compress_result;
        do {
            strm.next_out = out;
            strm.avail_out = sizeof(out);
            strm.total_out = 0;
            compress_result = deflate(&strm, Z_DEFAULT_COMPRESSION);
            if (compress_result != Z_OK && compress_result != Z_STREAM_END)
                printf("Compression failed\n");
        } while (compress_result == Z_OK);

        // Add compressed record to the array
        record* compressed_rec = &compressed_records[i];
        compressed_rec->value = rec->value;
        compressed_rec->str = malloc(sizeof(char) * (strm.total_out + 1));
        memcpy(compressed_rec->str, out, strm.total_out);
        compressed_rec->next = NULL;

        // Free temporary memory
        free(compressed_str);
    }
    return compressed_records;
}

void printRecords(record* records, int count) {
    for (int i = 0; i < count; i++) {
        record* rec = &records[i];
        printf("Value: %d, String: %s\n", rec->value, rec->str);
    }
}
