// Define a point structure
typedef struct {
    double x, y;
} Point;

void* allocate_and_init_arrays(int max_memory_limit) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for arrays
    double* doubles = (double*)malloc(max_memory_limit / sizeof(double));
    char** strings = (char**)malloc(max_memory_limit / sizeof(char*));
    Point* points = (Point*)malloc(max_memory_limit / sizeof(Point));
    Record* records = (Record*)malloc(max_memory_limit / sizeof(Record));

    // Initialize arrays
    for (int i = 0; i < max_memory_limit / sizeof(double); i++) {
        doubles[i] = rand() / (double)RAND_MAX;
    }
    for (int i = 0; i < max_memory_limit / sizeof(char*); i++) {
        strings[i] = (char*)malloc(10);
        sprintf(strings[i], "String %d", i);
    }
    for (int i = 0; i < max_memory_limit / sizeof(Point); i++) {
        points[i].x = rand() / (double)RAND_MAX;
        points[i].y = rand() / (double)RAND_MAX;
    }
    for (int i = 0; i < max_memory_limit / sizeof(Record); i++) {
        records[i].value = rand() % 100;
    }

    // Persist data to disk
    FILE* file = fopen("data.bin", "wb");
    fwrite(doubles, sizeof(double), max_memory_limit / sizeof(double), file);
    for (int i = 0; i < max_memory_limit / sizeof(char*); i++) {
        fwrite(strings[i], sizeof(char), strlen(strings[i]) + 1, file);
    }
    fwrite(points, sizeof(Point), max_memory_limit / sizeof(Point), file);
    fwrite(records, sizeof(Record), max_memory_limit / sizeof(Record), file);
    fclose(file);

    // Free memory
    free(doubles);
    for (int i = 0; i < max_memory_limit / sizeof(char*); i++) {
        free(strings[i]);
    }
    free(points);
    free(records);

    return NULL;
}

void recover_data() {
    FILE* file = fopen("data.bin", "rb");
    double* doubles;
    char** strings;
    Point* points;
    Record* records;

    // Read data from disk
    fseek(file, 0, SEEK_END);
    int size = ftell(file);
    rewind(file);

    doubles = (double*)malloc(size / sizeof(double));
    fread(doubles, sizeof(double), size / sizeof(double), file);

    for (int i = 0; i < size / sizeof(char*); i++) {
        strings[i] = (char*)malloc(strlen(doubles[i]) + 1);
        fread(strings[i], sizeof(char), strlen(doubles[i]) + 1, file);
    }

    points = (Point*)malloc(size / sizeof(Point));
    fread(points, sizeof(Point), size / sizeof(Point), file);

    records = (Record*)malloc(size / sizeof(Record));
    fread(records, sizeof(Record), size / sizeof(Record), file);

    // Free memory
    free(doubles);
    for (int i = 0; i < size / sizeof(char*); i++) {
        free(strings[i]);
    }
    free(points);
    free(records);

    fclose(file);
}

