typedef struct {
    int value;
    double dval;
    char* str;
    time_t timestamp;
} record;

record** allocateRecords(int count, size_t maxMemory) {
    record** records = NULL;
    size_t totalBytes = sizeof(record*) * count + sizeof(record) * count;

    if (totalBytes > maxMemory) return NULL; // check memory limit

    records = malloc(sizeof(record*) * count);
    if (!records) return NULL; // handle allocation failure

    for (int i = 0; i < count; i++) {
        record* r = malloc(sizeof(record));
        if (!r) { // handle string allocation failure
            free(records);
            return NULL;
        }

        r->value = rand() % INT_MAX;
        r->timestamp = time(NULL);
        r->str = malloc(64); // allocate 64-byte string
        if (!r->str) {
            free(r);
            free(records);
            return NULL;
        }

        records[i] = r;
    }

    return records;
}

void freeRecords(record** records, int count) {
    for (int i = 0; i < count; i++) {
        record* r = records[i];
        if (r->str) free(r->str);
        free(r);
    }
    free(records);
}
