#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <zlib.h>

typedef struct {
    float value;
    char* string;
} SensorRecord;

SensorRecord* generate_sensor_records(size_t max_memory, size_t num_records);
void encrypt_record(SensorRecord* record);
int compress_record(SensorRecord* record);

int main() {
    // Define maximum memory limit
    size_t max_memory = 1024 * 1024; // 1MB

    // Generate sensor records with random float values and strings
    SensorRecord* records = generate_sensor_records(max_memory, 1000);

    for (size_t i = 0; i < 1000; i++) {
        encrypt_record(&records[i]);
        compress_record(&records[i]);
    }

    return 0;
}

SensorRecord* generate_sensor_records(size_t max_memory, size_t num_records) {
    SensorRecord* records = (SensorRecord*)malloc(max_memory * sizeof(SensorRecord));
    if (!records) {
        printf("Failed to allocate memory\n");
        return NULL;
    }

    for (size_t i = 0; i < num_records; i++) {
        // Generate random float value and string
        records[i].value = rand() / (RAND_MAX + 1.0);
        char str[16];
        sprintf(str, "Sensor Record %d", i);
        records[i].string = strdup(str);
    }

    return records;
}

void encrypt_record(SensorRecord* record) {
    // Initialize encryption context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_add_cipher(ctx, EVP_aes_256_cbc(), NULL);

    // Encrypt record value
    unsigned char* encrypted_value = (unsigned char*)malloc(EVP_MAX_BLOCK_LENGTH);
    size_t encrypted_len = 0;
    EVP_encrypt_init(ctx, &record->value, sizeof(float));
    EVP_encrypt_update(ctx, encrypted_value, &encrypted_len);
    EVP_encrypt_final(ctx);

    // Update record value
    free((void*)&record->value);
    record->value = *(float*)encrypted_value;

    EVP_CIPHER_CTX_free(ctx);
    free(encrypted_value);
}

int compress_record(SensorRecord* record) {
    // Initialize compression context
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    deflateInit2(&strm, Z_DEFAULT_COMPRESSION, Z_DEFLATED, 16 + 15, 8, Z_DEFAULT_STRATEGY);

    // Compress record string
    char* compressed_string = (char*)malloc(strlen(record->string) * 5);
    strm.next_in = (Bytef*)record->string;
    strm.avail_in = strlen(record->string);
    strm.total_out = 0;
    deflate(strm, Z_FINISH);
    strm.next_out += strm.total_out;
    strm.avail_out = 0;

    // Update record string
    free(record->string);
    record->string = malloc(compressed_string);
    memcpy(record->string, compressed_string, strm.total_out);

    deflateEnd(&strm);
    free(compressed_string);
}

