void init_records(long offset_range_start, long offset_range_end,
                  int key_range_start, int key_range_end) {
    srand(time(NULL)); // Seed the random number generator

    long *offsets = (long *)malloc((offset_range_end - offset_range_start + 1) *
                                     sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Unable to allocate memory for offsets.\n");
        return;
    }

    int *keys = (int *)malloc((offset_range_end - offset_range_start + 1) *
                                sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Error: Unable to allocate memory for keys.\n");
        return;
    }

    record_t *records = (record_t *)malloc((offset_range_end - offset_range_start + 1) *
                                             sizeof(record_t));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Error: Unable to allocate memory for records.\n");
        return;
    }

    long offset_idx = 0;
    for (long i = offset_range_start; i <= offset_range_end; i++) {
        offsets[offset_idx++] = i;

        int key_idx = 0;
        do {
            keys[key_idx] = rand() % (key_range_end - key_range_start + 1) +
                            key_range_start;
            bool found_duplicate = false;
            for (int j = 0; j < key_idx; j++) {
                if (keys[j] == keys[key_idx]) {
                    found_duplicate = true;
                    break;
                }
            }

            if (found_duplicate) {
                key_idx++;
            } else {
                break;
            }
        } while (true);

        records[offset_idx - 1].value = rand() % (key_range_end - key_range_start + 1) +
                                          key_range_start;
    }

    // Initialize offset and key arrays from external data source
    FILE *file = fopen("data.txt", "r");
    if (file != NULL) {
        int line_idx = 0;
        while (fscanf(file, "%ld %d\n", &offsets[line_idx], &keys[line_idx]) == 2) {
            line_idx++;
        }
        fclose(file);
    }

    printf("Offsets: ");
    for (long i = offset_range_start; i <= offset_range_end; i++) {
        printf("%ld ", offsets[i - offset_range_start]);
    }
    printf("\n");

    printf("Keys: ");
    for (int i = 0; i < offset_idx; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");

    printf("Records: ");
    for (long i = offset_range_start; i <= offset_range_end; i++) {
        printf("Record {%d}\n", records[i - offset_range_start].value);
    }

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    init_records(0, 10000, 0, 10000);
    return 0;
}
