#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <zlib.h>

#define MAX_MEMORY 1000000
#define AES_KEY_SIZE 32
#define CHACha20_KEY_SIZE 32

typedef struct {
    float value;
    char* string;
} SensorDataRecord;

SensorDataRecord* generate_sensor_data(int count, int max_memory) {
    // Allocate memory for sensor data records
    int allocated = 0;
    int total_allocated = 0;
    SensorDataRecord* records = NULL;

    while (total_allocated < max_memory && allocated < count) {
        int record_size = sizeof(SensorDataRecord);
        records = realloc(records, (allocated + 1) * record_size);
        if (!records) break; // Out of memory

        SensorDataRecord* record = &records[allocated];
        record->value = rand() / (float)RAND_MAX;
        char buffer[32];
        sprintf(buffer, "Sensor %d", allocated);
        record->string = malloc(strlen(buffer) + 1);
        strcpy(record->string, buffer);
        total_allocated += record_size;

        // Encrypt the record using AES
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_add_cipher(ctx, "AES-256-CBC");
        int out_len;
        unsigned char out[total_allocated];
        encrypt_record(record, out, &out_len);

        // Compress the encrypted data using Zlib
        z_stream strm;
        strm.zalloc = Z_NULL;
        strm.zfree = Z_NULL;
        strm.opaque = Z_NULL;
        deflateInit(&strm, Z_DEFAULT_COMPRESSION);
        int compress_len = 0;
        unsigned char* compressed = malloc(total_allocated + out_len);
        strm.next_in = (Bytef*)out;
        strm.avail_in = out_len;
        do {
            strm.next_out = compressed + compress_len;
            strm.avail_out = total_allocated - compress_len;
            deflate(&strm, Z_FINISH);
            if (strm.avail_out == 0) break; // Compression done
            compress_len += strm.total_out;
        } while (1);

        // Store the compressed record in memory
        record_size = compress_len + sizeof(int); // Include length prefix
        records[allocated] = *record;

        allocated++;
    }

    if (!records || total_allocated > max_memory) {
        free(records);
        return NULL;
    }

    return records;
}

void encrypt_record(SensorDataRecord* record, unsigned char* out, int* out_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_add_cipher(ctx, "AES-256-CBC");
    int len = 0;
    unsigned char key[AES_KEY_SIZE] = {'\0'};
    for (int i = 0; i < AES_KEY_SIZE; i++) {
        key[i] = rand() % 256;
    }
    EVP_add_key(ctx, key, strlen((char*)key));
    EVP_add_digest(ctx, "SHA-256");
    int out_len_;
    unsigned char* iv = malloc(AES_KEY_SIZE);
    for (int i = 0; i < AES_KEY_SIZE; i++) {
        iv[i] = rand() % 256;
    }
    EVP_crypt_data(record->value, strlen((char*)record->string), out, &out_len_);
    EVP_encrypt_ctx(ctx, out, out_len_, iv);
    free(iv);

    if (*out_len_ > *out_len) {
        // Handle error
    }

    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    int count = 100;
    int max_memory = MAX_MEMORY;
    SensorDataRecord* records = generate_sensor_data(count, max_memory);
    // Use the sensor data records
    return 0;
}
