void* generate_sensor_data(size_t max_memory_limit, void (*callback)(int)) {
    // Initialize memory pool with a maximum limit
    void* memory_pool = malloc(max_memory_limit);

    // Define structure for sensor data record
    struct SensorDataRecord {
        float value;
        char* string_ptr;
    };

    // Function pointer to perform encryption using different algorithms
    void (*encryption_algorithm)(void*, size_t) = NULL;

    while (1) {
        // Generate new sensor data record
        struct SensorDataRecord* record = malloc(sizeof(struct SensorDataRecord));
        record->value = rand() / (RAND_MAX + 1.0f);
        char buffer[1024];
        sprintf(buffer, "Sensor Data Record: %f", record->value);
        record->string_ptr = strdup(buffer);

        // Apply chosen encryption algorithm to the record
        if (encryption_algorithm) {
            size_t record_size = sizeof(struct SensorDataRecord) + strlen(record->string_ptr) + 1;
            void* encrypted_record = malloc(record_size);
            encryption_algorithm(encrypted_record, record_size);
            free(record);
            record = encrypted_record;
        }

        // Asynchronously log resource usage statistics
        callback(max_memory_limit);

        // Check if the allocated memory is within the specified limits
        if (max_memory_limit < (size_t)record->value + strlen(record->string_ptr)) {
            printf("Memory limit exceeded.\n");
            break;
        }
    }

    free(memory_pool);
    return record;
}

void set_encryption_algorithm(void (*algorithm)(void*, size_t)) {
    encryption_algorithm = algorithm;
