int* config_data_alloc(size_t limit, FILE* conf_file) {
    // Initialize pointers to null
    Record** records = NULL;
    Value** values = NULL;

    // Read initial offset values from external configuration file (if provided)
    if (conf_file != NULL) {
        fseek(conf_file, 0, SEEK_END);
        size_t fileSize = ftell(conf_file);
        rewind(conf_file);

        if (fileSize > limit) {
            fprintf(stderr, "Error: Configuration file exceeds memory limit.\n");
            return NULL;
        }

        records = malloc((fileSize / sizeof(Record)) * sizeof(Record*));
        fread(records, sizeof(Record), fileSize / sizeof(Record), conf_file);
    } else {
        // Allocate memory for array of record structures
        size_t numRecords = (limit / sizeof(Record)) - 1;
        records = malloc((numRecords + 1) * sizeof(Record*));
        memset(records, 0, (numRecords + 1) * sizeof(Record*));

        // Initialize record values randomly within valid bounds
        for (size_t i = 0; i < numRecords; i++) {
            records[i]->offset = rand() % ((limit - sizeof(Record)) / sizeof(int));
            records[i]->key = rand() % (int)sizeof(int);
        }
    }

    // Allocate memory for array of value structures
    size_t numValues = limit / sizeof(Value);
    values = malloc(numValues * sizeof(Value*));

    // Initialize value structures randomly within valid bounds
    for (size_t i = 0; i < numValues; i++) {
        values[i]->value = rand() % ((limit - sizeof(Value)) / sizeof(int));
    }

    return values;
}
