        size_t string_length = rand() % RANDOM_STRING_LENGTH_MAX;
        strings[i] = (char*)malloc(string_length + 1);
        if (!strings[i]) {
            free(events);  // Free allocated memory in case of failure
            free(strings);
            return NULL;  // Error: Allocation failed
        }
        for (size_t j = 0; j < string_length; j++) {
            strings[i][j] = 'a' + rand() % ('z' - 'a');
        }
        strings[i][string_length] = '\0';
        events[i].timestamp = i;
        events[i].temperature = (double)rand() / RAND_MAX;
        events[i].humidity = rand() % 100;
        events[i].weather_condition = strings[i];
    }

    // Periodic logging and flushing
    FILE* log_file = fopen("weather_events.log", "w");
    if (!log_file) {
        free(events);  // Free allocated memory in case of failure
        free(strings);
        return NULL;  // Error: File opening failed
