    // Initialize metrics
    clock_t last_update = clock();
    int* recent_counts = (int*)malloc(sizeof(int) * 1000);
    for (int i = 0; i < 1000; i++) {
        recent_counts[i] = 0;
    }

    int max_weighted_sum = 0;
    int max_weighted_sum_key = -1;

    for (int i = 0; i < num_transactions; i++) {
        struct transaction* transaction = transactions[i];

        // Filter out transactions that don't meet criteria
        if (recent_counts[transaction->key] >= 3) {
            int timestamp_age = clock() - last_update;
            recent_counts[transaction->key]++;

            float weighted_sum = (float)transaction->amount / (float)(timestamp_age + 1);

            // Update metrics and check for new maximum
            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                max_weighted_sum_key = transaction->key;
            }
        }
    }

    free(recent_counts);
}
