void traverse_DOM(struct _node *root, char *selector, int (**result)[3], int *count) {
    if (root == NULL)
        return;

    if (!strcmp(root->name, selector)) {
        *result = realloc(*result, (*count + 1) * sizeof(int[3]));
        (*result)[*count][0] = root->class;
        (*result)[*count][1] = root->id;
        (*result)[*count][2] = root->value;
        (*count)++;
    }

    traverse_DOM(root->child, selector, result, count);
    traverse_DOM(root->next, selector, result, count);
}

int main() {
    srand(time(NULL));

    int n_records = 10;
    int n_nodes = 20;

