    *keys = realloc(*keys, count * sizeof(int));
    *values = realloc(*values, count * sizeof(float));
    for (int i = 0; i < count; i++) {
        (*data_points)[i] = realloc((*data_points)[i], sizeof(data_point));
    }

    // Clear remaining memory
