        free((*offset_values) + count * sizeof(long));
        free((*keys) + count * sizeof(int));
        free((*values) + count * sizeof(float));
        free((*data_points)[count]->index);
        free((*data_points)[count]);
    }
    free(*offset_values);
    free(*keys);
    free(*values);
    for (int i = 0; i < count; i++) {
        free((*data_points)[i]->index);
        free((*data_points)[i]);
    }
    free(*data_points);
}
