        // Allocate a new block
        void* block = malloc(ALLOCATOR_BLOCK_SIZE * RECORD_SIZE);
        allocated_blocks++;
        total_allocated += ALLOCATOR_BLOCK_SIZE;

        // Initialize the block with records
