#include <pthread.h>

#define MAX_ALLOCATIONS 10000
#define BLOCK_SIZE 1024

typedef struct node {
    int value;
    struct node* next;
} Node;

Node* allocate_node() {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    static unsigned char* block = NULL;
    static size_t allocation_count = 0;

    if (block == NULL || allocation_count >= MAX_ALLOCATIONS) {
        block = (unsigned char*)malloc(BLOCK_SIZE);
        allocation_count = 0;
    }

    Node* node = (Node*)((size_t)block + allocation_count * sizeof(Node));
    node->value = -1; // Initialize with sentinel value
    node->next = NULL;

    pthread_mutex_unlock(&lock);
    return node;
}

void free_nodes(Node** head) {
    while (*head != NULL) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

Node* init_list(int max_size) {
    if (max_size < 0) {
        printf("Invalid maximum size. Setting to default.\n");
        max_size = MAX_ALLOCATIONS;
    }

    Node* head = NULL;
    for (int i = 0; i < max_size; i++) {
        head = allocate_node();
        head->value = i;
        if (i > 0) {
            Node* prev = NULL;
            for (Node* current = head; current != NULL; current = current->next) {
                prev = current;
                current->next = allocate_node();
            }
        }
    }

    return head;
}

void print_list(Node* head) {
    while (head != NULL) {
        printf("%d ", head->value);
        head = head->next;
    }
    printf("\n");
}
