#include <pthread.h>

#define MAX_RECORDS 10000
#define CHUNK_SIZE (1024 * 1024)
#define MAX_ALLOCATED 128 * 1024 * 1024
#define MIN_FREE_SPACE 16 * 1024

typedef struct record {
    int value;
} Record;

Record* allocate_records(int count, int* initial_values) {
    pthread_mutex_lock(&mutex);

    if (count > MAX_RECORDS || total_allocated + (sizeof(Record) * count) > MAX_ALLOCATED) {
        printf("Exceeded maximum allocated memory or record count.\n");
        return NULL;
    }

    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        if (initial_values[i]) {
            records[i].value = initial_values[i];
        } else {
            // Use a random value generator to avoid overflow/underflow
            // or use other mechanisms as required
            int value = rand() % 100;
            records[i].value = value;
        }
    }

    total_allocated += (sizeof(Record) * count);
    free_space -= (sizeof(Record) * count);

    pthread_mutex_unlock(&mutex);
    return records;
}

void deallocate_records(Record* records, int count) {
    if (!records) {
        return;
    }

    pthread_mutex_lock(&mutex);

    total_allocated -= (sizeof(Record) * count);
    free_space += (sizeof(Record) * count);

    Record* temp = records;
    records = NULL; // Make sure the records are not accessed after deallocation
    while (count--) {
        free(temp);
        temp = NULL;
    }

    pthread_mutex_unlock(&mutex);
}

