}

void* custom_malloc(size_t size) {
    void* block = malloc(CHUNK_SIZE);
    if (!block) {
        return NULL;
    }

    int remaining = 0;
    char* current = (char*)block;
    while ((remaining = CHUNK_SIZE - (current - block)) >= size + sizeof(Record)) {
        // Create a record and initialize it
        Record* record = (Record*)current;
        if (!initial_values) {
            record->value = rand() % 100;
        } else {
            record->value = initial_values[0];
            initial_values++;
        }

        current += sizeof(Record);

        total_allocated += sizeof(Record);
        free_space -= sizeof(Record);

        num_allocations++;

        if (total_allocated + size > MAX_ALLOCATED || free_space < MIN_FREE_SPACE) {
            printf("Memory allocation failed due to memory constraints.\n");
            return NULL;
        }
    }

    // Handle remaining space
    int chunk_remaining = remaining - size;
    Record* record = (Record*)current;
    if (!initial_values) {
        record->value = rand() % 100;
    } else {
        record->value = initial_values[0];
        initial_values++;
    }

    current += sizeof(Record);

    total_allocated += sizeof(Record);
    free_space -= sizeof(Record);

    num_allocations++;

    return block;
}

void* custom_free(void* ptr) {
    Record* record = (Record*)ptr;

    // Add the size of each record to the deallocation size
    int allocation_size = sizeof(Record);

    total_allocated -= allocation_size;
    free_space += allocation_size;

    num_deallocations++;

    return ptr;
}

void init_allocator() {
    pthread_mutex_init(&mutex, NULL);
    total_allocated = 0;
    free_space = CHUNK_SIZE;
    num_allocations = 0;
    num_deallocations = 0;
}

int main() {
    init_allocator();

    Record* records = allocate_records(100, NULL); // Use random values
    // Deallocate individual records or blocks as needed

    print_memory_stats();

    deallocate_records(records, 50);

    print_memory_stats();

    return 0;
}
