```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <resolv.h>

int perform_dns_resolution(const char* hostname, u_char* ip_addr) {
    // Perform DNS resolution using standard library functions
    struct hostent* host = gethostbyname(hostname);
    if (!host) {
        return -1;  // Error: no such host
    }

    // Copy IP address to the provided array
    memcpy(ip_addr, host->h_addr, host->h_length);

    return 0;
}

int main() {
    u_char ip_addr[16];  // Assuming maximum IPv4 address length is 15 bytes
    int ret = perform_dns_resolution("example.com", ip_addr);
    if (ret == -1) {
        printf("Error: no such host\n");
    } else {
        printf("Resolved IP address: ");
        for (int i = 0; i < sizeof(ip_addr); i++) {
            printf("%02x ", ip_addr[i]);
        }
        printf("\n");
    }
    return 0;
}
```
