typedef struct {
    char name[64];
    int priority;
    struct task* next;
} task;

task* allocate_task(size_t max_limit) {
    size_t size = sizeof(task);
    if (size > max_limit) {
        return NULL; // Memory allocation failed
    }

    task* task_ptr = (task*)malloc(size);
    if (!task_ptr) {
        return NULL; // Memory allocation failed
    }

    task_ptr->priority = 0;
    task_ptr->next = NULL;
    bzero(task_ptr->name, sizeof(task_ptr->name));
    return task_ptr;
}

void free_task(task* task_ptr) {
    if (task_ptr != NULL) {
        free(task_ptr);
    }
}

int main() {
    // Example usage:
    size_t max_limit = 1024; // Adjust according to your needs
    task* head = NULL;

    for (int i = 0; i < 10; i++) {
        task* new_task = allocate_task(max_limit);
        if (!new_task) {
            printf("Memory allocation failed\n");
        } else {
            // Initialize the task structure...
            strcpy(new_task->name, "Task ");
            new_task->priority = i;
            new_task->next = head;
            head = new_task;
        }
    }

    for (task* task_ptr = head; task_ptr != NULL; task_ptr = task_ptr->next) {
        // Process each task...
    }

    for (task* task_ptr = head; task_ptr != NULL; ) {
        task* temp = task_ptr;
        task_ptr = task_ptr->next;
        free_task(temp);
    }
}
