device* allocate_device(int num_devices) {
    device* devices = (device*)malloc(num_devices * sizeof(device));
    if (!devices) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num_devices; i++) {
        devices[i].name[0] = '\0';
        devices[i].type = -1;
        devices[i].next = &devices[i + 1];
    }
    devices[num_devices - 1].next = NULL;

    return devices;
}

void free_devices(device* devices) {
    device* curr = devices;
    while (curr != NULL) {
        device* next = curr->next;
        free(curr);
        curr = next;
    }
}
