    free(keys);

    return records;
}

// Function to resize the offset and key arrays dynamically
void* resize_arrays(void* data, int new_num_offsets, int new_num_keys) {
    Record** records = (Record**)data;

    // Resize offset array
    long* new_offsets = (long*)realloc((long*)records[0]->offsets, new_num_offsets * sizeof(long));
    if (!new_offsets) {
        printf("Failed to resize memory for offsets\n");
        return NULL;
    }

    // Resize key array
    int* new_keys = (int*)realloc((int*)records[0]->keys, new_num_keys * sizeof(int));
    if (!new_keys) {
        printf("Failed to resize memory for keys\n");
        free(new_offsets);
        return NULL;
    }

    // Reallocate memory for records and update record count
    Record** new_records = (Record**)realloc((Record*)records[0], new_num_records * sizeof(Record*));
    if (!new_records) {
        printf("Failed to resize memory for records\n");
        free(new_offsets);
        free(new_keys);
        return NULL;
    }
    int new_num_records = new_num_records + (new_num_offsets - *num_offsets);

    // Reallocate memory for each record and update record count
    for (int i = 0; i < new_num_records; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            printf("Failed to allocate memory for records\n");
            free(new_offsets);
            free(new_keys);
            return NULL;
        }
        record->key = rand() % 1000000;
        record->offset = new_offsets[rand() % new_num_offsets];
        record->value = rand() % 100;
        new_records[i] = record;
    }

    // Free old memory and update pointers
    free(records[0]->offsets);
    free(records[0]->keys);

    return new_records;
}

// Function to release allocated memory
void clean_up(Record** records) {
    for (int i = 0; i < *num_records; i++) {
        free(records[i]);
    }
    free(records);
}
