    // Initialize variables for memory allocation and statistics
    int totalBytesUsed = 0;
    int peakBytesUsed = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for arrays based on maximum limit
    while (totalBytesUsed < maxMemory) {
        int floatArraySize = min(maxRecords, maxMemory / sizeof(float));
        floatArray = realloc(floatArray, sizeof(float) * floatArraySize);
        if (!floatArray) break;

        int stringArraySize = min(maxLength, maxMemory / sizeof(char *));
        stringArray = realloc(stringArray, sizeof(char *) * stringArraySize);
