            if (sensorArray[i].value > 1.0 || sensorArray[i].value < -1.0)
                sensorArray[i].value = (float)rand() / RAND_MAX;
        }

        totalBytesUsed += sizeof(float) * floatArraySize + sizeof(char *) * stringArraySize + sizeof(SensorData) * sensorArraySize;
        peakBytesUsed = max(peakBytesUsed, totalBytesUsed);
    }

    // Periodically check and log resource usage statistics
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < totalBytesUsed; i++) {
        if ((i + 1) % (totalBytesUsed / 10) == 0)
            printf("Peak memory usage: %d bytes\n", peakBytesUsed);
