        if ((i + 1) % (totalBytesUsed / 10) == 0)
            realloc(floatArray, sizeof(float) * min(maxRecords, peakBytesUsed / sizeof(float)));
        if ((i + 1) % (totalBytesUsed / 10) == 0)
            for (int j = 0; j < stringArraySize; j++) {
                free(stringArray[j]);
                realloc(stringArray, sizeof(char *) * min(maxLength, peakBytesUsed / sizeof(char *)));
                for (int k = 0; k < min(maxLength, peakBytesUsed / sizeof(char *)); k++)
