        if ((i + 1) % (totalBytesUsed / 10) == 0)
            realloc(sensorArray, sizeof(SensorData) * min(floatArraySize, peakBytesUsed / sizeof(float)));
    }

    // Free allocated memory
    for (int i = 0; i < totalBytesUsed; i++) {
        free(floatArray);
        free(stringArray);
        free(sensorArray);
    }
