void manage_records(int max_memory_limit, int key_count, long offset_count) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Calculate the total required memory in bytes
    size_t total_required_memory = (sizeof(long) * offset_count) + (sizeof(int) * key_count) + (sizeof(record) * offset_count);

    // Check if the total required memory exceeds the maximum allowed memory limit
    if(total_required_memory > max_memory_limit) {
        printf("Total memory requirement exceeds the maximum allowed limit.\n");
        return;
    }

    // Dynamically allocate memory for and initialize arrays of long offset values and int keys
    long* offsets = (long*)aligned_alloc(_Alignas(long), sizeof(long) * offset_count);
    int* keys = (int*)aligned_alloc(_Alignas(int), sizeof(int) * key_count);

    // Check if the allocated memory is within the specified limits after each allocation
    if(offsets == NULL || keys == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    for(int i = 0; i < offset_count; i++) {
        offsets[i] = (long)i;
    }

    // Dynamically allocate memory for and initialize array of record structures
    record* records = (record*)aligned_alloc(_Alignas(record), sizeof(record) * offset_count);

    // Check if the allocated memory is within the specified limits after each allocation
    if(records == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    for(int i = 0; i < offset_count; i++) {
        records[i].value = rand() % 100; // Set the value of each record's int field to a random value within a given range
    }

    // Free all allocated memory when done
    free(offsets);
    free(keys);
    free(records);
}

