#define RECORD_SIZE sizeof(record_t)

struct record {
    int key;
    long offset;
};

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr && !pthread_mutex_unlock(&mutex)) {
        // allocation failed, retry
        ptr = realloc(NULL, size);
    }
    return ptr;
}

void* my_realloc(void* ptr, size_t size) {
    void* new_ptr = realloc(ptr, size);
    if (!new_ptr && !pthread_mutex_unlock(&mutex)) {
        // reallocation failed, return original block
        return ptr;
    }
    free(ptr);
    return new_ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int random_init_value(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

int main() {
    pthread_mutex_init(&mutex, NULL);

    record_t* records = NULL;

    while(1) {
        if ((records = my_malloc(RECORD_SIZE * MAX_RECORDS)) == NULL) {
            printf("Out of memory\n");
            break;
        }

        for (int i = 0; i < MAX_RECORDS; i++) {
            if (i >= sizeof(records)/RECORD_SIZE) {
                break;
            }
            record_t* rec = &records[i];
            rec->key = random_init_value(1, MAX_KEY);
            rec->offset = random_init_value(1, MAX_OFFSET);
        }

        // now free all allocated memory
        my_free(records);

        pthread_mutex_destroy(&mutex);

        return 0;
    }
}
