#include <pthread.h>

typedef struct {
    int key;
    long offset;
} record;

void* manage_records(int max_memory_limit, int key_count, long offset_count) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize arrays and records
    int *keys = (int *)malloc(key_count * sizeof(int));
    long *offsets = (long *)malloc(offset_count * sizeof(long));
    record *records = (record *)malloc((key_count + offset_count) * sizeof(record));

    pthread_mutex_lock(&mutex);

    // Set values for records
    srand(time(NULL));  // Initialize random number generator with current time as seed

    for(int i = 0; i < key_count; i++) {
        keys[i] = rand() % (max_memory_limit / sizeof(int));
    }

    for(long j = 0; j < offset_count; j++) {
        offsets[j] = rand() % (max_memory_limit / sizeof(long)) + 1;
    }

    // Set values for records
    for(int i = 0, k = 0; i < key_count || k < offset_count; i++, k++) {
        if(i < key_count) {
            records[k].key = keys[i];
        } else {
            records[k].key = rand() % (max_memory_limit / sizeof(int));
            records[k].offset = offsets[k - key_count] + 1;
            k++;
        }
    }

    pthread_mutex_unlock(&mutex);

    return (void *)records;
}
