    dataRecords = malloc(numRecords * sizeof(DataRecord));
    recordCount = numRecords;

    // Initialize each record with a random double value and a null-terminated string
    for (size_t i = 0; i < numRecords; i++) {
        dataRecords[i].value = rand() / (double)RAND_MAX;
        dataRecords[i].string = malloc((stringLength + 1) * sizeof(char));
        sprintf(dataRecords[i].string, "Record %zu", i);
    }
}

// Function to free allocated memory
void freeRecords() {
    if (recordCount > 0) {
        for (size_t i = 0; i < recordCount; i++) free(dataRecords[i].string);
        free(dataRecords);
    }
    dataRecords = NULL;
    recordCount = 0;
}

// Function to encrypt a data record using AES
void encryptRecord(DataRecord *record, const char *key) {
    EVP_CIPHER_CTX ctx;
    unsigned char *ciphertext = malloc(AES_BLOCK_SIZE + sizeof(double) + strlen(record->string));
    unsigned char *keyBytes = (unsigned char *)key;

    EVP_CIPHER_CTX_init(&ctx);
    EVP_EncryptInit_ex(&ctx, EVP_aes_256_cbc(), NULL, keyBytes, NULL);
    EVP_EncryptUpdate(&ctx, ciphertext, &record->value, sizeof(double), 0);
    EVP_EncryptUpdate(&ctx, ciphertext + AES_BLOCK_SIZE, strlen(record->string), record->string, 0);
    EVP_CIPHER_CTX_cleanup(&ctx);

    // Update the original record with the encrypted values
    * ((double *)ciphertext) = record->value;
    strcpy((char *)ciphertext + sizeof(double), record->string);
}

// Function to compress a data record using Zlib
void compressRecord(DataRecord *record) {
    uLongf outlen;
    char *compressed = malloc(ZLIB_WBITS + 1);

    deflateInit2(&z_stream, Z_DEFAULT_COMPRESSION, Z_DEFLATED, 31, 8, Z_DEFAULT_STRATEGY);
    z_stream.zalloc = Z_NULL;
    z_stream.zfree = Z_NULL;
    z_stream.opaque = NULL;
    deflateInit2(&z_stream, Z_DEFAULT_COMPRESSION, Z_DEFLATED, 31, 8, Z_DEFAULT_STRATEGY);

    deflate((void **)&compressed, &outlen, record->value, sizeof(double), strlen(record->string));
    deflateEnd(&z_stream);

    // Update the original record with the compressed values
    * ((double *)compressed) = record->value;
    strcpy((char *)compressed + sizeof(double), record->string);
}

// Function to log resource usage statistics asynchronously
void logStatistics() {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_t loggerThread;

    pthread_create(&loggerThread, NULL, (void *)logStats, NULL);
}

void *logStats(void *arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        // Log resource usage statistics here
        printf("Peak memory usage: %zu MB\n", currentMemoryUsage / 1024 / 1024);
        pthread_mutex_unlock(&lock);
        sleep(5); // Log every 5 seconds
    }
}

