// Data record structure
typedef struct {
    double value;
    char* string;
} Record;

// Function to dynamically generate and manage data records
void* data_records_manager(int max_memory_limit, int num_records) {
    // Initialize the maximum memory limit
    size_t max_memory = max_memory_limit * sizeof(Record);

    // Allocate the initial memory block
    void* mem_block = malloc(max_memory);
    Record* records = mem_block;

    // Check if the allocated memory is within the specified limits
    if (max_memory > max_memory_limit) {
        free(mem_block);
        return NULL;
    }

    // Initialize the data record array
    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        // Randomly generate a double value within a given range
        record->value = (double)rand() / RAND_MAX;

        // Dynamically allocate memory for the string field
        int str_len = rand() % 100 + 1;
        char* str = malloc(str_len * sizeof(char));
        strcpy(str, "Random string ");
        sprintf(str + strlen(str), "%d", i);

        record->string = str;
    }

    // Initialize compression and encryption
    z_stream stream;
    deflateInit(&stream, Z_DEFAULT_COMPRESSION);
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    // Perform concurrent initialization, compression, and encryption of data records
    pthread_t threads[num_records];
    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        pthread_create(&threads[i], NULL, compress_and_encrypt_record, record);
    }

    // Periodically check and log resource usage statistics
    size_t peak_memory_usage = 0;
    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        pthread_join(threads[i], NULL);

        // Update the maximum memory limit if necessary
        size_t current_memory_usage = malloc_usable_size(record) + strlen(record->string) + sizeof(double);
        if (current_memory_usage > peak_memory_usage) {
            peak_memory_usage = current_memory_usage;
        }
    }

    // Free all allocated memory when done
    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        free(record->string);
    }
    free(mem_block);

    return NULL;
}

// Function to compress and encrypt a single data record concurrently
void* compress_and_encrypt_record(void* arg) {
    // Get the record pointer from the argument
    Record* record = (Record*)arg;

    // Compress the string field using zlib
    z_stream stream;
    deflateInit(&stream, Z_DEFAULT_COMPRESSION);
    char* compressed_str = malloc(stream.avail_in + 1);
    int ret = deflate(&stream, Z_NO_FLUSH, compressed_str);
    if (ret != Z_OK) {
        // Handle compression error
    }

    // Encrypt the compressed string using OpenSSL
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    AES_encrypt(ctx, compressed_str, strlen(compressed_str));

    // Log resource usage statistics periodically
    size_t current_memory_usage = malloc_usable_size(record) + strlen(record->string) + sizeof(double);
    if (current_memory_usage > peak_memory_usage) {
        peak_memory_usage = current_memory_usage;
    }

    return NULL;
}

int main() {
    int max_memory_limit = 1024 * 1024; // 1MB
    int num_records = 1000;

    data_records_manager(max_memory_limit, num_records);

    return 0;
}
