void initialize_records(data_record** records, int num_records, int min_value, int max_value) {
    // Allocate memory for the offset array
    long* offsets = (long*)malloc(num_records * sizeof(long));

    // Initialize the offset array
    for (int i = 0; i < num_records; i++) {
        offsets[i] = (long)(rand() % ((max_value - min_value) + 1)) + min_value;
    }

    // Allocate memory for the key array
    int* keys = (int*)malloc(num_records * sizeof(int));

    // Initialize the key array
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % ((max_value - min_value) + 1);
    }

    // Allocate memory for the value array
    float* values = (float*)malloc(num_records * sizeof(float));

    // Initialize the value array
