        values[i] = (float)(rand() % ((max_value - min_value) + 1)) / 10.0f;
    }

    // Allocate memory for the data records array
    *records = (data_record*)malloc(num_records * sizeof(data_record));

    // Initialize the data records array
    char** identifiers = (char**)malloc(num_records * sizeof(char*));
    for (int i = 0; i < num_records; i++) {
        // Generate a unique string identifier
        int id_len = strlen("id_") + 1;
        char* id_str = (char*)malloc(id_len);
        strcpy(id_str, "id_");
        sprintf(&id_str[3], "%d", i);

        // Set the record's value and identifier
        (*records)[i].value = values[i];
        (*records)[i].identifier = id_str;

        // Add the identifier to the array of identifiers
        identifiers[i] = id_str;
    }

    // Free any dynamically allocated memory
    for (int i = 0; i < num_records; i++) {
        free(identifiers[i]);
    }
    free(identifiers);
    free(keys);
    free(values);
    free(offsets);
}
