typedef struct {
    int value;
} record;

record** allocate_and_init_records(int* num_records, int max_num_records, int threshold) {
    if (*num_records > max_num_records || *num_records > (threshold / sizeof(record))) {
        *num_records = (threshold / sizeof(record));
    }

    record** records = (record**)malloc(*num_records * sizeof(record*));
    for (int i = 0; i < *num_records; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->value = rand() % 100;
    }

    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    } else {
        return records;
    }
}

void free_records(record** records, int num_records) {
    for (int i = 0; i < num_records; i++) {
