['```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

struct record {
    int value;
};

int initialize_records(record **records, long **offsets, int **keys, int num_records, size_t max_size) {
    *records = NULL;
    *offsets = NULL;
    *keys = NULL;

    size_t total_alloc_size = num_records * sizeof(struct record);
    total_alloc_size += num_records * sizeof(long) + num_records * sizeof(int);

    if (total_alloc_size > max_size) {
        return 0; // Error: Memory allocation exceeds maximum size
    }

    struct record *recs;
    long *off;
    int *ky;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cleanup_push(cleanup, &mutex);

    recs = (struct record *)malloc(total_alloc_size);
    off = (long *)malloc(num_records * sizeof(long));
    ky = (int *)malloc(num_records * sizeof(int));

    if (!recs || !off || !ky) {
        return -1; // Error: Memory allocation failed
    }

    pthread_cleanup_pop(1);

    // Initialize offsets and keys
    for (int i = 0; i < num_records; i++) {
        off[i] = rand();
        ky[i] = rand();
    }

    // Initialize records
    for (int i = 0; i < num_records; i++) {
        recs[i].value = rand();
    }

    *records = recs;
    *offsets = off;
    *keys = ky;

    return num_records; // Successfully initialized records
}

void cleanup(void *arg) {
    pthread_mutex_t *mutex = arg;
    pthread_mutex_unlock(mutex);
}
```']

