record *initialize_records(int num_records, int max_size) {
    int total_size = (sizeof(long) + sizeof(int)) * num_records + sizeof(record) * num_records;
    if (total_size > max_size) {
        printf("Memory limit exceeded. Maximum size is %d bytes.\n", max_size);
        return NULL;
