    record *records = malloc(sizeof(record) * num_records);
    if (!records) {
        printf("Error: Could not allocate memory for records.\n");
        return NULL;
    }

    long *offsets = malloc(num_records * sizeof(long));
    if (!offsets) {
        free(records);
        printf("Error: Could not allocate memory for offsets.\n");
        return NULL;
    }

    int *keys = malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        printf("Error: Could not allocate memory for keys.\n");
