    for (int i = 0; i < num_records; i++) {
        records[i].key = rand();
        offsets[i] = rand();
        keys[i] = rand();
    }

    return records;
}

void free_memory(record *records) {
    free(records);
    free((void *)records + sizeof(record) * (records ? 0 : -1));
}
