} MemoryBlock;

MemoryBlock* memory_block_alloc(size_t size) {
    MemoryBlock* block = (MemoryBlock*)malloc(sizeof(MemoryBlock));
    if (!block) {
        return NULL;
    }
    block->data = malloc(size);
    if (!block->data) {
        free(block);
        return NULL;
    }
    block->size = size;
    pthread_mutex_init(&block->mutex, NULL);
    return block;
}

void memory_block_free(MemoryBlock* block) {
    pthread_mutex_destroy(&block->mutex);
    free(block->data);
    free(block);
}

Record* record_alloc(size_t size) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        return NULL;
    }
    record->value = 0;
    return record;
}

void record_free(Record* record) {
    free(record);
}

int log_init(size_t max_size, size_t* offset_log_size, size_t* key_log_size) {
    *offset_log_size = memory_block_alloc(max_size / 2)->size;
    *key_log_size = memory_block_alloc(max_size / 2)->size;
    return 0;
}

void log_free() {
    // free all allocated memory
}

int record_init(size_t size, Record** records) {
    *records = (Record*)malloc(sizeof(Record) * size);
    if (!*records) {
        return -1; // allocation failed
    }
    for (size_t i = 0; i < size; i++) {
        (*records)[i].value = 0;
    }
    return 0;
}

