// Function to initialize and return a JSON object
json_object* read_json_file(const char* filename) {
    json_object* json = NULL;
    FILE* file = fopen(filename, "r");
    if (file == NULL)
        return NULL;  // File not found or unable to open

    fseek(file, 0, SEEK_END);
    size_t len = ftell(file);
    rewind(file);

    char* buffer = (char*)malloc(len + 1);
    fread(buffer, 1, len, file);
    fclose(file);

    json_object* result = json_load_buffer(buffer, len);
    free(buffer);
    return result;
}

