    json_object_iter iter;
    json_object_iter_init(&iter, json);
    while (json_object_iter_next(&iter, NULL)) {
        const char* key = iter.key;
        if (strcmp(key, "offsets") == 0) {
            offsets = (long*)malloc(iter.val->size * sizeof(long));
