#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MAX_MEMORY (1024 * 1024 * 10) // 10 MB
#define RANDOM_RANGE 1000000

typedef struct {
    int key;
    long offset;
} Record;

Record* records = NULL;
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_memory(int size) {
    void* ptr = malloc(size);
    if (ptr == NULL || size > MAX_MEMORY) {
        printf("Memory allocation failed: Out of memory\n");
        exit(-1);
    }
    return ptr;
}

int random_value() {
    return rand() % RANDOM_RANGE;
}

void initialize_records(int count, Record** array) {
    for (int i = 0; i < count; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (record == NULL) {
            printf("Memory allocation failed: Out of memory\n");
            exit(-1);
        }
        record->key = random_value();
        record->offset = random_value();
        array[i] = record;
    }
}

void free_records(int count, Record** array) {
    for (int i = 0; i < count; i++) {
        free(array[i]);
    }
}

int main() {
    srand(time(NULL));
    int records_per_alloc = MAX_RECORDS / 2;

    while (true) {
        Record* temp_records;
        int new_count = MIN(MAX_RECORDS, record_count + records_per_alloc);

        pthread_mutex_lock(&mutex);
        if ((temp_records = (Record*)allocate_memory(sizeof(Record) * new_count)) == NULL)
            break; // Out of memory

        initialize_records(new_count - record_count, &temp_records[record_count]);
        for (int i = 0; i < records_per_alloc; i++)
            temp_records[i].key = random_value();
        for (int i = 0; i < records_per_alloc; i++)
            temp_records[i].offset = random_value();

        record_count = new_count;
        if ((records = (Record*)realloc(records, sizeof(Record) * record_count)) == NULL)
            break; // Out of memory

        for (int i = record_count - records_per_alloc; i < record_count; i++)
            records[i] = temp_records[i - (record_count - records_per_alloc)];

        free(temp_records);

        pthread_mutex_unlock(&mutex);
    }

    if (records) {
        free(records);
    }
}
