            std::vector<int> getHistoricalData() const;

        private:
            struct SensorRecord {
                int timestamp;
                int key;
                int value;
            };

            std::vector<SensorRecord> records_;
    };
}

WeatherSystem::StationList::~StationList() {}

WeatherSystem::StationList::StationList(int numStations) {
    // Initialize random number generator
    static std::random_device rd;
    static std::mt19937 gen(rd());
    for (int i = 0; i < numStations; ++i) {
        SensorRecord record;
        record.timestamp = gen();
        record.key = gen() % 100;
        record.value = gen() % 100;
        records_.push_back(record);
    }
}

void WeatherSystem::StationList::addSensor(std::string sensorType, int stationId) {
    // Implement sensor addition logic
}

std::vector<int> WeatherSystem::StationList::getHistoricalData() const {
    std::vector<int> historicalData;
    for (const auto& record : records_) {
        historicalData.push_back(record.value);
    }
    return historicalData;
}
