}

shape* init_shapes(int num_shapes, int max_size) {
    shape *shapes = (shape*)my_malloc(num_shapes * sizeof(shape));

    if(shapes == NULL || !check_memory_limits((size_t)num_shapes * sizeof(shape))) return NULL;

    for(int i = 0; i < num_shapes; i++) {
