        if(shapes[i].p == NULL || !check_memory_limits((size_t)max_size * sizeof(point))) return NULL;

        shapes[i].c = (color*)my_malloc(max_size * sizeof(color));

        if(shapes[i].c == NULL || !check_memory_limits((size_t)max_size * sizeof(color))) return NULL;

        for(int j = 0; j < max_size; j++) {
