            shapes[i].p[j].y = (float)(rand() % MAX_SIZE);

            shapes[i].c[j].r = rand() % COLOR_MAX;
            shapes[i].c[j].g = rand() % COLOR_MAX;
            shapes[i].c[j].b = rand() % COLOR_MAX;
        }
    }

    return shapes;
}

void free_shapes(shape* shapes, int num_shapes) {
    for(int i = 0; i < num_shapes; i++) {
        my_free(shapes[i].p);
        my_free(shapes[i].c);
    }
    my_free(shapes);
}

int check_memory_limits(size_t size) {
