// Function to allocate and initialize arrays and records
char* append_slash(char* str, int size_limit) {
    char* new_str = NULL;

    // Allocate memory for 'long' offset values array
    long* offsets = (long*)malloc(size_limit * sizeof(long));
    if (!offsets) {
        return NULL;
    }

    // Initialize 'int' keys array
    int* keys = (int*)malloc(size_limit * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Allocate memory for and initialize array of record structures
    Record* records = (Record*)malloc(size_limit * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        return NULL;
    }

    // Loop to set value of each record's int field to a random value
    srand(time(NULL));
    for (int i = 0; i < size_limit; i++) {
        records[i].value = rand() % 100;
    }

    // Check if total memory usage exceeds specified maximum limit
    size_t total_bytes = sizeof(long) * size_limit + sizeof(int) * size_limit + sizeof(Record) * size_limit;
    if (total_bytes > size_limit) {
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    // Append slash to end of input string
    int str_len = strlen(str);
    new_str = malloc(str_len + 2);
    strcpy(new_str, str);
    strcat(new_str, "/");

    if (!new_str) {
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    return new_str;
}

// Function to free all allocated memory
void free_memory(long* offsets, int* keys, Record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
