    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (!strcmp(key, "num_offsets")) {
            *offsets = malloc(sizeof(long) * atoi(value));
        } else if (!strcmp(key, "num_keys")) {
            *keys = malloc(sizeof(int) * atoi(value));
        } else if (!strcmp(key, "num_records")) {
            *records = malloc(sizeof(struct record *) * atoi(value));
        }
    }

    fclose(file);
}

