                        free(record_cache[k]);
                    }
                    free(record_cache);
                    return 2;
                }
                record_cache[cache_count++] = new_record;
            } else {
                // Cache hit: log and reuse existing record
                printf("Cache hit!\n");
            }
        }

        // Handle real-time data processing
        process_new_data();
    }

    // Clean up
    free_records(record_cache, cache_count);
    for (int i = 0; i < cache_count; i++) {
        free(record_cache[i]);
    }
    free(record_cache);
    free(offsets);
    free(keys);
    return 0;
}
