typedef struct {
    int value;
    char* string;
} record;

typedef struct {
    record* records;
    size_t num_records;
} metadata;

metadata* create_metadata(size_t max_records) {
    metadata* meta = (metadata*)malloc(sizeof(metadata));
    if (!meta) return NULL;

    meta->records = (record*)calloc(max_records, sizeof(record));
    if (!meta->records) {
        free(meta);
        return NULL;
    }

    meta->num_records = 0;
    return meta;
}

int create_arrays(metadata** meta_ptr, size_t max_records) {
    *meta_ptr = create_metadata(max_records);
    if (*meta_ptr == NULL) return -1;

    long* offsets = (long*)calloc(max_records, sizeof(long));
    int* keys = (int*)calloc(max_records, sizeof(int));

    if (!offsets || !keys) {
        free((*meta_ptr)->records);
        free(*meta_ptr);
        return -1;
    }

    (*meta_ptr)->records[0].value = 0; // placeholder
    return 0;
}

void set_record_values(metadata* meta, int min_value, int max_value) {
    srand(time(NULL));
    for (size_t i = 0; i < meta->num_records; ++i) {
        record& rec = meta->records[i];
        rec.value = rand() % (max_value - min_value + 1) + min_value;
        size_t string_len = sprintf(NULL, "%d", rec.value) + 1;
        char* str = (char*)malloc(string_len * sizeof(char));
        if (!str) return; // handle allocation failure
        sprintf(str, "%d", rec.value);
        rec.string = str;
    }
}

int main() {
    size_t max_records = 1000;
    metadata* meta = create_arrays(&meta, max_records);
    if (meta == NULL) return -1;

    set_record_values(meta, 1, 100);

    // release allocated memory
    for (size_t i = 0; i < meta->num_records; ++i) {
        free(meta->records[i].string);
    }
    free(meta->records);
    free(meta);
    return 0;
}
