    }

    // Allocate memory for an array of 'dataRecord' structures
    int totalRecords = offsetCount + doublePrecisionCount + floatPrecisionCount;
    dataRecord* records = allocateDataRecords(totalRecords, totalRecords * sizeof(dataRecord));

    // Use a loop to set the value of each record's double field to a random value within a given range
    for (int i = 0; i < totalRecords; i++) {
        records[i].value = (double)(rand() % 10000) / 100.0;
    }

    // Free all allocated memory when done
    freeDataRecords(records, totalRecords);
    free(offsets);
    free(doublePrecisions);
    free(floatPrecisions);

    return 0;
}

