#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define RECORD_SIZE 3
#define MAX_RECORDS 1000
#define MAX_INT_VALUE 2147483647
#define MAX_DOUBLE_VALUE 1.7976931348623157e+308

typedef struct {
    int integer;
    double decimal;
    char* string;
} record_t;

record_t* create_records(int size, int max_memory);
void free_records(record_t** records);
int check_memory_usage(const record_t* records, int size);

// Function to generate random values within the specified limits
int random_int() {
    return rand() % ((MAX_INT_VALUE + 1) / 2 * 2 - 1) + 1;
}

double random_double() {
    return (double)random_int() / RAND_MAX;
}

char* random_string(int length) {
    char* str = (char*)malloc((length + 1) * sizeof(char));
    for (int i = 0; i < length; i++) {
        str[i] = 'a' + rand() % 26;
    }
    str[length] = '\0';
    return str;
}

record_t* create_records(int size, int max_memory) {
    if (size > MAX_RECORDS || size * RECORD_SIZE * sizeof(record_t) > max_memory) {
        printf("Error: Requested record count exceeds maximum allowed or memory limit.\n");
        return NULL;
    }

    record_t* records = (record_t*)malloc(size * sizeof(record_t));
    for (int i = 0; i < size; i++) {
        int integer = random_int();
        double decimal = random_double();

        // Check for overflow/underflow in integer and double fields
        if (integer > MAX_INT_VALUE || integer < -MAX_INT_VALUE) {
            printf("Warning: Integer value exceeds maximum limit.\n");
            integer = MAX_INT_VALUE;
        }
        if (decimal > MAX_DOUBLE_VALUE || decimal < -MAX_DOUBLE_VALUE) {
            printf("Warning: Double value exceeds maximum limit.\n");
            decimal = MAX_DOUBLE_VALUE;
        }

        records[i].integer = integer;
        records[i].decimal = decimal;

        int string_length = rand() % 100 + 1; // Random length between 1 and 100
        char* str = random_string(string_length);

        // Check for memory allocation failure
        if (!str) {
            printf("Error: String allocation failed.\n");
            return NULL;
        }

        records[i].string = str;
    }
    return records;
}

void free_records(record_t** records) {
    for (int i = 0; i < *records->size; i++) {
        if ((*records)[i].string) {
            free((*records)[i].string);
        }
    }
    free(*records);
}

int check_memory_usage(const record_t* records, int size) {
    return size * RECORD_SIZE * sizeof(record_t);
}
