                         MAX_ARRAY_SIZE * sizeof(int) + \
                         MAX_METADATA_RECORDS * sizeof(record_t) + \
                         MAX_METADATA_RECORDS * (STRING_KEY_MAX_LENGTH + 1) * sizeof(char) + \
                         sizeof(int))

typedef struct {
    int value;
} record_t;

void* allocate_arrays(size_t max_array_size, size_t metadata_records) {
    // Calculate total memory usage
    size_t total_memory_usage = max_array_size * sizeof(long) + 
                                 max_array_size * sizeof(int) + 
                                 metadata_records * sizeof(record_t) + 
                                 metadata_records * (STRING_KEY_MAX_LENGTH + 1) * sizeof(char);

    if (total_memory_usage > MEMORY_LIMIT) {
        // Handle memory limit exceeded
        return NULL;
    }

    void* ptr = malloc(total_memory_usage);
    if (!ptr) {
        // Handle allocation failure
        return NULL;
    }

    // Initialize arrays and records
    long* offsets = ptr;
    int* keys = (int*) ((char*) ptr + max_array_size * sizeof(long));
    record_t* records = (record_t*) ((char*) ptr + max_array_size * sizeof(long) + 
                                     max_array_size * sizeof(int));
    char** metadata_keys = (char**) ((char*) ptr + max_array_size * sizeof(long) + 
                                       max_array_size * sizeof(int) + 
                                       metadata_records * sizeof(record_t));

    // Handle additional metadata records
    for (size_t i = 0; i < metadata_records; i++) {
        // Allocate memory for string key and integer value
        char* key = (char*) malloc(STRING_KEY_MAX_LENGTH + 1);
        if (!key) {
            // Handle allocation failure
            return NULL;
        }
        sprintf(key, "Metadata Record %zu", i);

        metadata_keys[i] = key;

        // Initialize record structure
        record_t record = {i};
        records[i] = record;
    }

    return ptr;
}

void free_allocated_memory(void* ptr) {
    // Free arrays and records
    long* offsets = ptr;
    int* keys = (int*) ((char*) ptr + MAX_ARRAY_SIZE * sizeof(long));
    record_t* records = (record_t*) ((char*) ptr + MAX_ARRAY_SIZE * sizeof(long) + 
                                     MAX_ARRAY_SIZE * sizeof(int));
    char** metadata_keys = (char**) ((char*) ptr + MAX_ARRAY_SIZE * sizeof(long) + 
                                       MAX_ARRAY_SIZE * sizeof(int) + 
                                       MAX_METADATA_RECORDS * sizeof(record_t));

    // Free additional metadata records
    for (size_t i = 0; i < MAX_METADATA_RECORDS; i++) {
        free(metadata_keys[i]);
    }

    free(ptr);
}

int main() {
    void* ptr = allocate_arrays(MAX_ARRAY_SIZE, MAX_METADATA_RECORDS);
    if (!ptr) {
        // Handle allocation failure
        return -1;
    }

    // Use allocated memory

    free_allocated_memory(ptr);

    return 0;
}
