#include <time.h>

typedef struct node {
    long value;
    struct node* next;
} Node;

typedef struct record {
    long field;
} Record;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) printf("Memory allocation failed!\n");
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int init_data(struct node** head, int count) {
    *head = (struct node*)my_malloc(sizeof(Node));
    (*head)->next = NULL;
    for (int i = 1; i < count; i++) {
        Node* new_node = (Node*)my_malloc(sizeof(Node));
        new_node->value = rand() % (2^31-1) - (2^31)/2;
        new_node->next = (*head)->next;
        (*head)->next = new_node;
    }
    return 0;
}

int init_records(Record** records, int count) {
    *records = (Record*)my_malloc(sizeof(Record) * count);
    for (int i = 0; i < count; i++) {
        (*records)[i].field = rand() % (2^31-1) - (2^31)/2;
    }
    return 0;
}

void free_all(void** head, Record* records, int size) {
    Node* temp = *head;
    while (temp != NULL) {
        Node* next = temp->next;
        my_free(temp);
        temp = next;
    }
    for (int i = 0; i < size; i++) {
        my_free(&records[i]);
    }
}

