        AES_cfb128_encrypt(NULL, NULL, &records[i], ctx);
        EVP_CIPHER_CTX_free(ctx);

        // Compress the encrypted data using Zlib
        z_stream stream;
        deflateInit2(&stream, Z_DEFAULT_COMPRESSION, Z_DEFAULT_STRATEGY);
        char* compressed = (char*)malloc(strlen(buffer) + 1);
        deflate(stream, plaintext, strlen(plaintext), compressed, strlen(compressed));

        // Encrypt the compressed data using ChaCha20
        EVP_CIPHER_CTX* ctx2 = EVP_CIPHER_CTX_new();
        ChaCha20_cfb128_encrypt(NULL, NULL, &records[i], ctx2);
        EVP_CIPHER_CTX_free(ctx2);

        free(plaintext);
    }
}

