// Define the maximum limit for memory usage
#define MAX_MEMORY 1024 * 1024

// Define the structure of a record
typedef struct {
    int value;
    char* str;
} Record;

// Function to dynamically allocate and initialize arrays
void initArrays(long** offsets, int** keys, Record** records, int size) {
    // Initialize arrays using thread-safe mechanism
    *offsets = (long*)calloc(size, sizeof(long));
    *keys = (int*)calloc(size, sizeof(int));
    *records = (Record*)calloc(size, sizeof(Record));

    // Check if memory allocation exceeded the limit
    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
}

// Function to free allocated memory
void freeArrays(long* offsets, int* keys, Record* records, int size) {
    // Free arrays using thread-safe mechanism
    free(offsets);
    free(keys);
    free(records);

    // Check if freeing operation was successful
    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Memory freeing failed.\n");
    }
}

// Function to generate random values within a specified range
void generateRandom(int* min, int* max, int size, Record* records) {
    // Use cryptographic functions for random number generation
    EVP_add_cipher(AES_256_CBC);
    EVP_add_cipher(CAMELLIA_256_CBC);

    for (int i = 0; i < size; i++) {
        // Generate random values within the specified range
        int value = (rand() % (*max - *min)) + *min;
        records[i].value = value;

        // Handle overflow or underflow in 'int' field of record structure
        if (records[i].value > *max || records[i].value < *min) {
            printf("Value out of range.\n");
            return;
        }
    }

    EVP_remove_cipher(AES_256_CBC);
    EVP_remove_cipher(CAMELLIA_256_CBC);
}

// Function to allocate memory for string fields and populate 'record' array
void initRecords(long* offsets, int* keys, Record* records, int size) {
    // Initialize record values with random generation
    generateRandom(&MIN_INT, &MAX_INT, size, records);

    // Allocate memory for string fields of each record
    for (int i = 0; i < size; i++) {
        char* str = (char*)malloc(strlen("Random String") + 1);
        strcpy(str, "Random String");
        records[i].str = str;

        // Check if memory allocation exceeded the limit
        if (records[i].str == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }
    }
}

// Function to check if allocated memory is within the specified limits
int checkMemoryUsage(long* offsets, int* keys, Record* records, int size) {
    // Calculate total memory usage
    long total = sizeof(long) * size + sizeof(int) * size + sizeof(Record) * size;
    for (int i = 0; i < size; i++) {
        total += strlen(records[i].str) + 1;
    }

    // Check if total memory usage exceeds the specified limit
    if (total > MAX_MEMORY) {
        printf("Memory exceeded the limit.\n");
        return -1;
    }
    else {
        return 0;
    }
}

// Function to free allocated memory for string fields
void freeStringFields(Record* records, int size) {
    // Free string fields using thread-safe mechanism
    for (int i = 0; i < size; i++) {
        if (records[i].str != NULL) {
            free(records[i].str);
        }
    }

    // Check if freeing operation was successful
    if (records == NULL) {
        printf("Memory freeing failed.\n");
    }
}

// Function to add AES and MD5 cryptographic primitives
void initCrypto() {
    EVP_add_cipher(AES_256_CBC);
    EVP_add_digest(MD5);

    // Add RSA with SHA1 using EVP_add_digest_alias
    EVP_add_digest_alias(RSA, SHA1);
}
