#define MAX_SENSORS 1000
#define MAX_MEMORY (1024 * 1024) // 1MB

typedef struct {
    time_t timestamp;
    int sensor_id;
    float temperature;
    float humidity;
    float pressure;
} Sensor;

Sensor* sensors = NULL;
int num_sensors = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_memory(int num_elements) {
    void* ptr = calloc(num_elements, sizeof(Sensor));
    if (ptr == NULL || num_elements * sizeof(Sensor) > MAX_MEMORY) {
        printf("Failed to allocate memory. Max limit exceeded.\n");
        return NULL;
    }
    return ptr;
}

void free_memory() {
    if (sensors != NULL) {
        free(sensors);
        sensors = NULL;
    }
}

void* initialize_sensors(int num_elements) {
    void* ptr = allocate_memory(num_elements);
    for (int i = 0; i < num_elements; i++) {
        Sensor* sensor = ptr + i * sizeof(Sensor);
        sensor->timestamp = time(NULL);
        sensor->sensor_id = i;
        sensor->temperature = (float)rand() / RAND_MAX * (100 - (-40)) + (-40);
        sensor->humidity = (float)rand() / RAND_MAX * 100;
        sensor->pressure = (float)rand() / RAND_MAX * (1200 - 500) + 500;
    }
    return ptr;
}

void print_sensors() {
    for (int i = 0; i < num_sensors; i++) {
        Sensor* sensor = sensors + i;
        printf("Timestamp: %ld, Sensor ID: %d, Temperature: %.2f°C, Humidity: %.2f%%, Pressure: %.2fhPa\n", 
               sensor->timestamp, sensor->sensor_id, sensor->temperature, sensor->humidity, sensor->pressure);
    }
}

int main() {
    int max_sensors = MAX_SENSORS;
    while (1) {
        // Dynamic adjustment of maximum memory limit
        if (num_sensors >= max_sensors) {
            printf("Memory usage exceeded. Adjusting limits...\n");
            max_sensors += 1000; // adjust the limit dynamically
        }

        void* ptr = initialize_sensors(max_sensors - num_sensors);
        pthread_mutex_lock(&mutex);
        if (sensors != NULL) {
            free(sensors);
        }
        sensors = ptr;
        num_sensors = max_sensors;
        pthread_mutex_unlock(&mutex);

        // Periodic logging of resource usage statistics
        printf("Peak memory usage: %d bytes\n", (int)(num_sensors * sizeof(Sensor)));

        print_sensors();

        // Error handling for any failed operations
        if (pthread_mutex_init(&mutex, NULL) != 0) {
            printf("Failed to initialize mutex.\n");
        }
    }
}
