#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 100
#define MAX_STRING_LENGTH 256
#define MIN_INT_VALUE 0
#define MAX_INT_VALUE 255
#define OVERFLOW_THRESHOLD (MAX_INT_VALUE + 1)

typedef struct {
    int key;
    double precision;
    char* string;
} Record;

void initArraysAndRecords(int maxLimit, long** offsets, int** keys, double** values, Record** records) {
    int i;

    // Initialize arrays
    for (i = 0; i < MAX_RECORDS; i++) {
        if (!(*offsets)[i]) (*offsets)[i] = malloc(sizeof(long));
        if (!(*keys)[i]) (*keys)[i] = malloc(sizeof(int));
        if (!(*values)[i]) (*values)[i] = malloc(sizeof(double));

        // Initialize arrays
        *((*offsets)[i]) = i;
        *((*keys)[i]) = i;
        *((*values)[i]) = (double)i;

        // Allocate memory for string and initialize it with the record index
        char* temp = (char*)malloc(MAX_STRING_LENGTH);
        sprintf(temp, "Record %d", i);
        (*records)[i].key = i;
        (*records)[i].precision = (double)i;
        (*records)[i].string = temp;

        // Check if memory allocation exceeded the limit
        if (i > 0) {
            for (int j = 0; j < i; j++) {
                free((*offsets)[j]);
                free((*keys)[j]);
                free((*values)[j]);
                free((*records)[j].string);
            }
            if ((size_t)i * sizeof(Record) > maxLimit) {
                printf("Memory allocation exceeded the limit. Cleaning up...\n");
                exit(-1);
            }
        }
    }
}

void freeArraysAndRecords(long** offsets, int** keys, double** values, Record** records) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        free((*offsets)[i]);
        free((*keys)[i]);
        free((*values)[i]);
        free((*records)[i].string);
    }
}

int main() {
    int maxLimit = 100000;
    long* offsets = malloc(MAX_RECORDS * sizeof(long));
    int* keys = malloc(MAX_RECORDS * sizeof(int));
    double* values = malloc(MAX_RECORDS * sizeof(double));
    Record* records = malloc(MAX_RECORDS * sizeof(Record));

    srand(time(NULL)); // Seed the random number generator

    initArraysAndRecords(maxLimit, &offsets, &keys, &values, &records);

    for (int i = 0; i < MAX_RECORDS; i++) {
        int recordKey = rand() % (MAX_INT_VALUE - MIN_INT_VALUE + 1) + MIN_INT_VALUE;
        if (recordKey > OVERFLOW_THRESHOLD) {
            // Handle overflow or underflow
            printf("Overflow or underflow detected in record %d. Value set to the maximum value.\n", i);
            recordKey = OVERFLOW_THRESHOLD;
        }

        (*records)[i].key = recordKey;
    }

    freeArraysAndRecords(&offsets, &keys, &values, &records);

    return 0;
}
