// Define a record structure to store int values
typedef struct {
    int key;
    long offset;
} Record;

void freeRecords(Record **records, size_t numRecords) {
    // Free each record in the array
    for (size_t i = 0; i < numRecords; i++) {
        if (records[i] != NULL) {
            free(records[i]);
        }
    }

    // Free the records array itself
    free(*records);
}

void setRecordValues(Record **records, size_t numRecords, int minVal, int maxVal) {
    for (size_t i = 0; i < numRecords; i++) {
        Record *record = records[i];
        if (record != NULL) {
            record->key = rand() % (maxVal - minVal + 1) + minVal;
        }
    }
}

void setRecordOffsets(Record **records, size_t numRecords, long minOffset, long maxOffset) {
    for (size_t i = 0; i < numRecords; i++) {
        Record *record = records[i];
        if (record != NULL) {
            record->offset = rand() % (maxOffset - minOffset + 1) + minOffset;
        }
    }
}

void freeArrays(int **keys, long **offsets, size_t numKeys) {
    // Free each array in the array
    for (size_t i = 0; i < numKeys; i++) {
        if (keys[i] != NULL) {
            free(keys[i]);
        }
        if (offsets[i] != NULL) {
            free(offsets[i]);
        }
    }

    // Free the keys and offsets arrays themselves
    free(*keys);
    free(*offsets);
}

void setArrays(int **keys, long **offsets, size_t numKeys, int minKey, int maxKey, long minOffset, long maxOffset) {
    for (size_t i = 0; i < numKeys; i++) {
        keys[i] = malloc(sizeof(int));
        offsets[i] = malloc(sizeof(long));
        if (keys[i] == NULL || offsets[i] == NULL) {
            // Handle memory allocation failure
            printf("Memory allocation failed.\n");
            freeArrays(keys, offsets, i);
            return;
        }
        *keys[i] = rand() % (maxKey - minKey + 1) + minKey;
        *offsets[i] = rand() % (maxOffset - minOffset + 1) + minOffset;
    }
}

void checkParams(int numKeys, size_t maxRecords, int minKey, int maxKey, long minOffset, long maxOffset) {
    if (numKeys < 0 || maxRecords < 0 || minKey < 0 || maxKey < minKey || minOffset < 0 || maxOffset < minOffset) {
        // Handle invalid input parameters
        printf("Invalid input parameters.\n");
    }
}

void initArraysAndRecords(int numKeys, size_t maxRecords, int minKey, int maxKey, long minOffset, long maxOffset) {
    checkParams(numKeys, maxRecords, minKey, maxKey, minOffset, maxOffset);

    // Dynamically allocate memory for and initialize arrays
    int **keys = malloc(sizeof(int *) * numKeys);
    long **offsets = malloc(sizeof(long *) * numKeys);

    if (keys == NULL || offsets == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    setArrays(keys, offsets, numKeys, minKey, maxKey, minOffset, maxOffset);

    // Dynamically allocate memory for and initialize records array
    Record **records = malloc(sizeof(Record *) * maxRecords);
    if (records == NULL) {
        printf("Memory allocation failed.\n");
        freeArrays(keys, offsets, numKeys);
        return;
    }

    setRecordValues(records, maxRecords, minKey, maxKey);

    // Use a loop to set the value of each record's int field
    for (size_t i = 0; i < maxRecords; i++) {
        records[i]->key = rand() % (maxKey - minKey + 1) + minKey;
        if (i >= numKeys) {
            free(records[i]);
        }
    }

    // Use a loop to set the value of each record's long field
    for (size_t i = 0; i < maxRecords; i++) {
        records[i]->offset = rand() % (maxOffset - minOffset + 1) + minOffset;
    }
}

int main() {
    int numKeys = 10;
    size_t maxRecords = 20;
    int minKey = 1;
    int maxKey = 100;
    long minOffset = 0;
    long maxOffset = 10000;

    initArraysAndRecords(numKeys, maxRecords, minKey, maxKey, minOffset, maxOffset);

    return 0;
}
