#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    int value;
} record_t;

record_t** hash_table;
int* keys;
long* offsets;

void init_hash_table(int size) {
    hash_table = (record_t**)malloc(size * sizeof(record_t*));
    for (int i = 0; i < size; i++) {
        hash_table[i] = NULL;
    }
}

int insert_into_hash_table(int key, long offset, int value, int table_size) {
    int index = key % table_size;
    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    new_record->key = key;
    new_record->offset = offset;
    new_record->value = value;

    if (hash_table[index] == NULL || hash_table[index]->key != key) {
        // Insert at the beginning of the chain
        record_t* current = new_record;
        while (hash_table[index]) {
            record_t* next = hash_table[index];
            hash_table[index] = current;
            current = next;
        }
        hash_table[index] = new_record;
    } else {
        free(new_record);
    }

    return 0;
}

void free_hash_table(int table_size) {
    for (int i = 0; i < table_size; i++) {
        record_t* current = hash_table[i];
        while (current) {
            record_t* next = current->next;
            free(current);
            current = next;
        }
    }

    free(hash_table);
}

void free_all_memory() {
    for (int i = 0; i < table_size; i++) {
        if (keys[i]) free(keys[i]);
    }
    free(keys);
    for (int i = 0; i < table_size; i++) {
        if (offsets[i]) free(offsets[i]);
    }
    free(offsets);
}

int main() {
    int table_size = 100;
    init_hash_table(table_size);

    // Dynamically allocate memory for the arrays
    keys = (int*)malloc(table_size * sizeof(int));
    offsets = (long*)malloc(table_size * sizeof(long));

    srand(time(NULL)); // Seed random number generator

    // Initialize the arrays with some values
    for (int i = 0; i < table_size; i++) {
        keys[i] = rand() % 100;
        offsets[i] = rand() % 10000000L;

        // Insert into hash table
        insert_into_hash_table(keys[i], offsets[i], rand() % 10, table_size);
    }

    free_all_memory();

    return 0;
}
