#include <time.h>

typedef struct {
    int value;
} record;

record* allocateArrays(int** offsets, int** keys, record** records) {
    // Allocate memory for arrays
    *offsets = (int*)malloc((101) * sizeof(int));
    *keys = (int*)malloc((51) * sizeof(int));
    *records = (record*)malloc(50 * sizeof(record));

    // Initialize offsets array with values ranging from 0 to 100, inclusive
    for (int i = 0; i < 101; i++) {
        (*offsets)[i] = i;
    }

    // Initialize keys array with unique values from 1 to 50, inclusive
    for (int i = 0; i < 50; i++) {
        (*keys)[i] = i + 1;
    }

    // Initialize records array and set each record's value randomly within the range of the corresponding key's value plus or minus 10 (inclusive)
    srand(time(NULL));
    for (int i = 0; i < 50; i++) {
        (*records)[i].value = rand() % ((*(keys + i) + 10) - (*(keys + i) - 10)) + *(keys + i) - 10;
    }

    return *records;
}

void validateRecords(record* records, int total) {
    if (total > 1000) {
        // Reallocate and adjust the records to ensure the sum is valid without altering the initial constraints
        int newTotal = 0;
        record* newRecords = (record*)malloc(50 * sizeof(record));
        for (int i = 0; i < 50; i++) {
            if ((newTotal += (*records)[i].value) > 1000) {
                // Adjust the value of the current record
                int adjust = 1000 - newTotal;
                (*newRecords + i).value -= (adjust / (i + 1)) | 0;
                if ((*newRecords + i).value < 0)
                    (*newRecords + i).value = 0;
            } else {
                *newRecords = (*records)[i];
            }
        }

        // Update the original arrays
        free(records);
        *records = newRecords;

        printf("Adjusted records to ensure sum does not exceed 1000.\n");
    }
}

int main() {
    int* offsets;
    int* keys;
    record* records = allocateArrays(&offsets, &keys, &records);

    // Calculate the total sum of all records' values
    int total = 0;
    for (int i = 0; i < 50; i++) {
        total += (*records)[i].value;
    }

    printf("Total sum: %d\n", total);

    validateRecords(records, total);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}

