#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct data_point {
    double value;
    int key;
} data_point;

data_point* initialize_data_points(int size, int seed) {
    // Initialize random number generator with system-provided seed if none is provided
    srand(seed);

    // Allocate memory for arrays of 'double' and 'int' values
    double* values = (double*) malloc(size * sizeof(double));
    int* keys = (int*) malloc(size * sizeof(int));

    if (values == NULL || keys == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Initialize arrays with random 'double' values and unique 'int' keys
    int i;
    for (i = 0; i < size; i++) {
        values[i] = (double)rand() / RAND_MAX;
        keys[i] = i;
    }

    // Allocate memory for array of 'data_point' structures
    data_point* points = (data_point*) malloc(size * sizeof(data_point));

    if (points == NULL) {
        free(values);
        free(keys);
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Initialize array of 'data_point' structures with corresponding values and keys
    for (i = 0; i < size; i++) {
        points[i].value = values[i];
        points[i].key = keys[i];
    }

    // Cleanly exit if memory allocation fails
    free(values);
    free(keys);

    return points;
}
