// Function to dynamically allocate memory for arrays
void* dynamicArrayAllocation(size_t size) {
    return malloc(size);
}

// Function to initialize arrays and records
void initArraysAndRecords(int*** offsets, int** keys, struct record*** records, int nOffsets, int nKeys) {
    // Initialize offsets array
    *offsets = (int**)dynamicArrayAllocation(nOffsets * sizeof(int*));
    for (int i = 0; i < nOffsets; i++) {
        (*offsets)[i] = (int*)dynamicArrayAllocation(sizeof(int));
        for (int j = 0; j <= i; j++) {
            (*(*offsets)[i]) = rand() % 101;
        }
    }

    // Initialize keys array
    *keys = (int**)dynamicArrayAllocation(nKeys * sizeof(int*));
    for (int i = 0; i < nKeys; i++) {
        (*keys)[i] = (int*)dynamicArrayAllocation(sizeof(int));
        *((*keys)[i]) = rand() % 50 + 1;
    }

    // Initialize records array
    *records = (struct record**)dynamicArrayAllocation(nOffsets * sizeof(struct record*));
    for (int i = 0; i < nOffsets; i++) {
        (*records)[i] = (struct record*)dynamicArrayAllocation(sizeof(struct record));
        ((*(records[i])).val) = rand() % (50 + 10) - 10;
    }
}

// Function to validate the sum of records
int validateRecords(int* offsets, int nOffsets) {
    int sum = 0;
    for (int i = 0; i < nOffsets; i++) {
        sum += *((offsets[i]));
