    records = temp_records;

    int* temp_keys = (int*)realloc(keys, old_size * sizeof(int));
    if (temp_keys == NULL) return -1;
    keys = temp_keys;

    long* temp_offsets = (long*)realloc(offsets, old_size * sizeof(long));
    if (temp_offsets == NULL) return -1;
    offsets = temp_offsets;
    return 0;
