record* init_records(int num_records, int min_value, int max_value, FILE* source) {
    if (num_records <= 0 || min_value > max_value) return NULL;

    record* records = (record*) malloc(num_records * sizeof(record));
    if (!records) return NULL;

    int* values = (int*) malloc(num_records * sizeof(int));
    if (!values) {
        free(records);
        return NULL;
    }

    char** strs = (char**) malloc(num_records * sizeof(char*));
    if (!strs) {
        free(values);
        free(records);
        return NULL;
    }

    int i;
    for (i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        values[i] = records[i].value;

        char buffer[256];
        if (!fgets(buffer, sizeof(buffer), source)) {
            for (; i > 0; i--) {
                free(strs[i]);
            }
            free(values);
            free(records);
            return NULL;
        }

        int len = strlen(buffer) - 1; // account for the newline
        strs[i] = (char*) malloc(len + 1);
        if (!strs[i]) {
            for (; i > 0; i--) {
                free(strs[i]);
            }
            free(values);
            free(records);
            return NULL;
        }

        strcpy(strs[i], buffer);
