    record* records = NULL;
    record** strings = NULL;

    // Allocate memory for the integer array and the string pointers array
    records = (record*)malloc(num_records * sizeof(record));
    if (!records) return NULL;

    strings = (record**)malloc(num_records * sizeof(record*));
    if (!strings) {
        free(records);
        return NULL;
