    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Parse and assign unique string identifiers from the external data source to each record
    char buffer[256];
    for (int i = 0; i < num_records; i++) {
        if (!fscanf(data_source, "%255s", buffer)) {
            // Handle parsing error or end of file
            free(records);
            free(strings);
            return NULL;
        }
        records[i].string = strdup(buffer);
        strings[i] = &records[i];
    }

    fclose(data_source);

    // Return an array of pointers to the initialized records
    return strings;
}

