    *value = min + rand() % range;
}

void thread_safe_malloc(void **ptr, size_t size) {
    void *temp = malloc(size);
    if (temp != NULL) {
        *ptr = temp;
        pthread_mutex_lock(&mutex);
        total_memory += size;
        pthread_mutex_unlock(&mutex);
        if (total_memory > MAX_MEMORY) {
            fprintf(stderr, "Memory limit exceeded!\n");
            exit(EXIT_FAILURE);
        }
    } else {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
}

void thread_safe_free(void **ptr) {
    pthread_mutex_lock(&mutex);
    free(*ptr);
    total_memory -= sizeof(**ptr);
