typedef struct {
    long offset;
    int key;
} record_t;

record_t* allocate_records(size_t count, size_t max_size) {
    if(count > (max_size / sizeof(record_t)) || max_size == 0) {
        return NULL;
    }
    record_t *records = malloc(max_size);
    if(records != NULL) {
        for(size_t i=0; i<count; i++) {
            records[i].offset = rand();
            records[i].key = (int)(rand() % RAND_MAX);
        }
    }
    return records;
}

void free_records(record_t *records, size_t count) {
    if(records != NULL) {
        free(records);
    }
}

uint32_t checksum(const record_t* records, size_t count) {
    uint32_t sum = 0;
    for(size_t i=0; i<count; i++) {
        sum += (uint32_t)(records[i].offset | (uint32_t)records[i].key << 32);
    }
    return sum;
}

void encrypt(record_t* records, size_t count, const uint8_t* key, int key_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if(ctx == NULL) {
        return;
    }
    EVP_add_cipher_alias(EVP_aes_128_cbc());
    if(EVP_CipherInit_ex(ctx, NULL, NULL, key, key_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    for(size_t i=0; i<count; i++) {
        record_t* r = &records[i];
        size_t len = sizeof(record_t);
        uint8_t *ciphertext = malloc(len);
        if(ciphertext == NULL) {
            break;
        }
        EVP_CipherUpdate(ctx, ciphertext, &len, (uint8_t*)&r, sizeof(record_t));
        memcpy(r, ciphertext, len);
        free(ciphertext);
    }
    EVP_CIPHER_CTX_free(ctx);
}

void decrypt(record_t* records, size_t count, const uint8_t* key, int key_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if(ctx == NULL) {
        return;
    }
    EVP_add_cipher_alias(EVP_aes_128_cbc());
    if(EVP_CipherInit_ex(ctx, NULL, NULL, key, key_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    for(size_t i=0; i<count; i++) {
        record_t* r = &records[i];
        size_t len = sizeof(record_t);
        uint8_t *plaintext = malloc(len);
        if(plaintext == NULL) {
            break;
        }
        EVP_CipherUpdate(ctx, plaintext, &len, (uint8_t*)&r, sizeof(record_t));
        memcpy(r, plaintext, len);
        free(plaintext);
    }
    EVP_CIPHER_CTX_free(ctx);
}

