#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <openssl/sha.h>

#define MAX_NODES 100000
#define MAX_STRING_LENGTH 256
#define MAX_MEMORY_LIMIT (MAX_NODES * sizeof(struct Node) + sizeof(struct Graph))

struct Node {
    int value;
    char string[MAX_STRING_LENGTH];
    double weight;
};

struct Graph {
    int nodeCount;
    struct Node** nodes;
    unsigned long totalMemoryUsage;
};

void* malloc(size_t size) {
    void* ptr = realloc(NULL, size);
    if (!ptr && size > 0) {
        printf("Memory allocation failed.\n");
        exit(-1);
    }
    return ptr;
}

struct Graph* graphCreate() {
    struct Graph* graph = (struct Graph*)malloc(sizeof(struct Graph));
    graph->nodeCount = 0;
    graph->nodes = NULL;
    graph->totalMemoryUsage = 0;
    return graph;
}

void graphFree(struct Graph* graph) {
    for (int i = 0; i < graph->nodeCount; i++) {
        free(graph->nodes[i]);
    }
    free(graph->nodes);
    free(graph);
}

struct Node* nodeCreate(int value, const char* string) {
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    if (!node) return NULL;

    node->value = value;
    strcpy(node->string, string);
    node->weight = 0.0;

    return node;
}

void graphInsertNode(struct Graph* graph, int value, const char* string) {
    struct Node* newNode = nodeCreate(value, string);

    if (graph->nodeCount >= MAX_NODES) {
        printf("Maximum number of nodes reached.\n");
        exit(-1);
    }

    graph->nodes = realloc(graph->nodes, (graph->nodeCount + 1) * sizeof(struct Node*));
    graph->nodes[graph->nodeCount] = newNode;
    graph->nodeCount++;
}

void graphDeleteNode(struct Graph* graph, int value) {
    for (int i = 0; i < graph->nodeCount; i++) {
        if (graph->nodes[i]->value == value) {
            free(graph->nodes[i]);
            memmove(&graph->nodes[i], &graph->nodes[i + 1], sizeof(struct Node*) * (graph->nodeCount - i));
            graph->nodeCount--;
            return;
        }
    }
}

int main() {
    // Example usage
    struct Graph* graph = graphCreate();
    graphInsertNode(graph, 42, "Hello");
    graphInsertNode(graph, 21, "World");
    printf("Total memory usage: %lu bytes\n", graph->totalMemoryUsage);
    graphDeleteNode(graph, 42);
    graphFree(graph);

    return 0;
}
