void *thread_safe_malloc(void **ptr, size_t size) {
    void *temp = malloc(size);

    if (temp != NULL) {
        *ptr = temp;
        pthread_mutex_lock(&mutex);
        total_memory += size;
        pthread_mutex_unlock(&mutex);

        if (total_memory > MAX_MEMORY) {
            fprintf(stderr, "Memory limit exceeded!\n");
            exit(EXIT_FAILURE);
        }

        // Additional check for name length
        if (((record *)*ptr)->name[5] == '\0') { // Ensure name is not empty or too short
            fprintf(stderr, "Name field is invalid!\n");
            exit(EXIT_FAILURE);
        }

        // Additional check for value range
        if (((record *)*ptr)->value < -1.0f || ((record *)*ptr)->value > 1.0f) {
            fprintf(stderr, "Value is out of range!\n");
            exit(EXIT_FAILURE);
        }

        return temp;
    } else {
        return NULL;
    }
}
