// Define the maximum memory limit
#define MAX_MEMORY 1024 * 1024 * 100 // 100 MB

typedef struct {
    double value;
    char* string;
} record_t;

record_t* data_records = NULL;
size_t num_records = 0;
size_t max_memory = 0;

// Function to generate a random record
void generate_record(double value, const char* string) {
    // Check if the maximum memory limit has been exceeded
    if (max_memory + sizeof(record_t) > MAX_MEMORY) {
        return; // Fail if exceeding the maximum memory limit
    }

    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    new_record->value = value;
    new_record->string = (char*)malloc(strlen(string) + 1);
    strcpy(new_record->string, string);

    // Encrypt and compress the record using AES and Zlib
    unsigned char encrypted_record[256];
    int compressed_len;
    int decrypted_len;

    // Perform encryption and compression
    if (!encrypt_compress_record(new_record, encrypted_record)) {
        free(new_record);
        return; // Fail if encryption or compression fails
    }

    // Update the data records array
    record_t* old_records = data_records;
    num_records++;
    max_memory += sizeof(record_t);

    data_records = (record_t*)realloc(data_records, num_records * sizeof(record_t));
    memcpy(&data_records[num_records - 1], new_record, sizeof(record_t));

    free(old_records);
}

// Function to encrypt and compress a record
int encrypt_compress_record(record_t* record, unsigned char* output) {
    // Encrypt the record using AES
    int encrypted_len = AES_encrypt(record->string, strlen(record->string), output);

    // Compress the encrypted record using Zlib
    int compressed_len;
    if (!compress(output, &compressed_len)) {
        return 0; // Fail if compression fails
    }

    // Update the max memory used
    max_memory += compressed_len;

    return 1; // Success
}

// Function to free allocated memory
void free_memory() {
    for (int i = 0; i < num_records; i++) {
        free(data_records[i].string);
    }
    free(data_records);
}

// Asynchronous logging function
void log_resource_usage() {
    printf("Peak memory usage: %zu MB\n", max_memory / (1024 * 1024));
}

int main() {
    // Initialize the data records array with a maximum size of MAX_MEMORY
    data_records = (record_t*)malloc(MAX_MEMORY / sizeof(record_t));

    for (int i = 0; i < 10000; i++) { // Generate 10,000 records
        double value = i * 3.14;
        const char* string = "Hello, World!";
        generate_record(value, string);
    }

    log_resource_usage();

    free_memory();
    return 0;
}

