#define MAX_RECORDS 1000
#define RECORD_SIZE sizeof(struct record)
#define AES_KEY_SIZE 16
#define HMAC_KEY_SIZE 32

typedef struct {
    int value;
} record;

record* records = NULL;
size_t record_count = 0;
size_t max_records = MAX_RECORDS;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_once_t once_init = PTHREAD_ONCE_INIT;
EVP_CIPHER_CTX* aes_ctx = NULL;
EVP_MD_CTX* md_ctx = NULL;
unsigned char* hmac_key = NULL;
unsigned char* aes_key = NULL;
size_t aes_key_len = AES_KEY_SIZE;
size_t hmac_key_len = HMAC_KEY_SIZE;

void record_init() {
    pthread_once(&once_init, () => {
        if ((aes_ctx = EVP_CIPHER_CTX_new()) == NULL || 
            (md_ctx = EVP_MD_CTX_new()) == NULL) {
            printf("Error initializing cryptographic contexts!\n");
            exit(1);
        }
        if (!(hmac_key = malloc(hmac_key_len))) {
            printf("Error allocating HMAC key memory!\n");
            exit(1);
        }
        if (!(aes_key = malloc(aes_key_len))) {
            printf("Error allocating AES key memory!\n");
            exit(1);
        }
    });
}

void record_free() {
    EVP_CIPHER_CTX_free(aes_ctx);
    EVP_MD_CTX_free(md_ctx);
    free(hmac_key);
    free(aes_key);
}

int record_set_value(int value) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < record_count; i++) {
        if (records[i].value == value) {
            records[i].value = value;
            pthread_mutex_unlock(&lock);
            return 1; // Update successful
        }
    }
    pthread_mutex_unlock(&lock);
    return -1; // Value not found
}

void* record_alloc() {
    void* ptr = NULL;
    size_t len = RECORD_SIZE * (record_count + 1);

    if ((ptr = malloc(len)) != NULL) {
        memset(ptr, 0x00, len);
    }

    pthread_mutex_lock(&lock);
    records = realloc(records, len);
    record_count++;
    pthread_mutex_unlock(&lock);

    return ptr;
}

void* record_realloc(size_t offset) {
    void* ptr = NULL;

    if ((ptr = malloc(RECORD_SIZE)) != NULL) {
        memset(ptr, 0x00, RECORD_SIZE);
        records[offset] = *(record*)ptr;
    }

    pthread_mutex_lock(&lock);
    free(records + offset * RECORD_SIZE);
    records = realloc(records, (record_count - 1) * RECORD_SIZE);
    pthread_mutex_unlock(&lock);

    return ptr;
}

void record_free_all() {
    for (size_t i = 0; i < record_count; i++) {
        free((void*)records + i * RECORD_SIZE);
    }
    free(records);
    records = NULL;
    record_count = 0;
}

int main() {
    // Initialize cryptographic contexts
    record_init();

    // Allocate memory for arrays and structures
    long* offset_values = (long*)malloc(sizeof(long) * max_records);
    int* keys = (int*)malloc(sizeof(int) * max_records);

    if ((records = malloc(RECORD_SIZE)) == NULL || 
        (offset_values == NULL) || (keys == NULL)) {
        printf("Error allocating memory!\n");
        exit(1);
    }

    // Set values for each record's int field
    for (size_t i = 0; i < max_records; i++) {
        if (!(records[i].value = rand() % 1000)) {
            // Handle overflow/underflow in 'int' field
            records[i].value = -1;
        }
    }

    // Free all allocated memory when done
    record_free_all();
    free(offset_values);
    free(keys);

    return 0;
}
