        if (allocated_memory > MAX_MEMORY) break;

        // Allocate a block of memory for the next record and string
        void* new_memory = realloc(memory, allocated_memory + sizeof(SensorRecord)+sizeof(char*)*max_string_length);
        if (!new_memory) {
            free(memory);
            return NULL;
        }
        memory = new_memory;
        allocated_memory += sizeof(SensorRecord)+sizeof(char*)*max_string_length;
    }

    // Initialize the sensor record array
    SensorRecord* records = (SensorRecord*)memory;

    // Generate random values for each float field and pointers to strings
    for (int i=0; i<max_records; i++) {
        records[i].value = rand() / (float)RAND_MAX;
        records[i].string = malloc(max_string_length);
        if (!records[i].string) return NULL;
        // Fill the string with random characters
        for (int j=0; j<max_string_length; j++)
            ((char*)records[i].string)[j] = rand() % 256;
    }

    // Encrypt each record using AES or ChaCha20
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    for (int i=0; i<max_records; i++) {
        unsigned char iv[EVP_MAX_IV_LENGTH];
        unsigned char key[EVP_MAX_KEY_LENGTH];

        // Generate random IV and key for AES or ChaCha20
        RAND_bytes(iv, sizeof(iv));
        RAND_bytes(key, sizeof(key));

        // Set the encryption algorithm and parameters
        EVP_CIPHER_CTX_set_params(ctx, iv, key);

        // Encrypt each record field using AES or ChaCha20
        unsigned char* encrypted = malloc(EVP_MAX_BLOCK_LENGTH);
        if (!encrypted) return NULL;
        int len = 0;
        if (EVP_CipherUpdate(ctx, encrypted, &len)) {
            // Log encryption errors
            printf("Encryption error: %s\n", EVP_CIPHER_CTX_error_string(ctx));
            free(encrypted);
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }

        // Store the encrypted record and string in memory
        records[i].value = *(float*)encrypted;
        records[i].string = realloc(records[i].string, len+1);
        memcpy(((char*)records[i].string), encrypted, len);
    }

    // Free resources and return the sensor record array
    EVP_CIPHER_CTX_free(ctx);
    for (int i=0; i<max_records; i++)
        free(((char*)records[i].string));
    free(memory);

    return records;
}

// Function to free all allocated memory when done
void free_sensor_data(SensorRecord* records) {
    if (!records) return;

    // Free each record's string and float field
    for (int i=0; i<max_records; i++) {
        free(((char*)records[i].string));
        free(&records[i]);
    }

    free(records);
}
