        if (total_size > max_memory_limit) {
            break;
        }

        if (!records) {
            records = malloc(total_size);
            memset(records, 0, total_size);
        } else {
            Record *prev_records = records;
            records = (Record *)realloc(prev_records, total_size);
            memset(&((char *)records)[total_size - record_size], 0, record_size);
