#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>

#define MAX_MEMORY 1024*1024 // 1MB

typedef struct {
    int key;
    long offset;
} Record;

Record *init_records(int num_records, int *keys, long *offsets) {
    Record *records = (Record *)malloc(num_records * sizeof(Record));

    if (!records || (num_records > MAX_MEMORY / sizeof(Record))) {
        free(records);
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    return records;
}

void free_records(Record *records) {
    free(records);
}

void encrypt_records(Record *records, int num_records) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);

    for (int i = 0; i < num_records; i++) {
        // Encrypt record
        unsigned char encrypted[sizeof(Record)];
        size_t encrypted_len = sizeof(encrypted);
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, iv, NULL);
        EVP_EncryptUpdate(ctx, &records[i], sizeof(Record), encrypted, &encrypted_len);
        EVP_EncryptFinal_ex(ctx, encrypted + encrypted_len, &encrypted_len);

        // Store IV with encrypted record
        records[i].key = *((int *)iv);
    }

    EVP_CIPHER_CTX_free(ctx);
}

void decrypt_records(Record *records, int num_records) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char iv[AES_BLOCK_SIZE];

    for (int i = 0; i < num_records; i++) {
        // Decrypt record
        unsigned char decrypted[sizeof(Record)];
        size_t decrypted_len = sizeof(decrypted);
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, iv, &records[i].key);
        EVP_DecryptUpdate(ctx, records + i, sizeof(Record), decrypted, &decrypted_len);
        EVP_DecryptFinal_ex(ctx, decrypted + decrypted_len, &decrypted_len);

        // Verify decryption
        if (memcmp(&((Record *)decrypted)->offset, &records[i].offset, sizeof(long)) != 0) {
            printf("Decryption failed\n");
        }
    }

    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    int *keys = malloc(100 * sizeof(int));
    long *offsets = malloc(100 * sizeof(long));

    // Initialize records
    Record *records = init_records(100, keys, offsets);

    if (records) {
        encrypt_records(records, 100);

        decrypt_records(records, 100);

        free_records(records);
    }

    return 0;
}
