// Function to manage the metadata data structure
directory_entry* create_metadata(int num_entries) {
    // Validate the input parameter
    if (num_entries < 1 || num_entries > 1000) {
        return NULL;
    }

    // Manage a cache of previously allocated memory for performance optimization
    static directory_entry *cached_metadata = NULL;

    // Check if a cached metadata already exists with the same number of entries
    if (cached_metadata && cached_metadata->num_files == num_entries) {
        return cached_metadata;
    }

    // Initialize the metadata structure with dynamically allocated memory
    directory_entry *metadata = (directory_entry *)malloc(sizeof(directory_entry));
    if (!metadata) {
        return NULL;
    }

    metadata->name = (char *)malloc((strlen("root") + 1) * sizeof(char));
    strcpy(metadata->name, "root");

    metadata->num_files = num_entries;

    // Dynamically allocate memory for the file entries
    metadata->files = (file_entry **)malloc(num_entries * sizeof(file_entry *));
    if (!metadata->files) {
        free(metadata->name);
        free(metadata);
        return NULL;
    }

    // Initialize each file entry with dynamically allocated memory
    int i;
    for (i = 0; i < num_entries; i++) {
        metadata->files[i] = (file_entry *)malloc(sizeof(file_entry));
        if (!metadata->files[i]) {
            for (int j = 0; j <= i; j++) {
                free(metadata->files[j]->name);
                free((void *)metadata->files[j]);
            }
            free(metadata->name);
            free(metadata->files);
            free(metadata);
            return NULL;
        }

        metadata->files[i]->name = (char *)malloc((strlen("file_name") + 1) * sizeof(char));
        strcpy(metadata->files[i]->name, "file_name");

        metadata->files[i]->size = i;
        metadata->files[i]->modified_time = time(NULL);
    }

    // Update the cached metadata for future use
    cached_metadata = metadata;

    return metadata;
}

int main() {
    int num_entries = 5;  // Test with a reasonable number of entries
    directory_entry *metadata = create_metadata(num_entries);

    if (metadata) {
        printf("Metadata created successfully!\n");
    } else {
        printf("Error creating metadata.\n");
    }

    return 0;
}

