#include <stdlib.h>
#include <pthread.h>

// Structure to represent a record
typedef struct {
    int value;
} Record;

// Structure to manage array of 'long' offset values, 'int' keys, and an array of 'record' structures
typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t max_size;
    pthread_mutex_t mutex;
} ArrayManager;

ArrayManager* array_manager_create(size_t max_size) {
    ArrayManager* manager = (ArrayManager*)malloc(sizeof(ArrayManager));
    manager->max_size = max_size;
    manager->offsets = (long*)calloc(max_size, sizeof(long));
    manager->keys = (int*)calloc(max_size, sizeof(int));
    manager->records = (Record**)calloc(max_size, sizeof(Record*));
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void array_manager_free(ArrayManager* manager) {
    free(manager->offsets);
    free(manager->keys);
    for (size_t i = 0; i < manager->max_size; i++) {
        if (manager->records[i] != NULL) {
            free(manager->records[i]);
        }
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

// Function to generate a new state list by finding a list of states in a given finite state automaton (FSA)
ArrayManager* fsa_state_list(const int* states, size_t num_states, const void* fsa, int last_state) {
    ArrayManager* manager = array_manager_create(num_states);
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < num_states; i++) {
        Record* record = malloc(sizeof(Record));
        record->value = states[i];
        manager->records[i] = record;
    }
    pthread_mutex_unlock(&manager->mutex);
    return manager;
}

// Function to limit memory usage by enforcing a maximum size for each state list and invalidating old lists when new ones are created
void fsa_state_list_limit(ArrayManager* manager, int last_state) {
    if (last_state >= manager->max_size) {
        array_manager_free(manager);
        ArrayManager* new_manager = array_manager_create(last_state + 1);
        // Copy data from old to new manager
        pthread_mutex_lock(&manager->mutex);
        for (size_t i = 0; i < manager->max_size; i++) {
            if (manager->records[i] != NULL) {
                Record* record = malloc(sizeof(Record));
                record->value = manager->records[i]->value;
                new_manager->records[i] = record;
            }
        }
        pthread_mutex_unlock(&manager->mutex);
    }
}
