                free(data);
                return NULL;
            }
        }
    }

    return data;
}

void free_sensor_data(sensor_data** data, int n) {
    for (int i = 0; i < n; i++) {
        sensor_data* current_sensor = &data[i];

        if (current_sensor->s != NULL) {
            free(current_sensor->s);
        }
        // Add OpenSSL cipher/digest deallocation here
        EVP_Cipher_CTX_free(EVP_CIPHER_CTX_new());
    }

    if (*data != NULL) {
        free(*data);
    }
}
