#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000
#define MIN_VALUE 0
#define MAX_VALUE 1000000
#define MEMORY_LIMIT 128 * (1024 * 1024)
#define THREAD_COUNT 5

typedef struct {
    int id;
    int key;
} Record;

Record* records = NULL;
int record_count = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* allocateRecords(int count) {
    Record* new_records = (Record*)malloc(count * sizeof(Record));
    if (!new_records) {
        printf("Memory allocation failed. Trying again...\n");
        sleep(1);
        return NULL;
    }
    record_count += count;
    pthread_mutex_lock(&mutex);
    records = realloc(records, (record_count + MAX_RECORDS) * sizeof(Record));
    pthread_mutex_unlock(&mutex);
    return new_records;
}

void validateMemory() {
    int total_bytes = record_count * sizeof(Record);
    if (total_bytes > MEMORY_LIMIT) {
        printf("Memory limit exceeded. Reallocating memory...\n");
        free(records);
        records = NULL;
        record_count = 0;
    }
}

int generateRandomValue(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

void* fillRecords(void* arg) {
