        record.key = generateRandomValue(MIN_VALUE, MAX_VALUE);

        // Validate and adjust memory as needed
        if ((record_count + 1) * sizeof(Record) > MEMORY_LIMIT) {
            validateMemory();
        }

        pthread_mutex_lock(&mutex);
        records[i].id = record.id;
        records[i].key = record.key;
        pthread_mutex_unlock(&mutex);

        // Simulate some work
        sleep(0.01);
    }
}

int main() {
    srand(time(NULL));

    int thread_count = THREAD_COUNT;
    int* start_indices = (int*)malloc(thread_count * sizeof(int));
    for (int i = 0; i < thread_count; i++) {
        start_indices[i] = i * MAX_RECORDS;
    }

    pthread_t threads[thread_count];
    for (int i = 0; i < thread_count; i++) {
        pthread_create(&threads[i], NULL, fillRecords, &start_indices[i]);
    }

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    free(start_indices);

    // Deallocate memory
    Record* temp_records = records;
    while (temp_records) {
        Record* next = temp_records;
        temp_records = temp_records->key;
        free(next);
    }
    return 0;
}
