record* allocate_records(int num_records, int max_value) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        data_entry* entry = (data_entry*)malloc(sizeof(data_entry));
        if (!entry) {
            free(records);
            return NULL;
        }

        entry->value = rand() % max_value;
        char* str_val = strdup(rand_string());
        if (!str_val) {
            free(entry);
            free(records);
            return NULL;
        }
        entry->string_val = str_val;

        int_array_t array = (int*)malloc(MAX_INT_VALUE * sizeof(int));
        for (int j = 0; j < MAX_INT_VALUE; j++) {
            array[j] = rand() % max_value;
        }

        record* r = (record*)malloc(sizeof(record));
        if (!r) {
            free(entry);
            free(records);
            return NULL;
        }
        r->value = entry->value;
        r->int_array = array;
        r->string_val = str_val;

        records[i] = *r;
    }

    return records;
}

char* rand_string() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 9);

    char* string_val = (char*)malloc(STRING_MAX_LENGTH);
    for (int i = 0; i < STRING_MAX_LENGTH; i++) {
        int random_value = dis(gen);
        char ch = 'a' + (random_value % 26);
        string_val[i] = ch;
    }
    return string_val;
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        data_entry* entry = &records[i].data_entry;
        free(entry->string_val);
        free(entry->int_array);
        free(&records[i]);
    }
    free(records);
}

