typedef struct {
    double value;
    char* string;
} Data;

void freeMemory(Data** data, int size) {
    for (int i = 0; i < size; i++) {
        if (data[i]->string != NULL)
            free(data[i]->string);
        free(data[i]);
    }
    free(data);
}

Data* allocateAndInitialize(int maxSize) {
    Data* data = NULL;
    int dataSize = 0;

    while (true) {
        data = realloc(data, (dataSize + 1) * sizeof(Data));
        if (data == NULL)
            break;

        if (dataSize >= maxSize) {
            free(data);
            return NULL; // Memory limit exceeded
        }

        for (int i = 0; i <= dataSize; i++) {
            data[i].value = (double)rand() / RAND_MAX;
            char temp[20];
            sprintf(temp, "String %d", i);
            data[i].string = strdup(temp);
        }
        dataSize++;
    }

    return data;
}

int main() {
    // Example usage
    int maxSize = 10;
    Data* data = allocateAndInitialize(maxSize);

    if (data == NULL)
        printf("Memory limit exceeded.\n");
    else {
        for (int i = 0; i < maxSize; i++) {
            printf("Value: %f, String: %s\n", data[i].value, data[i].string);
        }
        freeMemory(&data, maxSize);
    }

    return 0;
}
