#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the maximum limit for memory usage
#define MAX_MEMORY 10000000

// Structure to represent a graph node
typedef struct {
    int value;
    char *name;
    double weight;
} Node;

// Structure to manage the graph and its arrays
typedef struct {
    Node **nodes;
    long *offsets;
    int *keys;
    int size;
    int capacity;
} Graph;

// Function to initialize a new graph instance
Graph* create_graph(int capacity) {
    Graph *graph = (Graph*)malloc(sizeof(Graph));
    graph->size = 0;
    graph->capacity = capacity;
    graph->nodes = (Node**)calloc(capacity, sizeof(Node*));
    graph->offsets = (long*)calloc(capacity, sizeof(long));
    graph->keys = (int*)calloc(capacity, sizeof(int));
    return graph;
}

// Function to free all allocated memory
void destroy_graph(Graph *graph) {
    for (int i = 0; i < graph->capacity; i++) {
        if (graph->nodes[i] != NULL) {
            free(graph->nodes[i]->name);
            free(graph->nodes[i]);
        }
    }
    free(graph->offsets);
    free(graph->keys);
    free(graph);
}

// Function to add a new node to the graph
void add_node(Graph *graph, int value, const char *name, double weight) {
    // Check if memory limit is exceeded before allocating new memory
    if (graph->size >= graph->capacity || (graph->size + 1) * sizeof(Node) > MAX_MEMORY) {
        printf("Memory limit exceeded. Cannot add more nodes.\n");
        return;
    }

    Node *node = (Node*)malloc(sizeof(Node));
    node->value = value;
    node->name = strdup(name);
    node->weight = weight;

    graph->nodes[graph->size] = node;
    graph->offsets[graph->size] = (long)(void*)node;
    graph->keys[graph->size] = value;
    graph->size++;
}

// Function to remove a node from the graph
void remove_node(Graph *graph, int key) {
    for (int i = 0; i < graph->size; i++) {
        if (graph->keys[i] == key) {
            // Update array indices and free allocated memory
            for (int j = i + 1; j < graph->size; j++) {
                graph->nodes[j - 1] = graph->nodes[j];
                graph->offsets[j - 1] = graph->offsets[j];
                graph->keys[j - 1] = graph->keys[j];
            }
            free(graph->nodes[graph->size - 1]->name);
            free(graph->nodes[graph->size - 1]);
            graph->size--;
            break;
        }
    }
}

// Function to search for a node by its key
Node* find_node(Graph *graph, int key) {
    for (int i = 0; i < graph->size; i++) {
        if (graph->keys[i] == key) {
            return graph->nodes[i];
        }
    }
    return NULL;
}

// Function to calculate the SHA-256 hash of a string
unsigned char* sha256(const char *str, int len) {
    EVP_MD_CTX md_ctx;
    unsigned char result[SHA256_DIGEST_LENGTH];
    const EVP_MD *sha256 = EVP_sha256();
    unsigned char *input = (unsigned char *)str;
    size_t input_len = len;

    EVP_DigestInit_ex(&md_ctx, sha256, 0);
    EVP_DigestUpdate(&md_ctx, input, input_len);
    EVP_DigestFinal_ex(&md_ctx, result, &input_len);

    return result;
}
