['Here is the code for the C function that manages dynamic allocation and initialization of a graph structure:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha256.h>

#define MAX_MEMORY 1000000 // specify maximum memory limit in bytes

typedef struct {
    int value;
    char* string;
    double weight;
} Node;

Node* graph = NULL; // initialize graph pointer
int node_count = 0; // keep track of number of nodes in the graph
int max_memory = MAX_MEMORY; // set initial maximum memory limit
int current_memory = 0; // track currently used memory

// thread-safe mechanism to dynamically adjust memory limits based on system resource availability
void* realloc_if_needed(void* ptr, size_t size) {
    if (current_memory + size > max_memory) {
        max_memory *= 2; // double the maximum memory limit
    }
    return realloc(ptr, size);
}

// initialize graph structure with arrays for offsets and keys
int init_graph() {
    graph = NULL;
    node_count = 0;
    current_memory = 0;
    return 0;
}

// insert a new node into the graph structure
int insert_node(int value, char* string) {
    Node* new_node = (Node*) realloc_if_needed(graph, sizeof(Node) * (node_count + 1));
    if (!new_node) {
        printf("Memory error: insufficient memory for inserting a new node.\n");
        return -1;
    }
    graph = new_node;

    // initialize the new node's fields
    graph[node_count].value = value;
    graph[node_count].string = string;
    graph[node_count].weight = 0.0; // default weight is 0

    current_memory += sizeof(Node);
    node_count++;
    return 0;
}

// delete a node from the graph structure
int remove_node(int index) {
    if (index < 0 || index >= node_count) {
        printf("Error: node index out of bounds.\n");
        return -1;
    }

    Node* new_graph = (Node*) realloc_if_needed(graph, sizeof(Node) * (node_count - 1));
    if (!new_graph) {
        printf("Memory error: insufficient memory for deleting a node.\n");
        return -1;
    }
    graph = new_graph;

    // shift the remaining nodes to fill the gap
    memmove(&graph[index], &graph[index + 1], sizeof(Node) * (node_count - index - 1));
    current_memory -= sizeof(Node);
    node_count--;
    return 0;
}

// search for a node in the graph structure
int search_node(int value, char* string) {
    int i = 0;
    while (i < node_count) {
        if (graph[i].value == value && strcmp(graph[i].string, string) == 0) {
            return i; // found the node, return its index
        }
        i++;
    }
    return -1; // node not found
}

int main() {
    init_graph();

    // test the insert and remove operations
    insert_node(42, "Hello");
    insert_node(21, "World");

    int i = 0;
    while (i < node_count) {
        printf("Node %d: value = %d, string = %s\n", i, graph[i].value, graph[i].string);
        i++;
    }

    remove_node(1);

    i = 0;
    while (i < node_count) {
        printf("Node %d: value = %d, string = %s\n", i, graph[i].value, graph[i].string);
        i++;
    }

    return 0;
}
