// Define the maximum limit for memory allocation
const size_t MAX_MEMORY = 1024 * 1024 * 10; // 10MB

// Define the structure to store a data record
typedef struct {
    int offset;
    double value;
    char* string;
} DataRecord;

// Function to generate a random alphanumeric string of fixed length
char* generateRandomString(size_t length) {
    static const char alphanum[] = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char* str = (char*)malloc((length + 1) * sizeof(char));
    for (size_t i = 0; i < length; i++) {
        str[i] = alphanum[rand() % (sizeof(alphanum) / sizeof(alphanum[0]))];
    }
    str[length] = '\0';
    return str;
}

// Function to allocate and initialize arrays and data records
DataRecord** initDataRecords(size_t numRecords, size_t* offsetValues, size_t* intKeys, double* doubleValues, char*** stringArrays) {
    // Initialize the arrays and data records
    DataRecord** records = (DataRecord**)malloc(numRecords * sizeof(DataRecord*));
    for (size_t i = 0; i < numRecords; i++) {
        records[i] = (DataRecord*)malloc(sizeof(DataRecord));

        // Generate random values for each record's int and double fields
        records[i]->offset = offsetValues[i % 4];
        records[i]->value = doubleValues[i % 5];
        size_t stringLength = rand() % 10 + 1;
        char* str = generateRandomString(stringLength);
        records[i]->string = str;

        // Allocate memory for and initialize the array of strings
        stringArrays[i] = (char**)malloc((numRecords) * sizeof(char*));
        stringArrays[i][i] = str;
    }

    return records;
}

int main(int argc, char** argv) {
    srand(time(NULL));

    size_t numRecords = 1000; // Default number of records
    if (argc > 1) {
        numRecords = atoi(argv[1]);
    }

