    for (size_t i = 0; i < 4; i++) {
        offsetValues[i] = rand() % 100;
    }

    int* intKeys = (int*)malloc(numRecords * sizeof(int));
    for (size_t i = 0; i < numRecords; i++) {
        intKeys[i] = rand() % 10;
    }

    double* doubleValues = (double*)malloc(numRecords * sizeof(double));
    for (size_t i = 0; i < numRecords; i++) {
        doubleValues[i] = (double)rand() / RAND_MAX;
    }

    char*** stringArrays = (char***)malloc(numRecords * sizeof(char**));

    DataRecord** records = initDataRecords(numRecords, offsetValues, intKeys, doubleValues, stringArrays);

    // Free allocated memory
    for (size_t i = 0; i < numRecords; i++) {
        free(stringArrays[i][i]);
        free(stringArrays[i]);
    }
    free(stringArrays);
    free(intKeys);
    free(doubleValues);
    for (size_t i = 0; i < numRecords; i++) {
        free(records[i]->string);
        free(records[i]);
    }
    free(records);

    return 0;
}
