    point_t *coord;
} geometry_t;

void manage_records(int *values, int *keys, int **records, double *floats, point_t **points, geometry_t **geometries,
                    size_t max_memory, size_t initial_size) {
    // Initialize variables
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    size_t total_memory = 0;
    size_t current_records = initial_size;

    // Allocate memory for records
    *records = (int **)malloc(current_records * sizeof(int *));
    if (*records == NULL || total_memory > max_memory) {
        printf("Memory allocation failed!\n");
        return;
    }
    total_memory += current_records * sizeof(int *);

    // Initialize points and geometries arrays with initial size
    *points = (point_t *)malloc(current_records * sizeof(point_t));
    if (*points == NULL || total_memory > max_memory) {
        printf("Memory allocation failed!\n");
        return;
    }
    total_memory += current_records * sizeof(point_t);

    *geometries = (geometry_t *)malloc(current_records * sizeof(geometry_t));
    if (*geometries == NULL || total_memory > max_memory) {
        printf("Memory allocation failed!\n");
        return;
    }
    total_memory += current_records * sizeof(geometry_t);

    // Initialize arrays with random values
    for (size_t i = 0; i < current_records; i++) {
        (*records)[i] = rand();
        (*points)[i].x = rand() % 100;
        (*points)[i].y = rand() % 100;
        (*geometries)[i].value = (double)rand() / RAND_MAX;
        (*geometries)[i].coord = &(*points)[i];
    }

    // Implement dynamic resizing
    while (true) {
        pthread_mutex_lock(&mutex);
        if (total_memory + current_records * sizeof(int *) > max_memory) {
            printf("Memory exceeded limit!\n");
            break;
        }
        size_t new_size = current_records * 2;
        int **new_records = (int **)realloc(*records, new_size * sizeof(int *));
        if (new_records == NULL || total_memory + new_size * sizeof(int *) > max_memory) {
            printf("Memory allocation failed!\n");
            break;
        }
        total_memory += new_size - current_records;
        free(*points);
        *points = (point_t *)malloc(new_size * sizeof(point_t));
        if (*points == NULL || total_memory + new_size * sizeof(point_t) > max_memory) {
            printf("Memory allocation failed!\n");
            break;
        }
        total_memory += new_size - current_records;
        free(*geometries);
        *geometries = (geometry_t *)malloc(new_size * sizeof(geometry_t));
        if (*geometries == NULL || total_memory + new_size * sizeof(geometry_t) > max_memory) {
            printf("Memory allocation failed!\n");
            break;
        }
        total_memory += new_size - current_records;
        current_records = new_size;
        pthread_mutex_unlock(&mutex);
    }

    // Free allocated memory
    free(*records);
    free(*points);
    free(*geometries);

}

void initialize_records(int **records, size_t num_records) {
    for (size_t i = 0; i < num_records; i++) {
        (*records)[i] = rand();
    }
}

void initialize_points(point_t **points, size_t num_points) {
    for (size_t i = 0; i < num_points; i++) {
        (*points)[i].x = rand() % 100;
        (*points)[i].y = rand() % 100;
    }
}

void initialize_geometries(geometry_t **geometries, size_t num_geometries) {
    for (size_t i = 0; i < num_geometries; i++) {
        (*geometries)[i].value = (double)rand() / RAND_MAX;
        (*geometries)[i].coord = &(*points)[i];
    }
}

void free_memory(int **records, point_t **points, geometry_t **geometries) {
    free(*records);
    free(*points);
