#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define LOG_BUFFER_SIZE 1000
#define TIMESTAMP_LENGTH 20

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} log_level_t;

typedef struct {
    uint64_t timestamp;
    int level;
    char message[TIMESTAMP_LENGTH];
} log_entry_t;

// Function to initialize and allocate memory for the logging module
int init_logging_module(log_entry_t **log_entries, FILE **fp) {
    *log_entries = (log_entry_t *)malloc(LOG_BUFFER_SIZE * sizeof(log_entry_t));
    if (*log_entries == NULL) {
        return -1; // Allocation failed
    }

    *fp = fopen("log.txt", "w");
    if (*fp == NULL) {
        free(*log_entries);
        *log_entries = NULL;
        return -1; // File opening failed
    }

    return 0; // Initialization successful
}

// Function to log a message and update the timestamp
int log_message(log_entry_t **log_entries, FILE *fp, int level, const char *message) {
    if (!(*log_entries)) {
        return -1; // Log buffer is full
    }

    // Update timestamp
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    char timestamp_str[TIMESTAMP_LENGTH];
    strftime(timestamp_str, TIMESTAMP_LENGTH, "%Y-%m-%d %H:%M:%S", time_info);

    log_entry_t *new_log_entry = (*log_entries)++;
    new_log_entry->timestamp = current_time;
    new_log_entry->level = level;
    strcpy(new_log_entry->message, message);

    // Write log entry to file
    fprintf(fp, "%s - %d: %s\n", timestamp_str, level, message);

    return 0; // Logging successful
}

// Function to flush the log buffer to an external file
int flush_log_buffer(log_entry_t **log_entries, FILE *fp) {
    if (!(*log_entries)) {
        return -1; // Log buffer is empty
    }

    while (*log_entries > log_entries + LOG_BUFFER_SIZE) {
        log_entry_t *current_log_entry = *log_entries;
        fprintf(fp, "\n");
        *log_entries = current_log_entry + 1;
    }

    return 0; // Flushing successful
}

// Function to deallocate memory for the logging module
int clean_up_logging_module(log_entry_t **log_entries, FILE *fp) {
    if (*log_entries) {
        free(*log_entries);
        *log_entries = NULL;
    }

    fclose(fp);

    return 0; // Clean-up successful
}

// Function to log memory statistics
void log_memory_stats(uint64_t total_allocated_memory, uint64_t current_usage) {
    printf("Total allocated memory: %llu MB\n", (total_allocated_memory / (1024 * 1024)));
    printf("Current usage: %llu KB\n", (current_usage / 1024));
}

int main() {
    log_entry_t *log_entries;
    FILE *fp;

    int init_status = init_logging_module(&log_entries, &fp);
    if (init_status < 0) {
        printf("Initialization failed.\n");
        return -1;
    }

    // Example usage
    for (int i = 0; i < 10; i++) {
        log_message(&log_entries, fp, INFO, "Hello World!");
    }

    flush_log_buffer(&log_entries, fp);

    int clean_up_status = clean_up_logging_module(&log_entries, fp);
    if (clean_up_status < 0) {
        printf("Clean-up failed.\n");
        return -1;
    }

    log_memory_stats(total_allocated_memory, current_usage);

    return 0; // Successful execution
}
