size_t array_size = 0;

void* allocate_memory(void* arg) {
    size_t required = *(size_t*)arg;
    if (required > MAX_MEMORY - (array_size + RECORD_SIZE)) {
        // Log allocation failure due to exceeding the maximum memory limit
        printf("Failed to allocate %zu bytes, exceeded maximum memory limit.\n", required);
        return NULL;
    }

    record_t* new_array = realloc(array, (array_size + required) * RECORD_SIZE);
    if (!new_array) {
        // Log allocation failure due to insufficient memory
        printf("Failed to allocate %zu bytes, insufficient memory available.\n", required);
        return NULL;
    }

    array = new_array;
    array_size += required;

    return array + array_size - required;
}

void free_memory() {
    free(array);
    array = NULL;
    array_size = 0;
