Here is the JavaScript code for copying a specified number of bytes from a list of buffered data chunks:

```javascript
function copyBytes(chunks, numBytes) {
    if (!chunks || !numBytes) return Buffer.allocUnsafe(0);

    const buffer = Buffer.allocUnsafe(numBytes);
    let offset = 0;
    for (const chunk of chunks) {
        const bytesCopied = Math.min(numBytes - offset, chunk.length);
        chunk.copy(buffer, offset, offset + bytesCopied);
        offset += bytesCopied;
        if (offset >= numBytes) break;
    }
    return buffer;
}
```

