    node_list* head = (node_list*)malloc(sizeof(node_list));
    if (!head) return NULL; // insufficient memory
    head->num_nodes = num_nodes;
    head->last_node = last_node;
    head->protocol = "TCP";
    head->port = 8080;
    head->data = malloc(1024);
    head->next = NULL;
    return head;
}

void add_vertex(int num_vertices, distributed_system* sys) {
    // create new vertex
    node_list* new_vertex = (node_list*)malloc(sizeof(node_list));
    if (!new_vertex) return; // insufficient memory
    new_vertex->node_id = rand() % 1000;
    new_vertex->protocol = "TCP";
    new_vertex->port = 8081;
    new_vertex->data = malloc(1024);
    new_vertex->next = NULL;

    // add vertex to existing list
    node_list* current = sys->head;
    while (current) {
        if (current->num_vertices >= num_vertices) break;
        current->next = new_vertex;
        current = current->next;
    }
}

