And here is the validation function that checks if the sum of all records' int values is within the specified limit:

```c
int validateRecords(record** records, int maxRecords) {
    int totalValue = 0;
    for (int i = 0; i < maxRecords; i++) {
        totalValue += records[i]->value;
    }

    if (totalValue > 1000) {
        // reallocate and adjust the records to ensure the sum is valid
        record** newRecords = initArrays(maxRecords);
        for (int i = 0; i < maxRecords; i++) {
            int value = rand() % ((1000-totalValue+10) / (maxRecords-1)) - 5;
            newRecords[i]->value = value;
            totalValue += value;
        }

        // free the old records
        for (int i = 0; i < maxRecords; i++) {
            free(records[i]);
        }
        free(records);

        return validateRecords(newRecords, maxRecords);
    } else {
        return totalValue;
    }
}
