void initializeSensorData(sensorData **data, size_t numRecords, long startTimestamp, double minReading, double maxReading) {
    *data = (sensorData *)malloc(numRecords * sizeof(sensorData));

    for(size_t i = 0; i < numRecords; i++) {
        (*data)[i].timestamp = startTimestamp + i;

        // Initialize sensor reading within given range and ensure even distribution
        double range = maxReading - minReading;
        double increment = range / (numRecords - 1);
        double readingValue = minReading + (increment * i);
        (*data)[i].reading = fmod(readingValue, 0.01) + 0.005; // avoid overflow and even distribution
    }
}
