```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    long timestamp;
    double reading;
} sensorData;

void initializeSensorData(sensorData **data, size_t numRecords, long startTimestamp, double minReading, double maxReading) {
    *data = (sensorData *)malloc(numRecords * sizeof(sensorData));

    for(size_t i = 0; i < numRecords; i++) {
        (*data)[i].timestamp = startTimestamp + i;
        (*data)[i].reading = minReading + (maxReading - minReading) * ((double)i / (numRecords - 1));
    }
}

void readSensorDataFromFile(sensorData **data, const char *filename) {
    FILE *file = fopen(filename, "r");
    if(file == NULL) {
        printf("Error opening file.\n");
        return;
    }

    size_t numRecords = 0;
    while(fscanf(file, "%ld, %lf\n", &((*data)[numRecords].timestamp), &((*data)[numRecords].reading)) == 2) {
        numRecords++;
    }

    fclose(file);

    *data = (sensorData *)realloc(*data, numRecords * sizeof(sensorData));
}

void updateSensorData(sensorData *data, size_t numRecords, long newTimestamp, double newReading) {
    if(numRecords > 0) {
        sensorData *newData = (sensorData *)malloc((numRecords + 1) * sizeof(sensorData));

        for(size_t i = 0; i < numRecords; i++) {
            newData[i].timestamp = data[i].timestamp;
            newData[i].reading = data[i].reading;
        }

        newData[numRecords].timestamp = newTimestamp;
        newData[numRecords].reading = newReading;

        free(data);
        *data = newData;
    } else {
        sensorData *newData = (sensorData *)malloc(1 * sizeof(sensorData));

        newData[0].timestamp = newTimestamp;
        newData[0].reading = newReading;

        free(*data);
        *data = newData;
    }
}
```']

