// Define the maximum limit for the sum of records' int values
#define SUM_LIMIT 5000

// Define the maximum limit for memory allocation
#define MEMORY_LIMIT (1024 * 1024) // 1MB

// Define the record structure
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Function to initialize and allocate arrays and records
void* initArraysAndRecords(size_t size) {
    // Check if memory allocation would exceed the limit
    if (size > MEMORY_LIMIT) {
        printf("Memory allocation exceeds the limit. Exiting.\n");
        return NULL;
    }

    // Allocate memory for offsets, keys, and records arrays
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed. Exiting.\n");
        return NULL;
    }

    // Initialize arrays and records
    Record* records = (Record*)ptr;
    long* offsets = (long*)((char*)records + size);
    int* keys = (int*)((char*)offsets + sizeof(long) * 1001);

    // Initialize offsets array with values ranging from 0 to 1000, inclusive
    for (size_t i = 0; i < 1001; i++) {
        offsets[i] = i;
    }

    // Initialize keys array with unique values from 1 to 500, inclusive
    srand(time(NULL));
    for (size_t i = 0; i < 501; i++) {
        keys[i] = rand() % 500 + 1;
    }

    // Initialize records and set their int values randomly within the range of the corresponding key's value plus or minus 50 (inclusive)
    for (size_t i = 0; i < 1001; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i % 501]; // Ensure unique keys
        records[i].value = rand() % (keys[i % 501] + 50) + (-keys[i % 501] + 50);
    }

    return ptr;
}

// Function to validate the sum of all records' int values and adjust if necessary
void validateSum(void* ptr, size_t size) {
    Record* records = (Record*)ptr;
    long sum = 0;

    // Calculate the sum of all records' int values
    for (size_t i = 0; i < 1001; i++) {
        sum += records[i].value;
    }

    if (sum > SUM_LIMIT) {
        // Reallocate memory and adjust records to ensure the sum is valid without altering the initial constraints
        size_t newSize = size * 2; // Double the original size for adjustment
        void* newPtr = realloc(ptr, newSize);
        if (!newPtr) {
            printf("Memory reallocation failed. Exiting.\n");
            return;
        }

        Record* newRecords = (Record*)newPtr;
        long* newOffsets = (long*)((char*)newRecords + newSize);
        int* newKeys = (int*)((char*)newOffsets + sizeof(long) * 1001);

        // Initialize new records and set their int values randomly within the range of the corresponding key's value plus or minus 50 (inclusive)
        for (size_t i = 0; i < 1001; i++) {
            newRecords[i].offset = offsets[i];
            newRecords[i].key = keys[i % 501]; // Ensure unique keys
            newRecords[i].value = rand() % (keys[i % 501] + 50) + (-keys[i % 501] + 50);
        }

        // Copy adjusted records to the original memory block
        for (size_t i = 0; i < 1001; i++) {
            records[i].offset = newRecords[i].offset;
            records[i].key = newRecords[i].key;
            records[i].value = newRecords[i].value;
        }

        // Update the original memory block pointer
        ptr = newPtr;
    }
}

// Function to free all allocated memory when done
void freeMemory(void* ptr, size_t size) {
    if (ptr) {
        free(ptr);
    }
}
