    for(int i=0; i<50; i++) {
        keys[i] = i + 1;
    }

    // Allocate memory for records array and initialize records
    Record** records = (Record**)malloc(51 * sizeof(Record*));

    srand(time(NULL));  // Seed random number generator

    for(int i=0; i<50; i++) {
        Record* record = (Record*)malloc(sizeof(Record));

        // Set key and value for each record
        record->key = keys[i];
        record->value = rand() % (record->key + 11) - 10;

        records[i] = record;
    }

    // Function to validate the sum of all records' int values is within the specified limit
    int* recordValues = (int*)malloc(51 * sizeof(int));

    for(int i=0; i<50; i++) {
        recordValues[i] = records[i]->value;
    }

    int totalSum = 0;
    for(int i=0; i<50; i++) {
        totalSum += recordValues[i];
    }

    if(totalSum > 1000) {
        // Realocate and adjust the records to ensure the sum is valid
        int totalAdjustment = totalSum - 1000;

        for(int i=0; i<50; i++) {
            records[i]->value -= totalAdjustment / 50;
        }
    }

    // Free all allocated memory when done
