using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

public class DataRecord
{
    public int ID { get; set; }
    public string Name { get; set; }
    public DateTime Timestamp { get; set; }
}

public enum DeserializationMode
{
    Sequential,
    Parallel
}

public class FileDeserializer
{
    private readonly ILogger _logger;
    private readonly FileInfo _fileInfo;
    private readonly DeserializationMode _deserializationMode;

    public FileDeserializer(string filePath, Logger logger)
    {
        _fileInfo = new FileInfo(filePath);
        _logger = logger;
        _deserializationMode = GetDeserializationMode();
    }

    private DeserializationMode GetDeserializationMode()
    {
        // implement logic to determine deserialization mode
        return DeserializationMode.Sequential;
    }

    public async Task<List<DataRecord>> DeserializeAsync()
    {
        if (!_fileInfo.Exists)
        {
            _logger.LogError("File does not exist: {0}", _fileInfo.FullName);
            throw new FileNotFoundException();
        }

        List<DataRecord> dataRecords = new List<DataRecord>();

        using (FileStream fileStream = _fileInfo.OpenRead())
        {
            BinaryFormatter formatter = new BinaryFormatter();

            if (_deserializationMode == DeserializationMode.Parallel)
            {
                await ParallelDeserializeAsync(fileStream, formatter, dataRecords);
            }
            else
            {
                await SequentialDeserializeAsync(fileStream, formatter, dataRecords);
            }
        }

        return dataRecords;
    }

    private async Task ParallelDeserializeAsync(FileStream fileStream, BinaryFormatter formatter, List<DataRecord> dataRecords)
    {
        using (var reader = new BinaryReader(fileStream))
        {
            var tasks = new List<Task>();

            while (fileStream.Position < _fileInfo.Length)
            {
                byte[] buffer = new byte[1024];
                int bytesRead = reader.Read(buffer, 0, buffer.Length);

                if (bytesRead > 0)
                {
                    using (var memoryStream = new MemoryStream())
                    {
                        memoryStream.Write(buffer, 0, bytesRead);
                        memoryStream.Position = 0;

                        DataRecord dataRecord = (DataRecord)formatter.Deserialize(memoryStream);
                        dataRecords.Add(dataRecord);

                        Task.Run(() => LogDeserializationStatus(dataRecord)).Wait();
                    }
                }
            }
        }
    }

    private async Task SequentialDeserializeAsync(FileStream fileStream, BinaryFormatter formatter, List<DataRecord> dataRecords)
    {
        using (var reader = new BinaryReader(fileStream))
        {
            while (fileStream.Position < _fileInfo.Length)
            {
                byte[] buffer = new byte[1024];
                int bytesRead = reader.Read(buffer, 0, buffer.Length);

                if (bytesRead > 0)
                {
                    using (var memoryStream = new MemoryStream())
                    {
                        memoryStream.Write(buffer, 0, bytesRead);
                        memoryStream.Position = 0;

                        DataRecord dataRecord = (DataRecord)formatter.Deserialize(memoryStream);
                        dataRecords.Add(dataRecord);

                        await LogDeserializationStatus(dataRecord);
                    }
                }
            }
        }
    }

    private void LogDeserializationStatus(DataRecord dataRecord)
    {
        _logger.LogInformation("Deserialized {0} with ID {1} and Timestamp {2}", dataRecord.Name, dataRecord.ID, dataRecord.Timestamp);
    }
}

public interface ILogger
{
    void LogError(string message);
    void LogInformation(string message);
}
