    if (ptr == NULL || sizeof(shape) * n > max_memory) {
        return NULL;
    }
    shape** shapes = (shape**)malloc(n * sizeof(shape *));
    for (i = 0; i < n; i++) {
        shapes[i] = (shape*)malloc(sizeof(shape));
        shapes[i]->area = (double)(rand() / (RAND_MAX + 1.0)); // generate random area
    }
    free(ptr);
    return shapes;
}

point** init_points(int n, int max_memory) {
    int i;
    void* ptr = malloc(max_memory);
    if (ptr == NULL || sizeof(point) * n > max_memory) {
        return NULL;
    }
    point** points = (point**)malloc(n * sizeof(point *));
    for (i = 0; i < n; i++) {
        points[i] = (point*)malloc(sizeof(point));
        points[i]->x = (double)(rand() / (RAND_MAX + 1.0)); // generate random x
        points[i]->y = (double)(rand() / (RAND_MAX + 1.0)); // generate random y
    }
    free(ptr);
    return points;
}

double** init_doubles(int n, int max_memory) {
    int i;
    void* ptr = malloc(max_memory);
    if (ptr == NULL || sizeof(double) * n > max_memory) {
        return NULL;
    }
    double** doubles = (double**)malloc(n * sizeof(double *));
    for (i = 0; i < n; i++) {
        doubles[i] = (double*)malloc(sizeof(double));
        *doubles[i] = (double)(rand() / (RAND_MAX + 1.0)); // generate random double
    }
    free(ptr);
    return doubles;
}

void* init_arrays(int n, int max_memory) {
    point** points = init_points(n, max_memory);
    double** doubles = init_doubles(n, max_memory);
    shape** shapes = init_shapes(n, max_memory);
    // perform LAPACK operations
