    double A[10][10], B[10];
    for (int i = 0; i < n; i++) {
        dgesv(1, 1, &A[i][i], &B[i]);
    }
    // free allocated memory
    for (int i = 0; i < n; i++) {
        free(points[i]);
        free(doubles[i]);
        free(shapes[i]);
    }
    free(points);
    free(doubles);
    free(shapes);
    return NULL;
}

void* lapack_example(int max_memory) {
