void initializeList(Node** head, size_t maxMemory) {
    if (*head != NULL) return; // List already initialized
    srand(time(NULL)); // Seed random number generator

    double totalMemoryUsed = 0.0;
    *head = (Node*)malloc(sizeof(Node));
    (*head)->value = rand() % 100; // Initialize node value with a random int between 0 and 99
    strcpy((*head)->name, "Initial Node");
    (*head)->next = NULL;

    totalMemoryUsed += sizeof(Node);

    while (totalMemoryUsed < maxMemory) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->value = rand() % 100; // Initialize node value with a random int between 0 and 99
        strcpy(newNode->name, "Random Node");
        newNode->next = (*head);
        (*head) = newNode;

        totalMemoryUsed += sizeof(Node);
    }

    // Traverse the list to print all node values.
    for (Node* current = *head; current != NULL; current = current->next) {
        printf("Value: %d, Name: %s\n", current->value, current->name);
    }
}

void cleanUp(Node** head) {
    while (*head != NULL) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}
