struct Node {
    int value;
    char data[256];
    struct Node* next;
};

struct Record {
    double value;
    struct Node* node;
};

void manageMemory(int max_limit, FILE* csv_file) {
    // Initialize memory management
    size_t allocated_size = 0;
    size_t used_size = 0;
    struct Record* head = NULL;

    // Read initial values from CSV file
    char line[256];
    while (fgets(line, sizeof(line), csv_file)) {
        struct Record* record = malloc(sizeof(struct Record));
        record->value = atof(strtok(line, ","));
        record->node = NULL; // Initialize node pointer

        // Insert record into linked list if within memory limit
        if (used_size + sizeof(struct Record) <= max_limit && !head) {
            head = record;
        } else if (record->value != 0.0) { // Handle missing data
            printf("Memory exceeded; skipping record.\n");
        }

        allocated_size += sizeof(struct Record);
    }

    fclose(csv_file);

    // Generate random values for double field
    int num_records = 100;
    struct Record* records = malloc(num_records * sizeof(struct Record));
    for (int i = 0; i < num_records; i++) {
        records[i].value = (double)rand() / RAND_MAX;
        // Initialize node pointer to NULL
        records[i].node = NULL;

        allocated_size += sizeof(struct Record);
    }

    // Insert nodes into linked list
    struct Node* current_node = NULL;
    for (int i = 0; i < num_records; i++) {
        if (current_node) {
            current_node->next = malloc(sizeof(struct Node));
            current_node = current_node->next;
        } else {
            current_node = &records[i].node;
        }
        current_node->value = rand();
        strcpy(current_node->data, "Random Data");
    }

    // Traverse and print linked list
    struct Record* current_record = head;
    while (current_record) {
        printf("Record: %f, Node: %d, '%s'\n", current_record->value, current_record->node ? current_record->node->value : -1, current_record->node ? current_record->node->data : "NULL");
        current_record = current_record->next;
    }

    // Clean up memory resources
    while (current_record) {
        struct Record* temp = current_record;
        if (temp->node) {
            struct Node* node_temp = temp->node;
            while (node_temp) {
                struct Node* node_prev = node_temp;
                node_temp = node_temp->next;
                free(node_prev);
            }
        }
        free(temp);
        allocated_size -= sizeof(struct Record);
    }

    printf("Total memory usage: %zu bytes\n", allocated_size);
}
