#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define a structure for sensor data
typedef struct Sensor {
    char name[20];
    int value;
} Sensor;

// Define a structure for IoT system
typedef struct IoTSystem {
    int num_sensors;
    Sensor **sensors;
    int last_sensor;
} IoTSystem;

// Function to create and initialize a list of sensors in an IoT network
IoTSystem* create_iot_system(int num_sensors, IoTSystem* iot) {
    // Dynamically allocate memory for the sensor array
    IoTSystem* iot_system = (IoTSystem*)malloc(sizeof(IoTSystem));
    if (!iot_system) return NULL;

    // Initialize sensor array and last sensor index
    iot_system->num_sensors = num_sensors;
    iot_system->sensors = (Sensor**)malloc(num_sensors * sizeof(Sensor*));
    for (int i = 0; i < num_sensors; i++) {
        iot_system->sensors[i] = (Sensor*)malloc(sizeof(Sensor));
        strcpy(iot_system->sensors[i]->name, "Sensor");
        iot_system->sensors[i]->value = rand() % 100;
    }
    iot_system->last_sensor = num_sensors - 1;

    return iot_system;
}

// Function to add devices and channels to the IoT system
void add_devices(IoTSystem* iot, int num_devices, int num_channels) {
    // Dynamically allocate memory for new devices and channels
    Sensor** devices = (Sensor**)malloc(num_devices * sizeof(Sensor*));
    for (int i = 0; i < num_devices; i++) {
        devices[i] = (Sensor*)malloc(sizeof(Sensor));
        strcpy(devices[i]->name, "Device");
        devices[i]->value = rand() % 100;
    }

    // Dynamically allocate memory for new channels
    Sensor** channels = (Sensor**)malloc(num_channels * sizeof(Sensor*));
    for (int i = 0; i < num_channels; i++) {
        channels[i] = (Sensor*)malloc(sizeof(Sensor));
        strcpy(channels[i]->name, "Channel");
        channels[i]->value = rand() % 100;
    }

    // Add devices and channels to the IoT system
    for (int i = 0; i < num_devices; i++) {
        iot->sensors[i]->value += devices[i]->value;
    }
    for (int i = 0; i < num_channels; i++) {
        iot->sensors[i]->value += channels[i]->value;
    }
}

// Function to free allocated memory
void free_iot_system(IoTSystem* iot) {
    // Free sensor array and each sensor structure
    for (int i = 0; i < iot->num_sensors; i++) {
        free(iot->sensors[i]);
    }
    free(iot->sensors);

    // Free IoT system structure
    free(iot);
}

int main() {
    // Create an IoT system with 5 sensors
    IoTSystem* iot = create_iot_system(5, NULL);

    // Add devices and channels to the IoT system
    add_devices(iot, 2, 3);

    // Periodically log resource usage statistics
    printf("Resource usage: %d MB\n", (iot->num_sensors * sizeof(Sensor) + sizeof(IoTSystem)) / 1024);
    sleep(1);

    // Free allocated memory
    free_iot_system(iot);

    return 0;
}

