#include <pthread.h>

struct node_list {
    int* nodes;
    int num_nodes;
    struct sockaddr_in* protocols;
    int last_node;
};

node_list* create_node_list(int* nodes, int num_nodes, struct sockaddr_in** protocols, int last_node) {
    node_list* list = (node_list*)malloc(sizeof(node_list));
    if (!list) return NULL;

    list->nodes = (int*)malloc(num_nodes * sizeof(int));
    if (!list->nodes) {
        free(list);
        return NULL;
    }
    memcpy(list->nodes, nodes, num_nodes * sizeof(int));

    list->num_nodes = num_nodes;
    list->protocols = (struct sockaddr_in*)malloc((last_node + 1) * sizeof(struct sockaddr_in));
    if (!list->protocols) {
        free(list->nodes);
        free(list);
        return NULL;
    }
    for (int i = 0; i <= last_node; i++) {
        list->protocols[i].sin_family = AF_INET;
        inet_pton(AF_INET, "127.0.0.1", &list->protocols[i]);
    }

    list->last_node = last_node;

    return list;
}

void free_node_list(node_list* list) {
    if (!list) return;
    free(list->nodes);
    free(list->protocols);
    free(list);
}

int main() {
    int nodes[] = {1, 2, 3};
    node_list* list = create_node_list(nodes, sizeof(nodes) / sizeof(nodes[0]), NULL, 3);
    if (!list) {
        printf("Error allocating memory!\n");
        return 1;
    }

    // Initialize protocols
    int i;
    for (i = 0; i < 3; i++) {
        list->protocols[i].sin_port = htons(8080 + i);
    }
    list->last_node = i;

    // Start listening on all protocols
    pthread_t threads[3];
    for (i = 0; i < 3; i++) {
        pthread_create(&threads[i], NULL, listen_on_protocol, &list->protocols[i]);
    }

    // Wait for threads to finish
    for (i = 0; i < 3; i++) {
        pthread_join(threads[i], NULL);
    }

    free_node_list(list);

    return 0;
}

void* listen_on_protocol(void* arg) {
    struct sockaddr_in* protocol = arg;
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) return NULL;

    bind(sock, (struct sockaddr*)protocol, sizeof(struct sockaddr));
    listen(sock, 3);

    // Handle incoming connections
    while (1) {
        struct sockaddr_in client_addr;
        int client_sock = accept(sock, (struct sockaddr*)&client_addr, sizeof(client_addr));
        if (client_sock < 0) break;

        // Handle client connection
        close(client_sock);
    }

    return NULL;
}
