#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <zlib.h>

typedef struct {
    double value;
    char* string;
} Record;

Record* create_record(double value, const char* str) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->value = value;
    record->string = (char*)malloc(strlen(str)+1);
    strcpy(record->string, str);
    return record;
}

void encrypt_record(const Record* record, const char* key) {
    EVP_CIPHER_CTX ctx;
    EVP_EncryptInit_ex(&ctx, EVP_aes_256_cbc(), NULL, key, NULL);
    unsigned char encrypted[1024];
    int len = 0;
    EVP_EncryptUpdate(&ctx, (unsigned char*)record->string, strlen(record->string)+1, encrypted, 1024, &len);
