#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netinet/in.h>

struct node {
    int id;
    char* protocol;
};

// Function to dynamically allocate memory for and initialize a list of network nodes
struct node** create_node_list(int num_nodes, struct node*** last_node, struct sockaddr_in* addresses) {
    // Dynamically allocate memory for the node list
    *last_node = (struct node**)malloc((num_nodes + 1) * sizeof(struct node*));

    if (*last_node == NULL) {
        return NULL;
    }

    for (int i = 0; i <= num_nodes; i++) {
        // Initialize each node with a unique ID and protocol
        (*last_node)[i] = (struct node*)malloc(sizeof(struct node));
        (*(*last_node)[i]).id = i;
        strcpy((*(*last_node)[i]).protocol, "TCP");

        if (i < num_nodes) {
            // Initialize the socket address for each node except the last one
            addresses[i].sin_family = AF_INET;
            addresses[i].sin_port = htons(8080);
            inet_pton(AF_INET, "127.0.0.1", &addresses[i].sin_addr);
        }
    }

    return *last_node;
}

// Function to add vertices and edges to the graph
void add_to_graph(struct node** last_node, int num_vertices, int num_edges) {
    // Dynamically allocate memory for the graph
    struct edge* edges = (struct edge*)malloc(num_edges * sizeof(struct edge));
    struct vertex* vertices = (struct vertex*)malloc(num_vertices * sizeof(struct vertex));

    if (edges == NULL || vertices == NULL) {
        return;
    }

    // Initialize each edge with a random weight
    for (int i = 0; i < num_edges; i++) {
        edges[i].weight = rand() % 100;
    }

    // Initialize each vertex with a unique ID and random properties
    for (int i = 0; i < num_vertices; i++) {
        vertices[i].id = i;
        vertices[i].property = (char*)malloc(rand() % 10 * sizeof(char));

        if (vertices[i].property == NULL) {
            return;
        }

        // Set random properties on the vertex
        for (int j = 0; j < strlen(vertices[i].property); j++) {
            vertices[i].property[j] = (char)(rand() % 26 + 'a');
        }
    }

    // Add edges to the graph
    for (int i = 0; i < num_edges; i++) {
        // Randomly select two vertices and add an edge between them
        int vertex1 = rand() % num_vertices;
        int vertex2 = rand() % num_vertices;

        while (vertex1 == vertex2) {
            vertex2 = rand() % num_vertices;
        }

        edges[i].vertex1 = &vertices[vertex1];
        edges[i].vertex2 = &vertices[vertex2];
    }

    // Add vertices to the graph
    for (int i = 0; i < num_vertices; i++) {
        // Randomly select a node and add it to the graph
        int node_id = rand() % 10;

        while ((*last_node)[node_id] == NULL) {
            node_id = rand() % 10;
        }

        vertices[i].node = &(*last_node)[node_id];
    }
}

int main() {
    // Create a list of nodes
    int num_nodes = 5;
    struct node** last_node = (struct node**)malloc(sizeof(struct node));

    if (last_node == NULL) {
        return -1;
    }

    struct sockaddr_in* addresses = (struct sockaddr_in*)malloc(num_nodes * sizeof(struct sockaddr_in));

    // Initialize the list of nodes
    create_node_list(num_nodes, &last_node, addresses);

    // Add vertices and edges to the graph
    add_to_graph(last_node, 10, 20);

    return 0;
}
