void freeMemory(Shape **shapes, double **values, int numShapes) {
    for (int i = 0; i < numShapes; i++) {
        if (*shapes[i]->coords != NULL) {
            free((*shapes[i])->coords);
        }
        free(*shapes[i]);
    }
    free(*values);
}

Shape *initShapes(int maxShapes, int *maxMemoryUsage) {
    Shape *shapes = (Shape *)malloc(maxShapes * sizeof(Shape));
    if (shapes == NULL) {
        return NULL;
    }

    for (int i = 0; i < maxShapes; i++) {
        shapes[i].type = (rand() % (MAX_SHAPE_TYPE - 1)) + 1;
        shapes[i].coords = (Point *)malloc(sizeof(Point));
        if (shapes[i].coords == NULL) {
            freeMemory(&shapes, NULL, i);
            return NULL;
        }
        srand(time(NULL)); // To generate different random numbers for each shape
        shapes[i].coords->x = rand() % 1000;
        shapes[i].coords->y = rand() % 1000;

        if ((long int)(shapes[i].type) + (long int)(shapes[i].coords->x) + (long int)(shapes[i].coords->y) > *maxMemoryUsage) {
            freeMemory(&shapes, NULL, i);
            return NULL;
        }
    }

    *maxMemoryUsage += maxShapes * sizeof(Shape) + maxShapes * sizeof(Point);

    return shapes;
}

double **initValues(int maxShapes, int *maxMemoryUsage) {
    double *values = (double *)malloc(maxShapes * sizeof(double));
    if (values == NULL) {
        return NULL;
    }

    for (int i = 0; i < maxShapes; i++) {
        values[i] = (rand() % (MAX_DOUBLE - 1)) + 1.0;

        if ((long int)(values[i]) > *maxMemoryUsage) {
            free(values);
            return NULL;
        }
    }

    *maxMemoryUsage += maxShapes * sizeof(double);

    return &values;
}

int main() {
    int numShapes = 100; // number of shapes
    double maxMemoryUsage = 0.0;

    Shape *shapes = initShapes(numShapes, &maxMemoryUsage);
    if (shapes == NULL) {
        printf("Failed to initialize shapes.\n");
        return -1;
    }

    double **values = initValues(numShapes, &maxMemoryUsage);
