Record* initArrays(long offsetSize, long keySize, long dataSize, int minRange, int maxRange) {
    Record* records = NULL;
    long* offsets = NULL;
    int* keys = NULL;
    double* values = NULL;

    // Check for invalid input sizes
    if (offsetSize < 0 || keySize < 0 || dataSize < 0) {
        printf("Invalid size: offsetSize=%ld, keySize=%ld, dataSize=%ld\n", offsetSize, keySize, dataSize);
        return NULL;
    }

    // Allocate memory for arrays
    offsets = (long*)malloc(offsetSize * sizeof(long));
    if (offsets == NULL) {
        return NULL; // Allocation failed
    }

    keys = (int*)malloc(keySize * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        return NULL;
    }

    values = (double*)malloc(dataSize * sizeof(double));
    if (values == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize arrays with random values
    srand(time(NULL));
    for (long i = 0; i < offsetSize; i++) {
        offsets[i] = (rand() % ((maxRange - minRange) + 1)) + minRange;
    }

    for (long i = 0; i < keySize; i++) {
        keys[i] = (rand() % ((maxRange - minRange) + 1)) + minRange;
    }

    for (long i = 0; i < dataSize; i++) {
        values[i] = (double)(rand() % ((int)(maxRange - minRange) + 1)) / RAND_MAX * (maxRange - minRange) + minRange;
    }

    // Allocate memory for records and initialize with random data
    records = (Record*)malloc(dataSize * sizeof(Record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        free(values);
        return NULL; // Allocation failed
    }

    for (long i = 0; i < dataSize; i++) {
        records[i].offset = offsets[(i % offsetSize)];
        records[i].key = keys[(i % keySize)];
        records[i].value = values[i];
    }

    free(offsets);
    free(keys);
    free(values);

    return records;
}
