#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef struct {
    Record* data;
    int size;
    int capacity;
} Database;

int initDatabase(Database** db, int capacity) {
    *db = (Database*)malloc(sizeof(Database));
    if (*db == NULL)
        return -1; // Error: Memory allocation failed
    (*db)->data = (Record*)calloc(capacity, sizeof(Record));
    if ((*db)->data == NULL) {
        free(*db);
        return -2; // Error: Memory allocation failed
    }
    (*db)->size = 0;
    (*db)->capacity = capacity;
    return 0; // Success
}

int insertRecord(Database* db, long offset, int key, double value) {
    if (db->size >= db->capacity) {
        db->capacity *= 2;
        db->data = (Record*)realloc(db->data, db->capacity * sizeof(Record));
        if (db->data == NULL)
            return -1; // Error: Memory reallocation failed
    }
    Record* newRecord = (Record*)malloc(sizeof(Record));
    if (newRecord == NULL)
        return -2; // Error: Memory allocation failed
    newRecord->offset = offset;
    newRecord->key = key;
    newRecord->value = value;
    db->data[db->size] = *newRecord;
    free(newRecord);
    db->size++;
    return 0; // Success
}

int deleteRecord(Database* db, int key) {
    for (int i = 0; i < db->size; i++) {
        if (db->data[i].key == key) {
            Record* temp = &db->data[i];
            memmove(&db->data[i], &db->data[i + 1], sizeof(Record) * (db->size - i - 1));
            free(temp);
            db->size--;
            return 0; // Success
        }
    }
    return -1; // Error: Record not found
}

int sortDatabase(Database* db) {
    int n = db->size;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (db->data[i].key > db->data[j].key) {
                Record temp = db->data[i];
                db->data[i] = db->data[j];
                db->data[j] = temp;
            }
        }
    }
    return 0; // Success
}

int freeDatabase(Database* db) {
    for (int i = 0; i < db->size; i++) {
        free(&db->data[i]);
    }
    free(db->data);
    free(db);
    return 0; // Success
}
