#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Custom memory pool structure
typedef struct {
    void* mem;
    size_t size;
} MemPool;

// Record structure
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Function to initialize and populate the arrays
int initAndPopulateArrays(long*** offsets, int*** keys, double*** values, Record** records, int numRecords) {
    // Initialize memory pool
    MemPool* mp = (MemPool*)malloc(sizeof(MemPool));
    if (!mp) return -1;
    mp->mem = NULL;
    mp->size = 0;

    // Set up random number generator
    srand(time(NULL));

    // Allocate and initialize arrays using custom memory pool
    *offsets = (long**)mpool_alloc(mp, numRecords * sizeof(long*), "Offsets");
    if (!(*offsets)) return -1;
    for (int i = 0; i < numRecords; i++) {
        (*offsets)[i] = (long*)mpool_alloc(mp, sizeof(long), "Offset");
        if (!(*offsets)[i]) return -1;
        *((*offsets)[i]) = rand() % 10000;
    }

    *keys = (int**)mpool_alloc(mp, numRecords * sizeof(int*), "Keys");
    if (!(*keys)) return -1;
    for (int i = 0; i < numRecords; i++) {
        (*keys)[i] = (int*)mpool_alloc(mp, sizeof(int), "Key");
        if (!(*keys)[i]) return -1;
        *((*keys)[i]) = rand() % 10000;
    }

    *values = (double**)mpool_alloc(mp, numRecords * sizeof(double*), "Values");
    if (!(*values)) return -1;
    for (int i = 0; i < numRecords; i++) {
        (*values)[i] = (double*)mpool_alloc(mp, sizeof(double), "Value");
        if (!(*values)[i]) return -1;
        *((*values)[i]) = (double)rand() / RAND_MAX;
    }

    *records = (Record*)malloc(numRecords * sizeof(Record));
    if (!*records) return -1;
    for (int i = 0; i < numRecords; i++) {
        (*records)[i].offset = *((*offsets)[i]);
        (*records)[i].key = *((*keys)[i]);
        (*records)[i].value = *((*values)[i]);
    }

    return 0;
}

// Custom memory allocation function using the custom memory pool
void* mpool_alloc(MemPool* mp, size_t size, const char* name) {
    void* ret = NULL;

    // Check if we have enough space in the current block
    if (mp->size >= size) {
        ret = mp->mem;
        mp->mem += size;
        mp->size -= size;
    } else { // Need to allocate a new block
        void* new_mp = malloc(size + sizeof(void*) + 8); // Add some extra space for alignment and metadata
        if (!new_mp) return NULL;

        ((void**)new_mp)[0] = ret; // Store the address of the previous block
        ret = new_mp;
    }

    return ret;
}

// Custom memory deallocation function
void mpool_free(MemPool* mp, void* addr) {
    if (!addr) return;

    // Check if we have metadata at the start of the block
    void** meta = (void**)addr - 1;
    size_t size = *(size_t*)meta; // Get the size of the block

    // Free the block
    free(addr);

    mp->mem -= size;
    mp->size += size;

    // Remove metadata if we're freeing the last block in the pool
    if (!mp->mem) {
        free(mp);
    }
}
