    records = realloc(records, (num_records + 1) * RECORD_SIZE);
    if (!records) {
        printf("Memory reallocation failed\n");
        free(ptr);
        return NULL;
    }
    memcpy(&records[num_records], new_rec, size);
    num_records++;
    total_size += size;
    pthread_mutex_unlock(&mutex);
    return ptr;
}

void free_records() {
    for (int i = 0; i < num_records; i++) {
        free((void*) &records[i]);
    }
    free(records);
    records = NULL;
    num_records = 0;
    total_size = 0;
}

int validate_memory_usage() {
    return total_size <= MAX_MEMORY;
