        int_arr = (int64_t *)malloc(sizeof(int64_t) * count);
        if (int_arr == NULL) {
            fprintf(stderr, "Failed to allocate integer array.\n");
            goto free_and_exit;
        }

        // Initialize the integer array with random values
        size_t i;
        for (i = 0; i < count; i++) {
            int_arr[i] = (int64_t)rand() % RANDOM_RANGE;
        }

        // Allocate memory for uint32_t array
        uint_arr = (uint32_t *)malloc(sizeof(uint32_t) * count);
        if (uint_arr == NULL) {
            fprintf(stderr, "Failed to allocate uint32_t array.\n");
            goto free_and_exit;
        }

        // Allocate memory for record structures
        records = (record *)malloc(sizeof(record) * count);
        if (records == NULL) {
            fprintf(stderr, "Failed to allocate record array.\n");
            goto free_and_exit;
        }

        // Initialize string pointers
        str_arr = (char **)malloc(sizeof(char *) * count);
        if (str_arr == NULL) {
            fprintf(stderr, "Failed to allocate string pointer array.\n");
            goto free_and_exit;
        }

        pthread_mutex_unlock(mutex);

    } else {
        pthread_mutex_unlock(mutex);
    }

free_and_exit:
    // Free allocated memory
    if (int_arr != NULL) {
        free(int_arr);
    }
    if (uint_arr != NULL) {
        free(uint_arr);
    }
    if (records != NULL) {
        free_records(&records, mutex, count);
    }
    if (str_arr != NULL) {
        size_t i;
        for (i = 0; i < count; i++) {
            if (str_arr[i] != NULL) {
                free(str_arr[i]);
            }
        }
        free(str_arr);
    }

    return records;
}

void free_records(record **records, pthread_mutex_t *mutex, size_t count) {
    // Free allocated memory
    size_t i;
    for (i = 0; i < count; i++) {
        if ((*records)[i].str != NULL) {
            free((*records)[i].str);
        }
    }

    free(*records);

    pthread_mutex_unlock(mutex);
}
