#define MAX_MEMORY 1024
#define RECORD_SIZE sizeof(record)

typedef struct {
    int value;
} record;

record* init_record(int size) {
    return (record*)malloc(size * RECORD_SIZE);
}

void free_records(record** records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i]);
    }
}

record** merge_sets(record** set1, record** set2, int* size1, int* size2) {
    int total_size = *size1 + *size2;
    record** merged_set = (record**)malloc((total_size+1)*sizeof(record*));

    for (int i = 0; i < *size1; i++) {
        memcpy(&merged_set[i], &set1[i], RECORD_SIZE);
    }
    for (int i = 0; i < *size2; i++) {
        merged_set[*size1+i] = set2[i];
    }

    free(set1);
    free(set2);
    return merged_set;
}

void serialize_sets(record** sets, int count) {
    FILE* file = fopen("data.bin", "wb");
    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < count; i++) {
        fwrite(&sets[i], RECORD_SIZE, 1, file);
    }
    fclose(file);
}

record** deserialize_sets() {
    record** sets = NULL;
    int set_count = 0;

    FILE* file = fopen("data.bin", "rb");
    if (file == NULL) {
        perror("Error opening file");
        return sets;
    }

    while (fread(&sets[set_count], RECORD_SIZE, 1, file) > 0) {
        set_count++;
    }

    fclose(file);
    sets = (record**)realloc(sets, (set_count+1)*sizeof(record*));
    for (int i = set_count; i > 0; i--) {
        free(&sets[i-1]);
    }
    return sets;
}

void* allocate_memory(void* arg) {
    int size = *(int*)arg;
    record** records = (record**)malloc((size+1)*sizeof(record*));

    for (int i = 0; i <= size; i++) {
        records[i] = init_record(1);
    }

    free(arg);
    return (void*)records;
}

void deallocate_memory(void* arg) {
    record** records = (record**)arg;
    int size = *(int*)records;

    for (int i = 0; i <= size; i++) {
        free(&records[i]);
    }

    free(records);
}
