void* mem_init(size_t max_size) {
    if (max_size == 0) return NULL;

    size_t offset_array_size = (max_size / sizeof(long)) + 1;
    long* offsets = (long*)malloc(offset_array_size * sizeof(long));
    if (!offsets) return NULL;

    size_t key_array_size = (max_size / sizeof(int)) + 1;
    int* keys = (int*)malloc(key_array_size * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    size_t record_array_size = max_size / sizeof(record_t) + 1;
    record_t* records = (record_t*)malloc(record_array_size * sizeof(record_t));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    for (size_t i = 0; i < offset_array_size; ++i) {
        offsets[i] = -1;
    }
    for (size_t i = 0; i < key_array_size; ++i) {
        keys[i] = -1;
    }

    return records;
}

void mem_free(void* ptr) {
    if (!ptr) return;

    free(ptr);
}

int mem_in_range(void* ptr, size_t max_size) {
    if (!ptr) return 0;

    size_t total_size = (size_t)(record_t*)ptr + sizeof(record_t);

    return total_size <= max_size;
}
