void initialize_data(long *offsets, int *keys, record **records, time_t *timestamps, size_t num_records, size_t name_length) {
    // Validate input parameters
    if (num_records == 0 || offsets == NULL || keys == NULL || records == NULL || timestamps == NULL) {
        return;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Allocate memory for offsets and keys arrays
    offsets = (long *)malloc(num_records * sizeof(long));
    keys = (int *)malloc(num_records * sizeof(int));
    if (offsets == NULL || keys == NULL) {
        return;
    }

    // Allocate memory for records array
    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        free(offsets);
        free(keys);
        return;
    }

    // Allocate memory for timestamps array
    *timestamps = (time_t *)malloc(num_records * sizeof(time_t));
    if (*timestamps == NULL) {
        free(offsets);
        free(keys);
        free(*records);
        return;
    }

    // Initialize arrays
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % 10000 + 1;
        keys[i] = rand() % 256;
        (*records)[i].value = rand() % 10 + 1;
        // Fill name with random characters
        for (size_t j = 0; j < name_length; ++j) {
            (*records)[i].name[j] = (char)(rand() % 128);
        }
        (*records)[i].name[name_length - 1] = '\0';
    }

    // Validate array indices
    for (size_t i = 0; i < num_records; ++i) {
        if (offsets[i] > INT_MAX || keys[i] > INT_MAX) {
            free(offsets);
            free(keys);
            free(*records);
            free(*timestamps);
            return;
        }
    }
}
