#include "cJSON.h"

// Define the structure for products and orders
typedef struct {
    double price;
    int stockQuantity;
    char* productName;
} Product;

typedef struct {
    Product* product;
    int quantity;
    char* customerName;
} Order;

Product* createProductsFromJSON(const cJSON* json) {
    cJSON* products = json->child;
    int numProducts = 0;

    // Count the number of products
    while (products != NULL) {
        numProducts++;
        products = products->next;
    }

    Product* productArray = (Product*)malloc(numProducts * sizeof(Product));
    products = json->child;
    for (int i = 0; i < numProducts; i++) {
        cJSON* productJson = products->child;

        // Create a new Product structure
        Product* product = (Product*)malloc(sizeof(Product));
        product->price = productJson->valuedouble;
        product->stockQuantity = cJSON_GetValueInt(productJson, "stock_quantity");

        // Dynamically allocate memory for the product name and null-terminate it
        char* productName = malloc(strlen(productJson->valuestring) + 1);
        strcpy(productName, productJson->valuestring);
        product->productName = productName;

        productArray[i] = *product;

        products = products->next;
    }

    return productArray;
}

Order* createOrdersFromProducts(Product* products, int numProducts) {
    Order* orderArray = (Order*)malloc(numProducts * sizeof(Order));
    for (int i = 0; i < numProducts; i++) {
        // Create a new Order structure
        Order* order = (Order*)malloc(sizeof(Order));

        // Randomly generate quantity and customer name
        int quantity = rand() % 10 + 1;
        char* customerName = malloc(16);
        sprintf(customerName, "Customer-%d", i);

        // Dynamically allocate memory for the product name and null-terminate it
        order->product = &products[i];
        order->quantity = quantity;
        order->customerName = customerName;

        orderArray[i] = *order;
    }

    return orderArray;
}

int main() {
    cJSON* json = cJSON_ParseFile("products.json");
    Product* products = createProductsFromJSON(json);
    int numProducts = cJSON_GetArraySize(json, "products");

    Order* orders = createOrdersFromProducts(products, numProducts);

    // Free dynamically allocated memory
    for (int i = 0; i < numProducts; i++) {
        free(orders[i].customerName);
        free(orders[i].product->productName);
        free(&orders[i]);
    }
    free(orders);
    for (int i = 0; i < numProducts; i++) {
        free(products[i].productName);
        free(&products[i]);
    }
    free(products);

    cJSON_Delete(json);

    return 0;
}
```']

