Record* records = NULL;
int num_records = 0;
int record_capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initRecords(int size) {
    if (size <= 0) return;

    // Initialize thread-local storage
    pthread_cleanup_push((void*)freeRecords);
    pthread_setspecific(NULL, &records);

    // Dynamic memory allocation and initialization
    records = malloc(size * sizeof(Record));
    record_capacity = size;

    // Check for memory allocation failure
    if (records == NULL) {
        printf("Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

void freeRecords(void* ptr) {
    free(ptr);
    pthread_setspecific(NULL, NULL);
}

void addRecord(int key, long offset) {
    pthread_mutex_lock(&mutex);

    // Check for valid input parameters
    if (key < 0 || offset < 0) {
        printf("Error: Invalid record values.\n");
        return;
    }

    // Dynamic memory allocation and initialization for new records
    if (num_records == record_capacity) {
        int new_size = record_capacity * 2 + 1; // Double the capacity
        Record* temp = malloc(new_size * sizeof(Record));
        memcpy(temp, records, record_capacity * sizeof(Record));
        free(records);
        records = temp;
        record_capacity = new_size;
    }

    // Add a new record to the collection
    Record* new_record = &records[num_records++];
    new_record->key = key;
    new_record->offset = offset;

    pthread_mutex_unlock(&mutex);
}

void updateRecord(int key, long offset) {
    pthread_mutex_lock(&mutex);

    // Find and update the record with the given key
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            records[i].offset = offset;
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}

void retrieveRecord(int key, long* offset) {
    pthread_mutex_lock(&mutex);

    // Find and retrieve the record with the given key
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            *offset = records[i].offset;
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}

void freeRecords(void* ptr) {
    free(ptr);
    pthread_setspecific(NULL, NULL);
}

int main() {
    // Initialize the record collection
    initRecords(10);

    // Add and update records concurrently from multiple threads
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, (void*)add_update_records, NULL);
    }
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    // Retrieve and update records concurrently from multiple threads
    pthread_t threads2[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads2[i], NULL, (void*)retrieve_update_records, NULL);
    }
    for (int i = 0; i < 4; i++) {
        pthread_join(threads2[i], NULL);
    }

    // Free allocated memory
    freeRecords(records);

    return 0;
}

void* add_update_records(void* ptr) {
    // Add and update records concurrently from multiple threads
    for (int i = 0; i < 10; i++) {
        int key = rand() % 100;
        long offset = rand();
        addRecord(key, offset);
        sleep(1); // Simulate concurrent access
        updateRecord(key, offset + 1);
    }
    return NULL;
}

void* retrieve_update_records(void* ptr) {
    // Retrieve and update records concurrently from multiple threads
    for (int i = 0; i < 10; i++) {
        int key = rand() % 100;
        long offset;
        retrieveRecord(key, &offset);
        sleep(1); // Simulate concurrent access
        updateRecord(key, offset + 1);
    }
    return NULL;
}
