#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY 1000000
#define MAX_RECORDS 10000
#define KEY_RANGE 10
#define RECORD_VALUE_RANGE 1000
#define STRING_LENGTH 20

typedef struct {
    int value;
    char* str;
} record;

record* records = NULL;
long* offsets = NULL;
int* keys = NULL;
char** strings = NULL;

void init_data_sets(int num_data_sets) {
    for (int i = 0; i < num_data_sets; i++) {
        if (!records) {
            records = malloc(sizeof(record) * MAX_RECORDS);
            if (!records) {
                printf("Memory allocation failed\n");
                exit(-1);
            }
        }
        if (!offsets) {
            offsets = malloc(sizeof(long) * MAX_RECORDS);
            if (!offsets) {
                printf("Memory allocation failed\n");
                exit(-1);
            }
        }
        if (!keys) {
            keys = malloc(sizeof(int) * MAX_RECORDS);
            if (!keys) {
                printf("Memory allocation failed\n");
                exit(-1);
            }
        }
        for (int j = 0; j < MAX_RECORDS; j++) {
            offsets[j] = j;
            keys[j] = rand() % KEY_RANGE;
            records[j].value = rand() % RECORD_VALUE_RANGE;
            char key_str[STRING_LENGTH];
            sprintf(key_str, "%d", keys[j]);
            char offset_str[STRING_LENGTH];
            sprintf(offset_str, "%ld", offsets[j]);
            size_t len = strlen(key_str) + strlen(offset_str) + 1;
            strings[j] = malloc(len);
            if (!strings[j]) {
                printf("Memory allocation failed\n");
                exit(-1);
            }
            sprintf(strings[j], "%s_%s", key_str, offset_str);
        }
    }
}

void merge_data_sets(record* records1, int num_records1,
                         record* records2, int num_records2) {
    if (!records) {
        records = malloc(sizeof(record) * (num_records1 + num_records2));
        if (!records) {
            printf("Memory allocation failed\n");
            exit(-1);
        }
    }
    for (int i = 0; i < num_records1; i++) {
        records[i].value = records1[i].value;
        strcpy(records[i].str, strings[i]);
    }
    for (int i = num_records1; i < num_records2 + num_records1; i++) {
        records[i].value = records2[i - num_records1].value;
        strcpy(records[i].str, strings[i - num_records1]);
    }
}

void serialize_data_set(char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Error opening file\n");
        exit(-1);
    }
    for (int i = 0; i < MAX_RECORDS; i++) {
        fwrite(&records[i], sizeof(record), 1, file);
    }
    fclose(file);
}

void deserialize_data_set(char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file\n");
        exit(-1);
    }
    for (int i = 0; i < MAX_RECORDS; i++) {
        fread(&records[i], sizeof(record), 1, file);
    }
    fclose(file);
}

void free_memory() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (strings[i]) {
            free(strings[i]);
        }
    }
    free(records);
    free(offsets);
    free(keys);
}
```']

