// Function to dynamically allocate memory for and initialize a list of sensor nodes
SmartGrid* create_smart_grid(int num_nodes, int last_node) {
    // Dynamically allocate memory for the smart grid system structure
    SmartGrid* smart_grid = (SmartGrid*)malloc(sizeof(SmartGrid));

    // Set the number of devices in the smart grid system
    smart_grid->num_devices = 0;
    smart_grid->max_num_devices = last_node + 1;

    // Dynamically allocate memory for the device list and initialize it with all zeros
    smart_grid->devices = (SensorNode*)malloc((last_node + 1) * sizeof(SensorNode));

    // Initialize the add_device and update_config methods
    smart_grid->add_device = NULL;
    smart_grid->update_config = NULL;

    return smart_grid;
}

// Example implementation of adding a device to the smart grid system
void add_device(SmartGrid* smart_grid, int node_id, char* name, int configuration) {
    // Check if the maximum number of devices has been reached
    if (smart_grid->num_devices >= smart_grid->max_num_devices) {
        return;
    }

    // Set the device properties
    SensorNode* device = &smart_grid->devices[node_id];
    device->id = node_id;
    strcpy(device->name, name);
    device->configuration = configuration;

    // Increment the number of devices in the smart grid system
    smart_grid->num_devices++;
}

// Example implementation of updating a device's configuration in the smart grid system
void update_config(SmartGrid* smart_grid, int node_id, int new_config) {
    // Check if the device exists in the smart grid system
    if (node_id >= smart_grid->max_num_devices || smart_grid->devices[node_id].id == 0) {
        return;
    }

    // Update the device's configuration
    SensorNode* device = &smart_grid->devices[node_id];
    device->configuration = new_config;
}
