        strcpy(record->string, buffer);

        // Update the total memory usage and add the current record to the array
        totalMemory += recordMemory;
        records[i] = record;
    }

    return records;
}

// Function to free all allocated memory when done
void freeRecords(Record** records, size_t numRecords) {
    for (size_t i = 0; i < numRecords; i++) {
        if (records[i]) {
            free(records[i]->string);
            free(records[i]);
        }
    }
    free(records);
}

// Function to periodically check and log resource usage statistics
void logResourceUsage(size_t totalMemory) {
    printf("Peak memory usage: %zu bytes\n", totalMemory);
