        // Free allocated memory
        free_memory(doubles, indices, nodes);
    }

    return 0;
}

int init_arrays_from_file(char* filename, double** doubles_ref, int** indices_ref, Node*** nodes_ref) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filename);
        return -1;
    }

    // Read data from file and initialize arrays
    int count = 0;
    while (!feof(file)) {
        double val1;
        int val2;
        Node* node;

        fscanf(file, "%lf %d %p", &val1, &val2, (void**)&node);
        if (ferror(file) != 0 || feof(file) == 1) break;

        // Check for invalid data
        if (val1 > 100.0 || val2 < 0 || node->value < -100 || node->next != NULL) {
            printf("Invalid data in file: %s\n", filename);
            fclose(file);
            return -1;
        }

        *doubles_ref = realloc(*doubles_ref, (count + 1) * sizeof(double));
        *indices_ref = realloc(*indices_ref, (count + 1) * sizeof(int));
        **nodes_ref = realloc(**nodes_ref, (count + 1) * sizeof(Node*));

        (*doubles_ref)[count] = val1;
        (*indices_ref)[count] = val2;
        (**nodes_ref)[count] = node;

        count++;
    }

    fclose(file);

    return count;
}

void insert_node(Node** head_ref, int new_value) {
    Node* new_node = create_node(new_value);
    if (*head_ref == NULL || (*head_ref)->value > new_value) {
        new_node->next = *head_ref;
        *head_ref = new_node;
    } else {
        Node* current = *head_ref;
        while (current->next != NULL && current->next->value < new_value) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

Node* create_node(int value) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        printf("Memory allocation failed\n");
        exit(-1);
    }

    node->value = value;
    node->next = NULL;

    return node;
}

void free_memory(double* doubles, int* indices, Node** nodes) {
    for (int i = 0; i < sizeof(indices) / sizeof(indices[0]); i++) {
        if ((*nodes)[i] != NULL) {
            Node* current = (*nodes)[i];
            while (current->next != NULL) {
                Node* next_node = current->next;
                free(current);
                current = next_node;
            }
            free(current);
        }
    }

    free(doubles);
    free(indices);
    for (int i = 0; i < sizeof(indices) / sizeof(indices[0]); i++) {
        if ((*nodes)[i] != NULL) {
            free((*nodes)[i]);
        }
    }
    free(nodes);
}

void print_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%d ", current->value);
        current = current->next;
    }

    printf("\n");
}
