#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 100

typedef struct Node {
    int value;
    struct Node* next;
} Node;

Node* head = NULL;
int size = 0;

void insert_node(int value) {
    if (!head) {
        head = (Node*)malloc(sizeof(Node));
        head->value = value;
        head->next = NULL;
        size = 1;
    } else {
        Node* temp = head;
        while (temp->next && temp->next->value < value)
            temp = temp->next;
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->value = value;
        new_node->next = temp->next;
        temp->next = new_node;
    }
}

void print_list_forward() {
    Node* temp = head;
    int i = 0;
    while (temp) {
        printf("Index: %d, Value: %d\n", i++, temp->value);
        temp = temp->next;
    }
}

void print_list_reverse() {
    if (!head)
        return;
    Node* temp = head;
    Node* prev = NULL;
    int i = 0;
    while (temp) {
        printf("Index: %d, Value: %d\n", i++, temp->value);
        Node* next = temp->next;
        temp->next = prev;
        prev = temp;
        temp = next;
    }
}

void free_memory() {
    Node* temp = head;
    while (temp) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }
    head = NULL;
    size = 0;
}

int main() {
    int i;
    for (i = 1; i <= MAX_SIZE; i++) {
        insert_node(i);
    }

    printf("Forward List:\n");
    print_list_forward();

    printf("\nReverse List:\n");
    print_list_reverse();

    printf("\nFreeing Memory...\n");
    free_memory();

    return 0;
}
