typedef struct {
    int value;
} record;

record* create_record(int n) {
    record* arr = (record*)malloc(n * sizeof(record));
    for (int i = 0; i < n; i++) {
        arr[i].value = rand() % 100 + 1; // random value between 1-100
    }
    return arr;
}

void print_record(record* r, int n) {
    for (int i = 0; i < n; i++) {
        printf("%d ", r[i].value);
    }
    printf("\n");
}

// Function to calculate mean
double calc_mean(record* records, int n) {
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += records[i].value;
    }
    return sum / n;
}

// Function to calculate median
double calc_median(record* records, int n) {
    qsort(records, n, sizeof(record), compare_records);
    if (n % 2 == 0)
        return ((double)records[n/2-1].value + (double)records[n/2].value) / 2.0;
    else
        return (double)records[n/2].value;
}

int compare_records(const void *a, const void *b) {
    record* rec_a = (record*)a;
    record* rec_b = (record*)b;

    if (rec_a->value < rec_b->value)
        return -1;
    else if (rec_a->value > rec_b->value)
        return 1;
    else
        return 0;
}

// Function to calculate standard deviation
double calc_stddev(record* records, int n) {
    double mean = calc_mean(records, n);
    double sum = 0.0;

    for (int i = 0; i < n; i++) {
        sum += pow((records[i].value - mean), 2);
    }

    return sqrt(sum / n);
}

void print_statistic(record* records, int n) {
    printf("Mean: %.2f\n", calc_mean(records, n));
    printf("Median: %.2f\n", calc_median(records, n));
    printf("Standard Deviation: %.2f\n", calc_stddev(records, n));
}
