} custom_node;

node* head1 = NULL, *tail1 = NULL;
custom_node* head2 = NULL, *tail2 = NULL;

void free_memory() {
    node* temp = head1;
    while (temp != NULL) {
        node* next = temp->next;
        free(temp);
        temp = next;
    }
    tail1 = NULL;

    custom_node* temp2 = head2;
    while (temp2 != NULL) {
        custom_node* next2 = temp2->next;
        free(temp2);
        temp2 = next2;
    }
    tail2 = NULL;
}

node* insert_node(int value, node** head) {
    node* new_node = (node*)malloc(sizeof(node));
    new_node->value = value;
    new_node->next = *head;
    *head = new_node;
    return new_node;
}

custom_node* insert_custom_node(int value1, double value2, custom_node** head) {
    custom_node* new_node = (custom_node*)malloc(sizeof(custom_node));
    new_node->value = value1;
    new_node->value2 = value2;
    new_node->next = *head;
    *head = new_node;
    return new_node;
}

void print_list(node* head) {
    node* temp = head;
    while (temp != NULL) {
        printf("%d ", temp->value);
        temp = temp->next;
    }
    printf("\n");
}

node* insert_node_sorted(int value, node** head) {
    if (*head == NULL || value < (*head)->value) {
        return insert_node(value, head);
    }
    node* current = *head;
    while (current->next != NULL && current->next->value >= value) {
        current = current->next;
    }
    node* new_node = insert_node(value, &current->next);
    current->next = new_node;
    return *head;
}

custom_node* insert_custom_node_sorted(int value1, double value2, custom_node** head) {
    if (*head == NULL || value1 < ((*head)->value)) {
        return insert_custom_node(value1, value2, head);
    }
    custom_node* current = *head;
    while (current->next != NULL && current->next->value >= value1) {
        current = current->next;
    }
    custom_node* new_node = insert_custom_node(value1, value2, &current->next);
    current->next = new_node;
    return *head;
}

int main() {
    // Example usage
    node* head = NULL;
    for (int i = 0; i < 5; i++) {
        head = insert_node_sorted(i, &head);
    }
    print_list(head);

