// Define a record structure with int, float, and string fields
typedef struct {
    int offset;
    int key;
    float value;
    char* str;
    int metadata;
} Record;

// Function to dynamically allocate memory for arrays and initialize them
Record** initArrays(int maxRecords, long* offsets, int* keys, float* values, char** strs) {
    // Allocate memory for the arrays
    Record** records = (Record**)malloc(maxRecords * sizeof(Record*));
    if (!records) return NULL;

    for (int i = 0; i < maxRecords; i++) {
        // Initialize each record with random int value, float value, and string pointer
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            free(records);
            return NULL;
        }
        records[i]->offset = rand() % 1000;
        records[i]->key = rand() % 100;
        records[i]->value = (float)rand() / RAND_MAX;
        records[i]->str = strs[i];
        records[i]->metadata = i;
    }

    return records;
}

// Function to free allocated memory
void freeArrays(Record** records, int maxRecords) {
    for (int i = 0; i < maxRecords; i++) {
        if (records[i]) free(records[i]);
    }
    free(records);
}

// Function to persist records to disk using binary serialization
void serializeRecords(Record** records, int maxRecords, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    for (int i = 0; i < maxRecords; i++) {
        fwrite(&records[i]->offset, sizeof(int), 1, file);
        fwrite(&records[i]->key, sizeof(int), 1, file);
        fwrite(&records[i]->value, sizeof(float), 1, file);
        fwrite(records[i]->str, strlen(records[i]->str) + 1, 1, file);
        fwrite(&records[i]->metadata, sizeof(int), 1, file);
    }

    fclose(file);
}

// Function to load records from disk using binary deserialization
Record** deserializeRecords(const char* filename, int maxRecords) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    Record** records = (Record**)malloc(maxRecords * sizeof(Record*));
    for (int i = 0; i < maxRecords; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        fread(&records[i]->offset, sizeof(int), 1, file);
        fread(&records[i]->key, sizeof(int), 1, file);
        fread(&records[i]->value, sizeof(float), 1, file);
        char temp[1024];
        fread(temp, strlen(records[i]->str) + 1, 1, file);
        records[i]->str = (char*)malloc(strlen(temp) + 1);
        strcpy(records[i]->str, temp);
        fread(&records[i]->metadata, sizeof(int), 1, file);
    }

    fclose(file);
    return records;
}

int main() {
    // Initialize arrays and record structures
    int maxRecords = 1000;
    long* offsets = (long*)malloc(maxRecords * sizeof(long));
    int* keys = (int*)malloc(maxRecords * sizeof(int));
    float* values = (float*)malloc(maxRecords * sizeof(float));
    char** strs = (char**)malloc(maxRecords * sizeof(char*));

    // Initialize record structures with random data
    for (int i = 0; i < maxRecords; i++) {
        offsets[i] = rand() % 10000000;
        keys[i] = rand() % 10000;
        values[i] = (float)rand() / RAND_MAX;
        strs[i] = malloc(1024);
        sprintf(strs[i], "Record %d", i);
