void read_csv_data(char *filename, long **offsets, int **keys, double **values, data_point ***data_points) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    char line[1024];
    int offset_count = 0;

    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ",");
        long offset = atol(token);
        token = strtok(NULL, ",");
        int key = atoi(token);
        token = strtok(NULL, ",");
        double value = atof(token);

        // dynamically allocate memory for data_points array
        (*data_points)[offset_count] = (data_point *)malloc(sizeof(data_point));
        if ((*data_points)[offset_count] == NULL) {
            printf("Memory allocation failed\n");
            fclose(file);
            return;
        }

        (*data_points)[offset_count]->value = value;

        // dynamically allocate memory for string field with random length
        int str_len = rand() % 100 + 1;
        (*data_points)[offset_count]->string = (char *)malloc((str_len + 1) * sizeof(char));
        if ((*data_points)[offset_count]->string == NULL) {
            printf("Memory allocation failed\n");
            fclose(file);
            return;
        }
        // set random string value
        for (int i = 0; i < str_len; i++) {
            (*data_points)[offset_count]->string[i] = 'a' + rand() % 26;
        }
        (*data_points)[offset_count]->string[str_len] = '\0';

        offsets[offset_count] = &offset;
        keys[offset_count] = &key;

        offset_count++;
    }

    fclose(file);

    // set random value for each data point
    srand(time(NULL));
    for (int i = 0; i < offset_count; i++) {
        (*data_points)[i]->value = (double)rand() / RAND_MAX;
    }
}
