#include <time.h>
#include <sys/sysinfo.h>

#define LOG_FILE "log.txt"
#define CRITICAL_ERROR_THRESHOLD 0.5
#define MAX_RECORDS 1000000
#define MIN_OFFSET 0
#define MAX_OFFSET 999
#define TIMESTAMP_RESOLUTION 1000 // in milliseconds

void initializeData(int n, int seed) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", LOG_FILE);
        return;
    }

    srand(seed);

    int *offsets = (int *)malloc(n * sizeof(int));
    int *keys = (int *)malloc(n * sizeof(int));
    struct record **records = (struct record **)malloc(n * sizeof(struct record *));
    if (!offsets || !keys || !records) {
        syslog(LOG_ERR, "Memory allocation failed");
        free(offsets);
        free(keys);
        for (int i = 0; i < n; i++) {
            if (records[i]) {
                free(records[i]);
            }
        }
        free(records);
        return;
    }

    struct sysinfo si;
    getrlimit(RLIMIT_AS, &si);

    int total_memory = si.hugepages * si.hpage_size + si.filesize / 1024;
    if (n > (int)(total_memory * CRITICAL_ERROR_THRESHOLD)) {
        syslog(LOG_ERR, "Memory allocation exceeds 50% of system's available physical memory");
        free(offsets);
        free(keys);
        for (int i = 0; i < n; i++) {
            if (records[i]) {
                free(records[i]);
            }
        }
        free(records);
        return;
    }

    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % (MAX_OFFSET - MIN_OFFSET + 1) + MIN_OFFSET;
        keys[i] = rand() % (INT_MAX + 1);

        records[i] = (struct record *)malloc(sizeof(struct record));
        if (!records[i]) {
            syslog(LOG_ERR, "Memory allocation failed");
            for (int j = i; j >= 0; j--) {
                free(offsets[j]);
                free(keys[j]);
                if (records[j]) {
                    free(records[j]);
                }
            }
            free(offsets);
            free(keys);
            free(records);
            return;
        }

        records[i]->value = keys[i];
        records[i]->timestamp = time(NULL) * TIMESTAMP_RESOLUTION + rand() % TIMESTAMP_RESOLUTION;
    }

    for (int i = 0; i < n; i++) {
        fprintf(log_file, "Record %d: offset=%d, key=%d, timestamp=%lu\n", i, offsets[i], keys[i], records[i]->timestamp);
    }
    fclose(log_file);

    for (int i = 0; i < n; i++) {
        free(offsets[i]);
        free(keys[i]);
        if (records[i]) {
            free(records[i]);
        }
    }

    free(offsets);
    free(keys);
    free(records);
}

struct record {
    int value;
    unsigned long timestamp;
};
