// Define the maximum memory limit
#define MAX_MEMORY 1024 * 1024 * 5

// Define the record structure
typedef struct {
    int integer;
    double decimal;
    char* string;
} Record;

// Function to allocate and initialize records
void* init_records(int num_records) {
    // Check if the total memory usage exceeds the maximum limit
    if (num_records * sizeof(Record) > MAX_MEMORY) return NULL;

    // Allocate memory for an array of records
    void* ptr = malloc(num_records * sizeof(Record));

    // Check if allocation was successful
    if (!ptr) return NULL;

    // Initialize each record with random values and strings
    for (int i = 0; i < num_records; i++) {
        Record* rec = (Record*) ((char*) ptr + i * sizeof(Record));
        rec->integer = rand() % 100;
        rec->decimal = (double)rand() / RAND_MAX;

        // Generate a random string
        int str_len = rand() % 100 + 1;
        char* str = malloc(str_len);
        for (int j = 0; j < str_len; j++) {
            str[j] = 'a' + (rand() % 26);
        }
        rec->string = str;
    }

    return ptr;
}

// Function to compress records using Zlib
void* compress_records(void* data, int num_records) {
    // Create a zlib compressor context
    z_stream stream;
    deflateInit2(&stream, Z_DEFAULT_COMPRESSION, Z_DEFLATED, 31, 8, Z_DEFAULT_STRATEGY);

    // Compress each record
    void* compressed_data = malloc(num_records * sizeof(Record));
    for (int i = 0; i < num_records; i++) {
        Record* rec = (Record*) ((char*) data + i * sizeof(Record));
        unsigned char buf[1024];
        int len = compress2((Bytef*)buf, &len, 
                (const Bytef*)rec, sizeof(Record), Z_DEFAULT_COMPRESSION);
        // Store the compressed record
        void* ptr = malloc(len);
        memcpy(ptr, buf, len);
        ((char*)compressed_data + i * len) = ptr;
    }

    deflateEnd(&stream);

    return compressed_data;
}

// Function to encrypt records using AES
void* encrypt_records(void* data, int num_records, const char* key) {
    // Create an AES encryption context
    AES_KEY aes_key;
    AES_set_encrypt_key((const unsigned char*)key, strlen(key), &aes_key);

    // Encrypt each record
    void* encrypted_data = malloc(num_records * sizeof(Record));
    for (int i = 0; i < num_records; i++) {
        Record* rec = (Record*) ((char*) data + i * sizeof(Record));
        unsigned char buf[1024];
        int len = AES_encrypt((unsigned char*)rec, sizeof(Record), buf);
        // Store the encrypted record
        void* ptr = malloc(len);
        memcpy(ptr, buf, len);
        ((char*)encrypted_data + i * len) = ptr;
    }

    return encrypted_data;
}

// Function to free allocated memory
void free_memory(void* data, int num_records) {
    // Free each record's string and itself
    for (int i = 0; i < num_records; i++) {
        Record* rec = (Record*) ((char*)data + i * sizeof(Record));
        if (rec->string) free(rec->string);
        free(rec);
    }

    // Free the array of records and itself
    void* ptr = data;
    while (ptr) {
        Record* rec = (Record*) ((char*)ptr);
        ptr = rec + 1;
        free(rec);
    }
}

// Function to periodically log resource usage statistics
void log_resource_usage(void) {
    // Log the peak memory usage, number of records, and compression ratio
    printf("Peak memory usage: %d MB\n", (int)(get PeakMemoryUsage() / (1024 * 1024)));
    printf("Number of records: %d\n", getNumRecords());
    printf("Compression ratio: %.2f%%\n", getCompressionRatio());
}

// Function to dynamically add new encryption algorithms
void add_encryption_algorithm(const char* name, void (*func)(void*, int, const char*)) {
