        int key = rand_range(rand(), config->min_value, config->max_value);
        records[i].val = rand_range(rand(), config->min_value, config->max_value);

        offsets[i] = offset;
        keys[i] = key;
    }

    free(offsets);
    free(keys);
    free(records);
}

long rand_range(long *rand_ptr, int min, int max) {
    long result = ((*(rand_ptr)) % (max - min + 1)) + min;
    (*(rand_ptr))++;
    return result;
