```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

void initialize_data(long *offset_array, int *key_array, float *float_array, data_t **data_array, size_t count) {
    FILE *dict_file = fopen("dictionary.txt", "r");
    if (!dict_file) {
        printf("Error opening dictionary file\n");
        return;
    }

    // Initialize arrays with some initial capacity
    offset_array = (long *)malloc(count * sizeof(long));
    key_array = (int *)malloc(count * sizeof(int));
    float_array = (float *)malloc(count * sizeof(float));
    *data_array = (data_t **)malloc(count * sizeof(data_t *));

    // Initialize data array with null pointers
    for (size_t i = 0; i < count; i++) {
        (*data_array)[i] = (data_t *)malloc(sizeof(data_t));
    }

    int max_name_len = 20;
    srand(time(NULL));

    size_t idx = 0;
    char line[1024];
    while (fgets(line, sizeof(line), dict_file)) {
        // Parse line and store data
        int number = atoi(strtok(line, ":"));
        char name[max_name_len];
        strcpy(name, strtok(NULL, "\n"));

        offset_array[idx] = (long)number;
        key_array[idx] = number % 100; // Keep it simple for demonstration purposes
        float_array[idx] = (float)(rand() / (RAND_MAX + 1.0));

        (*data_array)[idx]->number = rand() % 100;
        strcpy((*data_array)[idx]->name, name);

        idx++;
    }

    fclose(dict_file);

    if (idx < count) {
        // Resize arrays
        offset_array = (long *)realloc(offset_array, idx * sizeof(long));
        key_array = (int *)realloc(key_array, idx * sizeof(int));
        float_array = (float *)realloc(float_array, idx * sizeof(float));
        *data_array = (data_t **)realloc(*data_array, idx * sizeof(data_t *));

        for (size_t i = 0; i < count; i++) {
            if (i >= idx) {
                free((*data_array)[i]);
            }
        }
    }

    printf("Data initialized successfully\n");
}
