#define MAX_RECORDS 1000
#define MAX_STRING_LENGTH 128
#define MAX_FLOAT_VALUE 1000000.0f

typedef struct {
    float value;
    char string[MAX_STRING_LENGTH];
} SensorDataRecord;

SensorDataRecord* generate_sensor_data_records(int num_records) {
    int i;
    SensorDataRecord* records = (SensorDataRecord*)malloc(num_records * sizeof(SensorDataRecord));
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int peak_memory_usage = 0;

    for (i = 0; i < num_records; i++) {
        SensorDataRecord record;
        record.value = (float)(rand() % MAX_FLOAT_VALUE);
        sprintf(record.string, "Sensor data record %d", i);

        pthread_mutex_lock(&mutex);
        peak_memory_usage += sizeof(SensorDataRecord);
        pthread_mutex_unlock(&mutex);

        records[i] = record;
    }

    return records;
}

void print_sensor_data_records(SensorDataRecord* records, int num_records) {
    int i;

    for (i = 0; i < num_records; i++) {
        printf("Value: %f, String: %s\n", records[i].value, records[i].string);
    }
}

int main() {
    pthread_t thread;
    SensorDataRecord* sensor_data_records;
    int num_records;

    num_records = generate_sensor_data_records(MAX_RECORDS);

    pthread_create(&thread, NULL, (void*)print_sensor_data_records, sensor_data_records);

    return 0;
}
