#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>

#define MAX_MEMORY 1024*1024*10 // 10MB
#define STRING_MAX_LENGTH 256

typedef struct {
    double value;
    char *string;
} Record;

void* malloc_safe(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL || size > MAX_MEMORY) {
        printf("Memory allocation failed: %p\n", ptr);
        exit(-1);
    }
    return ptr;
}

Record* generate_records(int num_records) {
    Record *records = NULL;
    int total_size = 0;

    for (int i = 0; i < num_records; i++) {
        size_t record_size = sizeof(Record);
        records = realloc(records, (num_records + 1) * record_size);
        if (!records) {
            printf("Memory allocation failed\n");
            return NULL;
        }

        Record* record = &records[num_records - 1];
        record->value = rand() / (double)RAND_MAX;
        record->string = malloc_safe(strlen("Random_string_") + STRING_MAX_LENGTH);
        sprintf(record->string, "Random_string_%d", i);

        total_size += record_size;
    }

    if (total_size > MAX_MEMORY) {
        printf("Total memory usage exceeds limit\n");
        return NULL;
    }

    return records;
}

void free_records(Record* records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i].string);
    }
    free(records);
}

void perform_cryptographic_operations(int num_records, Record* records) {
    // Initialize OpenSSL
    if (!EVP_add_cipher(EVP_aes_128_cbc())) {
        printf("AES cipher initialization failed\n");
        return;
    }
    if (!EVP_add_digest(EVP_sha256())) {
        printf("SHA-256 digest initialization failed\n");
        return;
    }

    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
