            strcpy(r.stringValue, buffer);
            r.intValue = keys[i % key_size];
            r.doubleValue = values[i];

            records[i] = r;
        }

        free(keys);
        free(values);

        return records;
    } else {
        printf("Invalid parameters.\n");
        exit(1);
    }
}

