        return NULL;
    }

    record* records = NULL;
    size_t total_size = 0;

    while (1) {
        record r;
        if (fscanf(file, "%ld %lf %f\n", &r.d, &r.x, &r.y) != 3) {
            break;
        }
        total_size += sizeof(record);

        if (!records) {
            records = malloc(total_size);
        } else {
            record* new_records = realloc(records, total_size);
            records = new_records;
        }

        memcpy(&records[total_size - sizeof(record)], &r, sizeof(record));
    }

    fclose(file);
    *max_size = total_size;

    return records;
}

void free_data(record* data) {
    free(data);
}

