        (keyArray = (int*)malloc(keyArraySize * sizeof(int))) == NULL ||
        (recordArray = (record**)malloc(recordArraySize * sizeof(record*))) == NULL) {
        pthread_mutex_unlock(&mutex);
        return NULL;
