    pthread_mutex_lock(&mutex);
    if ((offsetArray = realloc(offsetArray, offsetArraySize * sizeof(long))) == NULL ||
        (keyArray = realloc(keyArray, keyArraySize * sizeof(int))) == NULL ||
        (recordArray = realloc(recordArray, recordArraySize * sizeof(record*))) == NULL) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Initialize arrays and records
    for (int i = 0; i < offsetArraySize; i++) {
        offsetArray[i] = i;
    }
    for (int i = 0; i < keyArraySize; i++) {
        keyArray[i] = i;
