    }
    for (int i = 0; i < recordArraySize; i++) {
        totalMemoryUsage += sizeof(record);
    }

    // Log memory usage details
    logMemoryUsage(totalMemoryUsage);

    *prevSize = newLimit;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function to periodically compact allocated memory blocks
void compactAllocatedMemory() {
    // Compact memory for arrays and records
    if (offsetArray != NULL) {
        offsetArray = realloc(offsetArray, offsetArraySize * sizeof(long));
    }
    if (keyArray != NULL) {
