        }
    }

    // Log compaction details
    logMemoryCompaction();
}

// Function to handle error cases during dynamic resizing
void* resizeErrorHandling(int newLimit) {
    if (newLimit > maxLimit) {
        // Handle error: insufficient memory
        return NULL;
    } else {
        // Resize arrays and records
        return resizeArraysAndRecords(newLimit, &prevSize);
    }
}
