typedef struct {
    int key;
} record_t;

record_t* records;
int* keys;
long* offsets;

void* allocate_memory(void* arg) {
    int num_records = *(int*)arg;
    records = (record_t*)malloc(num_records * sizeof(record_t));
    keys = (int*)malloc(num_records * sizeof(int));
    offsets = (long*)malloc(num_records * sizeof(long));

    for(int i = 0; i < num_records; i++) {
        records[i].key = rand() % MAX_KEY;
        keys[i] = rand() % MAX_KEY;
        offsets[i] = (long)rand() % MAX_OFFSET;
    }

    free(arg);
    return NULL;
}

void deallocate_memory(void* arg) {
    if(records != NULL)
        free(records);

    if(keys != NULL)
        free(keys);

    if(offsets != NULL)
        free(offsets);

    free(arg);
}

int main() {
    pthread_t thread;
    int num_records = 1000;

    // Create a new thread to perform the memory allocation
    pthread_create(&thread, NULL, allocate_memory, &num_records);

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    // Deallocate the memory
    deallocate_memory(&num_records);

    return 0;
}
