class RandomRange {
public:
    RandomRange(int min, int max) {
        _min = min;
        _max = max;
    }

    int RandInt() {
        return rand() % (_max - _min + 1) + _min;
    }

    float RandFloat() {
        return (float)RandInt() / (float)(_max - _min);
    }

    virtual char* ToString() {
        return (char*)malloc((20 + strlen(std::to_string(_min)) + strlen(std::to_string(_max))) * sizeof(char));
        sprintf(this->ToString(), "Random values in range [%d, %d]", _min, _max);
        return this->ToString();
    }

private:
    int _min;
    int _max;
};

void generateArrays(int offsetCount, int keyValueCount, RandomRange* rr) {
    // Allocate memory for arrays
    long* offsets = (long*)malloc(offsetCount * sizeof(long));
    int* keys = (int*)malloc(keyValueCount * sizeof(int));

    // Initialize arrays with random values
    for (int i = 0; i < offsetCount; i++) {
        offsets[i] = rr->RandInt();
    }

    for (int j = 0; j < keyValueCount; j++) {
        keys[j] = rr->RandInt();
    }

    // Initialize array of record structures
    Record* records = (Record*)malloc(keyValueCount * sizeof(Record));

    // Set the value of each record's int field to a random value within the given range
    for (int k = 0; k < keyValueCount; k++) {
        records[k].value = rr->RandInt();
    }

    // Release memory
    free(offsets);
    free(keys);
    free(records);

    return;
}

