        char* token = strtok(line, "=");
        if (token != NULL) {
            token = strtok(NULL, "\n");
            if (token != NULL) {
                int value;
                if (sscanf(token, "%d", &value) == 1) {
                    // allocate memory for arrays
                    int size = value;
                    long* offsets = malloc(sizeof(long) * size);
                    int* keys = malloc(sizeof(int) * size);

                    // initialize arrays
                    for (int i = 0; i < size; i++) {
                        offsets[i] = i * 100; // random offset values
                        keys[i] = i % 10 + 1; // random key values
                    }

                    // allocate memory for record structures and string pointers
                    record** records = malloc(sizeof(record*) * size);
                    char** strings = malloc(sizeof(char*) * size);

                    for (int i = 0; i < size; i++) {
                        record* rec = malloc(sizeof(record));
                        rec->key = keys[i];
                        rec->offset = offsets[i];
                        rec->value = rand() % 100;

                        // generate random string
                        srand(time(NULL) + i);
                        char str[16];
                        sprintf(str, "random_string_%d", i);
                        strings[i] = strdup(str);

                        rec->string = strings[i];

                        records[i] = rec;
                    }

                    fclose(file);
                    return records; // successful initialization

                } else {
                    fclose(file); // invalid configuration file data
                    return NULL;
                }
            } else {
                fclose(file); // missing value in config file
                return NULL;
            }
        } else {
            fclose(file); // missing key-value pair in config file
            return NULL;
        }
    }

