    allocator->cache = calloc(cache_size, sizeof(void *));
    allocator->cache_size = cache_size;
    allocator->allocated = 0;
    pthread_mutex_init(&allocator->mutex, NULL);
    return allocator;
}

void slab_allocator_free(SlabAllocator *allocator) {
    free(allocator->cache);
    free(allocator);
    pthread_mutex_destroy(&allocator->mutex);
}

int record_allocate(SlabAllocator *allocator, size_t size, int *id, void **data) {
    // Find a free slot in the cache
    for (size_t i = 0; i < allocator->cache_size; i++) {
        if (!allocator->cache[i]) {
            break;
        }
    }

    // If no free slots are available, reallocate the cache
    if (i == allocator->cache_size) {
        size_t new_cache_size = allocator->cache_size * 2;
        void **new_cache = realloc(allocator->cache, new_cache_size * sizeof(void *));
        for (size_t j = allocator->cache_size; j < new_cache_size; j++) {
            new_cache[j] = NULL;
        }
        allocator->cache = new_cache;
        allocator->cache_size = new_cache_size;
    }

    // Allocate a record from the cache
    void *record = allocator->cache[i];
    allocator->cache[i] = NULL;

    // Initialize the record with the given ID and optional data
    Record *r = record;
    r->id = *id;
    *data = &r + 1; // Point to the additional data if any

    return 0;
}

int record_deallocate(SlabAllocator *allocator, void *record) {
    // Find the corresponding slot in the cache
    for (size_t i = 0; i < allocator->cache_size; i++) {
        if (record == allocator->cache[i]) {
            break;
        }
    }

    // Mark the slot as free
    allocator->cache[i] = NULL;

    return 0;
}

int main() {
    // Create a slab allocator with an initial cache size of SLAB_CACHE_SIZE
    SlabAllocator *allocator = slab_allocator_create(SLAB_CACHE_SIZE);

    // Allocate and initialize records
    int id = 1;
    void *data;
    record_allocate(allocator, sizeof(Record), &id, &data);
    id = 2;
    record_allocate(allocator, sizeof(Record), &id, &data);

    // Deallocate a record
    record_deallocate(allocator, data);

    // Free the slab allocator and its cache
    slab_allocator_free(allocator);

    return 0;
}
