#include <stdlib.h>
#include <stdio.h>
#include <stdatomic.h>
#include <sys/mman.h>

#define MAX_MEMORY 1024 * 1024 * 10
#define SLAB_SIZE 64
#define RECORD_SIZE sizeof(record)

struct record {
    int value;
};

void* custom_malloc(size_t size) {
    void* ptr = NULL;

    // Check if the requested memory is within limits
    if (size > MAX_MEMORY / 8 || (size & (SLAB_SIZE - 1))) {
        return NULL;
    }

    atomic_uint offset = {0};
    int index;
    for (; ; ) {
        // Acquire a unique slot number
        int slot = atomic_fetch_add(&offset, 1);
        index = slot % (MAX_MEMORY / SLAB_SIZE);

        // Check if the memory block is free
        ptr = mmap(NULL, SLAB_SIZE, PROT_READ | PROT_WRITE,
                   MAP_SHARED | MAP_ANONYMOUS, -1, 0);
        if (!ptr) {
            break;
        }

        // Mark as used
        *((char*)ptr + RECORD_SIZE * (index % (SLAB_SIZE / RECORD_SIZE))) = 1;

        return ptr;
    }
}

void custom_free(void* ptr) {
    munmap(ptr, SLAB_SIZE);
}
