// Helper functions to validate array values and allocate memory within specified limits
int validateArray(void* arr, size_t maxElements) {
    if (arr == NULL || maxElements > INT_MAX / sizeof(*arr)) {
        return 0;
    }
    return 1;
}

int validatePoint(point* p) {
