#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_ALLOCATED_MEMORY 1024
#define LOG_FILE "allocation.log"

typedef struct node {
    int integer_field;
    struct node* next;
} node_t;

node_t** array_nodes = NULL;
double* array_doubles = NULL;
char* array_chars = NULL;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL || pthread_mutex_lock() != 0) {
        fprintf(stderr, "Error allocating memory\n");
        exit(1);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
    pthread_mutex_unlock();
}

int init_arrays(int max_elements) {
    int total_size = sizeof(double) * max_elements + sizeof(char) * max_elements + sizeof(node_t*) * (max_elements+1);
    if (total_size > MAX_ALLOCATED_MEMORY) {
        return -1;
    }
    array_doubles = my_malloc(sizeof(double) * max_elements);
    array_chars = my_malloc(sizeof(char) * max_elements);
    array_nodes = my_malloc(sizeof(node_t*) * (max_elements + 1));

    for(int i=0; i<max_elements+1; i++) {
        array_nodes[i] = NULL;
    }
    return 0;
}

int free_arrays() {
    if(array_doubles) {
        my_free(array_doubles);
        array_doubles = NULL;
    }
    if(array_chars) {
        my_free(array_chars);
        array_chars = NULL;
    }
    if(array_nodes) {
        for(int i=0; i<max_elements+1; i++) {
            if(array_nodes[i]) {
                node_t* temp = array_nodes[i];
                while(temp != NULL) {
                    node_t* next = temp->next;
                    my_free(temp);
                    temp = next;
                }
            }
        }
        my_free(array_nodes);
        array_nodes = NULL;
    }
    return 0;
}

void log_allocation(int size, const char* type, const char* file, int line) {
    FILE *log_file = fopen(LOG_FILE, "a");
    fprintf(log_file, "%s: %s allocation of %d bytes at line %d in file %s\n", 
           asctime(localtime()), type, size, line, file);
    fclose(log_file);
}

