// Define the maximum memory limit
#define MAX_MEMORY 1024 * 1024 * 10 // 10 MB

// Structure to represent a data record
typedef struct {
    double value;
    char* string;
} Record;

// Function to generate and manage data records
void* generateRecords(size_t numRecords, int maxMem) {
    // Calculate the required memory size based on the number of records and maximum memory limit
    size_t memSize = sizeof(Record) * numRecords + (maxMem > 0 ? maxMem : MAX_MEMORY);

    // Allocate memory for the records array
    void* records = malloc(memSize);

    // Initialize the records with random values and strings
    Record* record = (Record*) records;
    for(size_t i = 0; i < numRecords; i++) {
        // Generate a random double value
        double val = (double) rand() / RAND_MAX;

        // Allocate memory for the string
        size_t strSize = strlen("RandomString") + 1;
        char* str = malloc(strSize);
        strcpy(str, "RandomString");

        record[i].value = val;
        record[i].string = str;

        // Encrypt and compress the record (optional)
        if(maxMem > 0) {
            int len = strlen(str);
            unsigned char* encrypted = malloc(len + AES_BLOCK_SIZE);
            AES_encrypt(encrypted, (unsigned char*)str, len);

            // Compress the encrypted data using Zlib
            unsigned char* compressed = malloc(len + ZLIB_WorstCase());
            deflateInit2(&compressor, 9, Z_DEFAULT_COMPRESSION, Z_DEFAULT_STRATEGY, NULL);
            deflateParams(compressor, encrypted, len);
            deflate(compressor, &data);

            // Update the record with the compressed data
            record[i].value = val;
            record[i].string = (char*)compressed;
        }
    }

    return records;
}

// Function to free allocated memory
void freeRecords(void* records) {
    Record* record = (Record*) records;

    for(size_t i = 0; i < numRecords; i++) {
        // Free the string and its corresponding data
        free(record[i].string);

        // Reset the record's values and strings
        record[i].value = 0.0;
        record[i].string = NULL;
    }

    // Free the records array
    free(records);
}

