#define MAX_SESSIONS 1000
#define MAX_SENSOR_READINGS 10000
#define MAX_SESSION_ID 1000000
#define MAX_SENSOR_NAME 50

typedef struct {
    int id;
    long duration;
} session_t;

session_t *sessions = NULL;
int num_sessions = 0;
pthread_mutex_t session_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_session_cache(int max_size) {
    sessions = (session_t *)malloc(max_size * sizeof(session_t));
}

void add_session(long session_id, int duration, char *username) {
    pthread_mutex_lock(&session_mutex);
    if (num_sessions >= MAX_SESSIONS) {
        printf("Session cache full. Cannot add new session.\n");
    } else {
        session_t *new_session = &sessions[num_sessions];
        new_session->id = session_id;
        new_session->duration = duration;
        strcpy(new_session->username, username);
        num_sessions++;
    }
    pthread_mutex_unlock(&session_mutex);
}

void sort_sessions() {
    pthread_mutex_lock(&session_mutex);
    qsort(sessions, num_sessions, sizeof(session_t), compare_sessions);
    pthread_mutex_unlock(&session_mutex);
}

int compare_sessions(const void *a, const void *b) {
    session_t *sa = (session_t *)a;
    session_t *sb = (session_t *)b;
    if (sa->duration < sb->duration)
        return -1;
    else if (sa->duration > sb->duration)
        return 1;
    return 0;
}

void free_session_cache() {
    pthread_mutex_lock(&session_mutex);
    free(sessions);
    sessions = NULL;
    num_sessions = 0;
    pthread_mutex_unlock(&session_mutex);
}

int main() {
    srand(time(NULL));

    // Initialize session cache
    init_session_cache(MAX_SESSIONS * sizeof(session_t));

    // Add some initial sessions
    for (int i = 0; i < 10; i++) {
        long session_id = rand() % MAX_SESSION_ID;
        int duration = rand() % 1000 + 1;
        char *username = malloc(MAX_SENSOR_NAME);
        sprintf(username, "User%d", i);
        add_session(session_id, duration, username);
    }

    // Sort sessions by duration
    sort_sessions();

    return 0;
}
