import json

class WeatherDataJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, dict):
            for key in list(obj.keys()):
                if key.startswith("_"):
                    del obj[key]
            return obj
        return super().default(obj)

def parse_weather_data_json(json_string):
    try:
        data = json.loads(json_string)
        return data
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON: {e}")

class WeatherDataJSONParser:
    def to_json(self, weather_data):
        return json.dumps(weather_data, cls=WeatherDataJSONEncoder)

    def from_json(self, json_string):
        return parse_weather_data_json(json_string)
