["Here are the C functions that dynamically allocate memory for and initialize three arrays:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Structure to represent a record
typedef struct {
    int key;
    int value;
} Record;

// Function to initialize and return three arrays: offsets, keys, and records
Record** initArrays() {
    Record **records = (Record **)malloc(50 * sizeof(Record *));
    long *offsets = (long *)malloc((100 + 1) * sizeof(long));
    int *keys = (int *)malloc(50 * sizeof(int));

    // Initialize offsets array with values ranging from 0 to 100, inclusive
    for (long i = 0; i <= 100; i++) {
        offsets[i] = i;
    }

    // Initialize keys array with unique values from 1 to 50, inclusive
    for (int i = 1; i <= 50; i++) {
        keys[i - 1] = i;
    }

    // Initialize records array and set each record's value within the range of the corresponding key plus or minus 10
    srand(time(NULL));  // Seed random number generator
    for (int i = 0; i < 50; i++) {
        Record *record = (Record *)malloc(sizeof(Record));
        record->key = keys[i];
        record->value = rand() % (keys[i] + 11) - 10;
        records[i] = record;
    }

    // Return pointers to the initialized arrays
    return (Record **)records;
}

// Function to validate if the sum of all records' int values is within the specified limit
int validateRecords(Record **records, int numRecords) {
    int total = 0;
    for (int i = 0; i < numRecords; i++) {
        total += records[i]->value;
    }
    return total <= 1000 ? 1 : 0;
}

// Function to adjust and re-allocate the records if their sum exceeds the limit
Record** adjustAndReAllocate(Record **records, int numRecords) {
    // Check if the sum of all records' int values exceeds the limit
    if (!validateRecords(records, numRecords)) {
        // Calculate the remaining value that needs to be allocated within the limit
        int remaining = 1000 - (int)validateRecords(records, numRecords);

        // Re-allocate and adjust the records' values
        for (int i = 0; i < numRecords; i++) {
