typedef struct {
    int timestamp;
    float reading;
    int quality_flag;
} sensor_data;

sensor_data* read_sensor_data_from_file(const char* filename, size_t* num_records) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        return NULL;
    }

    // Read the header to estimate the number of records
    fseek(file, 0, SEEK_END);
    size_t estimated_num_records = ftell(file) / (sizeof(sensor_data) + 1);
    rewind(file);

    sensor_data* data = malloc(estimated_num_records * sizeof(sensor_data));
    if (!data) {
        fclose(file);
        return NULL;
    }

    *num_records = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Tokenize the line and extract timestamp, reading, and quality flag
        char* token = strtok(line, ",");
        if (!token) continue; // Skip empty or malformed lines

        data[*num_records].timestamp = atoi(token);
        token = strtok(NULL, ",");
        if (!token) break; // End of file reached
        data[*num_records].reading = atof(token);

        token = strtok(NULL, ",");
        if (!token) break; // End of file reached
        int quality_flag = atoi(token);
        if (quality_flag < 0 || quality_flag > 2) {
            free(data);
            fclose(file);
            return NULL;
        }
        data[*num_records].quality_flag = quality_flag;

        (*num_records)++;
    }

    fclose(file);

    return data;
}

void free_sensor_data(sensor_data* data, size_t num_records) {
    for (size_t i = 0; i < num_records; i++) {
        free((data + i));
    }
    free(data);
}
