    for (int i = 0; i < count; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->value = -1;
        records[i]->name = NULL;
        records[i]->timestamp = 0;
    }
}

void free_arrays(int count) {
    for (int i = 0; i < count; i++) {
        if (records[i] != NULL) {
            free(records[i]->name);
            free(records[i]);
        }
    }

