['```csharp
using System;
using System.Threading.Tasks;
using System.Security.Cryptography;

public class DataBlockManager : IDisposable
{
    private const int MaxMemoryUsage = 16 * 1024 * 1024; // 16 MB
    private readonly object _lock = new object();
    private long _totalMemoryUsage;

    public void AllocateDataBlock(int blockSize, Action<int> blockInitAction)
    {
        lock (_lock)
        {
            if (_totalMemoryUsage + blockSize > MaxMemoryUsage)
                SplitDataBlock(blockSize);
            else
            {
                int allocatedBlock = 0;
                while (allocatedBlock < blockSize)
                {
                    int chunkSize = Math.Min(MaxMemoryUsage - _totalMemoryUsage, blockSize - allocatedBlock);
                    byte[] block = new byte[chunkSize];
                    // Initialize the data block
                    blockInitAction(chunkSize);
                    _totalMemoryUsage += chunkSize;
                    allocatedBlock += chunkSize;
                }
            }
        }
    }

    private void SplitDataBlock(int blockSize)
    {
        int chunkSize = Math.Min(MaxMemoryUsage / 4, blockSize); // split into 4 chunks
        while (blockSize > 0)
        {
            int remainingChunkSize = Math.Min(blockSize, chunkSize);
            byte[] block = new byte[remainingChunkSize];
            AllocateDataBlock(remainingChunkSize, _ => { });
            blockSize -= remainingChunkSize;
        }
    }

    public void EncryptDataBlock(byte[] dataBlock, byte[] key)
    {
        lock (_lock)
        {
            using (Aes aes = Aes.Create())
            {
                aes.Key = key;
                using (MemoryStream ms = new MemoryStream(dataBlock))
                {
                    using (CryptoStream cs = new CryptoStream(ms, aes.CreateEncryptor()))
                    {
                        byte[] buffer = new byte[1024];
                        int read;
                        while ((read = ms.Read(buffer, 0, buffer.Length)) > 0)
                            cs.Write(buffer, 0, read);
                    }
                }
            }
        }
    }

    public void DecryptDataBlock(byte[] dataBlock, byte[] key)
    {
        lock (_lock)
        {
            using (Aes aes = Aes.Create())
            {
                aes.Key = key;
                using (MemoryStream ms = new MemoryStream(dataBlock))
                {
                    using (CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor()))
                    {
                        byte[] buffer = new byte[1024];
                        int read;
                        while ((read = ms.Read(buffer, 0, buffer.Length)) > 0)
                            cs.Write(buffer, 0, read);
                    }
                }
            }
        }
    }

    public void LogMemoryUsage()
    {
        lock (_lock)
        {
            Console.WriteLine($"Total memory usage: {_totalMemoryUsage} bytes");
        }
    }

    public void Dispose()
    {
        _lock = null;
    }
}

public class DataBlock
{
    public byte[] Block { get; set; }
}
