int parse_csv_file(const char* file_path, long** offsets, int** keys, record_t*** records);
int validate_offsets_and_keys(long* offsets, int* keys, int max_offset, int max_key);

int dynamic_allocate_arrays(const char* file_path, int* max_offset, int* max_key) {
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", file_path);
        return 1;
    }

    long* offsets = NULL;
    int* keys = NULL;
    record_t** records = NULL;

    // Read CSV file and validate data
    int max_offset = 0, max_key = 0;
    if (fscanf(file, "%ld,%d\n", &max_offset, &max_key) != 2) {
        printf("Invalid file format: %s\n", file_path);
        fclose(file);
        return 1;
    }

    // Dynamically allocate memory for arrays
    int num_records = 0;
    while (fscanf(file, "%ld,%d\n", &num_records, NULL) == 2 && num_records <= MAX_RECORDS) {
        if (num_records > max_offset || max_key < num_records) {
            printf("Invalid range: %s\n", file_path);
            fclose(file);
            return 1;
        }
    }

    fclose(file);

    // Validate total memory usage
    int total_memory = (num_records * sizeof(record_t)) + (max_offset + max_key) * sizeof(long) + sizeof(int);
    if (total_memory > MEMORY_LIMIT) {
        printf("Memory allocation exceeded limit: %d MB\n", total_memory / 1024 / 1024);
        return 2;
    }

    // Allocate memory for arrays
    offsets = malloc((max_offset + 1) * sizeof(long));
    keys = malloc((max_key + 1) * sizeof(int));
    records = malloc(num_records * sizeof(record_t*));

    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Memory allocation failed: %s\n", file_path);
        free_record_array(&records);
        free(keys);
        free(offsets);
        return 3;
    }

    // Initialize arrays
    int i = 0;
    for (i = 0; i <= max_offset; i++) {
        offsets[i] = i;
    }
    for (i = 0; i <= max_key; i++) {
        keys[i] = i;
    }

    // Parse CSV file and populate arrays
    if (parse_csv_file(file_path, &offsets, &keys, &records) != 0) {
        printf("Error parsing CSV file: %s\n", file_path);
        free_record_array(&records);
        free(keys);
        free(offsets);
        return 4;
    }

    // Validate arrays
    if (validate_offsets_and_keys(offsets, keys, max_offset, max_key) != 0) {
        printf("Error validating offsets and keys: %s\n", file_path);
        free_record_array(&records);
        free(keys);
        free(offsets);
        return 5;
    }

    // Return success
    return 0;
}

int main() {
