    long *offsets = NULL;
    int *keys = NULL;

    // Validate input parameters
    if (numElements <= 0 || maxKey < 1) {
        printf("Invalid input. Please check your parameters.\n");
        return NULL;
    }

    // Allocate memory for arrays in chunks to manage fragmentation effectively
    offsets = (long *)malloc(numElements * sizeof(long));
    keys = (int *)malloc(numElements * sizeof(int));

    if (!offsets || !keys) {
        printf("Memory allocation failed. Please check your system resources.\n");
        return NULL;
    }

    // Initialize arrays with random values
    int randRange = maxKey + 1;
    srand(time(NULL));  // Seed random number generator

    for (int i = 0; i < numElements; i++) {
        offsets[i] = (long)rand() % (randRange - 1);
        keys[i] = rand() % randRange;
    }

    // Initialize record array
    records = (record *)malloc(numElements * sizeof(record));

    if (!records) {
        printf("Memory allocation failed. Please check your system resources.\n");
        free(offsets); 
        free(keys);
        return NULL;
    }

    for (int i = 0; i < numElements; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    // Free memory
    free(keys);
    free(offsets);

    return records;
}
