        exit(1);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int init_particles(int n, double** particles, int*** matrices, double*** vectors, size_t max_size, long seed) {
    std::random_device rd(seed);
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dis(0.0, 1.0);

    for (int i = 0; i < n; i++) {
        particles[i] = static_cast<double*>(my_malloc(sizeof(double)));
        if (*particles[i] == NULL) {
            return -1;
        }
        *(*(particles + i)) = dis(gen);
    }

    for (int i = 0; i < n; i++) {
        matrices[i] = static_cast<int**>(my_malloc(n * sizeof(int*)));
        vectors[i] = static_cast<double**>(my_malloc(n * sizeof(double*)));
        if (*matrices[i] == NULL || *vectors[i] == NULL) {
            for (int j = 0; j < i; j++) {
                my_free(*particles[j]);
                my_free(*(*(matrices + j)));
                my_free(*(*(vectors + j)));
            }
            return -1;
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            *((*(matrices + i) + j)) = dis(gen);
            *((*(vectors + i) + j)) = dis(gen);
        }
    }

    return 0;
}

void cleanup_particles(int n, double** particles, int*** matrices, double*** vectors, size_t max_size) {
    for (int i = 0; i < n; i++) {
        my_free(*particles[i]);
    }
    my_free(*matrices);
    my_free(*vectors);

    return;
}

int main() {
    // Set the maximum memory allocation
    const size_t max_size = 10000000;

    int particles = 1000;
    double** particle_array = static_cast<double**>(my_malloc(particles * sizeof(double*)));
    if (particle_array == NULL) {
        return -1;
    }

    int*** matrix_array = static_cast<int***>(my_malloc(particles * sizeof(int**)));
    if (*matrix_array == NULL) {
        my_free(*particle_array);
        return -1;
    }

    double*** vector_array = static_cast<double***>(my_malloc(particles * sizeof(double**)));
    if (*vector_array == NULL) {
        for (int i = 0; i < particles; i++) {
            my_free(*particle_array[i]);
        }
        my_free(*matrix_array);
        return -1;
    }

    int init_status = init_particles(particles, particle_array, matrix_array, vector_array, max_size, 1234567890L);

    if (init_status != 0) {
        // Handle allocation failure
        return -1;
    }

    // Perform linear algebra operations using BLAS and LAPACK

    for (int i = 0; i < particles; i++) {
        // Use dgemm to perform matrix multiplication
        int N = 10;
        double A[N][N], B[N][N];
        for (int j = 0; j < N; j++) {
            for (int k = 0; k < N; k++) {
                A[j][k] = dis(gen);
                B[j][k] = dis(gen);
            }
        }
        dgemm_("N", "N", &N, &N, &N, &A[0][0], &N, &B[0][0], &N, 1.0, 0.0);

        // Use dgetrf to solve a system of linear equations
        double X[N];
        for (int j = 0; j < N; j++) {
            X[j] = dis(gen);
        }
        dgetrf_(&N, &N, &X[0], &N, 1.0);

        // Free allocated memory
        cleanup_particles(particles, particle_array, matrix_array, vector_array, max_size);
    }

    return 0;
}
