```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct node {
    int value;
    struct node* next;
} Node;

typedef struct {
    int id;
    double data;
} Record;

void initialize_records(Record** records, int count, int min_val, int max_val) {
    *records = (Record*)malloc(count * sizeof(Record));

    for(int i = 0; i < count; i++) {
        (*records)[i].id = i;
        (*records)[i].data = (double)rand() / RAND_MAX * (max_val - min_val) + min_val;
    }
}

void initialize_nodes(Node** nodes, int count) {
    *nodes = (Node*)malloc(count * sizeof(Node));

    for(int i = 0; i < count; i++) {
        (*nodes)[i].value = rand() % 100;
        (*nodes)[i].next = NULL;
    }
}

void update_records_from_nodes(Record** records, Node* head) {
    Node* curr = head;

    while(curr != NULL) {
        for(int i = 0; i < count; i++) {
            if((*records)[i].id % (*curr).value == 0)
                (*records)[i].data *= (double)(*curr).value / 100.0;
        }

        curr = curr->next;
    }
}

void free_memory(Record** records, Node* head) {
    Node* curr = head;

    while(curr != NULL) {
        Node* next = curr->next;
        free(curr);
        curr = next;
    }

    free(*records);
}
