#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Structure definitions
typedef struct Node {
    int value;
    struct Node* next;
} Node;

typedef struct Record {
    int id;
    double data;
} Record;

void initialize_records(Record** records, int count, int min, int max);
void initialize_nodes(Node** nodes, int count);
void update_records_from_nodes(Record**, Node** nodes);
void free_memory(Record**, Node**);

// Function implementations
void initialize_records(Record** records, int count, int min, int max) {
    *records = (Record*)malloc(count * sizeof(Record));
    if (*records == NULL) {
        return;
    }
    for (int i = 0; i < count; i++) {
        Record* record = &(*records)[i];
        record->id = i;
        record->data = ((double)rand()) / RAND_MAX * (max - min) + min;
    }
}

void initialize_nodes(Node** nodes, int count) {
    *nodes = (Node*)malloc(count * sizeof(Node));
    if (*nodes == NULL) {
        return;
    }
    for (int i = 0; i < count; i++) {
        Node* node = &(*nodes)[i];
        node->value = i;
        node->next = (i == count - 1) ? NULL : *nodes + i + 1;
    }
}

void update_records_from_nodes(Record** records, Node** nodes) {
    for (int i = 0; i < count; i++) {
        Record* record = &(*records)[i];
        record->data = ((double)nodes[i].value / RAND_MAX) * (1.0 - 0.5);
    }
}

void free_memory(Record** records, Node** nodes) {
    for (int i = 0; i < count; i++) {
        free(nodes[i].next);
    }
    free(*nodes);
    for (int i = 0; i < count; i++) {
        free(records[i]);
    }
    free(*records);
}
