    struct StateList* state_list;
};

struct StateList* create_state_list(int* states, int num_states, struct FSA* fsa, int last_state) {
    if (num_states > 0 && last_state < num_states) {
        struct StateList* new_list = malloc(sizeof(struct StateList));
        if (!new_list) return NULL;

        new_list->states = malloc(num_states * sizeof(int));
        if (!new_list->states) {
            free(new_list);
            return NULL;
        }

        new_list->size = num_states;
        fsa->state_list = new_list;

        for (int i = 0; i < num_states; i++) {
            new_list->states[i] = states[i];
        }
    } else {
        printf("Error: Invalid state list creation request.\n");
        return NULL;
    }

    return fsa->state_list;
}
