// Function to generate a random double value within a range
double generate_random_double(double min, double max) {
    // Check for overflow/underflow
    if (max - min > 1e10) {
        // Handle very large ranges by sampling the log space instead
        static const int num_samples = 1000;
        static const double log_min = log(min), log_max = log(max);
        return exp(log_min + (log_max - log_min) * rand() / (RAND_MAX / (num_samples - 1)));
    } else {
        // Use a simple linear interpolation
        return min + (max - min) * (double)rand() / RAND_MAX;
    }
}

