geometry* create_geometries(size_t num_geoms, size_t max_memory_limit) {
    if(max_memory_limit > MAX_MEMORY) {
        printf("Memory limit exceeded. Aborting.\n");
        return NULL;
    }

    const int num_doubles_per_geom = 1;
    const int num_points_per_geom = sizeof(struct point) / sizeof(double);

    size_t total_memory_usage = (num_geoms * (sizeof(geometry) + sizeof(gsl_vector))) + max_memory_limit;

    if(total_memory_usage > MAX_MEMORY) {
        printf("Total memory usage exceeds maximum limit. Aborting.\n");
        return NULL;
    }

    geometry *geoms = (geometry *)malloc(num_geoms * sizeof(geometry));
    if(!geoms) {
        printf("Memory allocation failed. Aborting.\n");
        return NULL;
    }

    for(size_t i = 0; i < num_geoms; ++i) {
        geoms[i].p.x = rand() / (double)RAND_MAX * 2 - 1;
        geoms[i].p.y = rand() / (double)RAND_MAX * 2 - 1;

        const gsl_vector *rand_v = gsl_vector_alloc(1);
        if(!rand_v) {
            printf("Memory allocation failed. Aborting.\n");
            return NULL;
        }

        for(int j = 0; j < num_doubles_per_geom; ++j) {
            gsl_vector_set(rand_v, j, rand() / (double)RAND_MAX * RANDOM_RANGE);
        }

        init_geometry(&geoms[i], rand_v);
        gsl_vector_free(rand_v);

        if(i % 100 == 0) {
            printf("Allocated memory for %d geometries.\n", i);
        }
    }

    return geoms;
}

void free_geometries(geometry *geoms, size_t num_geoms) {
    for(size_t i = 0; i < num_geoms; ++i) {
        if(i % 100 == 0) {
            printf("Freed memory for %d geometries.\n", i);
        }
        free(geoms[i].p.x ? NULL : geoms + i);
    }

    free(geoms);
}
