int compress_data(sensorData* record, unsigned char** compressed_data) {
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    // Initialize compression state
    inflateInit2(&strm, 15);

    // Compress data and store in buffer
    strm.avail_in = sizeof(sensorData);
    strm.next_in = (Bytef*)record;
    do {
        strm.avail_out = 1024;
        strm.next_out = *compressed_data;

        deflate(&strm, Z_NO_COMPRESSION);
    } while (strm.avail_out == 0);

    // Clean up compression state
    inflateEnd(&strm);

    return strm.total_out;
}

