void* record_allocator(void* arg) {
    struct Record* records = NULL;
    int count = 0;

    while (1) {
        if (count >= MAX_MEMORY / sizeof(struct Record)) {
            break;
        }

        records = realloc(records, (count + 1) * sizeof(struct Record));
        if (!records) {
            syslog(LOG_ERR, "Memory allocation failed!");
            exit(1);
        }
        records[count].id = rand() % 1000000; // configurable random seed
        count++;
    }

    return &records;
}

int main(int argc, char** argv) {
