record* initialize_records(int num_records) {
    record* records = NULL;
    int* keys = NULL;
    long* offsets = NULL;

    records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return NULL;
    }

    keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(records);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return NULL;
    }

    offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        free(records);
        free(keys);
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return NULL;
    }

    // Initialize each record's int field to a random value within a given range.
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 1000 + 1;
        records[i].offset = rand();
    }

    return records;
}

void add_record(record** records, int* keys, long* offsets, int num_records) {
    // Add a new record at the end of the array.
    *records = (record*)realloc(*records, (++num_records) * sizeof(record));
    if (!(*records)) {
        fprintf(stderr, "Memory allocation failed for adding a new record.\n");
        return;
    }

    (*keys) = (int*)realloc(*keys, num_records * sizeof(int));
    if (!(*keys)) {
        free(*records);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return;
    }

    (*offsets) = (long*)realloc(offsets, num_records * sizeof(long));
    if (!offsets) {
        free(*records);
        free(*keys);
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return;
    }

    // Initialize each record's int field to a random value within a given range.
    srand(time(NULL));
    (*records)[num_records - 1].key = rand() % 1000 + 1;
    (*records)[num_records - 1].offset = rand();
}

void remove_record(record** records, int* keys, long* offsets, int num_records) {
    // Remove the last record from the array.
    if (num_records > 0) {
        free((*records[--num_records]).key);
        free(*keys);
        free(offsets);
    }
}
