#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY 1024*1024 // 1MB
#define MAX_RECORDS 1000

typedef struct {
    int integer;
    float floating_point;
    char* string;
} sensorData;

sensorData* records = NULL;
int record_count = 0;
int max_records = 0;
int current_memory_usage = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* malloc_checked(void* ptr) {
    size_t size = (size_t) ptr;
    if(size > MAX_MEMORY || current_memory_usage + size > MAX_MEMORY) {
        printf("Memory limit exceeded. Cannot allocate memory.\n");
        return NULL;
    }
    current_memory_usage += size;
    return ptr;
}

void sensor_data_init(int max_records_limit) {
    pthread_mutex_lock(&mutex);
    if(max_records_limit < 1 || max_records_limit > MAX_RECORDS) {
        printf("Invalid number of records. Using default value.\n");
        max_records = MAX_RECORDS;
    } else {
        max_records = max_records_limit;
    }
    records = (sensorData*)malloc_checked(calloc(max_records, sizeof(sensorData)));
    for(int i = 0; i < max_records; i++) {
        records[i].integer = rand() % 100;
        records[i].floating_point = (float)rand() / RAND_MAX;
        records[i].string = malloc_checked(calloc(1 + strlen("Sensor Data Record") + 1, sizeof(char)));
        sprintf(records[i].string, "Sensor Data Record %d", i);
    }
    pthread_mutex_unlock(&mutex);
}

void free_sensor_data() {
    pthread_mutex_lock(&mutex);
    for(int i = 0; i < max_records; i++) {
        if(records[i].string) {
            free(records[i].string);
        }
    }
    free(records);
    current_memory_usage = 0;
    pthread_mutex_unlock(&mutex);
}

void log_resource_usage() {
    pthread_mutex_lock(&mutex);
    printf("Peak memory usage: %d bytes\n", MAX_MEMORY - (MAX_MEMORY - current_memory_usage));
    pthread_mutex_unlock(&mutex);
}
