pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* alloc_func(void* arg) {
    int i = *(int*)arg;
    for (int j = 0; j < MAX_RECORDS; j++) {
        record_t* rec = (record_t*)malloc(sizeof(record_t));
        if (!rec) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        rec->offset = i * OFFSET_RANGE + j;
        rec->key = rand() % KEY_RANGE;
        pthread_mutex_lock(&mutex);
        records[j] = *rec;
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void init_records(int num_threads) {
    int* thread_ids = (int*)malloc(num_threads * sizeof(int));
    for (int i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
    }

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, alloc_func, &thread_ids[i]);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

void free_records() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i]) {
            free(records[i]);
            records[i] = NULL;
        }
    }
