#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MAX_KEY_SIZE 32
#define MAX_VALUE_SIZE 128
#define DELIMITER ":"
#define RANDOM_RANGE_MIN 1
#define RANDOM_RANGE_MAX 65535

// Define a record structure with an int field and a char buffer for key-value pairs
typedef struct {
    int id;
    char data[MAX_KEY_SIZE + MAX_VALUE_SIZE + 2];
} Record;

// Function to allocate memory for arrays, initialize records, and set their values
void* init_records(int max_records, size_t offset_size, size_t key_size, size_t value_size) {
    void* ptr = NULL;

    // Dynamically allocate memory for offsets (long), keys (int), and records (Record*)
    ptr = malloc(offsetof(long, *offsets) + sizeof(long) * max_records);
    if (!ptr) return NULL;  // Error: Offsets allocation failed
    long* offsets = ptr;

    ptr = realloc(ptr, sizeof(int) * max_records);  // Ensure contiguous memory
    int* keys = (int*) (ptr + offsetof(long, *offsets));

    ptr = malloc(sizeof(Record) * max_records);
    if (!ptr) return NULL;  // Error: Records allocation failed
    Record** records = (Record**) ptr;

    // Initialize and set record values
    for (int i = 0; i < max_records; i++) {
        // Set random int field value within specified range
        offsets[i] = rand() % RANDOM_RANGE_MAX + RANDOM_RANGE_MIN;

        // Initialize char buffer for key-value pairs in each record
        char* data = records[i]->data;
        sprintf(data, "%d", offsets[i]);  // Initialize with the offset value

        // Add a random key-value pair (optional)
        if (key_size > 0) {
            size_t key_len = rand() % key_size + 1;
            const char* key = "KEY";
            for (size_t j = 0; j < key_len; j++) {
                data[j] = key[rand() % strlen(key)];
            }
            data[key_len] = '\0';
            size_t value_len = rand() % value_size + 1;
            const char* value = "VALUE";
            for (size_t j = 0; j < value_len; j++) {
                data[key_len + j] = value[rand() % strlen(value)];
            }
            data[key_len + value_len] = '\0';
        }
    }

    return ptr;
}

// Function to free allocated memory
void free_records(void* records) {
    if (records) {
        Record** records_ptr = (Record**) records;
        for (int i = 0; i < MAX_RECORDS; i++) {
            free(records_ptr[i]);
        }
        free(records);
    }
}

// Helper function to add a key-value pair to a record
void add_pair(Record* record, const char* key, const char* value) {
    size_t data_len = strlen(record->data) + strlen(key) + strlen(value) + 2;
    if (data_len > MAX_KEY_SIZE + MAX_VALUE_SIZE) return;  // Error: Exceeds buffer size
    strcat(record->data, key);
    strcat(record->data, DELIMITER);
    strcat(record->data, value);
}

// Helper function to retrieve a key-value pair from a record
void get_pair(const Record* record, char** key, char** value) {
    *key = (char*) malloc(strlen(record->data) + 1);
    if (!*key) return;  // Error: Memory allocation failed
    strcpy(*key, strtok(record->data, DELIMITER));

    *value = (char*) malloc(strlen(strtok(NULL, DELIMITER)) + 1);
    if (!*value) {
        free(*key);  // Free memory to avoid leaks
        return;  // Error: Memory allocation failed
    }
    strcpy(*value, strtok(NULL, DELIMITER));
}

int main() {
    srand(time(NULL));  // Initialize random seed

    void* records = init_records(MAX_RECORDS, sizeof(long), MAX_KEY_SIZE, MAX_VALUE_SIZE);

    if (!records) return 1;  // Error: Memory allocation failed

    Record* record = (Record*) (records + offsetof(long, *offsets));
    char* key = NULL;
    char* value = NULL;
    add_pair(record, "KEY", "VALUE");
    get_pair(record, &key, &value);
    printf("Key: %s\nValue: %s\n", key, value);

    free_records(records);

    return 0;
}
