        return NULL;  // Return failure and avoid undefined behavior
    }

    // Initialize arrays and record structures
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc((numRecords + 1) * sizeof(int));
    record** records = (record**)malloc(numRecords * sizeof(record*));

    if (!offsets || !keys || !records) {
        // Free previously allocated memory and return failure
        free(offsets);
        free(keys);
        for (int i = 0; i < numRecords; i++) {
            free(records[i]);
        }
        free(records);

        return NULL;
    }

    // Initialize offset values and key ranges
    int minKey = 0;
    int maxRandomValue = RAND_MAX;

    // Set the value of each record's int field to a random value within the specified range
    for (int i = 0; i < numRecords; i++) {
        long randomOffset = rand() % ((long)maxRandomValue + 1);
        long randomKey = minKey + (rand() % ((maxKey - minKey) + 1));
        int recordValue = (int)(minKey + (rand() % ((maxRandomValue - minKey) + 1)));

        // Check for overflow or underflow in the record value
        if (recordValue > maxRandomValue || recordValue < minKey) {
            return NULL;  // Return failure and avoid undefined behavior
        }

        offsets[i] = randomOffset;
        keys[i] = randomKey;
        records[i] = (record*)malloc(sizeof(record));
        records[i]->value = recordValue;
    }

    // Set the last key value to maxKey
    keys[numRecords - 1] = maxKey;

    return records;
}

// Function to free allocated memory when done
