Record** createArrays(int* offsetCounts, int* keyCounts, int recordCount) {
    int offsetSize = sizeof(long);
    int keySize = sizeof(int);
    int recordSize = sizeof(Record);

    // Pre-allocate memory for arrays
    long* offsets = (long*)malloc(recordCount * offsetSize);
    int* keys = (int*)malloc(recordCount * keySize);
    Record* records = (Record*)malloc(recordCount * recordSize);

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < recordCount; i++) {
        offsets[i] = rand() % (long)(2^31 - 1);
        keys[i] = rand() % (int)(2^31 - 1);
        records[i].value = rand() % (int)(2^31 - 1);
    }

    // Allocate memory for array of pointers
    Record** recordPointers = (Record**)malloc(recordCount * sizeof(Record*));
    if (!recordPointers) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    for (int i = 0; i < recordCount; i++) {
        recordPointers[i] = &records[i];
    }

    // Reallocate memory to ensure unique values
    int* seenValues = (int*)malloc(recordCount * sizeof(int));
    if (!seenValues) {
        free(offsets);
        free(keys);
        free(records);
        free(recordPointers);
        return NULL;
    }

    for (int i = 0; i < recordCount; i++) {
        int value = rand() % (int)(2^31 - 1);
        while (seenValues[value]++) {
            value = rand() % (int)(2^31 - 1);
        }
        records[i].value = value;
    }

    free(seenValues);

    Record** result = recordPointers;
    recordPointers = NULL;

    // Free memory
    for (int i = 0; i < recordCount; i++) {
        if (!recordPointers) break;
        if (!(*recordPointers)) {
            *recordPointers = NULL;
            free(*recordPointers);
            recordPointers++;
        } else {
            free(*recordPointers);
            recordPointers++;
        }
    }

    free(recordPointers);

    return result;
}
