    for (int i = 0; i < numRecords; i++) {
        record_t* currentRecord = records[i];
        // Generate a random index
        int idx = rand() % numRecords;
        // Get the value at that index and add it to the record's value
        currentRecord->value += availableIds[idx];
        // Mark the ID as unavailable by moving it to the end of the array
        int temp = availableIds[numRecords - 1];
        for (int j = numRecords - 2; j >= idx; j--) {
            availableIds[j + 1] = availableIds[j];
        }
        availableIds[idx] = temp;
    }

    // Free the pool of IDs when done
    free(availableIds);
}

// Optimize the function to minimize memory fragmentation, balance between minimizing memory usage and ensuring robust memory management practices.
void* alloc(size_t size) {
    void* p = malloc(size);
    if (!p && (size > 0 || realloc == NULL)) {
        // Use a pre-allocated buffer
        p = alloca(size);
    }
    return p;
}

// Evaluate trade-offs between memory usage, performance, and maintainability when making design decisions.
void freeMemory(void* ptr) {
    if (ptr) {
        free(ptr);
    }
}
