        fscanf(file, "%d ", &keys[i]);
    }

    // Read data values from file
    for (int i = 0; i < n; i++) {
        fscanf(file, "%f\n", &data[i]);
    }

    // Close the file
    fclose(file);

    // Initialize records array with random float values
    *records = (Record*)malloc(n * sizeof(Record));
    for (int i = 0; i < n; i++) {
        (*records)[i].offset = offsets[i];
        (*records)[i].key = keys[i];
        (*records)[i].data = ((float)rand()) / RAND_MAX;
    }
}

// Example usage
int main() {
    int n = 10; // Number of records
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));
    float* data = (float*)malloc(n * sizeof(float));
    Record** records = NULL;

    initArraysAndRecords(offsets, keys, data, &records, n);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(data);
    free(records);

    return 0;
}
