void* allocate_and_initialize_arrays(int max_points, int max_memory, int* allocated_memory) {
    int i;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for offset values
    long* offset_values = (long*)malloc(max_points * sizeof(long));
    pthread_mutex_lock(&mutex);
    if (!offset_values) {
        return NULL;
    }
    pthread_mutex_unlock(&mutex);

    // Initialize offset values
    for (i = 0; i < max_points; i++) {
        offset_values[i] = i * 10;
    }

    // Allocate memory for keys
    int* keys = (int*)malloc(max_points * sizeof(int));
    pthread_mutex_lock(&mutex);
    if (!keys) {
        free(offset_values);
        return NULL;
    }
    pthread_mutex_unlock(&mutex);

    // Initialize keys
    for (i = 0; i < max_points; i++) {
        keys[i] = i % 10;
    }

    // Allocate memory for record structures
    struct {
        int value;
    }* records = (struct {int value;}*)malloc(max_points * sizeof(struct {int value;}));
    pthread_mutex_lock(&mutex);
    if (!records) {
        free(offset_values);
        free(keys);
        return NULL;
    }
    pthread_mutex_unlock(&mutex);

    // Initialize record structures
    for (i = 0; i < max_points; i++) {
        records[i].value = i % 10;
    }

    // Allocate memory for geometry structures
    geometry_t* geometries = (geometry_t*)malloc(max_points * sizeof(geometry_t));
    pthread_mutex_lock(&mutex);
    if (!geometries) {
        free(offset_values);
        free(keys);
        free(records);
        return NULL;
    }
    pthread_mutex_unlock(&mutex);

    // Initialize geometry structures
    for (i = 0; i < max_points; i++) {
        geometries[i].value = i * M_PI / 180.0;
        point_t* coord = (point_t*)malloc(sizeof(point_t));
        pthread_mutex_lock(&mutex);
        if (!coord) {
            free(geometries);
            for (; i >= 0; i--) {
                free(records[i].value);
            }
            return NULL;
        }
        pthread_mutex_unlock(&mutex);

        coord->x = i % 10;
        coord->y = (i / 10) % 10;

        geometries[i].coord = coord;
    }

    // Update allocated memory
    *allocated_memory = max_points * sizeof(long) + max_points * sizeof(int) + max_points * sizeof(struct {int value;}) + max_points * sizeof(geometry_t) + max_points * sizeof(point_t);

    return NULL;
}

void free_allocated_memory(void* ptr) {
    if (ptr != NULL) {
        // Free offset values
        free(((long*)ptr)[0]);
        // Free keys
        free(((int*)ptr)[1]);
        // Free record structures
        free(((struct {int value;})*)ptr + 2);
        // Free geometry structures
        for (int i = 0; i < MAX_POINTS; i++) {
            free((((geometry_t*)ptr) + i)->coord);
        }
    }
}
