#include <pthread.h>

#define MAX_POINTS 1000
#define MAX_MEMORY 1024 * 1024 * 10 // 10MB

typedef struct {
    int x;
    int y;
} point_t;

typedef struct {
    double value;
    point_t *coord;
} geometry_t;

int* allocated_memory = NULL;

void free_memory(void) {
    if (allocated_memory != NULL) {
        free(allocated_memory);
        allocated_memory = NULL;
    }
}

int check_allocated_memory(int memory) {
    if (memory > MAX_MEMORY || memory < 0) {
        return -1; // Memory allocation failed
    }
    return 0; // Allocation succeeded
}

geometry_t* init_geometry_arrays(int max_points, int* allocated_memory) {
    geometry_t* geometry_array = (geometry_t*)malloc(max_points * sizeof(geometry_t));
    if (geometry_array == NULL || check_allocated_memory((int)(max_points * sizeof(geometry_t))) < 0) {
        return NULL; // Memory allocation failed
    }
    point_t* points = (point_t*)malloc(max_points * sizeof(point_t));
    if (points == NULL || check_allocated_memory((int)(max_points * sizeof(point_t))) < 0) {
        free_geometry_arrays(geometry_array, max_points);
        return NULL; // Memory allocation failed
    }
    for (int i = 0; i < max_points; i++) {
        points[i].x = rand() % 100;
        points[i].y = rand() % 100;
    }
    geometry_t* result = (geometry_t*)malloc(max_points * sizeof(geometry_t));
    if (result == NULL || check_allocated_memory((int)(max_points * sizeof(geometry_t))) < 0) {
        free_geometry_arrays(geometry_array, max_points);
        return NULL; // Memory allocation failed
    }
    for (int i = 0; i < max_points; i++) {
        result[i].value = 5.0;
        result[i].coord = &points[i];
    }
    *allocated_memory += (int)(max_points * sizeof(geometry_t)) + (int)(max_points * sizeof(point_t));
    return result;
}

void free_geometry_arrays(geometry_t* geometry_array, int max_points) {
    if (geometry_array != NULL) {
        for (int i = 0; i < max_points; i++) {
            free((void*)geometry_array[i].coord);
        }
        free((void*)geometry_array);
    }
}

int main() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int max_points = MAX_POINTS;
    int* allocated_memory = (int*)malloc(sizeof(int));
    if (*allocated_memory == NULL) {
        return -1; // Memory allocation failed
    }
    *allocated_memory = 0;
    geometry_t* geometry_array = init_geometry_arrays(max_points, allocated_memory);
    if (geometry_array == NULL) {
        free_memory();
        return -1; // Memory allocation failed
    }
    for (int i = 0; i < max_points; i++) {
        printf("Point %d: (%d, %d)\n", i + 1, geometry_array[i].coord->x, geometry_array[i].coord->y);
    }
    free_memory();
    return 0;
}

