#include <stdlib.h>
#include <stdio.h>

record **init_records(int num_records, long *offsets, int *keys, int min_val, int max_val) {
    record **records = NULL;
    if (num_records <= 0 || offsets == NULL || keys == NULL) {
        return NULL; // invalid input
    }

    records = (record **)malloc(sizeof(record *) * num_records);
    if (!records) {
        return NULL; // memory allocation failed
    }

    for (int i = 0; i < num_records; i++) {
        record *rec = (record *)malloc(sizeof(record));
        if (!rec) {
            free_records(records);
            return NULL; // memory allocation failed
        }

        rec->value = min_val + (rand() % ((max_val - min_val) + 1)); // generate a random value
        rec->offset = &offsets[i]; // set the offset pointer
        rec->key = keys[i];

        records[i] = rec;
    }

    return records;
}

void free_records(record **records) {
    if (!records || !*records) {
        return; // nothing to free
    }

    for (int i = 0; i < (*records)[0]->value; i++) { // iterate over the number of records (assuming it's a valid value)
        record *rec = (*records)[i];
        if (!rec) {
            continue;
        }

        free(rec->offset); // free the offset pointer
        free(rec);
    }

    free(*records); // free the array of record pointers
}"]

