// Custom memory pool allocator structure
typedef struct {
    void *mem;
    size_t capacity;
    size_t used;
} MemoryPool;

// Initialize the offset array with increasing values starting from 0.
void* init_offset_array(size_t n) {
    void *ptr = malloc(n * sizeof(long));
    long *offsets = ptr;
    for (size_t i = 0; i < n; ++i) {
        offsets[i] = i;
    }
    return ptr;
}

// Initialize the key array with alternating values.
void* init_key_array(size_t n, int start_value) {
    void *ptr = malloc(n * sizeof(int));
    int *keys = ptr;
    for (size_t i = 0; i < n; ++i) {
        keys[i] = (i % 2 == 0) ? start_value : -start_value;
    }
    return ptr;
}

// Initialize the timestamp array with either the current system time or zero.
void* init_timestamp_array(size_t n, int use_current_time) {
    void *ptr = malloc(n * sizeof(time_t));
    time_t *timestamps = ptr;
    for (size_t i = 0; i < n; ++i) {
        if (use_current_time) {
            timestamps[i] = time(NULL);
        } else {
            timestamps[i] = 0;
        }
    }
    return ptr;
}

// Initialize the record array with corresponding offset, key, and timestamp.
void* init_record_array(size_t n, void *offsets, void *keys, void *timestamps) {
    void *ptr = malloc(n * sizeof(struct record));
    struct record *records = ptr;
    for (size_t i = 0; i < n; ++i) {
        records[i].int_value = *(int *)((void **)&keys + i);
        records[i].timestamp = *(time_t *)((void **)&timestamps + i);
    }
    return ptr;
}

// Custom memory pool allocator functions
MemoryPool* init_memory_pool(size_t capacity) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->mem = malloc(capacity * sizeof(void *));
    pool->capacity = capacity;
    pool->used = 0;
    return pool;
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->mem);
    free(pool);
}

// Thread-safe logging mechanism
void log_error(MemoryPool *pool, const char *message) {
    FILE *log_file = fopen("/path/to/log/file.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        // Log the error to the memory pool's internal buffer
        void **buffer = (void **)pool->mem;
        for (size_t i = 0; i < pool->used; ++i) {
            free(buffer[i]);
        }
        pool->used = 0;
    }
}

// Main function
