        (*records)[i] = (Record*)malloc(sizeof(Record));
        (*records)[i]->value = rand() % 10000 - 5000;
    }

    return 1;
}

// Function to free allocated memory
void freeMemory(int* offsetValues, int* keys, Record** records) {
