    }

    // Free memory for records array
    if (records != NULL) {
        for (int i = 0; i < 10; i++) {
            if (records[i] != NULL) {
                free(records[i]);
            }
        }
        free(records);
    }
}

// Function to serialize and deserialize records to/from file using binary format
void serializeRecords(Record** records, FILE* file) {
    // Serialize records to file
