int add_node(Node *node) {
    if (num_nodes >= max_connections || sizeof(*nodes) * (num_nodes + 1) > max_memory) {
        printf("Maximum connections reached or memory limit exceeded\n");
        return -1;
    }
    nodes[num_nodes++] = node;
    return 0;
}

