struct fsa {
    int num_states;
    struct state* states;
    int last_state;
};

struct fsa* create_state_list(int* states, int num_states, struct fsa* fsa) {
    struct fsa* result = (struct fsa*)malloc(sizeof(struct fsa));
    if (!result) return NULL;

    result->num_states = num_states;
    result->last_state = num_states - 1;

    result->states = (struct state*)calloc(num_states, sizeof(struct state));
