            g->edges[g->num_edges].props[1] = rand();
            g->edges[g->num_edges].props[2] = rand();
            break;
        }
    }
    g->num_edges++;
}

void free_state_list(struct fsa* f) {
    for (int i = 0; i < f->num_states; i++) {
