Record** create_state_list(int* states, int num_states, FSA* fsa, int last_state) {
    // Allocate memory for the state list
    int* state_list = (int*)malloc(num_states * sizeof(int));
    if (!state_list) {
        printf("Error: Unable to allocate memory for state list.\n");
        return NULL;
    }

    // Initialize the state list with states from input array
    memcpy(state_list, states, num_states * sizeof(int));

    // Allocate memory for offset and key arrays
    int* offset_array = (int*)malloc(10 * sizeof(int)); // Assuming 10 offsets are enough
    if (!offset_array) {
        printf("Error: Unable to allocate memory for offset array.\n");
        free(state_list);
        return NULL;
    }

    int* key_array = (int*)malloc(num_states * sizeof(int));
    if (!key_array) {
        printf("Error: Unable to allocate memory for key array.\n");
        free(offset_array);
        free(state_list);
        return NULL;
    }

    // Allocate memory for record array
    Record** record_array = (Record**)malloc(10 * sizeof(Record*)); // Assuming 10 records are enough
    if (!record_array) {
        printf("Error: Unable to allocate memory for record array.\n");
        free(key_array);
        free(offset_array);
        free(state_list);
        return NULL;
    }

    // Initialize the record array with dummy values
    for (int i = 0; i < 10; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            printf("Error: Unable to allocate memory for record.\n");
            free(record_array[i]);
            continue;
        }
        record->value = i;
    }

    return state_list;
}
